{"v_g?","v_g?"},
{"/\\?","/\\\\?"},
{"/\\z(\\)","/\\\\z(\\\\)"},
{"\\=","\\\\="},
{":s\\=",":s\\\\="},
{"[count]","\\[count]"},
{"[quotex]","\\[quotex]"},
