static mrb_value
fiber_switch(mrb_state *mrb, mrb_value self, mrb_int len, const mrb_value *a, mrb_bool resume, mrb_bool vmexec)
{
struct mrb_context *c = fiber_check(mrb, self);
struct mrb_context *old_c = mrb->c;
enum mrb_fiber_state status;
mrb_value value;
fiber_check_cfunc(mrb, c);
status = c->status;
switch (status) {
case MRB_FIBER_TRANSFERRED:
if (resume) {
mrb_raise(mrb, E_FIBER_ERROR, "resuming transferred fiber");
}
break;
case MRB_FIBER_RUNNING:
case MRB_FIBER_RESUMED:
mrb_raise(mrb, E_FIBER_ERROR, "double resume");
break;
case MRB_FIBER_TERMINATED:
mrb_raise(mrb, E_FIBER_ERROR, "resuming dead fiber");
break;
default:
break;
}
old_c->status = resume ? MRB_FIBER_RESUMED : MRB_FIBER_TRANSFERRED;
c->prev = resume ? mrb->c : (c->prev ? c->prev : mrb->root_c);
fiber_switch_context(mrb, c);
if (status == MRB_FIBER_CREATED) {
mrb_value *b, *e;
if (!c->ci->proc) {
mrb_raise(mrb, E_FIBER_ERROR, "double resume (current)");
}
mrb_stack_extend(mrb, len+2); 
b = c->stbase+1;
e = b + len;
while (b<e) {
*b++ = *a++;
}
if (vmexec) {
c->ci--;                    
}
c->cibase->n = len;
value = c->stbase[0] = MRB_PROC_ENV(c->cibase->proc)->stack[0];
}
else {
value = fiber_result(mrb, a, len);
if (vmexec) {
c->ci[1].stack[0] = value;
}
}
if (vmexec) {
c->vmexec = TRUE;
value = mrb_vm_exec(mrb, c->ci->proc, c->ci->pc);
mrb->c = old_c;
}
else {
MARK_CONTEXT_MODIFY(c);
}
return value;
}

int main (int argc, char *argv[])
{
int objectsCount = 0;
Guint numOffset = 0;
std::vector<Object> pages;
std::vector<Guint> offsets;
XRef *yRef, *countRef;
FILE *f;
OutStream *outStr;
int i;
int j, rootNum;
std::vector<PDFDoc *>docs;
int majorVersion = 0;
int minorVersion = 0;
char *fileName = argv[argc - 1];
int exitCode;
exitCode = 99;
const GBool ok = parseArgs (argDesc, &argc, argv);
if (!ok || argc < 3 || printVersion || printHelp) {
fprintf(stderr, "pdfunite version %s\n", PACKAGE_VERSION);
fprintf(stderr, "%s\n", popplerCopyright);
fprintf(stderr, "%s\n", xpdfCopyright);
if (!printVersion) {
printUsage("pdfunite", "<PDF-sourcefile-1>..<PDF-sourcefile-n> <PDF-destfile>",
argDesc);
}
if (printVersion || printHelp)
exitCode = 0;
return exitCode;
}
exitCode = 0;
globalParams = new GlobalParams();
for (i = 1; i < argc - 1; i++) {
GooString *gfileName = new GooString(argv[i]);
PDFDoc *doc = new PDFDoc(gfileName, NULL, NULL, NULL);
if (doc->isOk() && !doc->isEncrypted()) {
docs.push_back(doc);
if (doc->getPDFMajorVersion() > majorVersion) {
majorVersion = doc->getPDFMajorVersion();
minorVersion = doc->getPDFMinorVersion();
} else if (doc->getPDFMajorVersion() == majorVersion) {
if (doc->getPDFMinorVersion() > minorVersion) {
minorVersion = doc->getPDFMinorVersion();
}
}
} else if (doc->isOk()) {
error(errUnimplemented, -1, "Could not merge encrypted files ('{0:s}')", argv[i]);
return -1;
} else {
error(errSyntaxError, -1, "Could not merge damaged documents ('{0:s}')", argv[i]);
return -1;
}
}
if (!(f = fopen(fileName, "wb"))) {
error(errIO, -1, "Could not open file '{0:s}'", fileName);
return -1;
}
outStr = new FileOutStream(f, 0);
yRef = new XRef();
countRef = new XRef();
yRef->add(0, 65535, 0, gFalse);
PDFDoc::writeHeader(outStr, majorVersion, minorVersion);
Object intents;
Object afObj;
Object ocObj;
Object names;
if (docs.size() >= 1) {
Object catObj;
docs[0]->getXRef()->getCatalog(&catObj);
Dict *catDict = catObj.getDict();
catDict->lookup("OutputIntents", &intents);
catDict->lookupNF("AcroForm", &afObj);
Ref *refPage = docs[0]->getCatalog()->getPageRef(1);
if (!afObj.isNull()) {
docs[0]->markAcroForm(&afObj, yRef, countRef, 0, refPage->num, refPage->num);
}
catDict->lookupNF("OCProperties", &ocObj);
if (!ocObj.isNull() && ocObj.isDict()) {
docs[0]->markPageObjects(ocObj.getDict(), yRef, countRef, 0, refPage->num, refPage->num);
}
catDict->lookup("Names", &names);
if (!names.isNull() && names.isDict()) {
docs[0]->markPageObjects(names.getDict(), yRef, countRef, 0, refPage->num, refPage->num);
}
if (intents.isArray() && intents.arrayGetLength() > 0) {
for (i = 1; i < (int) docs.size(); i++) {
Object pagecatObj, pageintents;
docs[i]->getXRef()->getCatalog(&pagecatObj);
Dict *pagecatDict = pagecatObj.getDict();
pagecatDict->lookup("OutputIntents", &pageintents);
if (pageintents.isArray() && pageintents.arrayGetLength() > 0) {
for (j = intents.arrayGetLength() - 1; j >= 0; j--) {
Object intent;
intents.arrayGet(j, &intent, 0);
if (intent.isDict()) {
Object idf;
intent.dictLookup("OutputConditionIdentifier", &idf);
if (idf.isString()) {
GooString *gidf = idf.getString();
GBool removeIntent = gTrue;
for (int k = 0; k < pageintents.arrayGetLength(); k++) {
Object pgintent;
pageintents.arrayGet(k, &pgintent, 0);
if (pgintent.isDict()) {
Object pgidf;
pgintent.dictLookup("OutputConditionIdentifier", &pgidf);
if (pgidf.isString()) {
GooString *gpgidf = pgidf.getString();
if (gpgidf->cmp(gidf) == 0) {
pgidf.free();
removeIntent = gFalse;
break;
}
}
pgidf.free();
}
}
if (removeIntent) {
intents.arrayRemove(j);
error(errSyntaxWarning, -1, "Output intent {0:s} missing in pdf {1:s}, removed",
gidf->getCString(), docs[i]->getFileName()->getCString());
}
} else {
intents.arrayRemove(j);
error(errSyntaxWarning, -1, "Invalid output intent dict, missing required OutputConditionIdentifier");
}
idf.free();
} else {
intents.arrayRemove(j);
}
intent.free();
}
} else {
error(errSyntaxWarning, -1, "Output intents differs, remove them all");
intents.free();
break;
}
pagecatObj.free();
pageintents.free();
}
}
if (intents.isArray() && intents.arrayGetLength() > 0) {
for (j = intents.arrayGetLength() - 1; j >= 0; j--) {
Object intent;
intents.arrayGet(j, &intent, 0);
if (intent.isDict()) {
docs[0]->markPageObjects(intent.getDict(), yRef, countRef, numOffset, 0, 0);
} else {
intents.arrayRemove(j);
}
intent.free();
}
}
catObj.free();
}
for (i = 0; i < (int) docs.size(); i++) {
for (j = 1; j <= docs[i]->getNumPages(); j++) {
PDFRectangle *cropBox = NULL;
if (docs[i]->getCatalog()->getPage(j)->isCropped())
cropBox = docs[i]->getCatalog()->getPage(j)->getCropBox();
docs[i]->replacePageDict(j,
docs[i]->getCatalog()->getPage(j)->getRotate(),
docs[i]->getCatalog()->getPage(j)->getMediaBox(), cropBox);
Ref *refPage = docs[i]->getCatalog()->getPageRef(j);
Object page;
docs[i]->getXRef()->fetch(refPage->num, refPage->gen, &page);
Dict *pageDict = page.getDict();
Dict *resDict = docs[i]->getCatalog()->getPage(j)->getResourceDict();
if (resDict) {
Object *newResource = new Object();
newResource->initDict(resDict);
pageDict->set("Resources", newResource);
delete newResource;
}
pages.push_back(page);
offsets.push_back(numOffset);
docs[i]->markPageObjects(pageDict, yRef, countRef, numOffset, refPage->num, refPage->num);
Object annotsObj;
pageDict->lookupNF("Annots", &annotsObj);
if (!annotsObj.isNull()) {
docs[i]->markAnnotations(&annotsObj, yRef, countRef, numOffset, refPage->num, refPage->num);
annotsObj.free();
}
}
Object pageCatObj, pageNames, pageForm;
docs[i]->getXRef()->getCatalog(&pageCatObj);
Dict *pageCatDict = pageCatObj.getDict();
pageCatDict->lookup("Names", &pageNames);
if (!pageNames.isNull() && pageNames.isDict()) {
if (!names.isDict()) {
names.free();
names.initDict(yRef);
}
doMergeNameDict(docs[i], yRef, countRef, 0, 0, names.getDict(), pageNames.getDict(), numOffset);
}
pageCatDict->lookup("AcroForm", &pageForm);
if (i > 0 && !pageForm.isNull() && pageForm.isDict()) {
if (afObj.isNull()) {
pageCatDict->lookupNF("AcroForm", &afObj);
} else if (afObj.isDict()) {
doMergeFormDict(afObj.getDict(), pageForm.getDict(), numOffset);
}
}
pageForm.free();
pageNames.free();
pageCatObj.free();
objectsCount += docs[i]->writePageObjects(outStr, yRef, numOffset, gTrue);
numOffset = yRef->getNumObjects() + 1;
}
rootNum = yRef->getNumObjects() + 1;
yRef->add(rootNum, 0, outStr->getPos(), gTrue);
outStr->printf("%d 0 obj\n", rootNum);
outStr->printf("<< /Type /Catalog /Pages %d 0 R", rootNum + 1);
if (intents.isArray() && intents.arrayGetLength() > 0) {
outStr->printf(" /OutputIntents [");
for (j = 0; j < intents.arrayGetLength(); j++) {
Object intent;
intents.arrayGet(j, &intent, 0);
if (intent.isDict()) {
PDFDoc::writeObject(&intent, outStr, yRef, 0, NULL, cryptRC4, 0, 0, 0);
}
intent.free();
}
outStr->printf("]");
}
intents.free();
if (!afObj.isNull()) {
outStr->printf(" /AcroForm ");
PDFDoc::writeObject(&afObj, outStr, yRef, 0, NULL, cryptRC4, 0, 0, 0);
afObj.free();
}
if (!ocObj.isNull() && ocObj.isDict()) {
outStr->printf(" /OCProperties ");
PDFDoc::writeObject(&ocObj, outStr, yRef, 0, NULL, cryptRC4, 0, 0, 0);
ocObj.free();
}
if (!names.isNull() && names.isDict()) {
outStr->printf(" /Names ");
PDFDoc::writeObject(&names, outStr, yRef, 0, NULL, cryptRC4, 0, 0, 0);
names.free();
}
outStr->printf(">>\nendobj\n");
objectsCount++;
yRef->add(rootNum + 1, 0, outStr->getPos(), gTrue);
outStr->printf("%d 0 obj\n", rootNum + 1);
outStr->printf("<< /Type /Pages /Kids [");
for (j = 0; j < (int) pages.size(); j++)
outStr->printf(" %d 0 R", rootNum + j + 2);
outStr->printf(" ] /Count %zd >>\nendobj\n", pages.size());
objectsCount++;
for (i = 0; i < (int) pages.size(); i++) {
yRef->add(rootNum + i + 2, 0, outStr->getPos(), gTrue);
outStr->printf("%d 0 obj\n", rootNum + i + 2);
outStr->printf("<< ");
Dict *pageDict = pages[i].getDict();
for (j = 0; j < pageDict->getLength(); j++) {
if (j > 0)
outStr->printf(" ");
const char *key = pageDict->getKey(j);
Object value;
pageDict->getValNF(j, &value);
if (strcmp(key, "Parent") == 0) {
outStr->printf("/Parent %d 0 R", rootNum + 1);
} else {
outStr->printf("/%s ", key);
PDFDoc::writeObject(&value, outStr, yRef, offsets[i], NULL, cryptRC4, 0, 0, 0);
}
value.free();
}
outStr->printf(" >>\nendobj\n");
objectsCount++;
}
Goffset uxrefOffset = outStr->getPos();
Ref ref;
ref.num = rootNum;
ref.gen = 0;
Dict *trailerDict = PDFDoc::createTrailerDict(objectsCount, gFalse, 0, &ref, yRef,
fileName, outStr->getPos());
PDFDoc::writeXRefTableTrailer(trailerDict, yRef, gTrue,                                 uxrefOffset, outStr, yRef);
delete trailerDict;
outStr->close();
delete outStr;
fclose(f);
delete yRef;
delete countRef;
for (j = 0; j < (int) pages.size (); j++) pages[j].free();
for (i = 0; i < (int) docs.size (); i++) delete docs[i];
delete globalParams;
return exitCode;
}

static inline void tcp_check_send_head(struct sock *sk, struct sk_buff *skb_unlinked)
{
if (sk->sk_send_head == skb_unlinked)
sk->sk_send_head = NULL;
}

static int
svm_range_trigger_migration(struct mm_struct *mm, struct svm_range *prange,
bool *migrated)
{
uint32_t best_loc;
int r = 0;
*migrated = false;
best_loc = svm_range_best_prefetch_location(prange);
if (best_loc == KFD_IOCTL_SVM_LOCATION_UNDEFINED ||
best_loc == prange->actual_loc)
return 0;
if (!best_loc) {
r = svm_migrate_vram_to_ram(prange, mm, KFD_MIGRATE_TRIGGER_PREFETCH);
*migrated = !r;
return r;
}
r = svm_migrate_to_vram(prange, best_loc, mm, KFD_MIGRATE_TRIGGER_PREFETCH);
*migrated = !r;
return r;
}

static struct pending_op *pending_ccc_new(struct bt_att *att,
struct gatt_db_attribute *attrib,
uint16_t value,
uint8_t link_type)
{
struct pending_op *op;
struct btd_device *device;
device = att_get_device(att);
if (!device) {
error("Unable to find device object");
return NULL;
}
op = new0(struct pending_op, 1);
op->data.iov_base = UINT_TO_PTR(value);
op->data.iov_len = sizeof(value);
op->device = device;
op->attrib = attrib;
op->link_type = link_type;
return op;
}

static void
extract_slice(struct state *states, const int numfiles, const char *write_file_name,
const struct timeval *start_time, struct timeval *stop_time,
const int keep_dups, const int relative_time_merge,
const struct timeval *base_time)
{
struct state *s, *min_state;
struct timeval temp1, temp2, relative_start, relative_stop;
int i;
struct state *last_state;
struct pcap_pkthdr last_hdr;
u_char* last_pkt;
if (numfiles == 0)
error("no input files specified");
last_state = 0;
last_hdr.ts.tv_sec = last_hdr.ts.tv_usec = 0;
last_hdr.caplen = last_hdr.len = 0;
last_pkt = (u_char*) malloc(snaplen);
if (! last_pkt)
error("out of memory");
memset(last_pkt, 0, snaplen);
timersub(start_time, base_time, &relative_start);
timersub(stop_time, base_time, &relative_stop);
for (i = 0; i < numfiles; ++i) {
s = &states[i];
if (relative_time_merge) {
timeradd(&s->file_start_time, &relative_start, &temp1);
} else {
temp1 = *start_time;
}
if (sf_timestamp_less_than(&s->file_stop_time, &temp1)) {
s->done = 1;
pcap_close(s->p);
continue;
}
if (sf_timestamp_less_than(&temp1, &s->file_start_time)){
temp1 = s->file_start_time;
}
sf_find_packet(s->p, &s->file_start_time, s->start_pos,
&s->file_stop_time, s->stop_pos,
&temp1);
get_next_packet(s);
}
global_dumper = pcap_dump_open(states->p, write_file_name);
if (!global_dumper) {
error( "error creating output file %s: %s",
write_file_name, pcap_geterr( states->p ) );
}
while (1) {
struct timeval tvbuf;
min_state = 0;
for (i = 0; i < numfiles; ++i) {
s = &states[i];
if (! s->done) {
if (! min_state)
min_state = s;
if (relative_time_merge) {
timersub(&s->hdr.ts,
&s->file_start_time, &temp1);
timersub(&min_state->hdr.ts,
&min_state->file_start_time, &temp2);
} else {
TIMEVAL_FROM_PKTHDR_TS(temp1, s->hdr.ts);
TIMEVAL_FROM_PKTHDR_TS(temp2, min_state->hdr.ts);
}
if (sf_timestamp_less_than( &temp1, &temp2))
min_state = s;
}
}
if (! min_state)
break;
if (relative_time_merge) {
timeradd(&min_state->file_start_time, &relative_stop, &temp1);
} else
temp1 = *stop_time;
TIMEVAL_FROM_PKTHDR_TS(tvbuf, min_state->hdr.ts);
if (sf_timestamp_less_than(&temp1, &tvbuf)) {
if (!sessions_count) {
if (track_sessions)
sessions_exit();
min_state->done = 1;
pcap_close(min_state->p);
break;
} else {
bonus_time = 1;
*stop_time = min_state->file_stop_time;
}
}
if (relative_time_merge) {
timersub(&min_state->hdr.ts, &min_state->file_start_time, &temp1);
timeradd(&temp1, base_time, &min_state->hdr.ts);
}
#ifdef HAVE_LIBNIDS
if (track_sessions && min_state->hdr.caplen) {
u_char *pkt_copy = malloc(min_state->hdr.caplen);
if (!pkt_copy)
error("malloc() failed in %s()", __func__);
memcpy(pkt_copy, min_state->pkt, min_state->hdr.caplen);
nids_pcap_handler((u_char *)min_state->p, &min_state->hdr, pkt_copy);
free(pkt_copy);
}
#endif
if (!bonus_time)
if ( keep_dups ||
min_state == last_state ||
memcmp(&last_hdr, &min_state->hdr, sizeof(last_hdr)) ||
memcmp(last_pkt, min_state->pkt, last_hdr.caplen) ) {
pcap_dump((u_char *) global_dumper, &min_state->hdr, min_state->pkt);
if ( ! keep_dups ) {
last_state = min_state;
last_hdr = min_state->hdr;
memcpy(last_pkt, min_state->pkt, min_state->hdr.caplen);
}
}
get_next_packet(min_state);
}
free(last_pkt);
}

static void
tlstran_pipe_recv_cb(void *arg)
{
nni_aio *     aio;
nni_iov       iov[2];
uint8_t       type;
uint8_t       rv;
uint32_t      pos = 1;
uint64_t      len = 0;
size_t        n;
nni_msg      *msg, *qmsg;
tlstran_pipe *p     = arg;
nni_aio *     rxaio = p->rxaio;
conn_param *  cparam;
bool          ack   = false;
log_trace("tlstran_pipe_recv_cb %p\n", p);
nni_mtx_lock(&p->mtx);
aio = nni_list_first(&p->recvq);
if ((rv = nni_aio_result(rxaio)) != 0) {
log_warn(" recv aio error %s", nng_strerror(rv));
rv = NMQ_SERVER_BUSY;
goto recv_error;
}
n = nni_aio_count(rxaio);
p->gotrxhead += n;
nni_aio_iov_advance(rxaio, n);
len = get_var_integer(p->rxlen, &pos);
log_trace("new %ld recevied %ld header %x %d pos: %d len : %d", n,
p->gotrxhead, p->rxlen[0], p->rxlen[1], pos, len);
log_trace("still need byte count:%ld > 0\n", nni_aio_iov_count(rxaio));
if (nni_aio_iov_count(rxaio) > 0) {
log_trace("got: %x %x, %ld!!\n", p->rxlen[0], p->rxlen[1],
strlen((char *) p->rxlen));
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
} else if (p->gotrxhead <= NNI_NANO_MAX_HEADER_SIZE &&
p->rxlen[p->gotrxhead - 1] > 0x7f) {
if (p->gotrxhead == NNI_NANO_MAX_HEADER_SIZE) {
rv = NNG_EMSGSIZE;
goto recv_error;
}
iov[0].iov_buf = &p->rxlen[p->gotrxhead];
iov[0].iov_len = 1;
nni_aio_set_iov(rxaio, 1, iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
} else if (len == 0 && n == 2) {
if ((p->rxlen[0] & 0XFF) == CMD_PINGREQ) {
nng_aio_wait(p->rpaio);
p->txlen[0] = CMD_PINGRESP;
p->txlen[1] = 0x00;
iov[0].iov_len = 2;
iov[0].iov_buf = &p->txlen;
nni_aio_set_iov(p->rpaio, 1, iov);
nng_stream_send(p->conn, p->rpaio);
goto notify;
}
}
p->wantrxhead = len + p->gotrxhead;
cparam        = p->tcp_cparam;
if (p->rxmsg == NULL) {
log_trace("pipe %p header got: %x %x %x %x %x, %ld!!\n", p,
p->rxlen[0], p->rxlen[1], p->rxlen[2], p->rxlen[3],
p->rxlen[4], p->wantrxhead);
if (len > p->conf->max_packet_size) {
log_error("size error 0x95\n");
rv = NMQ_PACKET_TOO_LARGE;
goto recv_error;
}
if ((rv = nni_msg_alloc(&p->rxmsg, (size_t) len)) != 0) {
log_error("mem error %ld\n", (size_t) len);
rv = NMQ_SERVER_UNAVAILABLE;
goto recv_error;
}
if (len != 0) {
iov[0].iov_buf = nni_msg_body(p->rxmsg);
iov[0].iov_len = (size_t) len;
nni_aio_set_iov(rxaio, 1, iov);
nng_stream_recv(p->conn, rxaio);
nni_mtx_unlock(&p->mtx);
return;
}
}
nni_aio_list_remove(aio);
msg      = p->rxmsg;
p->rxmsg = NULL;
n        = nni_msg_len(msg);
type     = p->rxlen[0] & 0xf0;
fixed_header_adaptor(p->rxlen, msg);
nni_msg_set_conn_param(msg, cparam);
nni_msg_set_remaining_len(msg, len);
nni_msg_set_cmd_type(msg, type);
log_trace("remain_len %d cparam %p clientid %s username %s proto %d\n",
len, cparam, cparam->clientid.body, cparam->username.body,
cparam->pro_ver);
log_trace("The type of msg is %x", type);
uint16_t  packet_id   = 0;
uint8_t   reason_code = 0;
property *prop        = NULL;
uint8_t   ack_cmd     = 0;
if (type == CMD_PUBLISH) {
nni_msg_set_timestamp(msg, nng_clock());
uint8_t qos_pac = nni_msg_get_pub_qos(msg);
if (qos_pac > 0) {
if (p->tcp_cparam->pro_ver == 5) {
if (p->qrecv_quota > 0) {
p->qrecv_quota--;
} else {
rv = NMQ_RECEIVE_MAXIMUM_EXCEEDED;
goto recv_error;
}
}
if (qos_pac == 1) {
ack_cmd = CMD_PUBACK;
} else if (qos_pac == 2) {
ack_cmd = CMD_PUBREC;
}
packet_id = nni_msg_get_pub_pid(msg);
ack       = true;
}
} else if (type == CMD_PUBREC) {
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code, &prop,
cparam->pro_ver) != 0) {
log_error("decode PUBREC variable header failed!");
}
ack_cmd = CMD_PUBREL;
ack     = true;
} else if (type == CMD_PUBREL) {
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code, &prop,
cparam->pro_ver) != 0) {
log_error("decode PUBREL variable header failed!");
}
ack_cmd = CMD_PUBCOMP;
ack     = true;
} else if (type == CMD_PUBACK || type == CMD_PUBCOMP) {
if (nni_mqtt_pubres_decode(msg, &packet_id, &reason_code, &prop,
cparam->pro_ver) != 0) {
log_error("decode PUBACK or PUBCOMP variable header "
"failed!");
}
if (p->tcp_cparam->pro_ver == 5) {
property_free(prop);
p->qsend_quota++;
}
}
if (ack == true) {
if ((rv = nni_msg_alloc(&qmsg, 0)) != 0) {
ack = false;
rv  = NMQ_SERVER_BUSY;
goto recv_error;
}
nni_msg_set_cmd_type(qmsg, ack_cmd);
nni_mqtt_msgack_encode(
qmsg, packet_id, reason_code, prop, cparam->pro_ver);
nni_mqtt_pubres_header_encode(qmsg, ack_cmd);
if (p->busy == false) {
if (nni_aio_begin(aio) != 0) {
log_error("ACK aio error!!");
}
nni_msg_insert(qmsg, nni_msg_header(qmsg),
nni_msg_header_len(qmsg));
iov[0].iov_len = nni_msg_len(qmsg);
iov[0].iov_buf = nni_msg_body(qmsg);
p->busy        = true;
nni_aio_set_msg(p->qsaio, qmsg);
nni_aio_set_iov(p->qsaio, 1, iov);
nng_stream_send(p->conn, p->qsaio);
log_trace("QoS ACK msg sent!");
} else {
if (nni_lmq_full(&p->rslmq)) {
if (nni_lmq_cap(&p->rslmq) <=
NANO_MAX_QOS_PACKET) {
if ((rv = nni_lmq_resize(&p->rslmq,
nni_lmq_cap(&p->rslmq) *
2)) == 0) {
nni_lmq_put(&p->rslmq, qmsg);
} else {
nni_msg_free(qmsg);
}
} else {
nni_msg *old;
(void) nni_lmq_get(&p->rslmq, &old);
nni_msg_free(old);
nni_lmq_put(&p->rslmq, qmsg);
}
} else {
nni_lmq_put(&p->rslmq, qmsg);
}
}
ack = false;
}
if (!nni_list_empty(&p->recvq)) {
tlstran_pipe_recv_start(p);
}
nni_pipe_bump_rx(p->npipe, n);
nni_mtx_unlock(&p->mtx);
nni_aio_set_msg(aio, msg);
nni_aio_finish_sync(aio, 0, n);
log_trace("end of tlstran_pipe_recv_cb: synch! %p\n", p);
return;
recv_error:
nni_aio_list_remove(aio);
msg      = p->rxmsg;
p->rxmsg = NULL;
nni_pipe_bump_error(p->npipe, rv);
nni_mtx_unlock(&p->mtx);
nni_msg_free(msg);
nni_aio_finish_error(aio, rv);
log_trace("tlstran_pipe_recv_cb: recv error rv: %d\n", rv);
return;
notify:
nni_aio_list_remove(aio);
nni_mtx_unlock(&p->mtx);
nni_aio_set_msg(aio, NULL);
nni_aio_finish(aio, 0, 0);
return;
}

int pdf_load_xrefs(FILE *fp, pdf_t *pdf)
{
int  i, ver, is_linear;
long pos, pos_count;
char x, *c, buf[256];
c = NULL;
pdf->n_xrefs = 0;
fseek(fp, 0, SEEK_SET);
while (get_next_eof(fp) >= 0)
++pdf->n_xrefs;
if (!pdf->n_xrefs)
return 0;
fseek(fp, 0, SEEK_SET);
pdf->xrefs = calloc(1, sizeof(xref_t) * pdf->n_xrefs);
ver = 1;
for (i=0; i<pdf->n_xrefs; i++)
{
if ((pos = get_next_eof(fp)) < 0)
break;
pdf->xrefs[i].version = ver++;
pos_count = 0;
while (SAFE_F(fp, ((x = fgetc(fp)) != 'f')))
fseek(fp, pos - (++pos_count), SEEK_SET);
if (pos_count >= sizeof(buf)) {
ERR("Failed to locate the startxref token. "
"This might be a corrupt PDF.\n");
return -1;
}
memset(buf, 0, sizeof(buf));
SAFE_E(fread(buf, 1, pos_count, fp), pos_count,
"Failed to read startxref.\n");
c = buf;
while (*c == ' ' || *c == '\n' || *c == '\r')
++c;
pdf->xrefs[i].start = atol(c);
if (pdf->xrefs[i].start == 0)
get_xref_linear_skipped(fp, &pdf->xrefs[i]);
else
{
pos = ftell(fp);
fseek(fp, pdf->xrefs[i].start, SEEK_SET);
pdf->xrefs[i].end = get_next_eof(fp);
fseek(fp, pos, SEEK_SET);
}
if (!is_valid_xref(fp, pdf, &pdf->xrefs[i]))
{
is_linear = pdf->xrefs[i].is_linear;
memset(&pdf->xrefs[i], 0, sizeof(xref_t));
pdf->xrefs[i].is_linear = is_linear;
rewind(fp);
get_next_eof(fp);
continue;
}
load_xref_entries(fp, &pdf->xrefs[i]);
}
if (pdf->xrefs[0].is_linear)
resolve_linearized_pdf(pdf);
load_creator(fp, pdf);
return pdf->n_xrefs;
}

static void
lexer_process_char_literal (parser_context_t *context_p, 
const uint8_t *char_p, 
size_t length, 
uint8_t literal_type, 
bool has_escape) 
{
parser_list_iterator_t literal_iterator;
lexer_literal_t *literal_p;
uint32_t literal_index = 0;
JERRY_ASSERT (literal_type == LEXER_IDENT_LITERAL
|| literal_type == LEXER_STRING_LITERAL);
JERRY_ASSERT (literal_type != LEXER_IDENT_LITERAL || length <= PARSER_MAXIMUM_IDENT_LENGTH);
JERRY_ASSERT (literal_type != LEXER_STRING_LITERAL || length <= PARSER_MAXIMUM_STRING_LENGTH);
parser_list_iterator_init (&context_p->literal_pool, &literal_iterator);
while ((literal_p = (lexer_literal_t *) parser_list_iterator_next (&literal_iterator)) != NULL)
{
if (literal_p->type == literal_type
&& literal_p->prop.length == length
&& memcmp (literal_p->u.char_p, char_p, length) == 0)
{
context_p->lit_object.literal_p = literal_p;
context_p->lit_object.index = (uint16_t) literal_index;
literal_p->status_flags = (uint8_t) (literal_p->status_flags & ~LEXER_FLAG_UNUSED_IDENT);
return;
}
literal_index++;
}
JERRY_ASSERT (literal_index == context_p->literal_count);
if (literal_index >= PARSER_MAXIMUM_NUMBER_OF_LITERALS)
{
parser_raise_error (context_p, PARSER_ERR_LITERAL_LIMIT_REACHED);
}
literal_p = (lexer_literal_t *) parser_list_append (context_p, &context_p->literal_pool);
literal_p->prop.length = (uint16_t) length;
literal_p->type = literal_type;
literal_p->status_flags = has_escape ? 0 : LEXER_FLAG_SOURCE_PTR;
if (has_escape)
{
literal_p->u.char_p = (uint8_t *) jmem_heap_alloc_block (length);
memcpy ((uint8_t *) literal_p->u.char_p, char_p, length);
}
else
{
literal_p->u.char_p = char_p;
}
context_p->lit_object.literal_p = literal_p;
context_p->lit_object.index = (uint16_t) literal_index;
context_p->literal_count++;
}

static void *sgpd_parse_entry(u32 grouping_type, GF_BitStream *bs, u32 entry_size, u32 *total_bytes)
{
Bool null_size_ok = GF_FALSE;
GF_DefaultSampleGroupDescriptionEntry *ptr;
switch (grouping_type) {
case GF_ISOM_SAMPLE_GROUP_ROLL:
case GF_ISOM_SAMPLE_GROUP_PROL:
{
GF_RollRecoveryEntry *ptr;
GF_SAFEALLOC(ptr, GF_RollRecoveryEntry);
if (!ptr) return NULL;
ptr->roll_distance = gf_bs_read_int(bs, 16);
*total_bytes = 2;
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_RAP:
{
GF_VisualRandomAccessEntry *ptr;
GF_SAFEALLOC(ptr, GF_VisualRandomAccessEntry);
if (!ptr) return NULL;
ptr->num_leading_samples_known = gf_bs_read_int(bs, 1);
ptr->num_leading_samples = gf_bs_read_int(bs, 7);
*total_bytes = 1;
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_SAP:
{
GF_SAPEntry *ptr;
GF_SAFEALLOC(ptr, GF_SAPEntry);
if (!ptr) return NULL;
ptr->dependent_flag = gf_bs_read_int(bs, 1);
gf_bs_read_int(bs, 3);
ptr->SAP_type = gf_bs_read_int(bs, 4);
*total_bytes = 1;
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_SYNC:
{
GF_SYNCEntry *ptr;
GF_SAFEALLOC(ptr, GF_SYNCEntry);
if (!ptr) return NULL;
gf_bs_read_int(bs, 2);
ptr->NALU_type = gf_bs_read_int(bs, 6);
*total_bytes = 1;
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_TELE:
{
GF_TemporalLevelEntry *ptr;
GF_SAFEALLOC(ptr, GF_TemporalLevelEntry);
if (!ptr) return NULL;
ptr->level_independently_decodable = gf_bs_read_int(bs, 1);
gf_bs_read_int(bs, 7);
*total_bytes = 1;
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_SEIG:
{
GF_CENCSampleEncryptionGroupEntry *ptr;
GF_SAFEALLOC(ptr, GF_CENCSampleEncryptionGroupEntry);
if (!ptr) return NULL;
gf_bs_read_u8(bs); ptr->crypt_byte_block = gf_bs_read_int(bs, 4);
ptr->skip_byte_block = gf_bs_read_int(bs, 4);
ptr->IsProtected = gf_bs_read_u8(bs);
ptr->Per_Sample_IV_size = gf_bs_read_u8(bs);
gf_bs_read_data(bs, (char *)ptr->KID, 16);
*total_bytes = 20;
if ((ptr->IsProtected == 1) && !ptr->Per_Sample_IV_size) {
ptr->constant_IV_size = gf_bs_read_u8(bs);
assert((ptr->constant_IV_size == 8) || (ptr->constant_IV_size == 16));
gf_bs_read_data(bs, (char *)ptr->constant_IV, ptr->constant_IV_size);
*total_bytes += 1 + ptr->constant_IV_size;
}
if (!entry_size) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] seig sample group does not indicate entry size, deprecated in spec\n"));
}
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_OINF:
{
GF_OperatingPointsInformation *ptr = gf_isom_oinf_new_entry();
u32 s = (u32) gf_bs_get_position(bs);
gf_isom_oinf_read_entry(ptr, bs);
*total_bytes = (u32) gf_bs_get_position(bs) - s;
if (!entry_size) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] oinf sample group does not indicate entry size, deprecated in spec\n"));
}
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_LINF:
{
GF_LHVCLayerInformation *ptr = gf_isom_linf_new_entry();
u32 s = (u32) gf_bs_get_position(bs);
gf_isom_linf_read_entry(ptr, bs);
*total_bytes = (u32) gf_bs_get_position(bs) - s;
if (!entry_size) {
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] linf sample group does not indicate entry size, deprecated in spec\n"));
}
return ptr;
}
case GF_ISOM_SAMPLE_GROUP_TRIF:
if (! entry_size) {
u32 flags = gf_bs_peek_bits(bs, 24, 0);
if (flags & 0x10000) entry_size=3;
else {
if (flags & 0x80000) entry_size=7;
else entry_size=11;
if (flags & 0x200000) {
u32 nb_entries = gf_bs_peek_bits(bs, 16, entry_size);
entry_size += 2 + 2*nb_entries;
}
}
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] trif sample group does not indicate entry size, deprecated in spec\n"));
}
break;
case GF_ISOM_SAMPLE_GROUP_NALM:
if (! entry_size) {
u64 start = gf_bs_get_position(bs);
Bool rle, large_size;
u32 entry_count;
gf_bs_read_int(bs, 6);
large_size = gf_bs_read_int(bs, 1);
rle = gf_bs_read_int(bs, 1);
entry_count = gf_bs_read_int(bs, large_size ? 16 : 8);
gf_bs_seek(bs, start);
entry_size = 1 + large_size ? 2 : 1;
entry_size += entry_count * 2;
