double asn1_get_real(const guint8 *real_ptr, gint len) {
guint8 octet;
const guint8 *p;
guint8 *buf;
double val = 0;
if (len < 1) return val;
octet = real_ptr[0];
p = real_ptr + 1;
len -= 1;
if (octet & 0x80) {  
int i;
gboolean Eneg;
gint8 S; 
guint8 B; 
guint8 F; 
gint32 E = 0; 
guint64 N = 0; 
guint8 lenE, lenN;
if(octet & 0x40) S = -1; else S = 1;
switch(octet & 0x30) {
case 0x00: B = 2; break;
case 0x10: B = 8; break;
case 0x20: B = 16; break;
case 0x30: 
default:
return 0;
}
F = (octet & 0x0c) >> 2;
lenE = (octet & 0x3) + 1;
if(lenE == 4)
{
DISSECTOR_ASSERT_NOT_REACHED();
}
Eneg = (*p) & 0x80 ? TRUE : FALSE;
for (i = 0; i < lenE; i++) {
if(Eneg) {
E = (E<<8) | ((guint8) ~(*p));
} else {
E = (E<<8) | *p;
}
p++;
}
if(Eneg) {
E = -(E + 1);
}
lenN = len - lenE;
if(lenN > 8)
{
DISSECTOR_ASSERT_NOT_REACHED();
}
for (i=0; i<lenN; i++) {
N = (N<<8) | *p;
p++;
}
val = (double) S * N * pow(2, F) * pow(B, E);
#ifdef DEBUG
ws_debug_printf("S = %d, N = %lu, F = %u, B = %u, E = %d -> %f\n", S, N, F, B, E, val);
#endif
} else if (octet & 0x40) {  
switch (octet & 0x3F) {
case 0x00: val = HUGE_VAL; break;
case 0x01: val = -HUGE_VAL; break;
}
} else {  
buf = g_strndup(p, len);
val = g_ascii_strtod(buf, NULL);
g_free(buf);
}
return val;
}

