int rtp_packetize_xiph_config( sout_stream_id_sys_t *id, const char *fmtp,
int64_t i_pts )
{
if (fmtp == NULL)
return VLC_EGENERIC;
char *start = strstr(fmtp, "configuration=");
assert(start != NULL);
start += sizeof("configuration=") - 1;
char *end = strchr(start, ';');
assert(end != NULL);
size_t len = end - start;
char b64[len + 1];
memcpy(b64, start, len);
b64[len] = '\0';
int     i_max   = rtp_mtu (id) - 6; 
uint8_t *p_orig, *p_data;
int i_data;
i_data = vlc_b64_decode_binary(&p_orig, b64);
if (i_data <= 9)
{
free(p_orig);
return VLC_EGENERIC;
}
p_data = p_orig + 9;
i_data -= 9;
int i_count = ( i_data + i_max - 1 ) / i_max;
for( int i = 0; i < i_count; i++ )
{
int           i_payload = __MIN( i_max, i_data );
block_t *out = block_Alloc( 18 + i_payload );
unsigned fragtype, numpkts;
if (i_count == 1)
{
fragtype = 0;
numpkts = 1;
}
else
{
numpkts = 0;
if (i == 0)
fragtype = 1;
else if (i == i_count - 1)
fragtype = 3;
else
fragtype = 2;
}
uint32_t header = ((XIPH_IDENT & 0xffffff) << 8) |
(fragtype << 6) | (1 << 4) | numpkts;
rtp_packetize_common( id, out, 0, i_pts );
SetDWBE( out->p_buffer + 12, header);
SetWBE( out->p_buffer + 16, i_payload);
memcpy( &out->p_buffer[18], p_data, i_payload );
out->i_dts    = i_pts;
rtp_packetize_send( id, out );
p_data += i_payload;
i_data -= i_payload;
}
free(p_orig);
return VLC_SUCCESS;
}

int TNEFFillMapi(TNEFStruct *TNEF, BYTE *data, DWORD size, MAPIProps *p) {
int i, j;
DWORD num;
BYTE *d;
MAPIProperty *mp;
DWORD type;
DWORD length;
variableLength *vl;
WORD temp_word;
DWORD temp_dword;
DDWORD temp_ddword;
int count = -1;
int offset;
d = data;
p->count = SwapDWord((BYTE*)data, 4);
d += 4;
p->properties = calloc(p->count, sizeof(MAPIProperty));
ALLOCCHECK(p->properties);
mp = p->properties;
for (i = 0; i < p->count; i++) {
if (count == -1) {
mp->id = SwapDWord((BYTE*)d, 4);
d += 4;
mp->custom = 0;
mp->count = 1;
mp->namedproperty = 0;
length = -1;
if (PROP_ID(mp->id) >= 0x8000) {
SIZECHECK(16);
memcpy(&(mp->guid[0]), d, 16);
d += 16;
SIZECHECK(4);
length = SwapDWord((BYTE*)d, 4);
d += sizeof(DWORD);
if (length > 0) {
mp->namedproperty = length;
mp->propnames = calloc(length, sizeof(variableLength));
ALLOCCHECK(mp->propnames);
while (length > 0) {
SIZECHECK(4);
type = SwapDWord((BYTE*)d, 4);
mp->propnames[length - 1].data = calloc(type, sizeof(BYTE));
ALLOCCHECK(mp->propnames[length - 1].data);
mp->propnames[length - 1].size = type;
d += 4;
SIZECHECK(type);
for (j = 0; j < (type >> 1); j++) {
mp->propnames[length - 1].data[j] = d[j * 2];
}
d += type + ((type % 4) ? (4 - type % 4) : 0);
length--;
}
} else {
SIZECHECK(sizeof(DWORD));
type = SwapDWord((BYTE*)d, sizeof(DWORD));
d += sizeof(DWORD);
mp->id = PROP_TAG(PROP_TYPE(mp->id), type);
}
mp->custom = 1;
}
DEBUG2(TNEF->Debug, 3, "Type id = %04x, Prop id = %04x", PROP_TYPE(mp->id),
PROP_ID(mp->id));
if (PROP_TYPE(mp->id) & MV_FLAG) {
mp->id = PROP_TAG(PROP_TYPE(mp->id) - MV_FLAG, PROP_ID(mp->id));
SIZECHECK(4);
mp->count = SwapDWord((BYTE*)d, 4);
d += 4;
count = 0;
}
mp->data = calloc(mp->count, sizeof(variableLength));
ALLOCCHECK(mp->data);
vl = mp->data;
} else {
i--;
count++;
vl = &(mp->data[count]);
}
switch (PROP_TYPE(mp->id)) {
case PT_BINARY:
case PT_OBJECT:
case PT_STRING8:
case PT_UNICODE:
if (count == -1) {
SIZECHECK(4);
vl->size = SwapDWord((BYTE*)d, 4);
d += 4;
}
SIZECHECK(4);
vl->size = SwapDWord((BYTE*)d, 4);
d += 4;
if (vl->size != 0) {    
SIZECHECK(vl->size);
if (PROP_TYPE(mp->id) == PT_UNICODE) {
vl->data =(BYTE*) to_utf8(vl->size, (char*)d);
} else {
vl->data = calloc(vl->size, sizeof(BYTE));
ALLOCCHECK(vl->data);
memcpy(vl->data, d, vl->size);
}
} else {
vl->data = NULL;
}
num = vl->size;
offset = ((num % 4) ? (4 - num % 4) : 0);
