static Fixed lsr_translate_coords(GF_LASeRCodec *lsr, u32 val, u32 nb_bits)
{
if (!nb_bits) return 0;
#ifdef GPAC_FIXED_POINT
if (val >> (nb_bits-1) ) {
s32 neg = (s32) val - (1<<nb_bits);
if (neg < -FIX_ONE / 2)
return 2 * gf_divfix(INT2FIX(neg/2), lsr->res_factor);
return gf_divfix(INT2FIX(neg), lsr->res_factor);
} else {
if (val > FIX_ONE / 2)
return 2 * gf_divfix(INT2FIX(val/2), lsr->res_factor);
return gf_divfix(INT2FIX(val), lsr->res_factor);
}
#else
if (val >> (nb_bits-1) ) {
s32 neg = (s32) val - (1<<nb_bits);
return gf_divfix(INT2FIX(neg), lsr->res_factor);
} else {
return gf_divfix(INT2FIX(val), lsr->res_factor);
}
#endif
}

static Image *ReadTGAImage(const ImageInfo *image_info,
ExceptionInfo *exception)
{
Image
*image;
MagickBooleanType
status;
PixelInfo
pixel;
Quantum
index;
register Quantum
*q;
register ssize_t
i,
x;
size_t
base,
flag,
offset,
real,
skip;
ssize_t
count,
y;
TGAInfo
tga_info;
unsigned char
j,
k,
pixels[4],
runlength;
unsigned int
alpha_bits;
assert(image_info != (const ImageInfo *) NULL);
assert(image_info->signature == MagickCoreSignature);
if (image_info->debug != MagickFalse)
(void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
image_info->filename);
assert(exception != (ExceptionInfo *) NULL);
assert(exception->signature == MagickCoreSignature);
image=AcquireImage(image_info,exception);
status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
if (status == MagickFalse)
{
image=DestroyImageList(image);
return((Image *) NULL);
}
count=ReadBlob(image,1,&tga_info.id_length);
tga_info.colormap_type=(unsigned char) ReadBlobByte(image);
tga_info.image_type=(TGAImageType) ReadBlobByte(image);
if ((count != 1) ||
((tga_info.image_type != TGAColormap) &&
(tga_info.image_type != TGARGB) &&
(tga_info.image_type != TGAMonochrome) &&
(tga_info.image_type != TGARLEColormap) &&
(tga_info.image_type != TGARLERGB) &&
(tga_info.image_type != TGARLEMonochrome)) ||
(((tga_info.image_type == TGAColormap) ||
(tga_info.image_type == TGARLEColormap)) &&
(tga_info.colormap_type == 0)))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
tga_info.colormap_index=ReadBlobLSBShort(image);
tga_info.colormap_length=ReadBlobLSBShort(image);
tga_info.colormap_size=(unsigned char) ReadBlobByte(image);
tga_info.x_origin=ReadBlobLSBShort(image);
tga_info.y_origin=ReadBlobLSBShort(image);
tga_info.width=(unsigned short) ReadBlobLSBShort(image);
tga_info.height=(unsigned short) ReadBlobLSBShort(image);
tga_info.bits_per_pixel=(unsigned char) ReadBlobByte(image);
tga_info.attributes=(unsigned char) ReadBlobByte(image);
if (EOFBlob(image) != MagickFalse)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
if ((((tga_info.bits_per_pixel <= 1) || (tga_info.bits_per_pixel >= 17)) &&
(tga_info.bits_per_pixel != 24) && (tga_info.bits_per_pixel != 32)))
ThrowReaderException(CorruptImageError,"ImproperImageHeader");
image->columns=tga_info.width;
image->rows=tga_info.height;
alpha_bits=(tga_info.attributes & 0x0FU);
image->alpha_trait=(alpha_bits > 0) || (tga_info.bits_per_pixel == 32) ||
(tga_info.colormap_size == 32) ?  BlendPixelTrait : UndefinedPixelTrait;
if ((tga_info.image_type != TGAColormap) &&
(tga_info.image_type != TGARLEColormap))
image->depth=(size_t) ((tga_info.bits_per_pixel <= 8) ? 8 :
(tga_info.bits_per_pixel <= 16) ? 5 :
(tga_info.bits_per_pixel == 24) ? 8 :
(tga_info.bits_per_pixel == 32) ? 8 : 8);
else
image->depth=(size_t) ((tga_info.colormap_size <= 8) ? 8 :
(tga_info.colormap_size <= 16) ? 5 :
(tga_info.colormap_size == 24) ? 8 :
(tga_info.colormap_size == 32) ? 8 : 8);
if ((tga_info.image_type == TGAColormap) ||
(tga_info.image_type == TGAMonochrome) ||
(tga_info.image_type == TGARLEColormap) ||
(tga_info.image_type == TGARLEMonochrome))
image->storage_class=PseudoClass;
image->compression=NoCompression;
if ((tga_info.image_type == TGARLEColormap) ||
(tga_info.image_type == TGARLEMonochrome) ||
(tga_info.image_type == TGARLERGB))
image->compression=RLECompression;
if (image->storage_class == PseudoClass)
{
if (tga_info.colormap_type != 0)
image->colors=tga_info.colormap_index+tga_info.colormap_length;
else
{
size_t
one;
one=1;
image->colors=one << tga_info.bits_per_pixel;
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
}
}
if (tga_info.id_length != 0)
{
char
*comment;
size_t
length;
length=(size_t) tga_info.id_length;
comment=(char *) NULL;
if (~length >= (MagickPathExtent-1))
comment=(char *) AcquireQuantumMemory(length+MagickPathExtent,
sizeof(*comment));
if (comment == (char *) NULL)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
count=ReadBlob(image,tga_info.id_length,(unsigned char *) comment);
comment[tga_info.id_length]='\0';
(void) SetImageProperty(image,"comment",comment,exception);
comment=DestroyString(comment);
}
if (image_info->ping != MagickFalse)
{
(void) CloseBlob(image);
return(image);
}
status=SetImageExtent(image,image->columns,image->rows,exception);
if (status == MagickFalse)
return(DestroyImageList(image));
(void) ResetMagickMemory(&pixel,0,sizeof(pixel));
pixel.alpha=(MagickRealType) OpaqueAlpha;
if (tga_info.colormap_type != 0)
{
if (AcquireImageColormap(image,image->colors,exception) == MagickFalse)
ThrowReaderException(ResourceLimitError,"MemoryAllocationFailed");
for (i=0; i < (ssize_t) tga_info.colormap_index; i++)
image->colormap[i]=pixel;
for ( ; i < (ssize_t) image->colors; i++)
{
switch (tga_info.colormap_size)
{
case 8:
default:
{
pixel.red=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.green=pixel.red;
pixel.blue=pixel.red;
break;
}
case 15:
case 16:
{
QuantumAny
range;
j=(unsigned char) ReadBlobByte(image);
k=(unsigned char) ReadBlobByte(image);
range=GetQuantumRange(5UL);
pixel.red=(MagickRealType) ScaleAnyToQuantum(1UL*(k & 0x7c) >> 2,
range);
pixel.green=(MagickRealType) ScaleAnyToQuantum((1UL*(k & 0x03)
<< 3)+(1UL*(j & 0xe0) >> 5),range);
pixel.blue=(MagickRealType) ScaleAnyToQuantum(1UL*(j & 0x1f),range);
break;
}
case 24:
{
pixel.blue=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.green=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.red=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
break;
}
case 32:
{
pixel.blue=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.green=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.red=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
pixel.alpha=(MagickRealType) ScaleCharToQuantum((unsigned char)
ReadBlobByte(image));
break;
}
}
image->colormap[i]=pixel;
}
}
base=0;
flag=0;
skip=MagickFalse;
real=0;
index=0;
runlength=0;
offset=0;
for (y=0; y < (ssize_t) image->rows; y++)
{
real=offset;
if (((unsigned char) (tga_info.attributes & 0x20) >> 5) == 0)
real=image->rows-real-1;
q=QueueAuthenticPixels(image,0,(ssize_t) real,image->columns,1,exception);
if (q == (Quantum *) NULL)
break;
for (x=0; x < (ssize_t) image->columns; x++)
{
if ((tga_info.image_type == TGARLEColormap) ||
(tga_info.image_type == TGARLERGB) ||
(tga_info.image_type == TGARLEMonochrome))
{
if (runlength != 0)
{
runlength--;
skip=flag != 0;
}
else
{
count=ReadBlob(image,1,&runlength);
if (count != 1)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
flag=runlength & 0x80;
if (flag != 0)
runlength-=128;
skip=MagickFalse;
}
}
if (skip == MagickFalse)
switch (tga_info.bits_per_pixel)
{
case 8:
default:
{
index=(Quantum) ReadBlobByte(image);
if (tga_info.colormap_type != 0)
pixel=image->colormap[(ssize_t) ConstrainColormapIndex(image,
(ssize_t) index,exception)];
else
{
pixel.red=(MagickRealType) ScaleCharToQuantum((unsigned char)
index);
pixel.green=(MagickRealType) ScaleCharToQuantum((unsigned char)
index);
pixel.blue=(MagickRealType) ScaleCharToQuantum((unsigned char)
index);
}
break;
}
case 15:
case 16:
{
QuantumAny
range;
if (ReadBlob(image,2,pixels) != 2)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
j=pixels[0];
k=pixels[1];
range=GetQuantumRange(5UL);
pixel.red=(MagickRealType) ScaleAnyToQuantum(1UL*(k & 0x7c) >> 2,
range);
pixel.green=(MagickRealType) ScaleAnyToQuantum((1UL*
(k & 0x03) << 3)+(1UL*(j & 0xe0) >> 5),range);
pixel.blue=(MagickRealType) ScaleAnyToQuantum(1UL*(j & 0x1f),range);
if (image->alpha_trait != UndefinedPixelTrait)
pixel.alpha=(MagickRealType) ((k & 0x80) == 0 ? (Quantum)
TransparentAlpha : (Quantum) OpaqueAlpha);
if (image->storage_class == PseudoClass)
index=(Quantum) ConstrainColormapIndex(image,((ssize_t) (k << 8))+
j,exception);
break;
}
case 24:
{
if (ReadBlob(image,3,pixels) != 3)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
pixel.blue=(MagickRealType) ScaleCharToQuantum(pixels[0]);
pixel.green=(MagickRealType) ScaleCharToQuantum(pixels[1]);
pixel.red=(MagickRealType) ScaleCharToQuantum(pixels[2]);
break;
}
case 32:
{
if (ReadBlob(image,4,pixels) != 4)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
pixel.blue=(MagickRealType) ScaleCharToQuantum(pixels[0]);
pixel.green=(MagickRealType) ScaleCharToQuantum(pixels[1]);
pixel.red=(MagickRealType) ScaleCharToQuantum(pixels[2]);
pixel.alpha=(MagickRealType) ScaleCharToQuantum(pixels[3]);
break;
}
}
if (status == MagickFalse)
ThrowReaderException(CorruptImageError,"UnableToReadImageData");
if (image->storage_class == PseudoClass)
SetPixelIndex(image,index,q);
SetPixelRed(image,ClampToQuantum(pixel.red),q);
SetPixelGreen(image,ClampToQuantum(pixel.green),q);
SetPixelBlue(image,ClampToQuantum(pixel.blue),q);
if (image->alpha_trait != UndefinedPixelTrait)
SetPixelAlpha(image,ClampToQuantum(pixel.alpha),q);
q+=GetPixelChannels(image);
}
if (((unsigned char) (tga_info.attributes & 0xc0) >> 6) == 2)
offset+=2;
else
offset++;
if (offset >= image->rows)
{
base++;
offset=base;
}
if (SyncAuthenticPixels(image,exception) == MagickFalse)
break;
if (image->previous == (Image *) NULL)
{
status=SetImageProgress(image,LoadImageTag,(MagickOffsetType) y,
image->rows);
if (status == MagickFalse)
break;
}
}
if (EOFBlob(image) != MagickFalse)
ThrowFileException(exception,CorruptImageError,"UnexpectedEndOfFile",
image->filename);
(void) CloseBlob(image);
return(GetFirstImageInList(image));
}

static void
thunar_transfer_job_copy_node (ThunarTransferJob  *job,
ThunarTransferNode *node,
GFile              *target_file,
GFile              *target_parent_file,
GList             **target_file_list_return,
GError            **error)
{
ThunarThumbnailCache *thumbnail_cache;
ThunarApplication    *application;
ThunarJobResponse     response;
GFileInfo            *info;
GError               *err = NULL;
GFile                *real_target_file = NULL;
gchar                *base_name;
_thunar_return_if_fail (THUNAR_IS_TRANSFER_JOB (job));
_thunar_return_if_fail (node != NULL && G_IS_FILE (node->source_file));
_thunar_return_if_fail (target_file == NULL || node->next == NULL);
_thunar_return_if_fail ((target_file == NULL && target_parent_file != NULL) || (target_file != NULL && target_parent_file == NULL));
_thunar_return_if_fail (error == NULL || *error == NULL);
application = thunar_application_get ();
thumbnail_cache = thunar_application_get_thumbnail_cache (application);
g_object_unref (application);
for (; err == NULL && node != NULL; node = node->next)
{
if (G_LIKELY (target_file == NULL))
{
base_name = g_file_get_basename (node->source_file);
target_file = g_file_get_child (target_parent_file, base_name);
g_free (base_name);
}
else
target_file = g_object_ref (target_file);
info = g_file_query_info (node->source_file,
G_FILE_ATTRIBUTE_STANDARD_DISPLAY_NAME,
G_FILE_QUERY_INFO_NOFOLLOW_SYMLINKS,
exo_job_get_cancellable (EXO_JOB (job)),
&err);
if (info == NULL)
{
g_object_unref (target_file);
break;
}
exo_job_info_message (EXO_JOB (job), g_file_info_get_display_name (info));
retry_copy:
real_target_file = thunar_transfer_job_copy_file (job, node->source_file, 
target_file, &err);
if (G_LIKELY (real_target_file != NULL))
{
if (G_LIKELY (node->source_file != real_target_file))
{
thunar_thumbnail_cache_copy_file (thumbnail_cache, 
node->source_file, 
real_target_file);
if (node->children != NULL)
{
thunar_transfer_job_copy_node (job, node->children, NULL, real_target_file, NULL, &err);
thunar_transfer_node_free (node->children);
node->children = NULL;
}
if (G_UNLIKELY (err != NULL))
{
g_object_unref (real_target_file);
g_object_unref (target_file);
break;
}
if (G_LIKELY (target_file_list_return != NULL))
{
*target_file_list_return = 
thunar_g_file_list_prepend (*target_file_list_return, 
real_target_file);
}
retry_remove:
if (job->type == THUNAR_TRANSFER_JOB_MOVE)
{
if (g_file_delete (node->source_file, 
exo_job_get_cancellable (EXO_JOB (job)), 
&err))
{
thunar_thumbnail_cache_delete_file (thumbnail_cache, 
node->source_file);
}
else
{
response = thunar_job_ask_skip (THUNAR_JOB (job), "%s", 
err->message);
g_clear_error (&err);
if (G_UNLIKELY (response == THUNAR_JOB_RESPONSE_RETRY))
goto retry_remove;
}
}
}
g_object_unref (real_target_file);
}
else if (err != NULL)
{ 
if (err->domain != G_IO_ERROR || err->code != G_IO_ERROR_NO_SPACE) 
{
response = thunar_job_ask_skip (THUNAR_JOB (job), "%s", err->message);
g_clear_error (&err);
if (G_UNLIKELY (response == THUNAR_JOB_RESPONSE_RETRY))
goto retry_copy;
}
}
g_object_unref (target_file);
target_file = NULL;
g_object_unref (info);
}
g_object_unref (thumbnail_cache);
if (G_UNLIKELY (err != NULL))
g_propagate_error (error, err);
}

int main(int argc, char * argv[])
{
int c;
bool ignore_driver_version_mismatch = false;
DBusError error;
DBusConnection* connection;
dbus_error_init(&error);
srandom(time(NULL));
while (1) {
static struct option long_options[] = {
{"help", no_argument, 0, 'h'},
{"version", no_argument, 0, 'v'},
{"ignore-mismatch", no_argument, 0, 'i'},
{"debug", no_argument, 0, 'd'},
{"interface", required_argument, 0, 'I'},
{"file", required_argument, 0, 'f'},
{0, 0, 0, 0}
};
int option_index = 0;
if ((optind < argc) && (find_cmd(argv[optind]) != NULL)) {
break;
}
c = getopt_long(argc, argv, "hvidI:f:", long_options,
&option_index);
if (c == -1)
break;
switch (c) {
case 'h':
print_version();
print_arg_list_help(option_list,
argv[0],
"[options] <sub-command> [args]");
print_commands();
gRet = ERRORCODE_HELP;
goto bail;
case 'v':
print_version();
gRet = 0;
goto bail;
case 'd':
gDebugMode++;
break;
case 'I':
snprintf(gInterfaceName, sizeof(gInterfaceName),
"%s", optarg);
break;
case 'i':
ignore_driver_version_mismatch = true;
break;
case 'f':
#if HAVE_LIBREADLINE
if (NULL == freopen(optarg, "r", stdin))
{
fprintf(stderr,
"%s: error: Unable to open file \"%s\".\n",
argv[0], optarg);
return ERRORCODE_BADARG;
}
#else
fprintf(stderr,
"%s: Cannot read from file \"%s\" : Missing readline library.\n",
argv[0], optarg);
return ERRORCODE_BADARG;
#endif
default:
break;
}
}
istty = isatty(fileno(stdin));
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: isatty(fileno(stdin)) = %d\n", istty);
}
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: Will use interface '%s'.\n", gInterfaceName);
}
#if HAVE_PWD_H
if (getuid() == 0 && strcmp(WPANTUND_SERVICE_USER, "root")) {
uid_t target_uid = 0;
gid_t target_gid = 0;
struct passwd *passwd = getpwnam(WPANTUND_SERVICE_USER);
if (passwd == NULL) {
fprintf(stderr, "getpwnam: Unable to lookup user \"%s\".", WPANTUND_SERVICE_USER);
gRet = ERRORCODE_ERRNO;
goto bail;
}
target_uid = passwd->pw_uid;
target_gid = passwd->pw_gid;
if (target_gid != 0) {
if (setgid(target_gid) != 0) {
perror("setgid");
gRet = ERRORCODE_ERRNO;
goto bail;
}
}
if (target_uid != 0) {
if (setuid(target_uid) != 0) {
perror("setuid");
gRet = ERRORCODE_ERRNO;
goto bail;
}
}
}
#endif 
if (getenv("WPANCTL_DBUS_NAME") && gDebugMode>=1)
fprintf(stderr, "DEBUG: Using dbus \"%s\"\n", getenv("WPANCTL_DBUS_NAME"));
setenv("WPANCTL_DBUS_NAME", WPAN_TUNNEL_DBUS_NAME, 0);
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: trying dbus_bus_get(DBUS_BUS_SYSTEM). . .\n");
}
connection = dbus_bus_get(DBUS_BUS_SYSTEM, &error);
require_string(connection != NULL, bail, error.message);
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: DBusConnection: %p\n", connection);
}
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: Registering DBusConnection. . .\n");
}
dbus_bus_register(connection, &error);
require_string(error.name == NULL, bail, error.message);
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: DBusConnection registered.\n");
}
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: Requesting DBus name \"%s\". . .\n",WPAN_TUNNEL_DBUS_NAME ".wpanctl");
}
dbus_bus_request_name(connection,
WPAN_TUNNEL_DBUS_NAME ".wpanctl",
0,
&error);
if (gDebugMode >= 1) {
if (error.name != NULL) {
fprintf(stderr, "DEBUG: Requesting DBus name \"%s\" failed (no biggie): %s\n",WPAN_TUNNEL_DBUS_NAME ".wpanctl", error.name);
} else {
fprintf(stderr, "DEBUG: Requesting DBus name \"%s\" succeded.\n",WPAN_TUNNEL_DBUS_NAME ".wpanctl");
}
}
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: Performing wpantund version check. . .\n");
}
gRet = wpan_dbus_version_check(connection);
if (gRet != 0) {
fprintf(stderr,
"%s: error: `wpantund` is either not running, locked up, or incompatible with this version of `wpanctl`.\n",
argv[0]
);
if (!ignore_driver_version_mismatch)
goto bail;
} else {
if (gDebugMode >= 1) {
fprintf(stderr,
"DEBUG: wpantund version check succeded.\n");
}
}
if (optind < argc) {
if (gDebugMode >= 1) {
fprintf(stderr, "DEBUG: Executing command '%s'. . .\n",
argv[optind]);
}
argc -= optind;
argv += optind;
optind = 0;
gRet = exec_command(argc, argv);
goto bail;
}
if (istty) {
#if !HAVE_LIBREADLINE
fprintf(stderr,
"%s: error: Interactive mode disabled: Compiled without libeditline or libreadline support.\n",
argv[0]
);
print_arg_list_help(option_list,
argv[0],
"[options] <sub-command> [args]");
print_commands();
gRet = ERRORCODE_NOCOMMAND;
goto bail;
#else   setenv("WPANCTL_HISTORY_FILE", tilde_expand("~/.wpanctl_history"), 0);
gRet = initialize_readline();
if(gRet) {
fprintf(stderr,
"%s: error: Failed to initialize readline: %d\n",
argv[0], gRet
);
goto bail;
}
#endif  }
while ((gRet != ERRORCODE_QUIT) && !feof(stdin)) {
optind = 0;
#if HAVE_LIBREADLINE
if (istty) {
int dbus_fd = -1;
dbus_connection_get_unix_fd(connection, &dbus_fd);
struct pollfd polltable[2] = {
{ fileno(stdin), POLLIN | POLLHUP,               0                         },
{ dbus_fd,               POLLIN | POLLHUP,               0                         },
};
if (poll(
polltable,
(dbus_fd >= 0) ? 2 : 1,
1000
) < 0
) {
if (errno == EINTR) {
} else {
break;
}
}
if (polltable[0].revents)
rl_callback_read_char();
} else
#endif  {
char linebuffer[200];
process_input_line(fgets(linebuffer, sizeof(linebuffer), stdin));
}
dbus_connection_read_write_dispatch(connection, 0);
}
printf("\n");
bail:
#if HAVE_LIBREADLINE
rl_callback_handler_remove();
#endif  if (gRet == ERRORCODE_QUIT)
gRet = 0;
return gRet;
}

static int do_prlimit(struct task_struct *tsk, unsigned int resource,
struct rlimit *new_rlim, struct rlimit *old_rlim)
{
struct rlimit *rlim;
int retval = 0;
if (resource >= RLIM_NLIMITS)
return -EINVAL;
if (new_rlim) {
if (new_rlim->rlim_cur > new_rlim->rlim_max)
return -EINVAL;
if (resource == RLIMIT_NOFILE &&
new_rlim->rlim_max > sysctl_nr_open)
return -EPERM;
}
rlim = tsk->signal->rlim + resource;
task_lock(tsk->group_leader);
if (new_rlim) {
if (new_rlim->rlim_max > rlim->rlim_max &&
!capable(CAP_SYS_RESOURCE))
retval = -EPERM;
if (!retval)
retval = security_task_setrlimit(tsk, resource, new_rlim);
}
if (!retval) {
if (old_rlim)
*old_rlim = *rlim;
if (new_rlim)
*rlim = *new_rlim;
}
task_unlock(tsk->group_leader);
if (!retval && new_rlim && resource == RLIMIT_CPU &&
new_rlim->rlim_cur != RLIM_INFINITY &&
IS_ENABLED(CONFIG_POSIX_TIMERS)) {
update_rlimit_cpu(tsk->group_leader, new_rlim->rlim_cur);
}
return retval;
}

int snd_rawmidi_output_params(struct snd_rawmidi_substream *substream,
struct snd_rawmidi_params * params)
{
char *newbuf;
struct snd_rawmidi_runtime *runtime = substream->runtime;
if (substream->append && substream->use_count > 1)
return -EBUSY;
snd_rawmidi_drain_output(substream);
if (params->buffer_size < 32 || params->buffer_size > 1024L * 1024L) {
return -EINVAL;
}
if (params->avail_min < 1 || params->avail_min > params->buffer_size) {
return -EINVAL;
}
if (params->buffer_size != runtime->buffer_size) {
newbuf = krealloc(runtime->buffer, params->buffer_size,
GFP_KERNEL);
if (!newbuf)
return -ENOMEM;
runtime->buffer = newbuf;
runtime->buffer_size = params->buffer_size;
runtime->avail = runtime->buffer_size;
}
runtime->avail_min = params->avail_min;
substream->active_sensing = !params->no_active_sensing;
return 0;
}

