PIX  *
pixBlockconv(PIX     *pix,
l_int32  wc,
l_int32  hc)
{
l_int32  w, h, d;
PIX     *pixs, *pixd, *pixr, *pixrc, *pixg, *pixgc, *pixb, *pixbc;
PROCNAME("pixBlockconv");
if (!pix)
return (PIX *)ERROR_PTR("pix not defined", procName, NULL);
if (wc < 0) wc = 0;
if (hc < 0) hc = 0;
pixGetDimensions(pix, &w, &h, &d);
if (w < 2 * wc + 1 || h < 2 * hc + 1) {
wc = L_MIN(wc, (w - 1) / 2);
hc = L_MIN(hc, (h - 1) / 2);
L_WARNING("kernel too large; reducing!\n", procName);
L_INFO("wc = %d, hc = %d\n", procName, wc, hc);
}
if (wc == 0 && hc == 0)   
return pixCopy(NULL, pix);
if ((d == 2 || d == 4 || d == 8) && pixGetColormap(pix)) {
L_WARNING("pix has colormap; removing\n", procName);
pixs = pixRemoveColormap(pix, REMOVE_CMAP_BASED_ON_SRC);
d = pixGetDepth(pixs);
} else {
pixs = pixClone(pix);
}
if (d != 8 && d != 32) {
pixDestroy(&pixs);
return (PIX *)ERROR_PTR("depth not 8 or 32 bpp", procName, NULL);
}
if (d == 8) {
pixd = pixBlockconvGray(pixs, NULL, wc, hc);
} else { 
pixr = pixGetRGBComponent(pixs, COLOR_RED);
pixrc = pixBlockconvGray(pixr, NULL, wc, hc);
pixDestroy(&pixr);
pixg = pixGetRGBComponent(pixs, COLOR_GREEN);
pixgc = pixBlockconvGray(pixg, NULL, wc, hc);
pixDestroy(&pixg);
pixb = pixGetRGBComponent(pixs, COLOR_BLUE);
pixbc = pixBlockconvGray(pixb, NULL, wc, hc);
pixDestroy(&pixb);
pixd = pixCreateRGBImage(pixrc, pixgc, pixbc);
pixDestroy(&pixrc);
pixDestroy(&pixgc);
pixDestroy(&pixbc);
}
pixDestroy(&pixs);
return pixd;
}

static void
pci_vtblk_proc(struct pci_vtblk_softc *sc, struct vqueue_info *vq)
{
struct virtio_blk_hdr *vbh;
struct virtio_blk_discard_write_zeroes *vbdiscard;
struct pci_vtblk_ioreq *io;
int i, n;
int err;
ssize_t iolen;
int expectro, type;
struct iovec iov[BLOCKIF_IOV_MAX + 2];
uint16_t idx, flags[BLOCKIF_IOV_MAX + 2];
n = vq_getchain(vq, &idx, iov, BLOCKIF_IOV_MAX + 2, flags);
assert(n >= 2 && n <= BLOCKIF_IOV_MAX + 2);
io = &sc->vbsc_ios[idx];
assert((flags[0] & VRING_DESC_F_WRITE) == 0);
assert(iov[0].iov_len == sizeof(struct virtio_blk_hdr));
vbh = iov[0].iov_base;
memcpy(&io->io_req.br_iov, &iov[1],
sizeof(struct iovec) * ((size_t)n - 2));
io->io_req.br_iovcnt = n - 2;
io->io_req.br_offset = (off_t)(vbh->vbh_sector * DEV_BSIZE);
io->io_status = iov[--n].iov_base;
assert(iov[n].iov_len == 1);
assert(flags[n] & VRING_DESC_F_WRITE);
type = vbh->vbh_type & ~VBH_FLAG_BARRIER;
expectro = (type == VBH_OP_WRITE) || (type == VBH_OP_DISCARD);
iolen = 0;
for (i = 1; i < n; i++) {
assert(((flags[i] & VRING_DESC_F_WRITE) == 0) == expectro);
iolen += iov[i].iov_len;
}
io->io_req.br_resid = iolen;
DPRINTF(("virtio-block: %s op, %zd bytes, %d segs\n\r",
print_vbh_op(type), iolen, i - 1));
switch (type) {
case VBH_OP_READ:
err = blockif_read(sc->bc, &io->io_req);
break;
case VBH_OP_WRITE:
err = blockif_write(sc->bc, &io->io_req);
break;
case VBH_OP_DISCARD:
assert(iov[1].iov_len = sizeof(struct virtio_blk_discard_write_zeroes));
assert(n == 2);
vbdiscard = iov[1].iov_base;
io->io_req.br_offset = (off_t) vbdiscard->sector * DEV_BSIZE;
io->io_req.br_resid = vbdiscard->num_sectors * DEV_BSIZE;
err = blockif_delete(sc->bc, &io->io_req);
break;
case VBH_OP_FLUSH:
case VBH_OP_FLUSH_OUT:
err = blockif_flush(sc->bc, &io->io_req);
break;
case VBH_OP_IDENT:
memset(iov[1].iov_base, 0, iov[1].iov_len);
strncpy(iov[1].iov_base, sc->vbsc_ident,
MIN(iov[1].iov_len, sizeof(sc->vbsc_ident)));
pci_vtblk_done_locked(&io->io_req, 0);
return;
default:
pci_vtblk_done_locked(&io->io_req, EOPNOTSUPP);
return;
}
assert(err == 0);
}

static unsigned int clear_iommu_pte_present(unsigned long l1_mfn,
unsigned long dfn)
{
struct amd_iommu_pte *table, *pte;
unsigned int flush_flags;
table = map_domain_page(_mfn(l1_mfn));
pte = &table[pfn_to_pde_idx(dfn, 1)];
flush_flags = pte->pr ? IOMMU_FLUSHF_modified : 0;
memset(pte, 0, sizeof(*pte));
unmap_domain_page(table);
return flush_flags;
}

int wolfSSH_SFTP_RecvRename(WOLFSSH* ssh, int reqId, byte* data, word32 maxSz)
{
word32 sz = 0;
char*  old;
char*  nw;
word32 idx = 0;
int    ret = WS_SUCCESS;
byte*  out;
word32 outSz;
byte type = WOLFSSH_FTP_OK;
char  suc[] = "Renamed File";
char  err[] = "Rename File Error";
char* res   = suc;
if (ssh == NULL) {
return WS_BAD_ARGUMENT;
}
WLOG(WS_LOG_SFTP, "Receiving WOLFSSH_FTP_RENAME");
ato32(data + idx, &sz); idx += UINT32_SZ;
if (sz + idx > maxSz) {
ret = WS_BUFFER_E;
}
old = (char*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (old == NULL) {
ret = WS_MEMORY_E;
}
if (ret == WS_SUCCESS) {
WMEMCPY(old, data + idx, sz); idx += sz;
old[sz] = '\0';
}
ato32(data + idx, &sz); idx += UINT32_SZ;
if (sz + idx > maxSz) {
ret = WS_BUFFER_E;
}
nw = (char*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (nw == NULL) {
ret = WS_MEMORY_E;
}
if (ret == WS_SUCCESS) {
WMEMCPY(nw, data + idx, sz);
nw[sz] = '\0';
}
if (wolfSSH_CleanPath(ssh, old) < 0) {
ret =  WS_FATAL_ERROR;
}
if (wolfSSH_CleanPath(ssh, nw) < 0) {
ret = WS_FATAL_ERROR;
}
if (ret == WS_SUCCESS) {
#ifndef USE_WINDOWS_API
if (WRENAME(ssh->fs, old, nw) < 0)
#else 
if (WS_MoveFileA(old, nw, ssh->ctx->heap) == 0)
#endif 
{
WLOG(WS_LOG_SFTP, "Error renaming file");
ret = WS_BAD_FILE_E;
}
}
WFREE(old, ssh->ctx->heap, DYNTYPE_BUFFER);
WFREE(nw, ssh->ctx->heap, DYNTYPE_BUFFER);
if (ret != WS_SUCCESS) {
type = WOLFSSH_FTP_FAILURE;
res  = err;
}
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res, "English", NULL,
&outSz) != WS_SIZE_ONLY) {
return WS_FATAL_ERROR;
}
out = (byte*)WMALLOC(outSz, ssh->ctx->heap, DYNTYPE_BUFFER);
if (out == NULL) {
return WS_MEMORY_E;
}
if (wolfSSH_SFTP_CreateStatus(ssh, type, reqId, res, "English", out,
&outSz) != WS_SUCCESS) {
WFREE(out, ssh->ctx->heap, DYNTYPE_BUFFER);
return WS_FATAL_ERROR;
}
wolfSSH_SFTP_RecvSetSend(ssh, out, outSz);
return ret;
}

