static void  Ins_IP( INS_ARG )
{
TT_F26Dot6  org_a, org_b, org_x,
cur_a, cur_b, cur_x,
distance;
Int         point;
(void)args;
if ( CUR.top < CUR.GS.loop )
{
CUR.error = TT_Err_Invalid_Reference;
return;
}
org_a = CUR_Func_dualproj( CUR.zp0.org_x[CUR.GS.rp1],
CUR.zp0.org_y[CUR.GS.rp1] );
org_b = CUR_Func_dualproj( CUR.zp1.org_x[CUR.GS.rp2],
CUR.zp1.org_y[CUR.GS.rp2] );
cur_a = CUR_Func_project( CUR.zp0.cur_x[CUR.GS.rp1],
CUR.zp0.cur_y[CUR.GS.rp1] );
cur_b = CUR_Func_project( CUR.zp1.cur_x[CUR.GS.rp2],
CUR.zp1.cur_y[CUR.GS.rp2] );
while ( CUR.GS.loop > 0 )
{
CUR.args--;
point = (Int)CUR.stack[CUR.args];
if ( BOUNDS( point, CUR.zp2.n_points ) )
{
CUR.error = TT_Err_Invalid_Reference;
return;
}
org_x = CUR_Func_dualproj( CUR.zp2.org_x[point],
CUR.zp2.org_y[point] );
cur_x = CUR_Func_project( CUR.zp2.cur_x[point],
CUR.zp2.cur_y[point] );
if ( ( org_a <= org_b && org_x <= org_a ) ||
( org_a >  org_b && org_x >= org_a ) )
distance = ( cur_a - org_a ) + ( org_x - cur_x );
else if ( ( org_a <= org_b  &&  org_x >= org_b ) ||
( org_a >  org_b  &&  org_x <  org_b ) )
distance = ( cur_b - org_b ) + ( org_x - cur_x );
else
distance = MulDiv_Round( cur_b - cur_a,
org_x - org_a,
org_b - org_a ) + ( cur_a - cur_x );
CUR_Func_move( &CUR.zp2, point, distance );
CUR.GS.loop--;
}
CUR.GS.loop = 1;
CUR.new_top = CUR.args;
}

int LoadEXR(float **out_rgba, int *width, int *height, const char *filename,
const char **err) {
if (out_rgba == NULL) {
tinyexr::SetErrorMessage("Invalid argument for LoadEXR()", err);
return TINYEXR_ERROR_INVALID_ARGUMENT;
}
EXRVersion exr_version;
EXRImage exr_image;
EXRHeader exr_header;
InitEXRHeader(&exr_header);
InitEXRImage(&exr_image);
{
int ret = ParseEXRVersionFromFile(&exr_version, filename);
if (ret != TINYEXR_SUCCESS) {
return ret;
}
if (exr_version.multipart || exr_version.non_image) {
tinyexr::SetErrorMessage("Loading multipart or DeepImage is not supported  in LoadEXR() API", err);
return TINYEXR_ERROR_INVALID_DATA;      }
}
{
int ret = ParseEXRHeaderFromFile(&exr_header, &exr_version, filename, err);
if (ret != TINYEXR_SUCCESS) {
FreeEXRHeader(&exr_header);
return ret;
}
}
for (int i = 0; i < exr_header.num_channels; i++) {
if (exr_header.pixel_types[i] == TINYEXR_PIXELTYPE_HALF) {
exr_header.requested_pixel_types[i] = TINYEXR_PIXELTYPE_FLOAT;
}
}
{
int ret = LoadEXRImageFromFile(&exr_image, &exr_header, filename, err);
if (ret != TINYEXR_SUCCESS) {
return ret;
}
}
int idxR = -1;
int idxG = -1;
int idxB = -1;
int idxA = -1;
for (int c = 0; c < exr_header.num_channels; c++) {
if (strcmp(exr_header.channels[c].name, "R") == 0) {
idxR = c;
} else if (strcmp(exr_header.channels[c].name, "G") == 0) {
idxG = c;
} else if (strcmp(exr_header.channels[c].name, "B") == 0) {
idxB = c;
} else if (strcmp(exr_header.channels[c].name, "A") == 0) {
idxA = c;
}
}
if ((idxA == 0) && (idxR == -1) && (idxG == -1) && (idxB == -1)) {
if (exr_header.tiled) {
}
(*out_rgba) = reinterpret_cast<float *>(
malloc(4 * sizeof(float) * static_cast<size_t>(exr_image.width) *
static_cast<size_t>(exr_image.height)));
for (int i = 0; i < exr_image.width * exr_image.height; i++) {
const float val = reinterpret_cast<float **>(exr_image.images)[0][i];
(*out_rgba)[4 * i + 0] = val;
(*out_rgba)[4 * i + 1] = val;
(*out_rgba)[4 * i + 2] = val;
(*out_rgba)[4 * i + 3] = val;
}
} else {
if (idxR == -1) {
tinyexr::SetErrorMessage("R channel not found", err);
return TINYEXR_ERROR_INVALID_DATA;
}
if (idxG == -1) {
tinyexr::SetErrorMessage("G channel not found", err);
return TINYEXR_ERROR_INVALID_DATA;
}
if (idxB == -1) {
tinyexr::SetErrorMessage("B channel not found", err);
return TINYEXR_ERROR_INVALID_DATA;
}
(*out_rgba) = reinterpret_cast<float *>(
malloc(4 * sizeof(float) * static_cast<size_t>(exr_image.width) *
static_cast<size_t>(exr_image.height)));
if (exr_header.tiled) {
for (int it = 0; it < exr_image.num_tiles; it++) {
for (int j = 0; j < exr_header.tile_size_y; j++)
for (int i = 0; i < exr_header.tile_size_x; i++) {
const int ii =
exr_image.tiles[it].offset_x * exr_header.tile_size_x + i;
const int jj =
exr_image.tiles[it].offset_y * exr_header.tile_size_y + j;
const int idx = ii + jj * exr_image.width;
if (ii >= exr_image.width) {
continue;
}
if (jj >= exr_image.height) {
continue;
}
const int srcIdx = i + j * exr_header.tile_size_x;
unsigned char **src = exr_image.tiles[it].images;
(*out_rgba)[4 * idx + 0] =
reinterpret_cast<float **>(src)[idxR][srcIdx];
(*out_rgba)[4 * idx + 1] =
reinterpret_cast<float **>(src)[idxG][srcIdx];
(*out_rgba)[4 * idx + 2] =
reinterpret_cast<float **>(src)[idxB][srcIdx];
if (idxA != -1) {
(*out_rgba)[4 * idx + 3] =
reinterpret_cast<float **>(src)[idxA][srcIdx];
} else {
(*out_rgba)[4 * idx + 3] = 1.0;
}
}
}
} else {
for (int i = 0; i < exr_image.width * exr_image.height; i++) {
(*out_rgba)[4 * i + 0] =
reinterpret_cast<float **>(exr_image.images)[idxR][i];
(*out_rgba)[4 * i + 1] =
reinterpret_cast<float **>(exr_image.images)[idxG][i];
(*out_rgba)[4 * i + 2] =
reinterpret_cast<float **>(exr_image.images)[idxB][i];
if (idxA != -1) {
(*out_rgba)[4 * i + 3] =
reinterpret_cast<float **>(exr_image.images)[idxA][i];
} else {
(*out_rgba)[4 * i + 3] = 1.0;
}
}
}
}
(*width) = exr_image.width;
(*height) = exr_image.height;
FreeEXRHeader(&exr_header);
FreeEXRImage(&exr_image);
return TINYEXR_SUCCESS;
}

int 
dlt_en10mb_encode(tcpeditdlt_t *ctx, u_char *packet, int pktlen, tcpr_dir_t dir)
{
tcpeditdlt_plugin_t *plugin = NULL;
struct tcpr_ethernet_hdr *eth = NULL;
struct tcpr_802_1q_hdr *vlan = NULL;
en10mb_config_t *config = NULL;
en10mb_extra_t *extra = NULL;
int newl2len = 0;
assert(ctx);
assert(packet);
if (pktlen < TCPR_802_1Q_H) {
tcpedit_seterr(ctx->tcpedit, 
"Unable to process packet #" COUNTER_SPEC " since it is less then 14 bytes.", 
ctx->tcpedit->runtime.packetnum);
return TCPEDIT_ERROR;
}
plugin = tcpedit_dlt_getplugin(ctx, dlt_value);
if (!plugin)
return TCPEDIT_ERROR;
config = plugin->config;
if (plugin->config_size < sizeof(*config))
return TCPEDIT_ERROR;
extra = (en10mb_extra_t *)ctx->decoded_extra;
if (ctx->decoded_extra_size < sizeof(*extra))
return TCPEDIT_ERROR;
if (ctx->decoder->dlt == dlt_value) {
if ((ctx->l2len == TCPR_802_1Q_H && config->vlan == TCPEDIT_VLAN_OFF) ||
(config->vlan == TCPEDIT_VLAN_ADD)) {
newl2len = TCPR_802_1Q_H;
} else if ((ctx->l2len == TCPR_802_3_H && config->vlan == TCPEDIT_VLAN_OFF) ||
(config->vlan == TCPEDIT_VLAN_DEL)) {
newl2len = TCPR_802_3_H;
}
} 
else {
newl2len = config->vlan == TCPEDIT_VLAN_ADD ? TCPR_802_1Q_H : TCPR_802_3_H;
}
if (pktlen < newl2len) {
tcpedit_seterr(ctx->tcpedit,
"Unable to process packet #" COUNTER_SPEC " since its new length less then %d bytes.",
ctx->tcpedit->runtime.packetnum, newl2len);
return TCPEDIT_ERROR;
}
if (newl2len != ctx->l2len)
memmove(packet + newl2len, packet + ctx->l2len, pktlen - ctx->l2len);
pktlen += newl2len - ctx->l2len;
eth = (struct tcpr_ethernet_hdr *)packet;
if (dir == TCPR_DIR_C2S) {
if (config->mac_mask & TCPEDIT_MAC_MASK_SMAC1) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && 
is_unicast_ethernet(ctx, ctx->srcaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_shost, config->intf1_smac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);                
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a source address");
return TCPEDIT_ERROR;
}
if (config->mac_mask & TCPEDIT_MAC_MASK_DMAC1) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->dstaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_dhost, config->intf1_dmac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a destination address");
return TCPEDIT_ERROR;            
}
} else if (dir == TCPR_DIR_S2C) {
if (config->mac_mask & TCPEDIT_MAC_MASK_SMAC2) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->srcaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_shost, config->intf2_smac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_shost, ctx->srcaddr.ethernet, ETHER_ADDR_LEN);            
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a source address");
return TCPEDIT_ERROR;
}
if (config->mac_mask & TCPEDIT_MAC_MASK_DMAC2) {
if ((ctx->addr_type == ETHERNET && 
((ctx->skip_broadcast && is_unicast_ethernet(ctx, ctx->dstaddr.ethernet)) || !ctx->skip_broadcast))
|| ctx->addr_type != ETHERNET) {
memcpy(eth->ether_dhost, config->intf2_dmac, ETHER_ADDR_LEN);
} else {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);                
}
} else if (ctx->addr_type == ETHERNET) {
memcpy(eth->ether_dhost, ctx->dstaddr.ethernet, ETHER_ADDR_LEN);
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Please provide a destination address");
return TCPEDIT_ERROR;
}
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Encoders only support C2S or C2S!");
return TCPEDIT_ERROR;
}
if (config->subs.entries) {
int  entry = 0;
for (entry = 0 ; entry < config->subs.count; entry++) {
en10mb_sub_entry_t *current = &config->subs.entries[entry];
if (!memcmp(eth->ether_dhost, current->target, ETHER_ADDR_LEN)) {
memcpy(eth->ether_dhost, current->rewrite, ETHER_ADDR_LEN);
}
if (!memcmp(eth->ether_shost, current->target, ETHER_ADDR_LEN)) {
memcpy(eth->ether_shost, current->rewrite, ETHER_ADDR_LEN);
}
}
}
if (config->random.set) {
int unicast_src = is_unicast_ethernet(ctx, eth->ether_shost);
int unicast_dst = is_unicast_ethernet(ctx, eth->ether_dhost);
int i = config->random.keep;
for ( ; i < ETHER_ADDR_LEN; i++) {
eth->ether_shost[i] = MAC_MASK_APPLY(eth->ether_shost[i], config->random.mask[i], unicast_src);
eth->ether_dhost[i] = MAC_MASK_APPLY(eth->ether_dhost[i], config->random.mask[i], unicast_dst);
}
if (!config->random.keep) {
eth->ether_shost[0] &= ~(0x01 * unicast_src);
eth->ether_dhost[0] &= ~(0x01 * unicast_dst);
}
}
if (newl2len == TCPR_802_3_H) {
eth->ether_type = ctx->proto;
} else if (newl2len == TCPR_802_1Q_H) {
vlan = (struct tcpr_802_1q_hdr *)packet;
vlan->vlan_len = ctx->proto;
vlan->vlan_tpi = htons(ETHERTYPE_VLAN);
if (config->vlan_tag < 65535) {
vlan->vlan_priority_c_vid = 
htons((uint16_t)config->vlan_tag & TCPR_802_1Q_VIDMASK);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid = extra->vlan_tag;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-tag");
return TCPEDIT_ERROR;
}
if (config->vlan_pri < 255) {
vlan->vlan_priority_c_vid += htons((uint16_t)config->vlan_pri << 13);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid += extra->vlan_pri;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-pri");
return TCPEDIT_ERROR;
}
if (config->vlan_cfi < 255) {
vlan->vlan_priority_c_vid += htons((uint16_t)config->vlan_cfi << 12);
} else if (extra->vlan) {
vlan->vlan_priority_c_vid += extra->vlan_cfi;
} else {
tcpedit_seterr(ctx->tcpedit, "%s", "Non-VLAN tagged packet requires --enet-vlan-cfi");
return TCPEDIT_ERROR;            
}        
} else {
tcpedit_seterr(ctx->tcpedit, "Unsupported new layer 2 length: %d", newl2len);
return TCPEDIT_ERROR;
}
return pktlen;
}

ssize_t _import_ansi(caca_canvas_t *cv, void const *data, size_t size, int utf8)
{
struct import im;
unsigned char const *buffer = (unsigned char const*)data;
unsigned int i, j, skip, growx = 0, growy = 0, dummy = 0;
unsigned int width, height;
uint32_t savedattr;
int x = 0, y = 0, save_x = 0, save_y = 0;
if(utf8)
{
width = cv->width;
height = cv->height;
growx = !width;
growy = !height;
x = cv->frames[cv->frame].x;
y = cv->frames[cv->frame].y;
}
else
{
caca_set_canvas_size(cv, width = 80, height = 0);
growx = 0;
growy = 1;
}
if(utf8)
{
im.dfg = CACA_DEFAULT;
im.dbg = CACA_TRANSPARENT;
}
else
{
im.dfg = CACA_LIGHTGRAY;
im.dbg = CACA_BLACK;
}
caca_set_color_ansi(cv, im.dfg, im.dbg);
im.clearattr = caca_get_attr(cv, -1, -1);
ansi_parse_grcm(cv, &im, 1, &dummy);
for(i = 0; i < size; i += skip)
{
uint32_t ch = 0;
int wch = 0;
skip = 1;
if(!utf8 && buffer[i] == '\x1a' && i + 7 < size
&& !memcmp(buffer + i + 1, "SAUCE00", 7))
break; 
else if(buffer[i] == '\r')
{
x = 0;
}
else if(buffer[i] == '\n')
{
x = 0;
y++;
}
else if(buffer[i] == '\t')
{
x = (x + 8) & ~7;
}
else if(buffer[i] == '\x08')
{
if(x > 0)
x--;
}
else if(buffer[i] == '\033' && i + 2 >= size)
break;
else if(buffer[i] == '\033' && buffer[i + 1] == '('
&& buffer[i + 2] == 'B')
{
skip += 2;
}
else if(buffer[i] == '\033' && buffer[i + 1] == '[')
{
unsigned int argc = 0, argv[101];
unsigned int param, inter, final;
param = 2;
for(inter = param; i + inter < size; inter++)
if(buffer[i + inter] < 0x30 || buffer[i + inter] > 0x3f)
break;
for(final = inter; i + final < size; final++)
if(buffer[i + final] < 0x20 || buffer[i + final] > 0x2f)
break;
if(i + final >= size
|| buffer[i + final] < 0x40 || buffer[i + final] > 0x7e)
break; 
skip += final;
if(param < inter && buffer[i + param] >= 0x3c)
{
debug("ansi import: private sequence \"^[[%.*s\"",
final - param + 1, buffer + i + param);
continue; 
}
if(final - param > 100)
continue; 
if(param < inter)
{
argv[0] = 0;
for(j = param; j < inter; j++)
{
if(buffer[i + j] == ';')
argv[++argc] = 0;
else if(buffer[i + j] >= '0' && buffer[i + j] <= '9')
argv[argc] = 10 * argv[argc] + (buffer[i + j] - '0');
}
argc++;
}
switch(buffer[i + final])
{
case 'H': 
x = (argc > 1 && argv[1] > 0) ? argv[1] - 1 : 0;
y = (argc > 0 && argv[0] > 0) ? argv[0] - 1 : 0;
break;
case 'A': 
y -= argc ? argv[0] : 1;
if(y < 0)
y = 0;
break;
case 'B': 
y += argc ? argv[0] : 1;
break;
case 'C': 
x += argc ? argv[0] : 1;
break;
case 'D': 
x -= argc ? argv[0] : 1;
if(x < 0)
x = 0;
break;
case 'G': 
x = (argc && argv[0] > 0) ? argv[0] - 1 : 0;
break;
case 'J': 
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
if(!argc || argv[0] == 0)
{
caca_draw_line(cv, x, y, width, y, ' ');
caca_fill_box(cv, 0, y + 1, width - 1, height - 1, ' ');
}
else if(argv[0] == 1)
{
caca_fill_box(cv, 0, 0, width - 1, y - 1, ' ');
caca_draw_line(cv, 0, y, x, y, ' ');
}
else if(argv[0] == 2)
caca_fill_box(cv, 0, 0, width - 1, height - 1, ' ');
caca_set_attr(cv, savedattr);
break;
case 'K': 
if(!argc || argv[0] == 0)
caca_draw_line(cv, x, y, width, y, ' ');
else if(argv[0] == 1)
caca_draw_line(cv, 0, y, x, y, ' ');
else if(argv[0] == 2)
if((unsigned int)x < width)
caca_draw_line(cv, x, y, width - 1, y, ' ');
break;
case 'P': 
if(!argc || argv[0] == 0)
argv[0] = 1; 
for(j = 0; (unsigned int)(j + argv[0]) < width; j++)
{
caca_put_char(cv, j, y,
caca_get_char(cv, j + argv[0], y));
caca_put_attr(cv, j, y,
caca_get_attr(cv, j + argv[0], y));
}
#if 0
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
for( ; (unsigned int)j < width; j++)
caca_put_char(cv, j, y, ' ');
caca_set_attr(cv, savedattr);
#endif
break;
case 'X': 
if(argc && argv[0])
{
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
caca_draw_line(cv, x, y, x + argv[0] - 1, y, ' ');
caca_set_attr(cv, savedattr);
}
break;
case 'd': 
y = (argc && argv[0] > 0) ? argv[0] - 1 : 0;
break;
case 'f': 
x = (argc > 1 && argv[1] > 0) ? argv[1] - 1 : 0;
y = (argc > 0 && argv[0] > 0) ? argv[0] - 1 : 0;
break;
case 'h': 
debug("ansi import: set mode %i", argc ? (int)argv[0] : -1);
break;
case 'l': 
debug("ansi import: reset mode %i", argc ? (int)argv[0] : -1);
break;
case 'm': 
if(argc)
ansi_parse_grcm(cv, &im, argc, argv);
else
ansi_parse_grcm(cv, &im, 1, &dummy);
break;
case 's': 
save_x = x;
save_y = y;
break;
case 'u': 
x = save_x;
y = save_y;
break;
default:
debug("ansi import: unknown command \"^[[%.*s\"",
final - param + 1, buffer + i + param);
break;
}
}
else if(buffer[i] == '\033' && buffer[i + 1] == ']')
{
char *string;
unsigned int command = 0;
unsigned int mode = 2, semicolon, final;
for(semicolon = mode; i + semicolon < size; semicolon++)
{
if(buffer[i + semicolon] < '0' || buffer[i + semicolon] > '9')
break;
command = 10 * command + (buffer[i + semicolon] - '0');
}
if(i + semicolon >= size || buffer[i + semicolon] != ';')
break; 
for(final = semicolon + 1; i + final < size; final++)
if(buffer[i + final] < 0x20)
break;
if(i + final >= size || buffer[i + final] != '\a')
break; 
skip += final;
string = malloc(final - (semicolon + 1) + 1);
memcpy(string, buffer + (semicolon + 1), final - (semicolon + 1));
string[final - (semicolon + 1)] = '\0';
debug("ansi import: got OSC command %i string '%s'", command,
string);
free(string);
}
else if(buffer[i] == '\f' && buffer[i + 1] == '\n')
{
int f = caca_get_frame_count(cv);
caca_create_frame(cv, f);
caca_set_frame(cv, f);
x = y = 0;
skip++;
}
else if(utf8)
{
size_t bytes;
if(i + 6 < size)
ch = caca_utf8_to_utf32((char const *)(buffer + i), &bytes);
else
{
char tmp[7];
memcpy(tmp, buffer + i, size - i);
tmp[size - i] = '\0';
ch = caca_utf8_to_utf32(tmp, &bytes);
}
if(!bytes)
{
ch = buffer[i];
bytes = 1;
}
wch = caca_utf32_is_fullwidth(ch) ? 2 : 1;
skip += (int)(bytes - 1);
}
else
{
ch = caca_cp437_to_utf32(buffer[i]);
wch = 1;
}
while((unsigned int)x + wch > width)
{
if(growx)
{
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
caca_set_canvas_size(cv, width = x + wch, height);
caca_set_attr(cv, savedattr);
}
else
{
x -= width;
y++;
}
}
if((unsigned int)y >= height)
{
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
if(growy)
{
caca_set_canvas_size(cv, width, height = y + 1);
}
else
{
int lines = (y - height) + 1;
for(j = 0; j + lines < height; j++)
{
memcpy(cv->attrs + j * cv->width,
cv->attrs + (j + lines) * cv->width, cv->width * 4);
memcpy(cv->chars + j * cv->width,
cv->chars + (j + lines) * cv->width, cv->width * 4);
}
caca_fill_box(cv, 0, height - lines,
cv->width - 1, height - 1, ' ');
y -= lines;
}
caca_set_attr(cv, savedattr);
}
if(wch)
{
caca_put_char(cv, x, y, ch);
x += wch;
}
}
if(growy && (unsigned int)y > height)
{
savedattr = caca_get_attr(cv, -1, -1);
caca_set_attr(cv, im.clearattr);
caca_set_canvas_size(cv, width, height = y);
caca_set_attr(cv, savedattr);
}
cv->frames[cv->frame].x = x;
cv->frames[cv->frame].y = y;
return i;
}

struct posix_acl *ovl_get_acl(struct inode *inode, int type)
{
struct inode *realinode = ovl_inode_real(inode);
if (!realinode)
return ERR_PTR(-ENOENT);
if (!IS_POSIXACL(realinode))
return NULL;
if (!realinode->i_op->get_acl)
return NULL;
return realinode->i_op->get_acl(realinode, type);
}

static gboolean
iseries_check_file_type (wtap * wth, int *err, gchar **err_info, int format)
{
guint      line;
int        num_items_scanned;
char       buf[ISERIES_LINE_LENGTH], protocol[9];
iseries_t *iseries;
iseries                = (iseries_t *) g_malloc (sizeof (iseries_t));
wth->priv              = (void *) iseries;
iseries->have_date     = FALSE;
iseries->format        = format;
for (line = 0; line < ISERIES_HDR_LINES_TO_CHECK; line++)
{
if (file_gets (buf, ISERIES_LINE_LENGTH, wth->fh) == NULL)
{
*err = file_error (wth->fh, err_info);
if (*err == WTAP_ERR_SHORT_READ)
*err = 0;
return FALSE;
}
if (iseries->format == ISERIES_FORMAT_UNICODE)
{
iseries_UNICODE_to_ASCII ((guint8 *)buf, ISERIES_LINE_LENGTH);
}
ascii_strup_inplace (buf);
num_items_scanned = sscanf (buf,
"%*[ \n\t]OBJECT PROTOCOL%*[ .:\n\t]%8s",
protocol);
if (num_items_scanned == 1)
{
if (memcmp (protocol, "ETHERNET", 8) != 0)
return FALSE;
}
num_items_scanned = sscanf (buf,
"%*[ \n\t]START DATE/TIME%*[ .:\n\t]%2d/%2d/%2d",
&iseries->month, &iseries->day,
&iseries->year);
if (num_items_scanned == 3)
{
iseries->have_date = TRUE;
}
}
*err = 0;
return TRUE;
}

void SoftGSM::onQueueFilled(OMX_U32 ) {
if (mSignalledError) {
return;
}
List<BufferInfo *> &inQueue = getPortQueue(0);
List<BufferInfo *> &outQueue = getPortQueue(1);
while (!inQueue.empty() && !outQueue.empty()) {
BufferInfo *inInfo = *inQueue.begin();
OMX_BUFFERHEADERTYPE *inHeader = inInfo->mHeader;
BufferInfo *outInfo = *outQueue.begin();
OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
notifyEmptyBufferDone(inHeader);
outHeader->nFilledLen = 0;
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
outQueue.erase(outQueue.begin());
outInfo->mOwnedByUs = false;
notifyFillBufferDone(outHeader);
return;
}
if (inHeader->nFilledLen > kMaxNumSamplesPerFrame) {
ALOGE("input buffer too large (%d).", inHeader->nFilledLen);
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
}
if(((inHeader->nFilledLen / kMSGSMFrameSize) * kMSGSMFrameSize) != inHeader->nFilledLen) {
ALOGE("input buffer not multiple of %d (%d).", kMSGSMFrameSize, inHeader->nFilledLen);
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
}
uint8_t *inputptr = inHeader->pBuffer + inHeader->nOffset;
int n = mSignalledError ? 0 : DecodeGSM(mGsm,
reinterpret_cast<int16_t *>(outHeader->pBuffer), inputptr, inHeader->nFilledLen);
outHeader->nTimeStamp = inHeader->nTimeStamp;
outHeader->nOffset = 0;
outHeader->nFilledLen = n * sizeof(int16_t);
outHeader->nFlags = 0;
inInfo->mOwnedByUs = false;
inQueue.erase(inQueue.begin());
inInfo = NULL;
notifyEmptyBufferDone(inHeader);
inHeader = NULL;
outInfo->mOwnedByUs = false;
outQueue.erase(outQueue.begin());
outInfo = NULL;
notifyFillBufferDone(outHeader);
outHeader = NULL;
}
}

static bool
decode(const Node &node, YamlSNIConfig::Item &item)
{
for (const auto &elem : node) {
if (std::none_of(valid_sni_config_keys.begin(), valid_sni_config_keys.end(),
[&elem](const std::string &s) { return s == elem.first.as<std::string>(); })) {
Warning("unsupported key '%s' in SNI config", elem.first.as<std::string>().c_str());
}
}
if (node[TS_fqdn]) {
item.fqdn = node[TS_fqdn].as<std::string>();
} else {
return false;     }
if (node[TS_disable_h2]) {
item.offer_h2 = false;
}
if (node[TS_http2]) {
item.offer_h2 = node[TS_http2].as<bool>();
}
if (node[TS_http2_buffer_water_mark]) {
item.http2_buffer_water_mark = node[TS_http2_buffer_water_mark].as<int>();
}
if (node[TS_verify_client]) {
auto value = node[TS_verify_client].as<std::string>();
int level  = LEVEL_DESCRIPTOR.get(value);
if (level < 0) {
throw YAML::ParserException(node[TS_verify_client].Mark(), "unknown value \"" + value + "\"");
}
item.verify_client_level = static_cast<uint8_t>(level);
}
if (node[TS_verify_client_ca_certs]) {
#if !TS_HAS_VERIFY_CERT_STORE
throw YAML::ParserException(node[TS_verify_client_ca_certs].Mark(),
std::string(TS_verify_client_ca_certs) + " requires features from OpenSSL 1.0.2 or later");
#else
std::string file, dir;
auto const &n = node[TS_verify_client_ca_certs];
if (n.IsMap()) {
for (const auto &elem : n) {
std::string key = elem.first.as<std::string>();
if ("file" == key) {
if (!file.empty()) {
throw YAML::ParserException(elem.first.Mark(), "duplicate key \"file\"");
}
file = elem.second.as<std::string>();
} else if ("dir" == key) {
if (!dir.empty()) {
throw YAML::ParserException(elem.first.Mark(), "duplicate key \"dir\"");
}
dir = elem.second.as<std::string>();
} else {
throw YAML::ParserException(elem.first.Mark(), "unsupported key " + elem.first.as<std::string>());
}
}
} else {
file = n.as<std::string>();
}
ink_assert(!(file.empty() && dir.empty()));
if (!file.empty() && (file[0] != '/')) {
file = RecConfigReadConfigDir() + '/' + file;
}
if (!dir.empty() && (dir[0] != '/')) {
dir = RecConfigReadConfigDir() + '/' + dir;
}
item.verify_client_ca_file = file;
item.verify_client_ca_dir  = dir;
#endif
}
if (node[TS_host_sni_policy]) {
auto value           = node[TS_host_sni_policy].as<std::string>();
int policy           = POLICY_DESCRIPTOR.get(value);
item.host_sni_policy = static_cast<uint8_t>(policy);
}
YamlSNIConfig::TunnelPreWarm t_prewarm = YamlSNIConfig::TunnelPreWarm::UNSET;
uint32_t t_min                         = item.tunnel_prewarm_min;
int32_t t_max                          = item.tunnel_prewarm_max;
double t_rate                          = item.tunnel_prewarm_rate;
uint32_t t_connect_timeout             = item.tunnel_prewarm_connect_timeout;
uint32_t t_inactive_timeout            = item.tunnel_prewarm_inactive_timeout;
bool t_srv                             = item.tunnel_prewarm_srv;
if (node[TS_tunnel_prewarm]) {
auto is_prewarm_enabled = node[TS_tunnel_prewarm].as<bool>();
if (is_prewarm_enabled) {
t_prewarm = YamlSNIConfig::TunnelPreWarm::ENABLED;
} else {
t_prewarm = YamlSNIConfig::TunnelPreWarm::DISABLED;
}
}
if (node[TS_tunnel_prewarm_min]) {
t_min = node[TS_tunnel_prewarm_min].as<uint32_t>();
}
if (node[TS_tunnel_prewarm_max]) {
t_max = node[TS_tunnel_prewarm_max].as<int32_t>();
}
if (node[TS_tunnel_prewarm_rate]) {
t_rate = node[TS_tunnel_prewarm_rate].as<double>();
}
if (node[TS_tunnel_prewarm_connect_timeout]) {
t_connect_timeout = node[TS_tunnel_prewarm_connect_timeout].as<uint32_t>();
}
if (node[TS_tunnel_prewarm_inactive_timeout]) {
t_inactive_timeout = node[TS_tunnel_prewarm_inactive_timeout].as<uint32_t>();
}
if (node[TS_tunnel_prewarm_srv]) {
t_srv = node[TS_tunnel_prewarm_srv].as<bool>();
}
if (node[TS_tunnel_route]) {
item.tunnel_destination = node[TS_tunnel_route].as<std::string>();
item.tunnel_type        = SNIRoutingType::BLIND;
} else if (node[TS_forward_route]) {
item.tunnel_destination              = node[TS_forward_route].as<std::string>();
item.tunnel_type                     = SNIRoutingType::FORWARD;
item.tunnel_prewarm                  = t_prewarm;
item.tunnel_prewarm_min              = t_min;
item.tunnel_prewarm_max              = t_max;
item.tunnel_prewarm_rate             = t_rate;
item.tunnel_prewarm_connect_timeout  = t_connect_timeout;
item.tunnel_prewarm_inactive_timeout = t_inactive_timeout;
item.tunnel_prewarm_srv              = t_srv;
} else if (node[TS_partial_blind_route]) {
item.tunnel_destination              = node[TS_partial_blind_route].as<std::string>();
item.tunnel_type                     = SNIRoutingType::PARTIAL_BLIND;
item.tunnel_prewarm                  = t_prewarm;
item.tunnel_prewarm_min              = t_min;
item.tunnel_prewarm_max              = t_max;
item.tunnel_prewarm_rate             = t_rate;
item.tunnel_prewarm_connect_timeout  = t_connect_timeout;
item.tunnel_prewarm_inactive_timeout = t_inactive_timeout;
item.tunnel_prewarm_srv              = t_srv;
if (node[TS_tunnel_alpn]) {
load_tunnel_alpn(item.tunnel_alpn, node[TS_tunnel_alpn]);
}
}
if (node[TS_verify_server_policy]) {
auto value = node[TS_verify_server_policy].as<std::string>();
int policy = POLICY_DESCRIPTOR.get(value);
if (policy < 0) {
throw YAML::ParserException(node[TS_verify_server_policy].Mark(), "unknown value \"" + value + "\"");
}
item.verify_server_policy = static_cast<YamlSNIConfig::Policy>(policy);
}
if (node[TS_verify_server_properties]) {
auto value     = node[TS_verify_server_properties].as<std::string>();
int properties = PROPERTIES_DESCRIPTOR.get(value);
if (properties < 0) {
throw YAML::ParserException(node[TS_verify_server_properties].Mark(), "unknown value \"" + value + "\"");
}
item.verify_server_properties = static_cast<YamlSNIConfig::Property>(properties);
}
if (node[TS_client_cert]) {
item.client_cert = node[TS_client_cert].as<std::string>();
}
if (node[TS_client_key]) {
item.client_key = node[TS_client_key].as<std::string>();
}
if (node[TS_client_sni_policy]) {
item.client_sni_policy = node[TS_client_sni_policy].as<std::string>();
}
if (node[TS_ip_allow]) {
item.ip_allow = node[TS_ip_allow].as<std::string>();
}
if (node[TS_valid_tls_versions_in]) {
for (unsigned int i = 0; i < node[TS_valid_tls_versions_in].size(); i++) {
auto value   = node[TS_valid_tls_versions_in][i].as<std::string>();
int protocol = TLS_PROTOCOLS_DESCRIPTOR.get(value);
item.EnableProtocol(static_cast<YamlSNIConfig::TLSProtocol>(protocol));
}
}
return true;
}

char *gf_text_get_utf8_line(char *szLine, u32 lineSize, FILE *txt_in, s32 unicode_type)
{
u32 i, j, len;
char *sOK;
char szLineConv[2048];
unsigned short *sptr;
memset(szLine, 0, sizeof(char)*lineSize);
sOK = gf_fgets(szLine, lineSize, txt_in);
if (!sOK) return NULL;
if (unicode_type<=1) {
j=0;
len = (u32) strlen(szLine);
for (i=0; i<len; i++) {
if (!unicode_type && (szLine[i] & 0x80)) {
if ((szLine[i+1] & 0xc0) != 0x80) {
szLineConv[j] = 0xc0 | ( (szLine[i] >> 6) & 0x3 );
j++;
szLine[i] &= 0xbf;
}
else if ( (szLine[i] & 0xe0) == 0xc0) {
szLineConv[j] = szLine[i];
i++;
j++;
}
else if ( (szLine[i] & 0xf0) == 0xe0) {
szLineConv[j] = szLine[i];
i++;
j++;
szLineConv[j] = szLine[i];
i++;
j++;
}
else if ( (szLine[i] & 0xf8) == 0xf0) {
szLineConv[j] = szLine[i];
i++;
j++;
szLineConv[j] = szLine[i];
i++;
j++;
szLineConv[j] = szLine[i];
i++;
j++;
} else {
i+=1;
continue;
}
}
szLineConv[j] = szLine[i];
j++;
}
szLineConv[j] = 0;
strcpy(szLine, szLineConv);
return sOK;
}
#ifdef GPAC_BIG_ENDIAN
if (unicode_type==3)
#else
if (unicode_type==2)
#endif
{
i=0;
while (1) {
char c;
if (!szLine[i] && !szLine[i+1]) break;
c = szLine[i+1];
szLine[i+1] = szLine[i];
szLine[i] = c;
i+=2;
}
}
sptr = (u16 *)szLine;
i = gf_utf8_wcstombs(szLineConv, 2048, (const unsigned short **) &sptr);
if (i == GF_UTF8_FAIL) i = 0;
szLineConv[i] = 0;
strcpy(szLine, szLineConv);
if (unicode_type==3) gf_fgetc(txt_in);
return sOK;
}

void SoftMPEG4::onQueueFilled(OMX_U32 ) {
if (mSignalledError || mOutputPortSettingsChange != NONE) {
return;
}
List<BufferInfo *> &inQueue = getPortQueue(0);
List<BufferInfo *> &outQueue = getPortQueue(1);
while (!inQueue.empty() && outQueue.size() == kNumOutputBuffers) {
BufferInfo *inInfo = *inQueue.begin();
OMX_BUFFERHEADERTYPE *inHeader = inInfo->mHeader;
if (inHeader == NULL) {
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
continue;
}
PortInfo *port = editPortInfo(1);
OMX_BUFFERHEADERTYPE *outHeader =
port->mBuffers.editItemAt(mNumSamplesOutput & 1).mHeader;
if (inHeader->nFilledLen == 0) {
inQueue.erase(inQueue.begin());
inInfo->mOwnedByUs = false;
notifyEmptyBufferDone(inHeader);
++mInputBufferCount;
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
outHeader->nFilledLen = 0;
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
List<BufferInfo *>::iterator it = outQueue.begin();
while ((*it)->mHeader != outHeader) {
++it;
}
BufferInfo *outInfo = *it;
outInfo->mOwnedByUs = false;
outQueue.erase(it);
outInfo = NULL;
notifyFillBufferDone(outHeader);
outHeader = NULL;
}
return;
}
uint8_t *bitstream = inHeader->pBuffer + inHeader->nOffset;
uint32_t *start_code = (uint32_t *)bitstream;
bool volHeader = *start_code == 0xB0010000;
if (volHeader) {
PVCleanUpVideoDecoder(mHandle);
mInitialized = false;
}
if (!mInitialized) {
uint8_t *vol_data[1];
int32_t vol_size = 0;
vol_data[0] = NULL;
if ((inHeader->nFlags & OMX_BUFFERFLAG_CODECCONFIG) || volHeader) {
vol_data[0] = bitstream;
vol_size = inHeader->nFilledLen;
}
MP4DecodingMode mode =
(mMode == MODE_MPEG4) ? MPEG4_MODE : H263_MODE;
Bool success = PVInitVideoDecoder(
mHandle, vol_data, &vol_size, 1,
outputBufferWidth(), outputBufferHeight(), mode);
if (!success) {
ALOGW("PVInitVideoDecoder failed. Unsupported content?");
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
return;
}
MP4DecodingMode actualMode = PVGetDecBitstreamMode(mHandle);
if (mode != actualMode) {
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
return;
}
PVSetPostProcType((VideoDecControls *) mHandle, 0);
bool hasFrameData = false;
if (inHeader->nFlags & OMX_BUFFERFLAG_CODECCONFIG) {
inInfo->mOwnedByUs = false;
inQueue.erase(inQueue.begin());
inInfo = NULL;
notifyEmptyBufferDone(inHeader);
inHeader = NULL;
} else if (volHeader) {
hasFrameData = true;
}
mInitialized = true;
if (mode == MPEG4_MODE && handlePortSettingsChange()) {
return;
}
if (!hasFrameData) {
continue;
}
}
if (!mFramesConfigured) {
PortInfo *port = editPortInfo(1);
OMX_BUFFERHEADERTYPE *outHeader = port->mBuffers.editItemAt(1).mHeader;
PVSetReferenceYUV(mHandle, outHeader->pBuffer);
mFramesConfigured = true;
}
uint32_t useExtTimestamp = (inHeader->nOffset == 0);
uint32_t timestamp = 0xFFFFFFFF;
if (useExtTimestamp) {
mPvToOmxTimeMap.add(mPvTime, inHeader->nTimeStamp);
timestamp = mPvTime;
mPvTime++;
}
int32_t bufferSize = inHeader->nFilledLen;
int32_t tmp = bufferSize;
if (PVDecodeVideoFrame(
mHandle, &bitstream, &timestamp, &tmp,
&useExtTimestamp,
outHeader->pBuffer) != PV_TRUE) {
ALOGE("failed to decode video frame.");
notify(OMX_EventError, OMX_ErrorUndefined, 0, NULL);
mSignalledError = true;
return;
}
if (handlePortSettingsChange()) {
return;
}
outHeader->nTimeStamp = mPvToOmxTimeMap.valueFor(timestamp);
mPvToOmxTimeMap.removeItem(timestamp);
inHeader->nOffset += bufferSize;
inHeader->nFilledLen = 0;
if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
outHeader->nFlags = OMX_BUFFERFLAG_EOS;
} else {
outHeader->nFlags = 0;
}
if (inHeader->nFilledLen == 0) {
inInfo->mOwnedByUs = false;
inQueue.erase(inQueue.begin());
inInfo = NULL;
notifyEmptyBufferDone(inHeader);
inHeader = NULL;
}
++mInputBufferCount;
outHeader->nOffset = 0;
outHeader->nFilledLen = (mWidth * mHeight * 3) / 2;
List<BufferInfo *>::iterator it = outQueue.begin();
while ((*it)->mHeader != outHeader) {
++it;
}
BufferInfo *outInfo = *it;
outInfo->mOwnedByUs = false;
outQueue.erase(it);
outInfo = NULL;
notifyFillBufferDone(outHeader);
outHeader = NULL;
++mNumSamplesOutput;
}
}

static int amd_gpio_remove(struct platform_device *pdev)
{
