opts.idle_timeout_secs = DEFAULT_IDLE_TIMEOUT;
fill_own_user();
for (i = 1; i < (unsigned int)argc; i++) {
if (argv[i][0] != '-')
{
if (host_arg == NULL) {
host_arg = argv[i];
