}
break;
}
opt = OPT_OTHER;
for (j = 1; (c = argv[i][j]) != '\0' && !next && opt == OPT_OTHER; j++) {
switch (c) {
case 'y': 
if (cli_opts.always_accept_key) {
cli_opts.no_hostkey_check = 1;
}
