static ssize_t
pxa3xx_gcu_write(struct file *file, const char *buff,
size_t count, loff_t *offp)
{
int ret;
unsigned long flags;
struct pxa3xx_gcu_batch*buffer;
struct pxa3xx_gcu_priv *priv = to_pxa3xx_gcu_priv(file);
int words = count / 4;
priv->shared->num_writes++;
priv->shared->num_words += words;
if (words >= PXA3XX_GCU_BATCH_WORDS)
return -E2BIG;
if (!priv->free) {
ret = pxa3xx_gcu_wait_free(priv);
if (ret < 0)
return ret;
}
spin_lock_irqsave(&priv->spinlock, flags);
buffer = priv->free;
priv->free = buffer->next;
spin_unlock_irqrestore(&priv->spinlock, flags);
ret = copy_from_user(buffer->ptr, buff, words * 4);
if (ret) {
spin_lock_irqsave(&priv->spinlock, flags);
buffer->next = priv->free;
priv->free = buffer;
spin_unlock_irqrestore(&priv->spinlock, flags);
return -EFAULT;
}
buffer->length = words;
buffer->ptr[words] = 0x01000000;
spin_lock_irqsave(&priv->spinlock, flags);
buffer->next = NULL;
if (priv->ready) {
BUG_ON(priv->ready_last == NULL);
priv->ready_last->next = buffer;
} else
priv->ready = buffer;
priv->ready_last = buffer;
if (!priv->shared->hw_running)
run_ready(priv);
spin_unlock_irqrestore(&priv->spinlock, flags);
return words * 4;
}

static SIXELSTATUS
gif_process_raster(
gif_context_t  *s,
gif_t          *g
)
{
SIXELSTATUS status = SIXEL_FALSE;
unsigned char lzw_cs;
signed int len, code;
unsigned int first;
signed int codesize, codemask, avail, oldcode, bits, valid_bits, clear;
gif_lzw *p;
lzw_cs = gif_get8(s);
clear = 1 << lzw_cs;
first = 1;
codesize = lzw_cs + 1;
codemask = (1 << codesize) - 1;
bits = 0;
valid_bits = 0;
for (code = 0; code < clear; code++) {
g->codes[code].prefix = -1;
g->codes[code].first = (unsigned char) code;
g->codes[code].suffix = (unsigned char) code;
}
avail = clear + 2;
oldcode = (-1);
len = 0;
for(;;) {
if (valid_bits < codesize) {
if (len == 0) {
len = gif_get8(s); 
if (len == 0) {
return SIXEL_OK;
}
}
--len;
bits |= (signed int) gif_get8(s) << valid_bits;
valid_bits += 8;
} else {
code = bits & codemask;
bits >>= codesize;
valid_bits -= codesize;
if (code == clear) {  
codesize = lzw_cs + 1;
codemask = (1 << codesize) - 1;
avail = clear + 2;
oldcode = -1;
first = 0;
} else if (code == clear + 1) { 
s->img_buffer += len;
while ((len = gif_get8(s)) > 0) {
s->img_buffer += len;
}
return SIXEL_OK;
} else if (code <= avail) {
if (first) {
sixel_helper_set_additional_message(
"corrupt GIF (reason: no clear code).");
status = SIXEL_RUNTIME_ERROR;
goto end;
}
if (oldcode >= 0) {
if (avail < 4096) {
p = &g->codes[avail++];
p->prefix = (signed short) oldcode;
p->first = g->codes[oldcode].first;
p->suffix = (code == avail) ? p->first : g->codes[code].first;
}
} else if (code == avail) {
sixel_helper_set_additional_message(
"corrupt GIF (reason: illegal code in raster).");
status = SIXEL_RUNTIME_ERROR;
goto end;
}
gif_out_code(g, (unsigned short) code);
if ((avail & codemask) == 0 && avail <= 0x0FFF) {
codesize++;
codemask = (1 << codesize) - 1;
}
oldcode = code;
} else {
sixel_helper_set_additional_message(
"corrupt GIF (reason: illegal code in raster).");
status = SIXEL_RUNTIME_ERROR;
goto end;
}
}
}
status = SIXEL_OK;
end:
return status;
}

int
dwarf_global_formref_b(Dwarf_Attribute attr,
Dwarf_Off * ret_offset,
Dwarf_Bool * offset_is_info,
Dwarf_Error * error)
{
Dwarf_Debug dbg = 0;
Dwarf_Unsigned offset = 0;
Dwarf_CU_Context cu_context = 0;
Dwarf_Half context_version = 0;
Dwarf_Byte_Ptr section_end = 0;
Dwarf_Bool is_info = TRUE;
int res  = get_attr_dbg(&dbg,&cu_context,attr,error);
if (res != DW_DLV_OK) {
return res;
}
section_end =
_dwarf_calculate_info_section_end_ptr(cu_context);
context_version = cu_context->cc_version_stamp;
is_info = cu_context->cc_is_info;
switch (attr->ar_attribute_form) {
case DW_FORM_ref1:
offset = *(Dwarf_Small *) attr->ar_debug_ptr;
goto fixoffset;
case DW_FORM_ref2:
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_HALF_SIZE,
error,section_end);
goto fixoffset;
case DW_FORM_ref4:
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_32BIT_SIZE,
error,section_end);
goto fixoffset;
case DW_FORM_ref8:
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_64BIT_SIZE,
error,section_end);
goto fixoffset;
case DW_FORM_ref_udata:
{
Dwarf_Byte_Ptr ptr = attr->ar_debug_ptr;
Dwarf_Unsigned localoffset = 0;
DECODE_LEB128_UWORD_CK(ptr,localoffset,
dbg,error,section_end);
offset = localoffset;
fixoffset: 
if (offset >= cu_context->cc_length +
cu_context->cc_length_size +
cu_context->cc_extension_size) {
_dwarf_error(dbg, error, DW_DLE_ATTR_FORM_OFFSET_BAD);
return DW_DLV_ERROR;
}
offset += cu_context->cc_debug_offset;
}
break;
case DW_FORM_data4:
if (context_version >= DW_CU_VERSION4) {
_dwarf_error(dbg, error, DW_DLE_NOT_REF_FORM);
return DW_DLV_ERROR;
}
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_32BIT_SIZE,
error, section_end);
break;
case DW_FORM_data8:
if (context_version >= DW_CU_VERSION4) {
_dwarf_error(dbg, error, DW_DLE_NOT_REF_FORM);
return DW_DLV_ERROR;
}
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_64BIT_SIZE,
error,section_end);
break;
case DW_FORM_ref_addr:
{
unsigned length_size = 0;
if (context_version == 2) {
length_size = cu_context->cc_address_size;
} else {
length_size = cu_context->cc_length_size;
}
if (length_size == 4) {
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_32BIT_SIZE,
error,section_end);
} else if (length_size == 8) {
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_64BIT_SIZE,
error,section_end);
} else {
_dwarf_error(dbg, error,
DW_DLE_FORM_SEC_OFFSET_LENGTH_BAD);
return DW_DLV_ERROR;
}
}
break;
case DW_FORM_loclistx:
case DW_FORM_rnglistx: {
unsigned length_size = cu_context->cc_length_size;
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, length_size,
error,section_end);
}
break;
case DW_FORM_sec_offset:
case DW_FORM_GNU_ref_alt:  
case DW_FORM_GNU_strp_alt: 
case DW_FORM_strp_sup:     
case DW_FORM_line_strp:    
{
unsigned length_size = cu_context->cc_length_size;
if (length_size == 4) {
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_32BIT_SIZE,
error,section_end);
} else if (length_size == 8) {
READ_UNALIGNED_CK(dbg, offset, Dwarf_Unsigned,
attr->ar_debug_ptr, DWARF_64BIT_SIZE,
error,section_end);
} else {
_dwarf_error(dbg, error,
DW_DLE_FORM_SEC_OFFSET_LENGTH_BAD);
return DW_DLV_ERROR;
}
}
break;
case DW_FORM_ref_sig8: {
Dwarf_Sig8 sig8;
Dwarf_Bool t_is_info = TRUE;
Dwarf_Unsigned t_offset = 0;
memcpy(&sig8,attr->ar_debug_ptr,sizeof(Dwarf_Sig8));
res = find_sig8_target_as_global_offset(attr,
&sig8,&t_is_info,&t_offset,error);
if (res == DW_DLV_ERROR) {
_dwarf_error_string(dbg, error,
DW_DLE_REF_SIG8_NOT_HANDLED,
"DW_DLE_REF_SIG8_NOT_HANDLED: "
" problem finding target");
return DW_DLV_ERROR;
}
if (res == DW_DLV_NO_ENTRY) {
return res;
}
is_info = t_is_info;
offset = t_offset;
break;
}
default: {
dwarfstring m;
int formcode = attr->ar_attribute_form;
int fcres = 0;
const char *name = 0;
dwarfstring_constructor(&m);
dwarfstring_append_printf_u(&m,
"DW_DLE_BAD_REF_FORM: The form code is 0x%x ",
formcode);
fcres  = dwarf_get_FORM_name (formcode,&name);
if (fcres != DW_DLV_OK) {
name="<UnknownFormCode>";
}
dwarfstring_append_printf_s(&m,
" %s.",(char *)name);
_dwarf_error_string(dbg, error, DW_DLE_BAD_REF_FORM,
dwarfstring_string(&m));
dwarfstring_destructor(&m);
return DW_DLV_ERROR;
}
}
*offset_is_info = is_info;
*ret_offset = offset;
return DW_DLV_OK;
}

