ErrorStatus ShimPreparedModel::parseInputs(
const Request& request, bool measure, int64_t deadlineNs, int64_t loopTimeoutDurationNs,
::android::nn::sl_wrapper::Execution* execution,
std::vector<std::shared_ptr<::android::nn::sl_wrapper::Memory>>* requestMemoryPools,
const std::vector<TokenValuePair>& executionHints,
const std::vector<ExtensionNameAndPrefix>& extensionNameToPrefix) {
for (const auto& requestPool : request.pools) {
switch (requestPool.getTag()) {
case RequestMemoryPool::pool: {
const auto& memoryPool = requestPool.get<RequestMemoryPool::pool>();
std::shared_ptr<::android::nn::sl_wrapper::Memory> mem =
convertFromHAL(mNnapi.get(), memoryPool);
if (!mem) {
LOG(ERROR) << "Failed to convert request HAL memory pools into SL memory";
return ErrorStatus::INVALID_ARGUMENT;
}
requestMemoryPools->push_back(mem);
break;
}
case RequestMemoryPool::token: {
int token = requestPool.get<RequestMemoryPool::token>();
auto memory = mBufferTracker->get(static_cast<uint32_t>(token));
if (memory == nullptr) {
return ErrorStatus::INVALID_ARGUMENT;
}
requestMemoryPools->push_back(memory);
break;
}
}
}
const auto enablePaddingResult = execution->enableInputAndOutputPadding(true);
if (enablePaddingResult != Result::NO_ERROR) {
return convertResultToErrorStatus(enablePaddingResult);
}
const auto& model = mMainAndReferencedModels[0];
for (int i = 0; i < request.inputs.size(); ++i) {
const auto& input = request.inputs[i];
::android::nn::wrapper::OperandType operandType = model.getOperands()[model.getInputs()[i]];
if (!input.hasNoValue) {
if (input.dimensions.size() > 0) {
operandType.updateDimensions(::android::nn::toUnsigned(input.dimensions).value());
}
auto result = execution->setInputFromMemory(
i, requestMemoryPools->at(input.location.poolIndex).get(),
input.location.offset, input.location.length, &operandType.operandType);
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
} else {
auto result = execution->setInput(i, nullptr, 0);
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
}
}
for (int i = 0; i < request.outputs.size(); ++i) {
const auto& output = request.outputs[i];
::android::nn::wrapper::OperandType operandType =
model.getOperands()[model.getOutputs()[i]];
if (!output.hasNoValue) {
if (output.dimensions.size() > 0) {
operandType.updateDimensions(::android::nn::toUnsigned(output.dimensions).value());
}
auto result = execution->setOutputFromMemory(
i, requestMemoryPools->at(output.location.poolIndex).get(),
output.location.offset, output.location.length, &operandType.operandType);
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
} else {
auto result = execution->setOutput(i, nullptr, 0);
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
}
}
if (measure) {
execution->setMeasureTiming(true);
}
if (deadlineNs > -1) {
std::chrono::time_point<::android::base::boot_clock> deadlinePoint(
std::chrono::nanoseconds{deadlineNs});
const auto currentTime = ::android::base::boot_clock::now();
const auto timeoutDuration = std::chrono::nanoseconds(deadlinePoint - currentTime);
if (timeoutDuration <= std::chrono::nanoseconds::zero()) {
return ErrorStatus::MISSED_DEADLINE_TRANSIENT;
} else {
auto result = execution->setTimeout(std::max<uint64_t>(1, timeoutDuration.count()));
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
}
}
if (loopTimeoutDurationNs > 0) {
execution->setLoopTimeout(loopTimeoutDurationNs);
}
if (!executionHints.empty() || !extensionNameToPrefix.empty()) {
std::unordered_map<uint16_t, std::string> prefixToName;
for (const auto [name, prefix] : extensionNameToPrefix) {
prefixToName.emplace(prefix, name);
}
for (const auto& [token, value] : executionHints) {
const auto uToken = static_cast<uint32_t>(token);
const auto prefix = ::android::nn::getExtensionPrefix(uToken);
const auto attributeCodeWithinExtension = ::android::nn::getTypeWithinExtension(uToken);
const auto it = prefixToName.find(prefix);
if (it == prefixToName.end()) {
return ErrorStatus::INVALID_ARGUMENT;
}
const std::string& extensionName = it->second;
const auto result = execution->addExtensionAttribute(
extensionName, attributeCodeWithinExtension, value);
if (result != Result::NO_ERROR) {
return convertResultToErrorStatus(result);
}
}
}
return ErrorStatus::NONE;
}

static int __init mbochs_dev_init(void)
{
int ret = 0;
ret = alloc_chrdev_region(&mbochs_devt, 0, MINORMASK + 1, MBOCHS_NAME);
if (ret < 0) {
pr_err("Error: failed to register mbochs_dev, err: %d\n", ret);
return ret;
}
cdev_init(&mbochs_cdev, &vd_fops);
cdev_add(&mbochs_cdev, mbochs_devt, MINORMASK + 1);
pr_info("%s: major %d\n", __func__, MAJOR(mbochs_devt));
ret = mdev_register_driver(&mbochs_driver);
if (ret)
goto err_cdev;
mbochs_class = class_create(THIS_MODULE, MBOCHS_CLASS_NAME);
if (IS_ERR(mbochs_class)) {
pr_err("Error: failed to register mbochs_dev class\n");
ret = PTR_ERR(mbochs_class);
goto err_driver;
}
mbochs_dev.class = mbochs_class;
mbochs_dev.release = mbochs_device_release;
dev_set_name(&mbochs_dev, "%s", MBOCHS_NAME);
ret = device_register(&mbochs_dev);
if (ret)
goto err_class;
ret = mdev_register_device(&mbochs_dev, &mdev_fops);
if (ret)
goto err_device;
return 0;
err_device:
device_unregister(&mbochs_dev);
err_class:
class_destroy(mbochs_class);
err_driver:
mdev_unregister_driver(&mbochs_driver);
err_cdev:
cdev_del(&mbochs_cdev);
unregister_chrdev_region(mbochs_devt, MINORMASK + 1);
return ret;
}

void gnrc_sixlowpan_frag_sfr_arq_timeout(gnrc_sixlowpan_frag_fb_t *fbuf)
{
uint32_t now = xtimer_now_usec() / US_PER_MS;
_frag_desc_t *frag_desc = (_frag_desc_t *)fbuf->sfr.window.next;
uint32_t next_arq_offset = fbuf->sfr.arq_timeout;
bool reschedule_arq_timeout = false;
int error_no = ETIMEDOUT;   
DEBUG("6lo sfr: ARQ timeout for datagram %u\n", fbuf->tag);
fbuf->sfr.arq_timeout_event.msg.content.ptr = NULL;
if (IS_ACTIVE(CONFIG_GNRC_SIXLOWPAN_SFR_MOCK_ARQ_TIMER)) {
now -= (fbuf->sfr.arq_timeout * US_PER_MS) + 1;
}
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR_CONGURE) && frag_desc) {
gnrc_sixlowpan_frag_sfr_congure_snd_report_frags_timeout(fbuf);
_shrink_window(fbuf);   
frag_desc = (_frag_desc_t *)fbuf->sfr.window.next;
}
_frag_desc_t * const head = frag_desc;
if (frag_desc) {
do {
uint32_t diff;
frag_desc = (_frag_desc_t *)frag_desc->super.super.next;
diff = now - frag_desc->super.send_time;
if (diff < fbuf->sfr.arq_timeout) {
uint32_t offset = fbuf->sfr.arq_timeout - diff;
DEBUG("6lo sfr: wait for fragment %u in next reschedule\n",
_frag_seq(frag_desc));
if (offset < next_arq_offset) {
next_arq_offset = offset;
DEBUG("         (next ARQ timeout in %lu)\n",
(long unsigned)next_arq_offset);
}
reschedule_arq_timeout = true;
}
else if (_frag_ack_req(frag_desc)) {
if ((frag_desc->super.resends++) < CONFIG_GNRC_SIXLOWPAN_SFR_FRAG_RETRIES) {
DEBUG("6lo sfr: %u retries left for fragment (tag: %u, "
"X: %i, seq: %u, frag_size: %u, offset: %u)\n",
CONFIG_GNRC_SIXLOWPAN_SFR_FRAG_RETRIES -
(frag_desc->super.resends - 1), (uint8_t)fbuf->tag,
_frag_ack_req(frag_desc), _frag_seq(frag_desc),
_frag_size(frag_desc), frag_desc->offset);
if (_resend_frag(&frag_desc->super.super, fbuf) != 0) {
error_no = ENOMEM;
goto error;
}
else {
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR_CONGURE)) {
gnrc_sixlowpan_frag_sfr_congure_snd_report_frag_sent(fbuf);
}
if (IS_USED(MODULE_GNRC_SIXLOWPAN_FRAG_SFR_STATS)) {
_stats.fragment_resends.by_timeout++;
}
}
reschedule_arq_timeout = true;
}
else {
DEBUG("6lo sfr: no retries left for fragment "
"(tag: %u, X: %i, seq: %u, frag_size: %u, "
"offset: %u)\n",
(uint8_t)fbuf->tag, _frag_ack_req(frag_desc),
_frag_seq(frag_desc), _frag_size(frag_desc),
frag_desc->offset);
_retry_datagram(fbuf);
return;
}
}
else {
DEBUG("6lo sfr: nothing to do for fragment %u\n",
_frag_seq(frag_desc));
}
} while (frag_desc != head);
clist_foreach(&fbuf->sfr.window, _report_non_ack_req_window_sent, fbuf);
}
else {
error_no = GNRC_NETERR_SUCCESS;
}
assert(fbuf->sfr.frags_sent == clist_count(&fbuf->sfr.window));
if (reschedule_arq_timeout) {
_sched_arq_timeout(fbuf, next_arq_offset);
return;
}
error:
_send_abort_frag(fbuf->pkt, fbuf, false, 0);
_clean_up_fbuf(fbuf, error_no);
}

static int slimpro_i2c_blkwr(struct slimpro_i2c_dev *ctx, u32 chip,
u32 addr, u32 addrlen, u32 protocol, u32 writelen,
void *data)
{
dma_addr_t paddr;
u32 msg[3];
int rc;
memcpy(ctx->dma_buffer, data, writelen);
paddr = dma_map_single(ctx->dev, ctx->dma_buffer, writelen,
DMA_TO_DEVICE);
if (dma_mapping_error(ctx->dev, paddr)) {
dev_err(&ctx->adapter.dev, "Error in mapping dma buffer %p\n",
ctx->dma_buffer);
return -ENOMEM;
}
msg[0] = SLIMPRO_IIC_ENCODE_MSG(SLIMPRO_IIC_BUS, chip, SLIMPRO_IIC_WRITE,
protocol, addrlen, writelen);
msg[1] = SLIMPRO_IIC_ENCODE_FLAG_BUFADDR |
SLIMPRO_IIC_ENCODE_UPPER_BUFADDR(paddr) |
SLIMPRO_IIC_ENCODE_ADDR(addr);
msg[2] = (u32)paddr;
if (ctx->mbox_client.tx_block)
reinit_completion(&ctx->rd_complete);
rc = slimpro_i2c_send_msg(ctx, msg, msg);
dma_unmap_single(ctx->dev, paddr, writelen, DMA_TO_DEVICE);
return rc;
}

int nbd_client_co_pdiscard(BlockDriverState *bs, int64_t offset, int count)
{
NBDClientSession *client = nbd_get_client_session(bs);
NBDRequest request = {
.type = NBD_CMD_TRIM,
.from = offset,
.len = count,
};
NBDReply reply;
ssize_t ret;
if (!(client->nbdflags & NBD_FLAG_SEND_TRIM)) {
return 0;
}
nbd_coroutine_start(client, &request);
ret = nbd_co_send_request(bs, &request, NULL);
if (ret < 0) {
reply.error = -ret;
} else {
nbd_co_receive_reply(client, &request, &reply, NULL);
}
nbd_coroutine_end(client, &request);
return -reply.error;
}

static void dom_load_html(INTERNAL_FUNCTION_PARAMETERS, int mode) 
{
zval *id;
xmlDoc *docp = NULL, *newdoc;
dom_object *intern;
dom_doc_propsptr doc_prop;
char *source;
int source_len, refcount, ret;
long options = 0;
htmlParserCtxtPtr ctxt;
id = getThis();
if (zend_parse_parameters(ZEND_NUM_ARGS() TSRMLS_CC, "p|l", &source, &source_len, &options) == FAILURE) {
return;
}
if (!source_len) {
php_error_docref(NULL TSRMLS_CC, E_WARNING, "Empty string supplied as input");
RETURN_FALSE;
}
if (mode == DOM_LOAD_FILE) {
ctxt = htmlCreateFileParserCtxt(source, NULL);
} else {
source_len = xmlStrlen(source);
ctxt = htmlCreateMemoryParserCtxt(source, source_len);
}
if (!ctxt) {
RETURN_FALSE;
}
if (options) {
htmlCtxtUseOptions(ctxt, options);
}
ctxt->vctxt.error = php_libxml_ctx_error;
ctxt->vctxt.warning = php_libxml_ctx_warning;
if (ctxt->sax != NULL) {
ctxt->sax->error = php_libxml_ctx_error;
ctxt->sax->warning = php_libxml_ctx_warning;
}
htmlParseDocument(ctxt);
newdoc = ctxt->myDoc;
htmlFreeParserCtxt(ctxt);
if (!newdoc)
RETURN_FALSE;
if (id != NULL && instanceof_function(Z_OBJCE_P(id), dom_document_class_entry TSRMLS_CC)) {
intern = (dom_object *)zend_object_store_get_object(id TSRMLS_CC);
if (intern != NULL) {
docp = (xmlDocPtr) dom_object_get_node(intern);
doc_prop = NULL;
if (docp != NULL) {
php_libxml_decrement_node_ptr((php_libxml_node_object *) intern TSRMLS_CC);
doc_prop = intern->document->doc_props;
intern->document->doc_props = NULL;
refcount = php_libxml_decrement_doc_ref((php_libxml_node_object *)intern TSRMLS_CC);
if (refcount != 0) {
docp->_private = NULL;
}
}
intern->document = NULL;
if (php_libxml_increment_doc_ref((php_libxml_node_object *)intern, newdoc TSRMLS_CC) == -1) {
RETURN_FALSE;
}
intern->document->doc_props = doc_prop;
}
php_libxml_increment_node_ptr((php_libxml_node_object *)intern, (xmlNodePtr)newdoc, (void *)intern TSRMLS_CC);
RETURN_TRUE;
} else {
DOM_RET_OBJ((xmlNodePtr) newdoc, &ret, NULL);
}
}

static void usb_ohci_init(OHCIState *ohci, DeviceState *dev,
int num_ports, dma_addr_t localmem_base,
char *masterbus, uint32_t firstport,
AddressSpace *as, Error **errp)
{
Error *err = NULL;
int i;
ohci->as = as;
if (usb_frame_time == 0) {
#ifdef OHCI_TIME_WARP
usb_frame_time = get_ticks_per_sec();
usb_bit_time = muldiv64(1, get_ticks_per_sec(), USB_HZ/1000);
#else
usb_frame_time = muldiv64(1, get_ticks_per_sec(), 1000);
if (get_ticks_per_sec() >= USB_HZ) {
usb_bit_time = muldiv64(1, get_ticks_per_sec(), USB_HZ);
} else {
usb_bit_time = 1;
}
#endif
trace_usb_ohci_init_time(usb_frame_time, usb_bit_time);
}
ohci->num_ports = num_ports;
if (masterbus) {
USBPort *ports[OHCI_MAX_PORTS];
for(i = 0; i < num_ports; i++) {
ports[i] = &ohci->rhport[i].port;
}
usb_register_companion(masterbus, ports, num_ports,
firstport, ohci, &ohci_port_ops,
USB_SPEED_MASK_LOW | USB_SPEED_MASK_FULL,
&err);
if (err) {
error_propagate(errp, err);
return;
}
} else {
usb_bus_new(&ohci->bus, sizeof(ohci->bus), &ohci_bus_ops, dev);
for (i = 0; i < num_ports; i++) {
usb_register_port(&ohci->bus, &ohci->rhport[i].port,
ohci, i, &ohci_port_ops,
USB_SPEED_MASK_LOW | USB_SPEED_MASK_FULL);
}
}
memory_region_init_io(&ohci->mem, OBJECT(dev), &ohci_mem_ops,
ohci, "ohci", 256);
ohci->localmem_base = localmem_base;
ohci->name = object_get_typename(OBJECT(dev));
usb_packet_init(&ohci->usb_packet);
ohci->async_td = 0;
}

static int SetupSavePath(const DetectEngineCtx *de_ctx,
char *save, size_t save_size)
{
