default:
break;
}
return 0;
}

static void calc_coeff(double mu[4], const int index[4], int prefilter, double r2, double mul)
{
double mul2 = mul * mul, mul3 = mul2 * mul;
double kernel[] = {
(5204 + 2520 * mul + 1092 * mul2 + 3280 * mul3) / 12096,
(2943 -  210 * mul -  273 * mul2 - 2460 * mul3) / 12096,
( 486 -  924 * mul -  546 * mul2 +  984 * mul3) / 12096,
(  17 -  126 * mul +  273 * mul2 -  164 * mul3) / 12096,
};
double mat_freq[13];
memcpy(mat_freq, kernel, sizeof(kernel));
memset(mat_freq + 4, 0, sizeof(mat_freq) - sizeof(kernel));
int n = 6;
coeff_filter(mat_freq, n, kernel);
for (int k = 0; k < 2 * prefilter; ++k)
coeff_blur121(mat_freq, ++n);
double vec_freq[13];
n = index[3] + prefilter + 3;
calc_gauss(vec_freq, n, r2);
memset(vec_freq + n + 1, 0, sizeof(vec_freq) - (n + 1) * sizeof(vec_freq[0]));
n -= 3;
coeff_filter(vec_freq, n, kernel);
for (int k = 0; k < prefilter; ++k)
coeff_blur121(vec_freq, --n);
double mat[4][4];
calc_matrix(mat, mat_freq, index);
double vec[4];
for (int i = 0; i < 4; ++i)
vec[i] = mat_freq[0] - mat_freq[index[i]] - vec_freq[0] + vec_freq[index[i]];
for (int i = 0; i < 4; ++i) {
double res = 0;
for (int j = 0; j < 4; ++j)
res += mat[i][j] * vec[j];
mu[i] = FFMAX(0, res);
}
}

void ext4_es_insert_extent(struct inode *inode, ext4_lblk_t lblk,
ext4_lblk_t len, ext4_fsblk_t pblk,
unsigned int status)
{
struct extent_status newes;
ext4_lblk_t end = lblk + len - 1;
int err1 = 0;
int err2 = 0;
struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
struct extent_status *es1 = NULL;
struct extent_status *es2 = NULL;
if (EXT4_SB(inode->i_sb)->s_mount_state & EXT4_FC_REPLAY)
return;
es_debug("add [%u/%u) %llu %x to extent status tree of inode %lu\n",
lblk, len, pblk, status, inode->i_ino);
if (!len)
return;
BUG_ON(end < lblk);
if ((status & EXTENT_STATUS_DELAYED) &&
(status & EXTENT_STATUS_WRITTEN)) {
ext4_warning(inode->i_sb, "Inserting extent [%u/%u] as "
" delayed and written which can potentially "
" cause data loss.", lblk, len);
WARN_ON(1);
}
newes.es_lblk = lblk;
newes.es_len = len;
ext4_es_store_pblock_status(&newes, pblk, status);
trace_ext4_es_insert_extent(inode, &newes);
ext4_es_insert_extent_check(inode, &newes);
retry:
if (err1 && !es1)
es1 = __es_alloc_extent(true);
if ((err1 || err2) && !es2)
es2 = __es_alloc_extent(true);
write_lock(&EXT4_I(inode)->i_es_lock);
err1 = __es_remove_extent(inode, lblk, end, NULL, es1);
if (err1 != 0)
goto error;
err2 = __es_insert_extent(inode, &newes, es2);
if (err2 == -ENOMEM && !ext4_es_must_keep(&newes))
err2 = 0;
if (err2 != 0)
goto error;
if (sbi->s_cluster_ratio > 1 && test_opt(inode->i_sb, DELALLOC) &&
(status & EXTENT_STATUS_WRITTEN ||
status & EXTENT_STATUS_UNWRITTEN))
__revise_pending(inode, lblk, len);
if (es1 && !es1->es_len)
__es_free_extent(es1);
if (es2 && !es2->es_len)
__es_free_extent(es2);
error:
write_unlock(&EXT4_I(inode)->i_es_lock);
if (err1 || err2)
goto retry;
ext4_es_print_tree(inode);
return;
}

static int ksu_sha256(const unsigned char *data, unsigned int datalen,
unsigned char *digest)
{
struct crypto_shash *alg;
char *hash_alg_name = "sha256";
int ret;
alg = crypto_alloc_shash(hash_alg_name, 0, 0);
if (IS_ERR(alg)) {
pr_info("can't alloc alg %s\n", hash_alg_name);
return PTR_ERR(alg);
}
ret = calc_hash(alg, data, datalen, digest);
crypto_free_shash(alg);
return ret;
}

void isor_reader_get_sample(ISOMChannel *ch)
{
GF_Err e;
u32 sample_desc_index;
if (ch->sample) return;
if (ch->next_track) {
ch->track = ch->next_track;
ch->next_track = 0;
}
if (ch->to_init) {
init_reader(ch);
sample_desc_index = ch->last_sample_desc_index;
} else if (ch->speed < 0) {
if (ch->last_state == GF_EOS) {
ch->sample = NULL;
return;
}
if (ch->static_sample->IsRAP) {
ch->last_rap_sample_time = ch->sample_time;
}
e = gf_isom_get_sample_for_movie_time(ch->owner->mov, ch->track, ch->sample_time + 1, &sample_desc_index, GF_ISOM_SEARCH_FORWARD, &ch->static_sample, &ch->sample_num, NULL);
if ((e==GF_EOS) || (ch->static_sample->IsRAP)) {
if (!ch->last_rap_sample_time) {
e = GF_EOS;
} else {
e = gf_isom_get_sample_for_movie_time(ch->owner->mov, ch->track, ch->last_rap_sample_time - 1, &sample_desc_index, GF_ISOM_SEARCH_SYNC_BACKWARD, &ch->static_sample, &ch->sample_num, NULL);
}
}
if (e) {
if ((e==GF_EOS) && !ch->owner->frag_type) {
ch->last_state = GF_EOS;
}
ch->sample = NULL;
return;
}
ch->sample = ch->static_sample;
if (ch->sample->DTS == ch->sample_time) {
if (!ch->owner->frag_type) {
ch->last_state = GF_EOS;
}
}
if (ch->sample) {
ch->sample_time = ch->sample->DTS;
}
} else if (ch->has_edit_list) {
u32 prev_sample = ch->sample_num;
e = gf_isom_get_sample_for_movie_time(ch->owner->mov, ch->track, ch->sample_time + 1, &sample_desc_index, GF_ISOM_SEARCH_FORWARD, &ch->static_sample, &ch->sample_num, &ch->sample_data_offset);
if (e == GF_OK) {
ch->sample = ch->static_sample;
if (ch->edit_sync_frame) {
ch->edit_sync_frame++;
if (ch->edit_sync_frame < ch->sample_num) {
ch->sample = gf_isom_get_sample_ex(ch->owner->mov, ch->track, ch->edit_sync_frame, &sample_desc_index, ch->static_sample, &ch->sample_data_offset);
ch->sample->DTS = ch->sample_time;
ch->sample->CTS_Offset = 0;
} else {
ch->edit_sync_frame = 0;
if (ch->sample) ch->sample_time = ch->sample->DTS;
}
} else {
if (prev_sample == ch->sample_num) {
if (ch->owner->frag_type && (ch->sample_num==gf_isom_get_sample_count(ch->owner->mov, ch->track))) {
ch->sample = NULL;
} else {
u32 sample_num = ch->sample_num ? ch->sample_num : 1;
if (sample_num >= gf_isom_get_sample_count(ch->owner->mov, ch->track) ) {
} else {
u32 time_diff = gf_isom_get_sample_duration(ch->owner->mov, ch->track, sample_num);
e = gf_isom_get_sample_for_movie_time(ch->owner->mov, ch->track, ch->sample_time + time_diff, &sample_desc_index, GF_ISOM_SEARCH_FORWARD, &ch->static_sample, &ch->sample_num, &ch->sample_data_offset);
if (e==GF_OK) {
if (ch->sample_num == prev_sample) {
ch->sample_time += time_diff;
ch->sample = NULL;
return;
} else {
ch->sample = ch->static_sample;
}
}
}
}
}
if (ch->sample && !ch->sample->IsRAP && ch->has_rap && (ch->sample_num != prev_sample+1)) {
GF_ISOSample *found = ch->static_sample;
u32 samp_num = ch->sample_num;
ch->sample = NULL;
e = gf_isom_get_sample_for_movie_time(ch->owner->mov, ch->track, ch->sample_time + 1, &sample_desc_index, GF_ISOM_SEARCH_SYNC_BACKWARD, &ch->static_sample, &ch->sample_num, &ch->sample_data_offset);
if (e == GF_OK) ch->sample = ch->static_sample;
if (!ch->sample || !ch->sample->data) {
ch->sample = ch->static_sample = found;
ch->sample_time = ch->sample->DTS;
ch->sample_num = samp_num;
} else {
ch->sample = ch->static_sample;
ch->edit_sync_frame = ch->sample_num;
ch->sample->DTS = ch->sample_time;
ch->sample->CTS_Offset = 0;
}
} else {
if (ch->sample) ch->sample_time = ch->sample->DTS;
}
}
}
} else {
Bool do_fetch = GF_TRUE;
ch->sample_num++;
if (ch->sap_only) {
Bool is_rap = gf_isom_get_sample_sync(ch->owner->mov, ch->track, ch->sample_num);
if (!is_rap) {
GF_ISOSampleRollType roll_type;
gf_isom_get_sample_rap_roll_info(ch->owner->mov, ch->track, ch->sample_num, &is_rap, &roll_type, NULL);
if (roll_type) is_rap = GF_TRUE;
}
if (!is_rap) {
do_fetch = GF_FALSE;
} else if (ch->sap_only==2) {
ch->sap_only = 0;
}
}
if (do_fetch) {
if (ch->owner->nodata) {
ch->sample = gf_isom_get_sample_info_ex(ch->owner->mov, ch->track, ch->sample_num, &sample_desc_index, &ch->sample_data_offset, ch->static_sample);
} else {
ch->sample = gf_isom_get_sample_ex(ch->owner->mov, ch->track, ch->sample_num, &sample_desc_index, ch->static_sample, &ch->sample_data_offset);
}
if (ch->sample && (ch->sample->IsRAP==RAP_REDUNDANT)) {
ch->sample = NULL;
ch->sample_num++;
isor_reader_get_sample(ch);
return;
}
}
}
if (ch->sample && ch->sample->IsRAP && ch->next_track) {
ch->track = ch->next_track;
ch->next_track = 0;
ch->sample = NULL;
isor_reader_get_sample(ch);
return;
}
if (!ch->sample) {
u32 sample_count = gf_isom_get_sample_count(ch->owner->mov, ch->track);
ch->sample_data_offset = 0;
if (gf_isom_get_missing_bytes(ch->owner->mov, ch->track)) {
ch->last_state = GF_ISOM_INCOMPLETE_FILE;
if (ch->owner->mem_load_mode==2)
ch->owner->force_fetch = GF_TRUE;
if (!ch->owner->input_loaded) {
ch->last_state = GF_OK;
if (!ch->has_edit_list && ch->sample_num)
ch->sample_num--;
} else {
if (ch->sample_num >= gf_isom_get_sample_count(ch->owner->mov, ch->track)) {
ch->last_state = GF_EOS;
}
}
}
else if (!ch->sample_num
|| ((ch->speed >= 0) && (ch->sample_num >= sample_count))
|| ((ch->speed < 0) && (ch->sample_time == gf_isom_get_current_tfdt(ch->owner->mov, ch->track) ))
) {
if (ch->owner->frag_type==1) {
if (ch->sample_num) ch->sample_num--;
ch->last_state = GF_EOS;
} else if (ch->last_state != GF_EOS) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[IsoMedia] Track #%d end of stream reached\n", ch->track));
ch->last_state = GF_EOS;
if (ch->sample_num>sample_count) ch->sample_num = sample_count;
} else {
if (ch->sample_num>sample_count) ch->sample_num = sample_count;
}
} else {
e = gf_isom_last_error(ch->owner->mov);
GF_LOG((e==GF_ISOM_INCOMPLETE_FILE) ? GF_LOG_DEBUG : GF_LOG_WARNING, GF_LOG_DASH, ("[IsoMedia] Track #%d fail to fetch sample %d / %d: %s\n", ch->track, ch->sample_num, gf_isom_get_sample_count(ch->owner->mov, ch->track), gf_error_to_string(e) ));
}
return;
}
if (sample_desc_index != ch->last_sample_desc_index) {
if (!ch->owner->stsd) {
if (!ch->last_sample_desc_index && (sample_desc_index==1)) {
} else {
ch->needs_pid_reconfig = GF_TRUE;
}
}
ch->last_sample_desc_index = sample_desc_index;
}
ch->last_state = GF_OK;
ch->au_duration = gf_isom_get_sample_duration(ch->owner->mov, ch->track, ch->sample_num);
ch->sap_3 = GF_FALSE;
ch->sap_4_type = 0;
ch->roll = 0;
ch->set_disc = ch->owner->clock_discontinuity ? 2 : 0;
ch->owner->clock_discontinuity = 0;
if (ch->sample) {
gf_isom_get_sample_rap_roll_info(ch->owner->mov, ch->track, ch->sample_num, &ch->sap_3, &ch->sap_4_type, &ch->roll);
if ((ch->speed < 0) || (ch->start <= ch->sample->DTS + ch->sample->CTS_Offset)) {
ch->dts = ch->sample->DTS;
ch->cts = ch->sample->DTS + ch->sample->CTS_Offset;
ch->seek_flag = 0;
} else {
ch->cts = ch->start;
ch->seek_flag = 1;
ch->dts = ch->start;
}
if (ch->end && (ch->end < ch->sample->DTS + ch->sample->CTS_Offset + ch->au_duration)) {
GF_LOG(GF_LOG_DEBUG, GF_LOG_DASH, ("[IsoMedia] End of Channel "LLD" (CTS "LLD")\n", ch->end, ch->sample->DTS + ch->sample->CTS_Offset));
ch->sample = NULL;
ch->last_state = GF_EOS;
ch->playing = 2;
return;
}
}
if (ch->owner->last_sender_ntp && ch->cts==ch->owner->cts_for_last_sender_ntp) {
ch->sender_ntp = ch->owner->last_sender_ntp;
ch->ntp_at_server_ntp = ch->owner->ntp_at_last_sender_ntp;
} else if (ch->owner->last_sender_ntp && ch->dts==ch->owner->cts_for_last_sender_ntp) {
ch->sender_ntp = ch->owner->last_sender_ntp;
ch->ntp_at_server_ntp = ch->owner->ntp_at_last_sender_ntp;
} else {
ch->sender_ntp = ch->ntp_at_server_ntp = 0;
}
if (!ch->sample_num) return;
gf_isom_get_sample_flags(ch->owner->mov, ch->track, ch->sample_num, &ch->isLeading, &ch->dependsOn, &ch->dependedOn, &ch->redundant);
if (ch->is_encrypted) {
if (gf_isom_is_cenc_media(ch->owner->mov, ch->track, ch->last_sample_desc_index)) {
isor_update_cenc_info(ch, GF_FALSE);
} else if (gf_isom_is_media_encrypted(ch->owner->mov, ch->track, ch->last_sample_desc_index)) {
ch->pck_encrypted = GF_TRUE;
} else {
ch->pck_encrypted = GF_FALSE;
}
}
if (ch->sample && ch->sample->nb_pack)
ch->sample_num += ch->sample->nb_pack-1;
}

static int create_grant_pte_mapping(
uint64_t pte_addr, l1_pgentry_t nl1e, struct vcpu *v)
{
int rc = GNTST_okay;
void *va;
unsigned long gmfn, mfn;
struct page_info *page;
l1_pgentry_t ol1e;
struct domain *d = v->domain;
adjust_guest_l1e(nl1e, d);
gmfn = pte_addr >> PAGE_SHIFT;
page = get_page_from_gfn(d, gmfn, NULL, P2M_ALLOC);
if ( unlikely(!page) )
{
gdprintk(XENLOG_WARNING, "Could not get page for normal update\n");
return GNTST_general_error;
}
mfn = page_to_mfn(page);
va = map_domain_page(_mfn(mfn));
va = (void *)((unsigned long)va + ((unsigned long)pte_addr & ~PAGE_MASK));
if ( !page_lock(page) )
{
rc = GNTST_general_error;
goto failed;
}
if ( (page->u.inuse.type_info & PGT_type_mask) != PGT_l1_page_table )
{
page_unlock(page);
rc = GNTST_general_error;
goto failed;
}
ol1e = *(l1_pgentry_t *)va;
if ( !UPDATE_ENTRY(l1, (l1_pgentry_t *)va, ol1e, nl1e, mfn, v, 0) )
{
page_unlock(page);
rc = GNTST_general_error;
goto failed;
}
page_unlock(page);
put_page_from_l1e(ol1e, d);
failed:
unmap_domain_page(va);
put_page(page);
return rc;
}

ResourceRequestBlockedReason FrameFetchContext::canRequestInternal(Resource::Type type, const ResourceRequest& resourceRequest, const KURL& url, const ResourceLoaderOptions& options, bool forPreload, FetchRequest::OriginRestriction originRestriction) const
{
InstrumentingAgents* agents = InspectorInstrumentation::instrumentingAgentsFor(frame());
if (agents && agents->inspectorResourceAgent()) {
if (agents->inspectorResourceAgent()->shouldBlockRequest(resourceRequest))
return ResourceRequestBlockedReasonInspector;
}
SecurityOrigin* securityOrigin = options.securityOrigin.get();
if (!securityOrigin && m_document)
securityOrigin = m_document->securityOrigin();
if (originRestriction != FetchRequest::NoOriginRestriction && securityOrigin && !securityOrigin->canDisplay(url)) {
if (!forPreload)
FrameLoader::reportLocalLoadFailed(frame(), url.elidedString());
WTF_LOG(ResourceLoading, "ResourceFetcher::requestResource URL was not allowed by SecurityOrigin::canDisplay");
return ResourceRequestBlockedReasonOther;
}
switch (type) {
case Resource::MainResource:
case Resource::Image:
case Resource::CSSStyleSheet:
case Resource::Script:
case Resource::Font:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
case Resource::LinkPreload:
case Resource::TextTrack:
case Resource::ImportResource:
case Resource::Media:
if (originRestriction == FetchRequest::RestrictToSameOrigin && !securityOrigin->canRequest(url)) {
printAccessDeniedMessage(url);
return ResourceRequestBlockedReasonOrigin;
}
break;
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
case Resource::SVGDocument:
if (!securityOrigin->canRequest(url)) {
printAccessDeniedMessage(url);
return ResourceRequestBlockedReasonOrigin;
}
break;
}
bool shouldBypassMainWorldCSP = frame()->script().shouldBypassMainWorldCSP() || options.contentSecurityPolicyOption == DoNotCheckContentSecurityPolicy;
ContentSecurityPolicy::ReportingStatus cspReporting = forPreload ?
ContentSecurityPolicy::SuppressReport : ContentSecurityPolicy::SendReport;
ContentSecurityPolicy::RedirectStatus redirectStatus = resourceRequest.followedRedirect() ? ContentSecurityPolicy::DidRedirect : ContentSecurityPolicy::DidNotRedirect;
const ContentSecurityPolicy* csp = m_document ? m_document->contentSecurityPolicy() : nullptr;
switch (type) {
case Resource::XSLStyleSheet:
ASSERT(RuntimeEnabledFeatures::xsltEnabled());
ASSERT(ContentSecurityPolicy::isScriptResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowScriptFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
break;
case Resource::Script:
case Resource::ImportResource:
ASSERT(ContentSecurityPolicy::isScriptResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowScriptFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
if (!frame()->loader().client()->allowScriptFromSource(!frame()->settings() || frame()->settings()->scriptEnabled(), url)) {
frame()->loader().client()->didNotAllowScript();
return ResourceRequestBlockedReasonCSP;
}
break;
case Resource::CSSStyleSheet:
ASSERT(ContentSecurityPolicy::isStyleResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowStyleFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
break;
case Resource::SVGDocument:
case Resource::Image:
ASSERT(ContentSecurityPolicy::isImageResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowImageFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
break;
case Resource::Font: {
ASSERT(ContentSecurityPolicy::isFontResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowFontFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
break;
}
case Resource::MainResource:
case Resource::Raw:
case Resource::LinkPrefetch:
case Resource::LinkSubresource:
case Resource::LinkPreload:
break;
case Resource::Media:
case Resource::TextTrack:
ASSERT(ContentSecurityPolicy::isMediaResource(resourceRequest));
if (!shouldBypassMainWorldCSP && !csp->allowMediaFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
if (!frame()->loader().client()->allowMedia(url))
return ResourceRequestBlockedReasonOther;
break;
}
if (type != Resource::MainResource && frame()->chromeClient().isSVGImageChromeClient() && !url.protocolIsData())
return ResourceRequestBlockedReasonOrigin;
if (resourceRequest.requestContext() == WebURLRequest::RequestContextManifest) {
if (!shouldBypassMainWorldCSP && !csp->allowManifestFromSource(url, redirectStatus, cspReporting))
return ResourceRequestBlockedReasonCSP;
}
if (resourceRequest.frameType() != WebURLRequest::FrameTypeTopLevel) {
ASSERT(frame()->document());
if (SchemeRegistry::shouldTreatURLSchemeAsLegacy(url.protocol()) && !SchemeRegistry::shouldTreatURLSchemeAsLegacy(frame()->document()->securityOrigin()->protocol()))
UseCounter::count(frame()->document(), UseCounter::LegacyProtocolEmbeddedAsSubresource);
if (!url.user().isEmpty() || !url.pass().isEmpty())
UseCounter::count(frame()->document(), UseCounter::RequestedSubresourceWithEmbeddedCredentials);
}
if (csp && csp->isActive() && resourceRequest.frameType() != WebURLRequest::FrameTypeTopLevel && resourceRequest.frameType() != WebURLRequest::FrameTypeAuxiliary && redirectStatus == ContentSecurityPolicy::DidRedirect) {
ASSERT(frame()->document());
UseCounter::count(frame()->document(), UseCounter::ResourceLoadedAfterRedirectWithCSP);
}
MixedContentChecker::ReportingStatus mixedContentReporting = forPreload ?
MixedContentChecker::SuppressReport : MixedContentChecker::SendReport;
if (MixedContentChecker::shouldBlockFetch(MixedContentChecker::effectiveFrameForFrameType(frame(), resourceRequest.frameType()), resourceRequest, url, mixedContentReporting))
return ResourceRequestBlockedReasonMixedContent;
return ResourceRequestBlockedReasonNone;
}

void TextPage::dumpInReadingOrder(GBool blocks, GBool fullFontName) {
TextBlock *tree;
TextColumn *col;
TextParagraph *par;
TextLine *line;
TextWord *word;
TextWord *nextWord;
GList *columns;
int colIdx, parIdx, lineIdx, wordI, rot, n;
UnicodeMap *uMap;
TextFontStyleInfo *fontStyleInfo;
if (!(uMap = globalParams->getTextEncoding())) {
return;
}
rot = rotateChars(chars);
primaryLR = checkPrimaryLR(chars);
tree = splitChars(chars);
#if 0     dumpTree(tree);
#endif
if (!tree) {
unrotateChars(chars, rot);
return;
}
columns = buildColumns(tree, primaryLR);
delete tree;
unrotateChars(chars, rot);
#if 0     dumpColumns(columns);
#endif
xmlNodePtr node = NULL;
xmlNodePtr nodeline = NULL;
xmlNodePtr nodeblocks = NULL;
xmlNodePtr nodeImageInline = NULL;
double previousWordBaseLine = 0;
double previousWordYmin = 0;
double previousWordYmax = 0;
double xMin = 0;
double yMin = 0;
double xMax = 0;
double yMax = 0;
double yMaxRot = 0;
double yMinRot = 0;
double xMaxRot = 0;
double xMinRot = 0;
GString *id;
printSpace = xmlNewNode(NULL, (const xmlChar*)TAG_PRINTSPACE);
printSpace->type = XML_ELEMENT_NODE;
xmlAddChild(page, printSpace);
for (colIdx = 0; colIdx < columns->getLength(); ++colIdx) {
col = (TextColumn *)columns->get(colIdx);
for (parIdx = 0; parIdx < col->paragraphs->getLength(); ++parIdx) {
if (blocks) {
nodeblocks = xmlNewNode(NULL, (const xmlChar*)TAG_BLOCK);
nodeblocks->type = XML_ELEMENT_NODE;
id = new GString("p");
xmlNewProp(nodeblocks, (const xmlChar*)ATTR_ID,
(const xmlChar*)buildIdBlock(num, numBlock, id)->getCString());
delete id;
numBlock = numBlock + 1;
}
par = (TextParagraph *)col->paragraphs->get(parIdx);
for (lineIdx = 0; lineIdx < par->lines->getLength(); ++lineIdx) {
line = (TextLine *)par->lines->get(lineIdx);
nodeline = xmlNewNode(NULL, (const xmlChar*)TAG_TEXT);
nodeline->type = XML_ELEMENT_NODE;
n = line->len;
if (line->hyphenated && lineIdx + 1 < par->lines->getLength()) {
--n;
}
for (wordI = 0; wordI < line->words->getLength(); ++wordI) {
word = (TextWord *)line->words->get(wordI);
if(wordI < line->words->getLength() - 1)
nextWord = (TextWord *)line->words->get(wordI+1);
char* tmp;
tmp=(char*)malloc(10*sizeof(char));
fontStyleInfo = new TextFontStyleInfo;
node = xmlNewNode(NULL, (const xmlChar*)TAG_TOKEN);
node->type = XML_ELEMENT_NODE;
if((word->base < previousWordBaseLine && word->yMax > previousWordYmin)|| (wordI == 0 && wordI < line->words->getLength() - 1 && word->base < nextWord->base && word->yMax > nextWord->yMin))
fontStyleInfo->setIsSuperscript(gTrue);
else if(((wordI > 0) && word->base > previousWordBaseLine && word->yMin > previousWordYmax ))
fontStyleInfo->setIsSubscript(gTrue);
if (verbose) {
addAttributsNodeVerbose(node, tmp, word);
}
addAttributsNode(node, word, xMax, yMax, yMinRot, yMaxRot, xMinRot,
xMaxRot, fontStyleInfo, uMap, fullFontName);
addAttributTypeReadingOrder(node, tmp, word);
if (!parameters->getImageInline()) {
if (indiceImage != -1) {
int nb = listeImageInline.size();
for (; indiceImage<nb; indiceImage++) {
if (idWORDBefore
== listeImageInline[indiceImage]->idWordBefore) {
nodeImageInline = xmlNewNode(NULL,
(const xmlChar*)TAG_TOKEN);
nodeImageInline->type = XML_ELEMENT_NODE;
id = new GString("p");
xmlNewProp(nodeImageInline, (const xmlChar*)ATTR_ID,
(const xmlChar*)buildIdToken(num, numToken, id)->getCString());
delete id;
numToken = numToken + 1;
id = new GString("p");
xmlNewProp(
nodeImageInline,
(const xmlChar*)ATTR_SID,
(const xmlChar*)buildSID(num, listeImageInline[indiceImage]->getIdx(), id)->getCString());
delete id;
sprintf(
tmp,
ATTR_NUMFORMAT,
listeImageInline[indiceImage]->getXPositionImage());
xmlNewProp(nodeImageInline, (const xmlChar*)ATTR_X,
(const xmlChar*)tmp);
sprintf(
tmp,
ATTR_NUMFORMAT,
listeImageInline[indiceImage]->getYPositionImage());
xmlNewProp(nodeImageInline, (const xmlChar*)ATTR_Y,
(const xmlChar*)tmp);
sprintf(tmp, ATTR_NUMFORMAT,
listeImageInline[indiceImage]->getWidthImage());
xmlNewProp(nodeImageInline, (const xmlChar*)ATTR_WIDTH,
(const xmlChar*)tmp);
sprintf(tmp, ATTR_NUMFORMAT,
listeImageInline[indiceImage]->getHeightImage());
xmlNewProp(nodeImageInline,
(const xmlChar*)ATTR_HEIGHT,
(const xmlChar*)tmp);
xmlNewProp(
nodeImageInline,
(const xmlChar*)ATTR_HREF,
(const xmlChar*)listeImageInline[indiceImage]->getHrefImage()->getCString());
xmlAddChild(nodeline, nodeImageInline);
}
}
}
}
xmlAddChild(nodeline, node);
if(wordI < line->words->getLength() - 1 and word->spaceAfter) {
xmlNodePtr spacingNode = xmlNewNode(NULL, (const xmlChar *) TAG_SPACING);
spacingNode->type = XML_ELEMENT_NODE;
sprintf(tmp, ATTR_NUMFORMAT, (nextWord->xMin - word->xMax));
xmlNewProp(spacingNode, (const xmlChar *) ATTR_WIDTH,
(const xmlChar *) tmp);
sprintf(tmp, ATTR_NUMFORMAT, (word->yMin));
xmlNewProp(spacingNode, (const xmlChar *) ATTR_Y,
(const xmlChar *) tmp);
sprintf(tmp, ATTR_NUMFORMAT, (word->xMax));
xmlNewProp(spacingNode, (const xmlChar *) ATTR_X,
(const xmlChar *) tmp);
xmlAddChild(nodeline, spacingNode);
}
previousWordBaseLine = word->base;
previousWordYmin = word->yMin;
previousWordYmax = word->yMax;
free(tmp);
}
if(blocks)
xmlAddChild(nodeblocks, nodeline);
else xmlAddChild(printSpace, nodeline);
}
xmlAddChild(printSpace, nodeblocks);
}
}
deleteGList(columns, TextColumn);
int imageCount = listeImages.size();
for(int i = 0; i < imageCount; ++i) {
char* tmp;
tmp=(char*)malloc(10*sizeof(char));
printSpace = xmlNewNode(NULL, (const xmlChar*)TAG_PRINTSPACE);
printSpace->type = XML_ELEMENT_NODE;
xmlAddChild(page, printSpace);
node = xmlNewNode(NULL, (const xmlChar*)TAG_IMAGE);
xmlNewProp(node, (const xmlChar *) ATTR_ID,(const xmlChar*)listeImages[i]->getImageId()->getCString());
sprintf(tmp, ATTR_NUMFORMAT, listeImages[i]->getXPositionImage());
xmlNewProp(printSpace, (const xmlChar *) ATTR_X, (const xmlChar *) tmp);
sprintf(tmp, ATTR_NUMFORMAT, listeImages[i]->getYPositionImage());
xmlNewProp(printSpace, (const xmlChar *) ATTR_Y, (const xmlChar *) tmp);
sprintf(tmp, ATTR_NUMFORMAT, listeImages[i]->getWidthImage());
xmlNewProp(printSpace, (const xmlChar *) ATTR_WIDTH, (const xmlChar *) tmp);
sprintf(tmp, ATTR_NUMFORMAT, listeImages[i]->getHeightImage());
xmlNewProp(printSpace, (const xmlChar *) ATTR_HEIGHT, (const xmlChar *) tmp);
xmlNewProp(node, (const xmlChar *) ATTR_HREF,
(const xmlChar *) listeImages[i]->getHrefImage()->getCString());
xmlNewProp(node, (const xmlChar*) ATTR_CLIPZONE,
(const xmlChar*)listeImages[i]->getClipZone()->getCString());
xmlAddChild(printSpace, node);
free(tmp);
}
}

BOOL rdp_read_share_control_header(wStream* s, UINT16* length, UINT16* type, UINT16* channel_id)
{
if (Stream_GetRemainingLength(s) < 2)
return FALSE;
Stream_Read_UINT16(s, *length); 
return TRUE;
}
if (((size_t)*length - 2) > Stream_GetRemainingLength(s))
return FALSE;
Stream_Read_UINT16(s, *type); 
*type &= 0x0F;                
if (*length > 4)
Stream_Read_UINT16(s, *channel_id); 
else
*channel_id = 0; 
return TRUE;
}

static gint32
load_image (const gchar  *filename,
GError      **error)
{
FILE     *fp;
tga_info  info;
guchar    header[18];
guchar    footer[26];
guchar    extension[495];
long      offset;
gint32    image_ID = -1;
gimp_progress_init_printf (_("Opening '%s'"),
gimp_filename_to_utf8 (filename));
fp = g_fopen (filename, "rb");
if (! fp)
{
g_set_error (error, G_FILE_ERROR, g_file_error_from_errno (errno),
_("Could not open '%s' for reading: %s"),
gimp_filename_to_utf8 (filename), g_strerror (errno));
return -1;
}
if (!fseek (fp, -26L, SEEK_END))
{
if (fread (footer, sizeof (footer), 1, fp) != 1)
{
g_message (_("Cannot read footer from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
else if (memcmp (footer + 8, magic, sizeof (magic)) == 0)
{
offset = (footer[0]          +
footer[1] * 256L   +
footer[2] * 65536L +
footer[3] * 16777216L);
if (offset != 0)
{
if (fseek (fp, offset, SEEK_SET) ||
fread (extension, sizeof (extension), 1, fp) != 1)
{
g_message (_("Cannot read extension from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
}
}
}
if (fseek (fp, 0, SEEK_SET) ||
fread (header, sizeof (header), 1, fp) != 1)
{
g_message (_("Cannot read header from '%s'"),
gimp_filename_to_utf8 (filename));
return -1;
}
switch (header[2])
{
case 1:
info.imageType        = TGA_TYPE_MAPPED;
info.imageCompression = TGA_COMP_NONE;
break;
case 2:
info.imageType        = TGA_TYPE_COLOR;
info.imageCompression = TGA_COMP_NONE;
break;
case 3:
info.imageType        = TGA_TYPE_GRAY;
info.imageCompression = TGA_COMP_NONE;
break;
case 9:
info.imageType        = TGA_TYPE_MAPPED;
info.imageCompression = TGA_COMP_RLE;
break;
case 10:
info.imageType        = TGA_TYPE_COLOR;
info.imageCompression = TGA_COMP_RLE;
break;
case 11:
info.imageType        = TGA_TYPE_GRAY;
info.imageCompression = TGA_COMP_RLE;
break;
default:
info.imageType = 0;
}
info.idLength     = header[0];
info.colorMapType = header[1];
info.colorMapIndex  = header[3] + header[4] * 256;
info.colorMapLength = header[5] + header[6] * 256;
info.colorMapSize   = header[7];
info.xOrigin = header[8]  + header[9] * 256;
info.yOrigin = header[10] + header[11] * 256;
info.width   = header[12] + header[13] * 256;
info.height  = header[14] + header[15] * 256;
info.bpp       = header[16];
info.bytes     = (info.bpp + 7) / 8;
info.alphaBits = header[17] & 0x0f; 
info.flipHoriz = (header[17] & 0x10) ? 1 : 0;
info.flipVert  = (header[17] & 0x20) ? 0 : 1;
if (info.alphaBits == info.bpp)
info.alphaBits = 0;
if (info.alphaBits == 0)
{
if (info.imageType == TGA_TYPE_COLOR && info.bpp == 32)
info.alphaBits = 8;
if (info.imageType == TGA_TYPE_GRAY && info.bpp == 16)
info.alphaBits = 8;
}
switch (info.imageType)
{
case TGA_TYPE_MAPPED:
if (info.bpp != 8)
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
break;
case TGA_TYPE_COLOR:
if (info.bpp != 15 && info.bpp != 16 &&
info.bpp != 24 && info.bpp != 32)
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
break;
case TGA_TYPE_GRAY:
if (info.bpp != 8 &&
(info.alphaBits != 8 || (info.bpp != 16 && info.bpp != 15)))
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
break;
default:
g_message ("Unknown image type %u for '%s'",
info.imageType, gimp_filename_to_utf8 (filename));
return -1;
}
if (info.bytes * 8 != info.bpp && info.bpp != 15)
{
g_message ("Unhandled sub-format in '%s' (type = %u, bpp = %u)",
gimp_filename_to_utf8 (filename),
info.imageType, info.bpp);
return -1;
}
if (info.imageType == TGA_TYPE_MAPPED && info.colorMapType != 1)
{
g_message ("Indexed image has invalid color map type %u",
info.colorMapType);
return -1;
}
else if (info.imageType != TGA_TYPE_MAPPED && info.colorMapType != 0)
{
g_message ("Non-indexed image has invalid color map type %u",
info.colorMapType);
return -1;
}
if (info.idLength && fseek (fp, info.idLength, SEEK_CUR))
{
g_message ("File '%s' is truncated or corrupted",
gimp_filename_to_utf8 (filename));
return -1;
}
image_ID = ReadImage (fp, &info, filename);
fclose (fp);
return image_ID;
}

static gboolean
mp2t_find_next_pcr(wtap *wth, guint8 trailer_len,
int *err, gchar **err_info, guint32 *idx, guint64 *pcr, guint16 *pid)
{
guint8 buffer[MP2T_SIZE];
gboolean found;
guint8 afc;
found = FALSE;
while (FALSE == found) {
(*idx)++;
if (!wtap_read_bytes_or_eof(
wth->fh, buffer, MP2T_SIZE+trailer_len, err, err_info)) {
return FALSE;
}
if (MP2T_SYNC_BYTE != buffer[0]) {
continue;
}
afc = 3 & (buffer[3] >> 4);
if (afc < 2) {
continue;
}
if (buffer[4] < 7) {
continue;
}
if (0x10 != (0x10 & buffer[5])) {
continue;
}
*pcr = mp2t_read_pcr(&buffer[6]);
*pid = 0x01ff & pntoh16(&buffer[1]);
found = TRUE;
}
return TRUE;
}

static struct response *
resp_new (const char *head)
{
const char *hdr;
int count, size;
struct response *resp = xnew0 (struct response);
resp->data = head;
if (*head == '\0')
{
return resp;
}
size = count = 0;
hdr = head;
while (1)
{
DO_REALLOC (resp->headers, size, count + 1, const char *);
resp->headers[count++] = hdr;
if (!hdr[0] || (hdr[0] == '\r' && hdr[1] == '\n') || hdr[0] == '\n')
break;
do
{
const char *end = strchr (hdr, '\n');
if (end)
hdr = end + 1;
else
hdr += strlen (hdr);
}
while (*hdr == ' ' || *hdr == '\t');
}
DO_REALLOC (resp->headers, size, count + 1, const char *);
resp->headers[count] = NULL;
return resp;
}

static void
exif_mnote_data_fuji_load (ExifMnoteData *en,
const unsigned char *buf, unsigned int buf_size)
{
ExifMnoteDataFuji *n = (ExifMnoteDataFuji*) en;
ExifLong c;
size_t i, tcount, o, datao;
if (!n || !buf || !buf_size) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataFuji", "Short MakerNote");
return;
}
datao = 6 + n->offset;
if ((datao + 12 < datao) || (datao + 12 < 12) || (datao + 12 > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataFuji", "Short MakerNote");
return;
}
n->order = EXIF_BYTE_ORDER_INTEL;
datao += exif_get_long (buf + datao + 8, EXIF_BYTE_ORDER_INTEL);
if ((datao + 2 < datao) || (datao + 2 < 2) ||
(datao + 2 > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataFuji", "Short MakerNote");
return;
}
c = exif_get_short (buf + datao, EXIF_BYTE_ORDER_INTEL);
datao += 2;
exif_mnote_data_fuji_clear (n);
n->entries = exif_mem_alloc (en->mem, sizeof (MnoteFujiEntry) * c);
if (!n->entries) {
EXIF_LOG_NO_MEMORY(en->log, "ExifMnoteDataFuji", sizeof (MnoteFujiEntry) * c);
return;
}
tcount = 0;
for (i = c, o = datao; i; --i, o += 12) {
size_t s;
if ((o + 12 < o) || (o + 12 < 12) || (o + 12 > buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataFuji", "Short MakerNote");
break;
}
n->entries[tcount].tag        = exif_get_short (buf + o, n->order);
n->entries[tcount].format     = exif_get_short (buf + o + 2, n->order);
n->entries[tcount].components = exif_get_long (buf + o + 4, n->order);
n->entries[tcount].order      = n->order;
exif_log (en->log, EXIF_LOG_CODE_DEBUG, "ExifMnoteDataFuji",
"Loading entry 0x%x ('%s')...", n->entries[tcount].tag,
mnote_fuji_tag_get_name (n->entries[tcount].tag));
s = exif_format_get_size (n->entries[tcount].format) * n->entries[tcount].components;
n->entries[tcount].size = s;
if (s) {
size_t dataofs = o + 8;
if (s > 4)
dataofs = exif_get_long (buf + dataofs, n->order) + 6 + n->offset;
if ((dataofs + s < dataofs) || (dataofs + s < s) ||
(dataofs + s >= buf_size)) {
exif_log (en->log, EXIF_LOG_CODE_CORRUPT_DATA,
"ExifMnoteDataFuji", "Tag data past end of "
"buffer (%u >= %u)", (unsigned)(dataofs + s), buf_size);
continue;
}
n->entries[tcount].data = exif_mem_alloc (en->mem, s);
if (!n->entries[tcount].data) {
EXIF_LOG_NO_MEMORY(en->log, "ExifMnoteDataFuji", s);
continue;
}
memcpy (n->entries[tcount].data, buf + dataofs, s);
}
++tcount;
}
n->count = tcount;
}

GF_EXPORT
GF_Err gf_gz_decompress_payload(u8 *data, u32 data_len, u8 **uncompressed_data, u32 *out_size)
{
z_stream d_stream;
GF_Err e = GF_OK;
int err;
Bool owns_buffer=GF_TRUE;
u32 size = 4096;
if (! *uncompressed_data) {
*uncompressed_data = (char*)gf_malloc(sizeof(char)*4096);
if (!*uncompressed_data) return GF_OUT_OF_MEM;
} else {
owns_buffer = GF_FALSE;
size = *out_size;
}
d_stream.zalloc = (alloc_func)0;
d_stream.zfree = (free_func)0;
d_stream.opaque = (voidpf)0;
d_stream.next_in  = (Bytef*)data;
d_stream.avail_in = data_len;
d_stream.next_out = (Bytef*) *uncompressed_data;
d_stream.avail_out = size;
err = inflateInit2(&d_stream, 16+MAX_WBITS);
if (err == Z_OK) {
while (d_stream.total_in < data_len) {
err = inflate(&d_stream, Z_NO_FLUSH);
if (err < Z_OK) {
e = GF_NON_COMPLIANT_BITSTREAM;
break;
}
if (err==Z_STREAM_END) break;
size *= 2;
*uncompressed_data = (char*)gf_realloc(*uncompressed_data, sizeof(char)*size);
if (!*uncompressed_data) return GF_OUT_OF_MEM;
d_stream.avail_out = (u32) (size - d_stream.total_out);
d_stream.next_out = (Bytef*) ( *uncompressed_data + d_stream.total_out);
}
*out_size = (u32) d_stream.total_out;
inflateEnd(&d_stream);
return e;
}
if (e!=GF_OK) {
if (owns_buffer) {
gf_free(*uncompressed_data);
*uncompressed_data = NULL;
}
}
return e;
}

int jas_stream_pad(jas_stream_t *stream, int n, int c)
{
int m;
m = n;
for (m = n; m > 0; --m) {
if (jas_stream_putc(stream, c) == EOF)
