Error ImageLoaderTGA::convert_to_image(Ref<Image> p_image, const uint8_t *p_buffer, const tga_header_s &p_header, const uint8_t *p_palette, const bool p_is_monochrome) {
#define TGA_PUT_PIXEL(r, g, b, a)             \
int image_data_ofs = ((y * width) + x);   \
image_data_w[image_data_ofs * 4 + 0] = r; \
image_data_w[image_data_ofs * 4 + 1] = g; \
image_data_w[image_data_ofs * 4 + 2] = b; \
image_data_w[image_data_ofs * 4 + 3] = a;
uint32_t width = p_header.image_width;
uint32_t height = p_header.image_height;
tga_origin_e origin = static_cast<tga_origin_e>((p_header.image_descriptor & TGA_ORIGIN_MASK) >> TGA_ORIGIN_SHIFT);
uint32_t x_start;
int32_t x_step;
uint32_t x_end;
uint32_t y_start;
int32_t y_step;
uint32_t y_end;
if (origin == TGA_ORIGIN_TOP_LEFT || origin == TGA_ORIGIN_TOP_RIGHT) {
y_start = 0;
y_step = 1;
y_end = height;
} else {
y_start = height - 1;
y_step = -1;
y_end = -1;
}
if (origin == TGA_ORIGIN_TOP_LEFT || origin == TGA_ORIGIN_BOTTOM_LEFT) {
x_start = 0;
x_step = 1;
x_end = width;
} else {
x_start = width - 1;
x_step = -1;
x_end = -1;
}
PoolVector<uint8_t> image_data;
image_data.resize(width * height * sizeof(uint32_t));
PoolVector<uint8_t>::Write image_data_w = image_data.write();
size_t i = 0;
uint32_t x = x_start;
uint32_t y = y_start;
if (p_header.pixel_depth == 8) {
if (p_is_monochrome) {
while (y != y_end) {
while (x != x_end) {
uint8_t shade = p_buffer[i];
TGA_PUT_PIXEL(shade, shade, shade, 0xff)
x += x_step;
i += 1;
}
x = x_start;
y += y_step;
}
} else {
while (y != y_end) {
while (x != x_end) {
uint8_t index = p_buffer[i];
uint8_t r = 0x00;
uint8_t g = 0x00;
uint8_t b = 0x00;
uint8_t a = 0xff;
if (p_header.color_map_depth == 24) {
r = (p_palette[(index * 3) + 2]);
g = (p_palette[(index * 3) + 1]);
b = (p_palette[(index * 3) + 0]);
} else {
return ERR_INVALID_DATA;
}
TGA_PUT_PIXEL(r, g, b, a)
x += x_step;
i += 1;
}
x = x_start;
y += y_step;
}
}
} else if (p_header.pixel_depth == 24) {
while (y != y_end) {
while (x != x_end) {
uint8_t r = p_buffer[i + 2];
uint8_t g = p_buffer[i + 1];
uint8_t b = p_buffer[i + 0];
TGA_PUT_PIXEL(r, g, b, 0xff)
x += x_step;
i += 3;
}
x = x_start;
y += y_step;
}
} else if (p_header.pixel_depth == 32) {
while (y != y_end) {
while (x != x_end) {
uint8_t a = p_buffer[i + 3];
uint8_t r = p_buffer[i + 2];
uint8_t g = p_buffer[i + 1];
uint8_t b = p_buffer[i + 0];
TGA_PUT_PIXEL(r, g, b, a)
x += x_step;
i += 4;
}
x = x_start;
y += y_step;
}
}
image_data_w.release();
p_image->create(width, height, 0, Image::FORMAT_RGBA8, image_data);
return OK;
}

int oidc_oauth_check_userid(request_rec *r, oidc_cfg *c) {
if (!ap_is_initial_req(r)) {
if (r->main != NULL)
r->user = r->main->user;
else if (r->prev != NULL)
r->user = r->prev->user;
if (r->user != NULL) {
oidc_debug(r,
"recycling user '%s' from initial request for sub-request",
r->user);
return OK;
}
} else if ((c->redirect_uri != NULL)
&& (oidc_util_request_matches_url(r, c->redirect_uri))) {
if (oidc_util_request_has_parameter(r, "jwks")) {
return oidc_handle_jwks(r, c);
}
}
const char *access_token = NULL;
if (oidc_oauth_get_bearer_token(r, &access_token) == FALSE)
return oidc_oauth_return_www_authenticate(r, "invalid_request",
"No bearer token found in the request");
json_t *token = NULL;
char *s_token = NULL;
if (c->oauth.introspection_endpoint_url != NULL) {
if (oidc_oauth_resolve_access_token(r, c, access_token, &token,
&s_token) == FALSE)
return oidc_oauth_return_www_authenticate(r, "invalid_token",
"Reference token could not be introspected");
} else {
if (oidc_oauth_validate_jwt_access_token(r, c, access_token, &token,
&s_token) == FALSE)
return oidc_oauth_return_www_authenticate(r, "invalid_token",
"JWT token could not be validated");
}
if (token == NULL) {
oidc_error(r, "could not resolve claims (token == NULL)");
return oidc_oauth_return_www_authenticate(r, "invalid_token",
"No claims could be parsed from the token");
}
oidc_request_state_set(r, OIDC_CLAIMS_SESSION_KEY, (const char *) s_token);
if (oidc_oauth_set_remote_user(r, c, token) == FALSE) {
oidc_error(r,
"remote user could not be set, aborting with HTTP_UNAUTHORIZED");
return oidc_oauth_return_www_authenticate(r, "invalid_token",
"Could not set remote user");
}
char *authn_header = oidc_cfg_dir_authn_header(r);
int pass_headers = oidc_cfg_dir_pass_info_in_headers(r);
int pass_envvars = oidc_cfg_dir_pass_info_in_envvars(r);
if ((r->user != NULL) && (authn_header != NULL)) {
oidc_debug(r, "setting authn header (%s) to: %s", authn_header,
r->user);
apr_table_set(r->headers_in, authn_header, r->user);
}
oidc_util_set_app_infos(r, token, c->claim_prefix, c->claim_delimiter,
pass_headers, pass_envvars);
if (access_token != NULL) {
oidc_util_set_app_info(r, "access_token", access_token,
OIDC_DEFAULT_HEADER_PREFIX, pass_headers, pass_envvars);
}
json_decref(token);
return OK;
}

bfd_boolean
_bfd_coff_get_external_symbols (bfd *abfd)
{
bfd_size_type symesz;
bfd_size_type size;
void * syms;
if (obj_coff_external_syms (abfd) != NULL)
return TRUE;
symesz = bfd_coff_symesz (abfd);
size = obj_raw_syment_count (abfd) * symesz;
if (size == 0)
return TRUE;
syms = bfd_malloc (size);
if (syms == NULL)
{
_bfd_error_handler (_("%B: Not enough memory to allocate space for %Lu symbols"),
abfd, size);
return FALSE;
}
if (bfd_seek (abfd, obj_sym_filepos (abfd), SEEK_SET) != 0
|| bfd_bread (syms, size, abfd) != size)
{
if (syms != NULL)
free (syms);
return FALSE;
}
obj_coff_external_syms (abfd) = syms;
return TRUE;
}

