SPIFFEValidator::SPIFFEValidator(const Envoy::Ssl::CertificateValidationContextConfig* config,
SslStats& stats, TimeSource& time_source)
: stats_(stats), time_source_(time_source) {
ASSERT(config != nullptr);
allow_expired_certificate_ = config->allowExpiredCertificate();
SPIFFEConfig message;
Config::Utility::translateOpaqueConfig(config->customValidatorConfig().value().typed_config(),
ProtobufMessage::getStrictValidationVisitor(), message);
if (!config->subjectAltNameMatchers().empty()) {
for (const auto& matcher : config->subjectAltNameMatchers()) {
subject_alt_name_matchers_.push_back(Matchers::StringMatcherImpl(matcher));
}
}
const auto size = message.trust_domains().size();
trust_bundle_stores_.reserve(size);
for (auto& domain : message.trust_domains()) {
if (trust_bundle_stores_.find(domain.name()) != trust_bundle_stores_.end()) {
throw EnvoyException(absl::StrCat(
"Multiple trust bundles are given for one trust domain for ", domain.name()));
}
auto cert = Config::DataSource::read(domain.trust_bundle(), true, config->api());
bssl::UniquePtr<BIO> bio(BIO_new_mem_buf(const_cast<char*>(cert.data()), cert.size()));
RELEASE_ASSERT(bio != nullptr, "");
bssl::UniquePtr<STACK_OF(X509_INFO)> list(
PEM_X509_INFO_read_bio(bio.get(), nullptr, nullptr, nullptr));
if (list == nullptr || sk_X509_INFO_num(list.get()) == 0) {
throw EnvoyException(
absl::StrCat("Failed to load trusted CA certificate for ", domain.name()));
}
auto store = X509StorePtr(X509_STORE_new());
bool has_crl = false;
bool ca_loaded = false;
for (const X509_INFO* item : list.get()) {
if (item->x509) {
X509_STORE_add_cert(store.get(), item->x509);
ca_certs_.push_back(bssl::UniquePtr<X509>(item->x509));
X509_up_ref(item->x509);
if (!ca_loaded) {
ca_loaded = true;
ca_file_name_ = absl::StrCat(domain.name(), ": ",
domain.trust_bundle().filename().empty()
? "<inline>"
: domain.trust_bundle().filename());
}
}
if (item->crl) {
has_crl = true;
X509_STORE_add_crl(store.get(), item->crl);
}
}
if (has_crl) {
X509_STORE_set_flags(store.get(), X509_V_FLAG_CRL_CHECK | X509_V_FLAG_CRL_CHECK_ALL);
}
trust_bundle_stores_[domain.name()] = std::move(store);
}
}

DNSResult DNS::GetResult()
{
DNSHeader header;
DNSRequest *req;
unsigned char buffer[sizeof(DNSHeader)];
irc::sockets::sockaddrs from;
memset(&from, 0, sizeof(from));
socklen_t x = sizeof(from);
int length = ServerInstance->SE->RecvFrom(this, (char*)buffer, sizeof(DNSHeader), 0, &from.sa, &x);
if (length < 12)
{
ServerInstance->Logs->Log("RESOLVER",DEBUG,"GetResult didn't get a full packet (len=%d)", length);
return DNSResult(-1,"",0,"");
}
if (from != myserver)
{
std::string server1 = from.str();
std::string server2 = myserver.str();
ServerInstance->Logs->Log("RESOLVER",DEBUG,"Got a result from the wrong server! Bad NAT or DNS forging attempt? '%s' != '%s'",
server1.c_str(), server2.c_str());
return DNSResult(-1,"",0,"");
}
DNS::FillHeader(&header,buffer,length - 12);
unsigned long this_id = header.id[1] + (header.id[0] << 8);
if (!requests[this_id])
{
ServerInstance->Logs->Log("RESOLVER",DEBUG,"Hmm, got a result that we didn't ask for (id=%lx). Ignoring.", this_id);
return DNSResult(-1,"",0,"");
}
else
{
req = requests[this_id];
requests[this_id] = NULL;
}
DNSInfo data = req->ResultIsReady(header, length);
std::string resultstr;
if (data.first == NULL)
{
std::string ro = req->orig;
delete req;
return DNSResult(this_id | ERROR_MASK, data.second, 0, ro);
}
else
{
unsigned long ttl = req->ttl;
char formatted[128];
switch (req->type)
{
case DNS_QUERY_A:
snprintf(formatted,16,"%u.%u.%u.%u",data.first[0],data.first[1],data.first[2],data.first[3]);
resultstr = formatted;
break;
case DNS_QUERY_AAAA:
{
if (!inet_ntop(AF_INET6, data.first, formatted, sizeof(formatted)))
{
std::string ro = req->orig;
delete req;
return DNSResult(this_id | ERROR_MASK, "inet_ntop() failed", 0, ro);
}
resultstr = formatted;
if (*formatted == ':')
resultstr.insert(0, "0");
}
break;
case DNS_QUERY_CNAME:
case DNS_QUERY_PTR:
resultstr = std::string((const char*)data.first);
break;
default:
break;
}
std::string ro = req->orig;
DNSResult result = DNSResult(this_id,resultstr,ttl,ro,req->type);
delete req;
return result;
}
}

static int construct_memop_from_reservation(
const struct xen_memory_reservation *r,
struct memop_args *a)
{
unsigned int address_bits;
a->extent_list  = r->extent_start;
a->nr_extents   = r->nr_extents;
a->extent_order = r->extent_order;
a->memflags     = 0;
address_bits = XENMEMF_get_address_bits(r->mem_flags);
if ( (address_bits != 0) &&
(address_bits < (get_order_from_pages(max_page) + PAGE_SHIFT)) )
{
if ( address_bits <= PAGE_SHIFT )
return -EINVAL;
a->memflags = MEMF_bits(address_bits);
}
if ( r->mem_flags & XENMEMF_vnode )
{
nodeid_t vnode, pnode;
struct domain *d = a->domain;
read_lock(&d->vnuma_rwlock);
if ( d->vnuma )
{
vnode = XENMEMF_get_node(r->mem_flags);
if ( vnode >= d->vnuma->nr_vnodes )
{
read_unlock(&d->vnuma_rwlock);
return -EINVAL;
}
pnode = d->vnuma->vnode_to_pnode[vnode];
if ( pnode != NUMA_NO_NODE )
{
a->memflags |= MEMF_node(pnode);
if ( r->mem_flags & XENMEMF_exact_node_request )
a->memflags |= MEMF_exact_node;
}
}
read_unlock(&d->vnuma_rwlock);
}
else
{
a->memflags |= MEMF_node(XENMEMF_get_node(r->mem_flags));
if ( r->mem_flags & XENMEMF_exact_node_request )
a->memflags |= MEMF_exact_node;
}
return 0;
}

xmlRefPtr
xmlAddRef(xmlValidCtxtPtr ctxt, xmlDocPtr doc, const xmlChar *value,
xmlAttrPtr attr) {
xmlRefPtr ret;
xmlRefTablePtr table;
xmlListPtr ref_list;
if (doc == NULL) {
return(NULL);
}
if (value == NULL) {
return(NULL);
}
if (attr == NULL) {
return(NULL);
}
table = (xmlRefTablePtr) doc->refs;
if (table == NULL) {
doc->refs = table = xmlHashCreateDict(0, doc->dict);
}
if (table == NULL) {
xmlVErrMemory(ctxt,
"xmlAddRef: Table creation failed!\n");
return(NULL);
}
ret = (xmlRefPtr) xmlMalloc(sizeof(xmlRef));
if (ret == NULL) {
xmlVErrMemory(ctxt, "malloc failed");
return(NULL);
}
ret->value = xmlStrdup(value);
if ((ctxt != NULL) && (ctxt->vstateNr != 0)) {
ret->name = xmlStrdup(attr->name);
ret->attr = NULL;
} else {
ret->name = NULL;
ret->attr = attr;
}
ret->lineno = xmlGetLineNo(attr->parent);
if (NULL == (ref_list = xmlHashLookup(table, value))) {
if (NULL == (ref_list = xmlListCreate(xmlFreeRef, xmlDummyCompare))) {
xmlErrValid(NULL, XML_ERR_INTERNAL_ERROR,
"xmlAddRef: Reference list creation failed!\n",
NULL);
goto failed;
}
if (xmlHashAddEntry(table, value, ref_list) < 0) {
xmlListDelete(ref_list);
xmlErrValid(NULL, XML_ERR_INTERNAL_ERROR,
"xmlAddRef: Reference list insertion failed!\n",
NULL);
goto failed;
}
}
if (xmlListAppend(ref_list, ret) != 0) {
xmlErrValid(NULL, XML_ERR_INTERNAL_ERROR,
"xmlAddRef: Reference list insertion failed!\n",
NULL);
goto failed;
}
return(ret);
failed:
if (ret != NULL) {
if (ret->value != NULL)
xmlFree((char *)ret->value);
if (ret->name != NULL)
xmlFree((char *)ret->name);
xmlFree(ret);
}
return(NULL);
}

