static bool is_legal_file(const std::string &filename)
{
DBG_FS << "Looking for '" << filename << "'.\n";
if (filename.empty()) {
LOG_FS << "  invalid filename\n";
return false;
}
if (filename.find("..") != std::string::npos) {
ERR_FS << "Illegal path '" << filename << "' (\"..\" not allowed).\n";
return false;
}
return true;
}

bool FromkLinuxSockAddr(const struct klinux_sockaddr *input,
socklen_t input_len, struct sockaddr *output,
socklen_t *output_len,
void (*abort_handler)(const char *)) {
if (!input || !output || !output_len || input_len == 0) {
output = nullptr;
return false;
}
int16_t klinux_family = input->klinux_sa_family;
if (klinux_family == kLinux_AF_UNIX) {
struct klinux_sockaddr_un *klinux_sockaddr_un_in =
const_cast<struct klinux_sockaddr_un *>(
reinterpret_cast<const struct klinux_sockaddr_un *>(input));
struct sockaddr_un sockaddr_un_out;
sockaddr_un_out.sun_family = AF_UNIX;
InitializeToZeroArray(sockaddr_un_out.sun_path);
ReinterpretCopyArray(
sockaddr_un_out.sun_path, klinux_sockaddr_un_in->klinux_sun_path,
std::min(sizeof(sockaddr_un_out.sun_path),
sizeof(klinux_sockaddr_un_in->klinux_sun_path)));
CopySockaddr(&sockaddr_un_out, sizeof(sockaddr_un_out), output, output_len);
} else if (klinux_family == kLinux_AF_INET) {
struct klinux_sockaddr_in *klinux_sockaddr_in_in =
const_cast<struct klinux_sockaddr_in *>(
reinterpret_cast<const struct klinux_sockaddr_in *>(input));
struct sockaddr_in sockaddr_in_out;
sockaddr_in_out.sin_family = AF_INET;
sockaddr_in_out.sin_port = klinux_sockaddr_in_in->klinux_sin_port;
InitializeToZeroSingle(&sockaddr_in_out.sin_addr);
ReinterpretCopySingle(&sockaddr_in_out.sin_addr,
&klinux_sockaddr_in_in->klinux_sin_addr);
InitializeToZeroArray(sockaddr_in_out.sin_zero);
ReinterpretCopyArray(sockaddr_in_out.sin_zero,
klinux_sockaddr_in_in->klinux_sin_zero);
CopySockaddr(&sockaddr_in_out, sizeof(sockaddr_in_out), output, output_len);
} else if (klinux_family == kLinux_AF_INET6) {
struct klinux_sockaddr_in6 *klinux_sockaddr_in6_in =
const_cast<struct klinux_sockaddr_in6 *>(
reinterpret_cast<const struct klinux_sockaddr_in6 *>(input));
struct sockaddr_in6 sockaddr_in6_out;
sockaddr_in6_out.sin6_family = AF_INET6;
sockaddr_in6_out.sin6_port = klinux_sockaddr_in6_in->klinux_sin6_port;
sockaddr_in6_out.sin6_flowinfo =
klinux_sockaddr_in6_in->klinux_sin6_flowinfo;
sockaddr_in6_out.sin6_scope_id =
klinux_sockaddr_in6_in->klinux_sin6_scope_id;
InitializeToZeroSingle(&sockaddr_in6_out.sin6_addr);
ReinterpretCopySingle(&sockaddr_in6_out.sin6_addr,
&klinux_sockaddr_in6_in->klinux_sin6_addr);
CopySockaddr(&sockaddr_in6_out, sizeof(sockaddr_in6_out), output,
output_len);
} else if (klinux_family == kLinux_AF_UNSPEC) {
output = nullptr;
*output_len = 0;
} else {
if (abort_handler != nullptr) {
std::string message = absl::StrCat(
"Type conversion error - Unsupported AF family: ", klinux_family);
abort_handler(message.c_str());
} else {
abort();
}
}
return true;
}

bool rebuild_header_jpg( void )
{
abytewriter* hdrw; 
unsigned char  type = 0x00;     uint32_t   len  = 0;     uint32_t   hpos = 0; 
hdrw = new abytewriter( 4096 );
while ( hpos < hdrs && (uint64_t)hpos + 3 < (uint64_t)hdrs ) {
type = hpos + 1 < hdrs ?  hdrdata[ hpos + 1 ] : 0;
len = 2 + B_SHORT( hpos + 2 < hdrs ? hdrdata[ hpos + 2 ]:0, hpos + 3 < hdrs ? hdrdata[ hpos + 3 ] :0);
if ( ( type == 0xDA ) || ( type == 0xC4 ) || ( type == 0xDB ) ||
( type == 0xC0 ) || ( type == 0xC1 ) || ( type == 0xC2 ) ||
( type == 0xDD ) ) {
uint32_t to_copy = hpos + len < hdrs ? len : hdrs - hpos;
hdrw->write_n( &(hdrdata[ hpos ]), to_copy);
if (to_copy <  len) {
for (uint32_t i = 0;i <to_copy -len;++i) {
uint8_t zero = 0;
hdrw->write_n(&zero, 1);
}
}
}
hpos += len;
}
custom_free( hdrdata );
hdrdata = hdrw->getptr_aligned();
hdrs    = hdrw->getpos();
delete( hdrw );
return true;
}

static void
print_line_detail(
Dwarf_Debug dbg,
const char *prefix,
int opcode,
unsigned curr_line,
struct Dwarf_Line_Registers_s * regs,
Dwarf_Bool is_single_table, Dwarf_Bool is_actuals_table)
{
dwarfstring m1;
dwarfstring_constructor_static(&m1,locallinebuf,
sizeof(locallinebuf));
if(!is_single_table && is_actuals_table) {
dwarfstring_append_printf_s(&m1,"%-15s ",(char *)prefix);
dwarfstring_append_printf_i(&m1,"%3d ",opcode);
dwarfstring_append_printf_u(&m1,"0x%" DW_PR_XZEROS DW_PR_DUx ,
regs->lr_address);
dwarfstring_append_printf_u(&m1,"/%01u",regs->lr_op_index);
dwarfstring_append_printf_u(&m1," %5lu", regs->lr_line);
dwarfstring_append_printf_u(&m1," %3d",regs->lr_isa);
dwarfstring_append_printf_i(&m1,"   %1d", regs->lr_basic_block);
dwarfstring_append_printf_i(&m1,"%1d\n",  regs->lr_end_sequence);
_dwarf_printf(dbg,dwarfstring_string(&m1));
dwarfstring_destructor(&m1);
return;
}
if(!is_single_table && !is_actuals_table) {
dwarfstring_append_printf_i(&m1,
"[%3d] "  , curr_line);
dwarfstring_append_printf_s(&m1,
"%-15s ",(char *)prefix);
dwarfstring_append_printf_i(&m1,
"%3d ",opcode);
dwarfstring_append_printf_u(&m1,
"x%" DW_PR_XZEROS DW_PR_DUx, regs->lr_address);
dwarfstring_append_printf_u(&m1,
"/%01u", regs->lr_op_index);
dwarfstring_append_printf_u(&m1," %2lu ",regs->lr_file);
dwarfstring_append_printf_u(&m1,"%4lu  ",regs->lr_line);
dwarfstring_append_printf_u(&m1,"%1lu",regs->lr_column);
if (regs->lr_discriminator ||
regs->lr_prologue_end ||
regs->lr_epilogue_begin ||
regs->lr_isa ||
regs->lr_is_stmt ||
regs->lr_call_context ||
regs->lr_subprogram) {
dwarfstring_append_printf_u(&m1,
"   x%02" DW_PR_DUx ,
regs->lr_discriminator); 
dwarfstring_append_printf_u(&m1,
"  x%02" DW_PR_DUx , regs->lr_call_context); 
dwarfstring_append_printf_u(&m1,
"  x%02" DW_PR_DUx , regs->lr_subprogram); 
dwarfstring_append_printf_i(&m1,
"  %1d", regs->lr_is_stmt);
dwarfstring_append_printf_i(&m1,
"%1d", (int) regs->lr_isa);
dwarfstring_append_printf_i(&m1,
"%1d", regs->lr_prologue_end); 
dwarfstring_append_printf_i(&m1,
"%1d", regs->lr_epilogue_begin); 
}
dwarfstring_append(&m1,"\n");
_dwarf_printf(dbg,dwarfstring_string(&m1));
dwarfstring_destructor(&m1);
return;
}
dwarfstring_append_printf_s(&m1,
"%-15s ",(char *)prefix);
dwarfstring_append_printf_i(&m1,
"%2d ",opcode);
dwarfstring_append_printf_u(&m1,
"0x%" DW_PR_XZEROS DW_PR_DUx " ",
regs->lr_address);
dwarfstring_append_printf_u(&m1,
"%2lu   ", regs->lr_file);
dwarfstring_append_printf_u(&m1,
"%4lu ", regs->lr_line);
dwarfstring_append_printf_u(&m1,
"%2lu   ", regs->lr_column);
dwarfstring_append_printf_i(&m1,
"%1d ",regs->lr_is_stmt);
dwarfstring_append_printf_i(&m1,
"%1d ", regs->lr_basic_block);
dwarfstring_append_printf_i(&m1,
"%1d",regs->lr_end_sequence);
if (regs->lr_discriminator ||
regs->lr_prologue_end ||
regs->lr_epilogue_begin ||
regs->lr_isa) {
dwarfstring_append_printf_i(&m1,
" %1d", regs->lr_prologue_end); 
dwarfstring_append_printf_i(&m1,
" %1d", regs->lr_epilogue_begin); 
dwarfstring_append_printf_i(&m1,
" %1d", regs->lr_isa); 
dwarfstring_append_printf_u(&m1,
" 0x%" DW_PR_DUx , regs->lr_discriminator); 
}
dwarfstring_append(&m1, "\n");
_dwarf_printf(dbg,dwarfstring_string(&m1));
dwarfstring_destructor(&m1);
}

AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32        size, 
AP4_UI08        version,
AP4_UI32        flags,
AP4_ByteStream& stream) :
AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags)
{
AP4_UI32 predefined;
stream.ReadUI32(predefined);
stream.ReadUI32(m_HandlerType);
stream.ReadUI32(m_Reserved[0]);
stream.ReadUI32(m_Reserved[1]);
stream.ReadUI32(m_Reserved[2]);
int name_size = size-(AP4_FULL_ATOM_HEADER_SIZE+20);
if (name_size == 0) return;
char* name = new char[name_size+1];
stream.Read(name, name_size);
name[name_size] = '\0';                 if (name[0] == name_size-1) {
m_HandlerName = name+1;
} else {
m_HandlerName = name;
}
delete[] name;
}

static MagickBooleanType ReadPSDChannelPixels(Image *image,const ssize_t row,
const PixelChannel channel,const unsigned char *pixels,
ExceptionInfo *exception)
{
Quantum
pixel;
const unsigned char
*p;
Quantum
*q;
ssize_t
x;
size_t
packet_size;
p=pixels;
q=GetAuthenticPixels(image,0,row,image->columns,1,exception);
if (q == (Quantum *) NULL)
return MagickFalse;
packet_size=GetPSDPacketSize(image);
for (x=0; x < (ssize_t) image->columns; x++)
{
if (packet_size == 1)
pixel=ScaleCharToQuantum(*p++);
else
if (packet_size == 2)
{
unsigned short
nibble;
p=PushShortPixel(MSBEndian,p,&nibble);
pixel=ScaleShortToQuantum(nibble);
}
else
{
MagickFloatType
nibble;
p=PushFloatPixel(MSBEndian,p,&nibble);
pixel=ClampToQuantum(((MagickRealType) QuantumRange)*nibble);
}
if (image->depth > 1)
{
SetPSDPixel(image,channel,packet_size,pixel,q,exception);
q+=GetPixelChannels(image);
}
else
{
ssize_t
bit,
number_bits;
number_bits=(ssize_t) image->columns-x;
if (number_bits > 8)
number_bits=8;
for (bit = 0; bit < (ssize_t) number_bits; bit++)
{
SetPSDPixel(image,channel,packet_size,(((unsigned char) pixel)
& (0x01 << (7-bit))) != 0 ? 0 : QuantumRange,q,exception);
q+=GetPixelChannels(image);
x++;
}
if (x != (ssize_t) image->columns)
x--;
continue;
}
}
return(SyncAuthenticPixels(image,exception));
}

NO_INLINE JsVar *jspeFactor() {
if (lex->tk==LEX_ID) {
JsVar *a = jspGetNamedVariable(jslGetTokenValueAsString(lex));
JSP_ASSERT_MATCH(LEX_ID);
#ifndef SAVE_ON_FLASH
if (lex->tk==LEX_TEMPLATE_LITERAL)
jsExceptionHere(JSET_SYNTAXERROR, "Tagged template literals not supported");
else if (lex->tk==LEX_ARROW_FUNCTION && jsvIsName(a)) {
JsVar *funcVar = jspeArrowFunction(0,a);
jsvUnLock(a);
a=funcVar;
}
#endif
return a;
} else if (lex->tk==LEX_INT) {
JsVar *v = 0;
if (JSP_SHOULD_EXECUTE) {
v = jsvNewFromLongInteger(stringToInt(jslGetTokenValueAsString(lex)));
}
JSP_ASSERT_MATCH(LEX_INT);
return v;
} else if (lex->tk==LEX_FLOAT) {
JsVar *v = 0;
if (JSP_SHOULD_EXECUTE) {
v = jsvNewFromFloat(stringToFloat(jslGetTokenValueAsString(lex)));
}
JSP_ASSERT_MATCH(LEX_FLOAT);
return v;
} else if (lex->tk=='(') {
JSP_ASSERT_MATCH('(');
if (!jspCheckStackPosition()) return 0;
#ifdef SAVE_ON_FLASH
JsVar *a = jspeExpression();
if (!JSP_SHOULDNT_PARSE) JSP_MATCH_WITH_RETURN(')',a);
return a;
#else
return jspeExpressionOrArrowFunction();
#endif
} else if (lex->tk==LEX_R_TRUE) {
JSP_ASSERT_MATCH(LEX_R_TRUE);
return JSP_SHOULD_EXECUTE ? jsvNewFromBool(true) : 0;
} else if (lex->tk==LEX_R_FALSE) {
JSP_ASSERT_MATCH(LEX_R_FALSE);
return JSP_SHOULD_EXECUTE ? jsvNewFromBool(false) : 0;
} else if (lex->tk==LEX_R_NULL) {
JSP_ASSERT_MATCH(LEX_R_NULL);
return JSP_SHOULD_EXECUTE ? jsvNewWithFlags(JSV_NULL) : 0;
} else if (lex->tk==LEX_R_UNDEFINED) {
JSP_ASSERT_MATCH(LEX_R_UNDEFINED);
return 0;
} else if (lex->tk==LEX_STR) {
JsVar *a = 0;
if (JSP_SHOULD_EXECUTE)
a = jslGetTokenValueAsVar(lex);
JSP_ASSERT_MATCH(LEX_STR);
return a;
#ifndef SAVE_ON_FLASH
} else if (lex->tk==LEX_TEMPLATE_LITERAL) {
return jspeTemplateLiteral();
#endif
} else if (lex->tk==LEX_REGEX) {
JsVar *a = 0;
#ifdef SAVE_ON_FLASH
jsExceptionHere(JSET_SYNTAXERROR, "RegEx are not supported in this version of Espruino\n");
#else
JsVar *regex = jslGetTokenValueAsVar(lex);
size_t regexEnd = 0, regexLen = 0;
JsvStringIterator it;
jsvStringIteratorNew(&it, regex, 0);
while (jsvStringIteratorHasChar(&it)) {
regexLen++;
if (jsvStringIteratorGetChar(&it)=='/')
regexEnd = regexLen;
jsvStringIteratorNext(&it);
}
jsvStringIteratorFree(&it);
JsVar *flags = 0;
if (regexEnd < regexLen)
flags = jsvNewFromStringVar(regex, regexEnd, JSVAPPENDSTRINGVAR_MAXLENGTH);
JsVar *regexSource = jsvNewFromStringVar(regex, 1, regexEnd-2);
a = jswrap_regexp_constructor(regexSource, flags);
jsvUnLock3(regex, flags, regexSource);
#endif
JSP_ASSERT_MATCH(LEX_REGEX);
return a;
} else if (lex->tk=='{') {
if (!jspCheckStackPosition()) return 0;
return jspeFactorObject();
} else if (lex->tk=='[') {
if (!jspCheckStackPosition()) return 0;
return jspeFactorArray();
} else if (lex->tk==LEX_R_FUNCTION) {
if (!jspCheckStackPosition()) return 0;
JSP_ASSERT_MATCH(LEX_R_FUNCTION);
return jspeFunctionDefinition(true);
#ifndef SAVE_ON_FLASH
} else if (lex->tk==LEX_R_CLASS) {
if (!jspCheckStackPosition()) return 0;
JSP_ASSERT_MATCH(LEX_R_CLASS);
return jspeClassDefinition(true);
} else if (lex->tk==LEX_R_SUPER) {
JSP_ASSERT_MATCH(LEX_R_SUPER);
if (jsvIsObject(execInfo.thisVar)) {
JsVar *proto1 = jsvObjectGetChild(execInfo.thisVar, JSPARSE_INHERITS_VAR, 0);       JsVar *proto2 = jsvIsObject(proto1) ? jsvObjectGetChild(proto1, JSPARSE_INHERITS_VAR, 0) : 0;       jsvUnLock(proto1);
if (!proto2) {
jsExceptionHere(JSET_SYNTAXERROR, "Calling 'super' outside of class");
return 0;
}
if (lex->tk=='(') return proto2;             JsVar *proto3 = jsvIsFunction(proto2) ? jsvObjectGetChild(proto2, JSPARSE_PROTOTYPE_VAR, 0) : 0;
jsvUnLock(proto2);
return proto3;
} else if (jsvIsFunction(execInfo.thisVar)) {
JsVar *proto1 = jsvObjectGetChild(execInfo.thisVar, JSPARSE_PROTOTYPE_VAR, 0);
JsVar *proto2 = jsvIsObject(proto1) ? jsvObjectGetChild(proto1, JSPARSE_INHERITS_VAR, 0) : 0;
jsvUnLock(proto1);
if (!proto2) {
jsExceptionHere(JSET_SYNTAXERROR, "Calling 'super' outside of class");
return 0;
}
return proto2;
}
jsExceptionHere(JSET_SYNTAXERROR, "Calling 'super' outside of class");
return 0;
#endif
} else if (lex->tk==LEX_R_THIS) {
JSP_ASSERT_MATCH(LEX_R_THIS);
return jsvLockAgain( execInfo.thisVar ? execInfo.thisVar : execInfo.root );
} else if (lex->tk==LEX_R_DELETE) {
if (!jspCheckStackPosition()) return 0;
return jspeFactorDelete();
} else if (lex->tk==LEX_R_TYPEOF) {
if (!jspCheckStackPosition()) return 0;
return jspeFactorTypeOf();
} else if (lex->tk==LEX_R_VOID) {
JSP_ASSERT_MATCH(LEX_R_VOID);
jsvUnLock(jspeUnaryExpression());
return 0;
}
JSP_MATCH(LEX_EOF);
jsExceptionHere(JSET_SYNTAXERROR, "Unexpected end of Input\n");
return 0;
}

LogicalResult matchAndRewriteSortOp(OpTy op, ValueRange xys, uint64_t nx,
uint64_t ny, bool isCoo,
PatternRewriter &rewriter) {
Location loc = op.getLoc();
SmallVector<Value> operands{constantIndex(rewriter, loc, 0), op.getN()};
for (Value v : xys) {
auto mtp = getMemRefType(v);
if (!mtp.isDynamicDim(0)) {
auto newMtp =
MemRefType::get({ShapedType::kDynamic}, mtp.getElementType());
v = rewriter.create<memref::CastOp>(loc, newMtp, v);
}
operands.push_back(v);
}
auto insertPoint = op->template getParentOfType<func::FuncOp>();
SmallString<32> funcName;
FuncGeneratorType funcGenerator;
uint32_t nTrailingP = 0;
switch (op.getAlgorithm()) {
case SparseTensorSortKind::HybridQuickSort: {
funcName = kHybridQuickSortFuncNamePrefix;
funcGenerator = createQuickSortFunc;
nTrailingP = 1;
Value pDepthLimit = rewriter.create<memref::AllocaOp>(
loc, MemRefType::get({}, rewriter.getI64Type()));
operands.push_back(pDepthLimit);
Value lo = operands[loIdx];
Value hi = operands[hiIdx];
Value len = rewriter.create<arith::IndexCastOp>(
loc, rewriter.getI64Type(),
rewriter.create<arith::SubIOp>(loc, hi, lo));
Value depthLimit = rewriter.create<arith::SubIOp>(
loc, constantI64(rewriter, loc, 64),
rewriter.create<math::CountLeadingZerosOp>(loc, len));
depthLimit = rewriter.create<arith::ShLIOp>(loc, depthLimit,
constantI64(rewriter, loc, 1));
rewriter.create<memref::StoreOp>(loc, depthLimit, pDepthLimit);
break;
}
case SparseTensorSortKind::QuickSort:
funcName = kQuickSortFuncNamePrefix;
funcGenerator = createQuickSortFunc;
break;
case SparseTensorSortKind::InsertionSortStable:
funcName = kSortStableFuncNamePrefix;
funcGenerator = createSortStableFunc;
break;
case SparseTensorSortKind::HeapSort:
funcName = kHeapSortFuncNamePrefix;
funcGenerator = createHeapSortFunc;
break;
}
FlatSymbolRefAttr func =
getMangledSortHelperFunc(rewriter, insertPoint, TypeRange(), funcName, nx,
ny, isCoo, operands, funcGenerator, nTrailingP);
rewriter.replaceOpWithNewOp<func::CallOp>(op, func, TypeRange(), operands);
return success();
}

xmlXPathObjectPtr
xmlXPtrNewRangeNodeObject(xmlNodePtr start, xmlXPathObjectPtr end) {
xmlXPathObjectPtr ret;
if (start == NULL)
return(NULL);
if (end == NULL)
return(NULL);
switch (end->type) {
case XPATH_POINT:
case XPATH_RANGE:
break;
case XPATH_NODESET:
if (end->nodesetval->nodeNr <= 0)
return(NULL);
break;
default:
return(NULL);
}
ret = (xmlXPathObjectPtr) xmlMalloc(sizeof(xmlXPathObject));
if (ret == NULL) {
xmlXPtrErrMemory("allocating range");
return(NULL);
}
memset(ret, 0 , (size_t) sizeof(xmlXPathObject));
ret->type = XPATH_RANGE;
ret->user = start;
ret->index = -1;
switch (end->type) {
case XPATH_POINT:
ret->user2 = end->user;
ret->index2 = end->index;
break;
case XPATH_RANGE:
ret->user2 = end->user2;
ret->index2 = end->index2;
break;
case XPATH_NODESET: {
ret->user2 = end->nodesetval->nodeTab[end->nodesetval->nodeNr - 1];
ret->index2 = -1;
break;
}
default:
STRANGE
return(NULL);
}
xmlXPtrRangeCheckOrder(ret);
return(ret);
}

int nfc_enable_se(struct nfc_dev *dev, u32 se_idx)
{
struct nfc_se *se;
int rc;
pr_debug("%s se index %d\n", dev_name(&dev->dev), se_idx);
device_lock(&dev->dev);
if (!device_is_registered(&dev->dev)) {
rc = -ENODEV;
goto error;
}
if (!dev->dev_up) {
rc = -ENODEV;
goto error;
}
if (dev->polling) {
rc = -EBUSY;
goto error;
}
if (!dev->ops->enable_se || !dev->ops->disable_se) {
rc = -EOPNOTSUPP;
goto error;
}
se = nfc_find_se(dev, se_idx);
if (!se) {
rc = -EINVAL;
goto error;
}
if (se->state == NFC_SE_ENABLED) {
rc = -EALREADY;
goto error;
}
rc = dev->ops->enable_se(dev, se_idx);
if (rc >= 0)
se->state = NFC_SE_ENABLED;
error:
device_unlock(&dev->dev);
return rc;
}

static int n_tty_ioctl(struct tty_struct *tty, struct file *file,
unsigned int cmd, unsigned long arg)
{
struct n_tty_data *ldata = tty->disc_data;
int retval;
switch (cmd) {
case TIOCOUTQ:
return put_user(tty_chars_in_buffer(tty), (int __user *) arg);
case TIOCINQ:
down_write(&tty->termios_rwsem);
if (L_ICANON(tty))
retval = inq_canon(ldata);
else
retval = read_cnt(ldata);
up_write(&tty->termios_rwsem);
return put_user(retval, (unsigned int __user *) arg);
default:
return n_tty_ioctl_helper(tty, file, cmd, arg);
}
}

static bool net_tx_pkt_do_sw_fragmentation(struct NetTxPkt *pkt,
NetClientState *nc)
{
struct iovec fragment[NET_MAX_FRAG_SG_LIST];
size_t fragment_len = 0;
bool more_frags = false;
void *l2_iov_base, *l3_iov_base;
size_t l2_iov_len, l3_iov_len;
int src_idx =  NET_TX_PKT_PL_START_FRAG, dst_idx;
size_t src_offset = 0;
size_t fragment_offset = 0;
l2_iov_base = pkt->vec[NET_TX_PKT_L2HDR_FRAG].iov_base;
l2_iov_len = pkt->vec[NET_TX_PKT_L2HDR_FRAG].iov_len;
l3_iov_base = pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_base;
l3_iov_len = pkt->vec[NET_TX_PKT_L3HDR_FRAG].iov_len;
fragment[NET_TX_PKT_FRAGMENT_L2_HDR_POS].iov_base = l2_iov_base;
fragment[NET_TX_PKT_FRAGMENT_L2_HDR_POS].iov_len = l2_iov_len;
fragment[NET_TX_PKT_FRAGMENT_L3_HDR_POS].iov_base = l3_iov_base;
fragment[NET_TX_PKT_FRAGMENT_L3_HDR_POS].iov_len = l3_iov_len;
do {
fragment_len = net_tx_pkt_fetch_fragment(pkt, &src_idx, &src_offset,
fragment, &dst_idx);
more_frags = (fragment_offset + fragment_len < pkt->payload_len);
eth_setup_ip4_fragmentation(l2_iov_base, l2_iov_len, l3_iov_base,
l3_iov_len, fragment_len, fragment_offset, more_frags);
eth_fix_ip4_checksum(l3_iov_base, l3_iov_len);
net_tx_pkt_sendv(pkt, nc, fragment, dst_idx);
fragment_offset += fragment_len;
} while (more_frags);
return true;
}

static int instance_mkdir (struct inode *inode, struct dentry *dentry, umode_t mode)
{
