bool SQClass::NewSlot(SQSharedState *ss,const SQObjectPtr &key,const SQObjectPtr &val,bool bstatic)
{
SQObjectPtr temp;
bool belongs_to_static_table = sq_type(val) == OT_CLOSURE || sq_type(val) == OT_NATIVECLOSURE || bstatic;
if(_locked && !belongs_to_static_table)
return false;     if(_members->Get(key,temp) && _isfield(temp))     {
_defaultvalues[_member_idx(temp)].val = val;
return true;
}
if(belongs_to_static_table) {
SQInteger mmidx;
if((sq_type(val) == OT_CLOSURE || sq_type(val) == OT_NATIVECLOSURE) &&
(mmidx = ss->GetMetaMethodIdxByName(key)) != -1) {
_metamethods[mmidx] = val;
}
else {
SQObjectPtr theval = val;
if(_base && sq_type(val) == OT_CLOSURE) {
theval = _closure(val)->Clone();
_closure(theval)->_base = _base;
__ObjAddRef(_base);             }
if(sq_type(temp) == OT_NULL) {
bool isconstructor;
SQVM::IsEqual(ss->_constructoridx, key, isconstructor);
if(isconstructor) {
_constructoridx = (SQInteger)_methods.size();
}
SQClassMember m;
m.val = theval;
_members->NewSlot(key,SQObjectPtr(_make_method_idx(_methods.size())));
_methods.push_back(m);
}
else {
_methods[_member_idx(temp)].val = theval;
}
}
return true;
}
SQClassMember m;
m.val = val;
_members->NewSlot(key,SQObjectPtr(_make_field_idx(_defaultvalues.size())));
_defaultvalues.push_back(m);
return true;
}

void Compile(XlaOpKernelContext* ctx) override {
int64_t output_size;
xla::XlaOp output_size_param = ctx->Input("size");
StatusOr<xla::Shape> output_shape_or =
ctx->builder()->GetShape(output_size_param);
OP_REQUIRES_OK(ctx, output_shape_or.status());
auto output_shape_param = output_shape_or.ValueOrDie();
auto output_rank = output_shape_param.rank();
OP_REQUIRES(ctx, output_rank == 0,
errors::InvalidArgument("Shape must be rank 0 but is rank ",
output_rank));
OP_REQUIRES_OK(ctx, ctx->ConstantInputAsIntScalar("size", &output_size));
OP_REQUIRES(ctx, output_size >= 0,
errors::InvalidArgument("size (", output_size,
") must be non-negative"));
xla::XlaOp idx, updates, output;
xla::XlaOp input = ctx->Input(0);
auto input_xla_type = ctx->input_xla_type(0);
xla::PrimitiveType dtype = ctx->InputXlaType("weights");
auto zero = xla::Zero(ctx->builder(), dtype);
auto one = xla::One(ctx->builder(), dtype);
StatusOr<xla::Shape> input_shape_or = ctx->builder()->GetShape(input);
OP_REQUIRES_OK(ctx, input_shape_or.status());
auto input_shape = input_shape_or.ValueOrDie();
auto size = input_shape.dimensions(0);
if (!size) {
output = xla::Broadcast(zero, {output_size});
ctx->SetOutput(0, output);
return;
}
auto rank = input_shape.rank();
OP_REQUIRES(ctx, rank <= 2,
errors::InvalidArgument(
"Shape must be at most rank 2 but is rank ", rank));
xla::XlaOp weights = ctx->Input(2);
StatusOr<xla::Shape> weights_shape_or = ctx->builder()->GetShape(weights);
OP_REQUIRES_OK(ctx, weights_shape_or.status());
auto weights_shape = weights_shape_or.ValueOrDie();
auto weights_size = weights_shape.dimensions(0);
bool has_weights = false;
if (weights_size) {
has_weights = true;
}
xla::Shape output_shape = xla::ShapeUtil::MakeShape(dtype, {output_size});
xla::ScatterDimensionNumbers scatter_dnums;
scatter_dnums.set_index_vector_dim(1);
scatter_dnums.add_inserted_window_dims(0);
scatter_dnums.add_scatter_dims_to_operand_dims(0);
if (rank == 2) {
output_shape = xla::ShapeUtil::MakeShape(dtype, {size, output_size});
scatter_dnums.add_inserted_window_dims(1);
scatter_dnums.add_scatter_dims_to_operand_dims(1);
auto i_shape =
xla::ShapeUtil::MakeShape(input_xla_type, {input_shape.dimensions()});
auto i = xla::Iota(ctx->builder(), i_shape, 0);
i = xla::Reshape(
i, {input_shape.dimensions(0) * input_shape.dimensions(1), 1});
auto j = xla::Reshape(
input, {input_shape.dimensions(0) * input_shape.dimensions(1), 1});
std::vector<xla::XlaOp> iotas_to_concat;
iotas_to_concat.push_back(i);
iotas_to_concat.push_back(j);
idx = xla::ConcatInDim(ctx->builder(), iotas_to_concat, 1);
updates = xla::Broadcast(
one, {input_shape.dimensions(0) * input_shape.dimensions(1)});
output = xla::Broadcast(
zero, {output_shape.dimensions(0), output_shape.dimensions(1)});
if (has_weights && !binary_output_) {
weights = xla::Reshape(
weights, {input_shape.dimensions(0) * input_shape.dimensions(1)});
updates = weights;
}
} else {
input = xla::Reshape(input, {size, 1});
idx = xla::Reshape(input, {size, 1});
updates = xla::Broadcast(one, {size});
output = xla::Broadcast(zero, {output_size});
if (has_weights && !binary_output_) {
updates = weights;
}
}
xla::XlaComputation assn_computation = [&] {
std::unique_ptr<xla::XlaBuilder> subb =
ctx->builder()->CreateSubBuilder("scatter_bincount");
xla::Shape param_shape = xla::ShapeUtil::MakeShape(dtype, {});
auto p0 = xla::Parameter(subb.get(), 0, param_shape, "p0");
auto p1 = xla::Parameter(subb.get(), 1, param_shape, "p1");
if (!binary_output_) {
xla::Add(p0, p1);
}
return subb->BuildAndNoteError();
}();
output = xla::Scatter(output, idx, updates, assn_computation, scatter_dnums,
false, false);
ctx->SetOutput(0, output);
}

static NO_INLINE JsVar *jspGetNamedFieldInParents(JsVar *object, const char* name, bool returnName) {
JsVar * child = jspeiFindChildFromStringInParents(object, name);
if (!child) {
child = jswFindBuiltInFunction(object, name);
}
if (child && returnName) {
if (jsvIsName(child)) {
JsVar *t = jsvGetValueOfName(child);
jsvUnLock(child);
child = t;
}
JsVar *nameVar = jsvNewFromString(name);
JsVar *newChild = jsvCreateNewChild(object, nameVar, child);
jsvUnLock2(nameVar, child);
child = newChild;
}
if (!child) {
if (jsvIsFunction(object) && strcmp(name, JSPARSE_PROTOTYPE_VAR)==0) {
JsVar *proto = jsvNewObject();
jsvObjectSetChild(proto, JSPARSE_CONSTRUCTOR_VAR, object);
child = jsvAddNamedChild(object, proto, JSPARSE_PROTOTYPE_VAR);
jspEnsureIsPrototype(object, child);
jsvUnLock(proto);
} else if (strcmp(name, JSPARSE_INHERITS_VAR)==0) {
const char *objName = jswGetBasicObjectName(object);
if (objName) {
child = jspNewPrototype(objName);
}
}
}
return child;
}

int
dwg_decode_add_object (Dwg_Data *restrict dwg, Bit_Chain *dat,
Bit_Chain *hdl_dat, long unsigned int address)
{
long unsigned int objpos, restartpos;
Bit_Chain abs_dat = { NULL };
unsigned char previous_bit;
Dwg_Object *restrict obj;
BITCODE_BL num = dwg->num_objects;
int error = 0;
int realloced = 0;
abs_dat = *dat;
dat->byte = address;
dat->bit = 0;
realloced = dwg_add_object (dwg);
if (realloced > 0)
{
*dat = abs_dat;
return realloced;     }
obj = &dwg->object[num];
LOG_INFO ("==========================================\n"
"Object number: %lu/%lX",
(unsigned long)num, (unsigned long)num)
obj->size = bit_read_MS (dat);
LOG_INFO (", Size: %d [MS]", obj->size)
SINCE (R_2010)
{
obj->handlestream_size = bit_read_UMC (dat);
LOG_INFO (", Hdlsize: " FORMAT_UMC " [UMC] ", obj->handlestream_size);
obj->bitsize = obj->size * 8 - obj->handlestream_size;
}
objpos = bit_position (dat);   obj->address = dat->byte;
bit_reset_chain (dat);
if (obj->size > dat->size || dat->chain + dat->size > abs_dat.chain + abs_dat.size)
{
LOG_TRACE ("\n");
LOG_WARN ("Invalid object size %u > %ld. Would overflow", obj->size,
dat->size);
error |= DWG_ERR_VALUEOUTOFBOUNDS;
#if 0
obj->size = dat->size - 1;
#else
*dat = abs_dat;
return error;
#endif
}
dat->size = obj->size;
SINCE (R_2010) { obj->type = bit_read_BOT (dat); }
else { obj->type = bit_read_BS (dat); }
LOG_INFO (", Type: %d [%s], Address: %lu\n", obj->type,
dat->from_version >= R_2010 ? "BOT" : "BS", obj->address);
restartpos = bit_position (dat); 
switch (obj->type)
{
case DWG_TYPE_TEXT:
error = dwg_decode_TEXT (dat, obj);
break;
case DWG_TYPE_ATTRIB:
error = dwg_decode_ATTRIB (dat, obj);
break;
case DWG_TYPE_ATTDEF:
error = dwg_decode_ATTDEF (dat, obj);
break;
case DWG_TYPE_BLOCK:
error = dwg_decode_BLOCK (dat, obj);
break;
case DWG_TYPE_ENDBLK:
error = dwg_decode_ENDBLK (dat, obj);
break;
case DWG_TYPE_SEQEND:
error = dwg_decode_SEQEND (dat, obj);
if (dat->from_version >= R_13 && obj->tio.entity->ownerhandle)
{
Dwg_Object *restrict owner = dwg_resolve_handle (
dwg, obj->tio.entity->ownerhandle->absolute_ref);
if (!owner)
{
LOG_WARN ("no SEQEND.ownerhandle")
}
else if (owner->fixedtype == DWG_TYPE_INSERT
|| owner->fixedtype == DWG_TYPE_MINSERT)
{
hash_set (dwg->object_map, obj->handle.value, (uint32_t)num);
(void)dwg_validate_INSERT (owner);
}
else if (owner->fixedtype == DWG_TYPE_POLYLINE_2D
|| owner->fixedtype == DWG_TYPE_POLYLINE_3D
|| owner->fixedtype == DWG_TYPE_POLYLINE_PFACE
|| owner->fixedtype == DWG_TYPE_POLYLINE_MESH)
{
Dwg_Entity_POLYLINE_2D *restrict _obj
= owner->tio.entity->tio.POLYLINE_2D;
if (!_obj->seqend)
hash_set (dwg->object_map, obj->handle.value, (uint32_t)num);
(void)dwg_validate_POLYLINE (owner);
}
}
break;
case DWG_TYPE_INSERT:
error = dwg_decode_INSERT (dat, obj);
break;
case DWG_TYPE_MINSERT:
error = dwg_decode_MINSERT (dat, obj);
break;
case DWG_TYPE_VERTEX_2D:
error = dwg_decode_VERTEX_2D (dat, obj);
break;
case DWG_TYPE_VERTEX_3D:
error = dwg_decode_VERTEX_3D (dat, obj);
break;
case DWG_TYPE_VERTEX_MESH:
error = dwg_decode_VERTEX_MESH (dat, obj);
break;
case DWG_TYPE_VERTEX_PFACE:
error = dwg_decode_VERTEX_PFACE (dat, obj);
break;
case DWG_TYPE_VERTEX_PFACE_FACE:
error = dwg_decode_VERTEX_PFACE_FACE (dat, obj);
break;
case DWG_TYPE_POLYLINE_2D:
error = dwg_decode_POLYLINE_2D (dat, obj);
if (dat->from_version >= R_2010)
check_POLYLINE_handles (obj);
break;
case DWG_TYPE_POLYLINE_3D:
