int crxFreeImageData(CrxImage *img)
{
CrxTile *tile = img->tiles;
int nTiles = img->tileRows * img->tileCols;
if (img->tiles)
{
for (int32_t curTile = 0; curTile < nTiles; curTile++, tile++)
if (tile[curTile].comps)
for (int32_t curPlane = 0; curPlane < img->nPlanes; curPlane++)
crxFreeSubbandData(img, tile[curTile].comps + curPlane);
free(img->tiles);
img->tiles = 0;
}
if (img->planeBuf)
{
free(img->planeBuf);
img->planeBuf = 0;
}
return 0;
}

void Compute(OpKernelContext* context) override {
const Tensor& input = context->input(0);
const Tensor& sizes = context->input(1);
OP_REQUIRES(
context,
(TensorShapeUtils::IsVector(sizes.shape()) ||
TensorShapeUtils::IsScalar(sizes.shape())),
errors::InvalidArgument("sizes input must be 1-D, not ",
sizes.shape().DebugString()));
TensorShape shape;
int64_t product = 1;
int unknown_index = -1;
bool sizes_has_zero_dim;
switch (sizes.dtype()) {
case DT_INT32:
OP_REQUIRES_OK(context,
ValidateSizes<int32>(sizes, &product, &unknown_index,
&shape, &sizes_has_zero_dim));
break;
case DT_INT64:
OP_REQUIRES_OK(context,
ValidateSizes<int64_t>(sizes, &product, &unknown_index,
&shape, &sizes_has_zero_dim));
break;
default:
context->CtxFailure(errors::InvalidArgument(
"desired shape must be a DT_INT32 or DT_INT64 vector, not a ",
DataTypeString(sizes.dtype())));
return;
}
if (unknown_index != -1) {
int64_t input_num_elements = 1;
bool input_has_zero_dim = false;
for (int dim = 0; dim < input.dims(); dim++) {
if (input.dim_size(dim) > 0 || !sizes_has_zero_dim) {
input_num_elements *= input.dim_size(dim);
} else {
input_has_zero_dim = true;
}
}
const int64_t missing = input_num_elements / product;
if (!input_has_zero_dim) {
OP_REQUIRES(
context, product * missing == input_num_elements,
errors::InvalidArgument(
"Input to reshape is a tensor with ", input_num_elements,
" values, but the requested shape requires a multiple of ",
product));
}
shape.set_dim(unknown_index, missing);
}
OP_REQUIRES(context, shape.num_elements() == input.NumElements(),
errors::InvalidArgument("Input to reshape is a tensor with ",
input.NumElements(),
" values, but the requested shape has ",
shape.num_elements()));
Tensor output(input.dtype());
CHECK(output.CopyFrom(input, shape));
context->set_output(0, output);
}

void Compute(OpKernelContext *ctx) override {
const Tensor *a_indices_t, *a_values_t, *a_shape_t, *b_indices_t,
*b_values_t, *b_shape_t;
OP_REQUIRES_OK(ctx, ctx->input("a_indices", &a_indices_t));
OP_REQUIRES_OK(ctx, ctx->input("a_values", &a_values_t));
OP_REQUIRES_OK(ctx, ctx->input("a_shape", &a_shape_t));
OP_REQUIRES_OK(ctx, ctx->input("b_indices", &b_indices_t));
OP_REQUIRES_OK(ctx, ctx->input("b_values", &b_values_t));
OP_REQUIRES_OK(ctx, ctx->input("b_shape", &b_shape_t));
OP_REQUIRES(
ctx,
TensorShapeUtils::IsMatrix(a_indices_t->shape()) &&
TensorShapeUtils::IsMatrix(b_indices_t->shape()),
errors::InvalidArgument("Inputs a_indices and b_indices should be "
"matrices but received shapes: ",
a_indices_t->shape().DebugString(), ", ",
b_indices_t->shape().DebugString()));
OP_REQUIRES(ctx,
TensorShapeUtils::IsVector(a_values_t->shape()) &&
TensorShapeUtils::IsVector(b_values_t->shape()),
errors::InvalidArgument(
"Inputs a_values and b_values should be vectors "
"but received shapes: ",
a_values_t->shape().DebugString(), " and ",
b_values_t->shape().DebugString()));
const int64_t a_nnz = a_indices_t->dim_size(0);
const int64_t b_nnz = b_indices_t->dim_size(0);
const auto a_values = a_values_t->vec<T>();
const auto b_values = b_values_t->vec<T>();
OP_REQUIRES(
ctx, a_values.size() == a_nnz && b_values.size() == b_nnz,
errors::InvalidArgument("Expected ", a_nnz, " and ", b_nnz,
" non-empty input values, got ",
a_values.size(), " and ", b_values.size()));
OP_REQUIRES(ctx,
TensorShapeUtils::IsVector(a_shape_t->shape()) &&
TensorShapeUtils::IsVector(b_shape_t->shape()),
errors::InvalidArgument(
"Input shapes should be a vector but received shapes ",
a_shape_t->shape().DebugString(), " and ",
b_shape_t->shape().DebugString()));
const int num_dims = a_indices_t->dim_size(1);
OP_REQUIRES(
ctx, a_shape_t->NumElements() == num_dims,
errors::InvalidArgument("Second dimension of a_indices and length of "
"a_shape must match, got ",
num_dims, " and ", a_shape_t->NumElements()));
OP_REQUIRES(ctx, num_dims > 0,
errors::InvalidArgument("Tensors must not be empty"));
OP_REQUIRES(ctx, a_shape_t->IsSameSize(*b_shape_t),
errors::InvalidArgument(
"Operands do not have the same ranks; got shapes: ",
a_shape_t->SummarizeValue(10), " and ",
b_shape_t->SummarizeValue(10)));
const auto a_shape = a_shape_t->flat<int64_t>();
const auto b_shape = b_shape_t->flat<int64_t>();
for (int i = 0; i < a_shape_t->NumElements(); ++i) {
OP_REQUIRES(ctx, a_shape(i) == b_shape(i),
errors::InvalidArgument("Operands' shapes do not match: got ",
a_shape(i), " and ", b_shape(i),
" for dimension ", i));
}
const auto a_indices_mat = a_indices_t->matrix<int64_t>();
const auto b_indices_mat = b_indices_t->matrix<int64_t>();
std::vector<T> a_augmented_values, b_augmented_values;
std::vector<std::pair<bool, int64>> entries_to_copy;      UnionSparseIndicesAndValues(a_indices_mat, a_values, a_nnz, b_indices_mat,
b_values, b_nnz, num_dims, &a_augmented_values,
&b_augmented_values, &entries_to_copy);
const int64_t sum_nnz = a_augmented_values.size();
Tensor *output_indices_t, *output_values_t;
OP_REQUIRES_OK(ctx,
ctx->allocate_output(0, TensorShape({sum_nnz, num_dims}),
&output_indices_t));
OP_REQUIRES_OK(
ctx, ctx->allocate_output(1, TensorShape({sum_nnz}), &output_values_t));
auto output_indices_mat = output_indices_t->matrix<int64_t>();
for (int64_t i = 0; i < sum_nnz; ++i) {
const bool from_a = entries_to_copy[i].first;
const int64_t idx = entries_to_copy[i].second;
output_indices_mat.chip<0>(i) =
from_a ? a_indices_mat.chip<0>(idx) : b_indices_mat.chip<0>(idx);
}
using UnalignedTensorMap =
Eigen::TensorMap<Eigen::Tensor<const T, 1, Eigen::RowMajor>,
Eigen::Unaligned>;
auto a_augmented_values_t =
UnalignedTensorMap(a_augmented_values.data(), sum_nnz);
auto b_augmented_values_t =
UnalignedTensorMap(b_augmented_values.data(), sum_nnz);
output_values_t->flat<T>().device(ctx->eigen_device<Device>()) =
a_augmented_values_t.binaryExpr(b_augmented_values_t,
typename Functor::func());
}

int
bracketed_paste(paste_mode_T mode, int drop, garray_T *gap)
{
intc;
char_ubuf[NUMBUFLEN + MB_MAXBYTES];
intidx = 0;
char_u*end = find_termcode((char_u *)"PE");
intret_char = -1;
intsave_allow_keys = allow_keys;
intsave_paste = p_paste;
if (end != NULL && STRLEN(end) >= NUMBUFLEN)
end = NULL;
++no_mapping;
allow_keys = 0;
if (!p_paste)
set_option_value((char_u *)"paste", TRUE, NULL, 0);
for (;;)
{
if (end == NULL && vpeekc() == NUL)
break;
do
c = vgetc();
while (c == K_IGNORE || c == K_VER_SCROLLBAR || c == K_HOR_SCROLLBAR);
if (c == NUL || got_int || (ex_normal_busy > 0 && c == Ctrl_C))
break;
if (has_mbyte)
idx += (*mb_char2bytes)(c, buf + idx);
else
buf[idx++] = c;
buf[idx] = NUL;
if (end != NULL && STRNCMP(buf, end, idx) == 0)
{
if (end[idx] == NUL)
break;     continue;
}
if (!drop)
{
switch (mode)
{
case PASTE_CMDLINE:
put_on_cmdline(buf, idx, TRUE);
break;
case PASTE_EX:
if (gap != NULL && ga_grow(gap, idx) == OK)
{
mch_memmove((char *)gap->ga_data + gap->ga_len,
buf, (size_t)idx);
gap->ga_len += idx;
}
break;
case PASTE_INSERT:
if (stop_arrow() == OK)
{
c = buf[0];
if (idx == 1 && (c == CAR || c == K_KENTER || c == NL))
ins_eol(c);
else
{
ins_char_bytes(buf, idx);
AppendToRedobuffLit(buf, idx);
}
}
break;
case PASTE_ONE_CHAR:
if (ret_char == -1)
{
if (has_mbyte)
ret_char = (*mb_ptr2char)(buf);
else
ret_char = buf[0];
}
break;
}
}
idx = 0;
}
--no_mapping;
allow_keys = save_allow_keys;
if (!save_paste)
set_option_value((char_u *)"paste", FALSE, NULL, 0);
return ret_char;
}

void
kc_var_col (dbe_key_t * key, buffer_desc_t * buf, db_buf_t row, dbe_col_loc_t * cl, db_buf_t * p1, row_size_t * l1, db_buf_t * p2, row_size_t* l2, unsigned short * offset)
{
row_ver_t rv = IE_ROW_VERSION (row);
int off, len;
if (rv & cl->cl_row_version_mask)
{
int irow = SHORT_REF (row + cl->cl_pos[rv]);
row = buf->bd_buffer + buf->bd_content_map->pm_entries[irow & ROW_NO_MASK];
rv = IE_ROW_VERSION (row);
*offset = ((unsigned short)irow) >> COL_OFFSET_SHIFT;
}
else
*offset = 0;
len = cl->cl_pos[rv];
if (CL_FIRST_VAR == len)
{
if (key->key_version != IE_KEY_VERSION (row))
key = key->key_versions[IE_KEY_VERSION (row)];
off = 0 == IE_KEY_VERSION (row) ? key->key_key_var_start[rv] : key->key_row_var_start[rv];
len = SHORT_REF (row + key->key_length_area[rv]) - off;
}
else
{
len = -len;
off = SHORT_REF (row + len) & COL_VAR_LEN_MASK;
len = SHORT_REF (row + len + 2) - off;
}
if (len & COL_VAR_SUFFIX)
{
unsigned short irow;
short pref_len;
len &= COL_VAR_LEN_MASK;
irow = SHORT_REF_NA (row + off);
pref_len = irow >> COL_OFFSET_SHIFT;
if (15 == pref_len)
{
*l1 = row[off + 2];
*p2 = row + off + 3;
*l2 = len - 3;
}
else
{
*l1 = pref_len;
*p2 = row + off + 2;
*l2 = len - 2;
}
if ((irow & ROW_NO_MASK) >= buf->bd_content_map->pm_count)
{
log_error ("Row ref %u is out of range %u", irow, buf->bd_content_map->pm_count);
GPF_T1 ("prefix row ref out of pm range");
}
row = buf->bd_buffer + buf->bd_content_map->pm_entries[irow & ROW_NO_MASK];
rv = IE_ROW_VERSION (row);
if (cl->cl_pos[rv] == CL_FIRST_VAR)
{
off = (0 == IE_KEY_VERSION (row) ? key->key_key_var_start[rv] : key->key_row_var_start[rv]);
}
else
{
off = COL_VAR_LEN_MASK & SHORT_REF (row - cl->cl_pos[rv]);
}
*p1 = row + off;
}
else
{
*l1 = len;
*p1 = row + off;
*l2 = 0;
}
}

