int WebObjects_translate(request_rec *r) {
WebObjects_config *wc;
WOURLComponents url;
WOURLError urlerr;
wc = ap_get_module_config(r->server->module_config, &WebObjects_module);
WOLog(WO_DBG, "<WebObjects Apache Module> new translate: %s", r->uri);
if (strncmp(wc->WebObjects_alias, r->uri, strlen(wc->WebObjects_alias)) == 0 || (r->handler != NULL && strcasecmp(r->handler, WEBOBJECTS) == 0)) {
#ifndef _MSC_VER         url = WOURLComponents_Initializer;
#else
memset(&url,0,sizeof(WOURLComponents));
#endif
urlerr = WOParseApplicationName(&url, r->uri);
if (urlerr != WOURLOK && !((urlerr == WOURLInvalidApplicationName) && ac_authorizeAppListing(&url))) {
WOLog(WO_DBG, "<WebObjects Apache Module> translate - DECLINED: %s", r->uri);
return DECLINED;
}
if (!adaptorEnabled)
{
WOLog(WO_ERR, "WebObjects_translate(): declining request due to initialization failure");
return DECLINED;
}
r->handler = (char *)apr_pstrdup(r->pool, WEBOBJECTS);
r->filename = (char *)apr_pstrdup(r->pool, r->uri);
return OK;
}
WOLog(WO_DBG, "<WebObjects Apache Module> translate - DECLINED: %s", r->uri);
return DECLINED;
}

static int rtmp_packet_read_one_chunk(URLContext *h, RTMPPacket *p,
int chunk_size, RTMPPacket **prev_pkt_ptr,
int *nb_prev_pkt, uint8_t hdr)
{
uint8_t buf[16];
int channel_id, timestamp, size;
uint32_t ts_field;     uint32_t extra = 0;
enum RTMPPacketType type;
int written = 0;
int ret, toread;
RTMPPacket *prev_pkt;
written++;
channel_id = hdr & 0x3F;
if (channel_id < 2) {         buf[1] = 0;
if (ffurl_read_complete(h, buf, channel_id + 1) != channel_id + 1)
return AVERROR(EIO);
written += channel_id + 1;
channel_id = AV_RL16(buf) + 64;
}
if ((ret = ff_rtmp_check_alloc_array(prev_pkt_ptr, nb_prev_pkt,
channel_id)) < 0)
return ret;
prev_pkt = *prev_pkt_ptr;
size  = prev_pkt[channel_id].size;
type  = prev_pkt[channel_id].type;
extra = prev_pkt[channel_id].extra;
hdr >>= 6;     if (hdr == RTMP_PS_ONEBYTE) {
ts_field = prev_pkt[channel_id].ts_field;
} else {
if (ffurl_read_complete(h, buf, 3) != 3)
return AVERROR(EIO);
written += 3;
ts_field = AV_RB24(buf);
if (hdr != RTMP_PS_FOURBYTES) {
if (ffurl_read_complete(h, buf, 3) != 3)
return AVERROR(EIO);
written += 3;
size = AV_RB24(buf);
if (ffurl_read_complete(h, buf, 1) != 1)
return AVERROR(EIO);
written++;
type = buf[0];
if (hdr == RTMP_PS_TWELVEBYTES) {
if (ffurl_read_complete(h, buf, 4) != 4)
return AVERROR(EIO);
written += 4;
extra = AV_RL32(buf);
}
}
}
if (ts_field == 0xFFFFFF) {
if (ffurl_read_complete(h, buf, 4) != 4)
return AVERROR(EIO);
timestamp = AV_RB32(buf);
} else {
timestamp = ts_field;
}
if (hdr != RTMP_PS_TWELVEBYTES)
timestamp += prev_pkt[channel_id].timestamp;
if (!prev_pkt[channel_id].read) {
if ((ret = ff_rtmp_packet_create(p, channel_id, type, timestamp,
size)) < 0)
return ret;
p->read = written;
p->offset = 0;
prev_pkt[channel_id].ts_field   = ts_field;
prev_pkt[channel_id].timestamp  = timestamp;
} else {
RTMPPacket *prev = &prev_pkt[channel_id];
p->data          = prev->data;
p->size          = prev->size;
p->channel_id    = prev->channel_id;
p->type          = prev->type;
p->ts_field      = prev->ts_field;
p->extra         = prev->extra;
p->offset        = prev->offset;
p->read          = prev->read + written;
p->timestamp     = prev->timestamp;
prev->data       = NULL;
}
p->extra = extra;
prev_pkt[channel_id].channel_id = channel_id;
prev_pkt[channel_id].type       = type;
prev_pkt[channel_id].size       = size;
prev_pkt[channel_id].extra      = extra;
size = size - p->offset;
toread = FFMIN(size, chunk_size);
if (ffurl_read_complete(h, p->data + p->offset, toread) != toread) {
ff_rtmp_packet_destroy(p);
return AVERROR(EIO);
}
size      -= toread;
p->read   += toread;
p->offset += toread;
if (size > 0) {
RTMPPacket *prev = &prev_pkt[channel_id];
prev->data = p->data;
prev->read = p->read;
prev->offset = p->offset;
p->data      = NULL;
return AVERROR(EAGAIN);
}
prev_pkt[channel_id].read = 0;     return p->read;
}

static cache_accel_t *read_cache_accel(RBuffer *cache_buf, cache_hdr_t *hdr, cache_map_t *maps) {
if (!cache_buf || !hdr || !hdr->accelerateInfoSize || !hdr->accelerateInfoAddr) {
return NULL;
}
ut64 offset = va2pa (hdr->accelerateInfoAddr, hdr->mappingCount, maps, cache_buf, 0, NULL, NULL);
if (!offset) {
return NULL;
}
ut64 size = sizeof (cache_accel_t);
cache_accel_t *accel = R_NEW0 (cache_accel_t);
if (!accel) {
return NULL;
}
if (r_buf_fread_at (cache_buf, offset, (ut8*) accel, "16il", 1) != size) {
R_FREE (accel);
return NULL;
}
accel->imagesExtrasOffset += offset;
accel->bottomUpListOffset += offset;
accel->dylibTrieOffset += offset;
accel->initializersOffset += offset;
accel->dofSectionsOffset += offset;
accel->reExportListOffset += offset;
accel->depListOffset += offset;
accel->rangeTableOffset += offset;
return accel;
}

static njs_jump_off_t
njs_vmcode_await(njs_vm_t *vm, njs_vmcode_await_t *await)
{
size_t              size;
njs_int_t           ret;
njs_frame_t         *frame;
njs_value_t         ctor, val, on_fulfilled, on_rejected, *value;
njs_promise_t       *promise;
njs_function_t      *fulfilled, *rejected;
njs_async_ctx_t     *ctx;
njs_native_frame_t  *active;
active = &vm->active_frame->native;
value = njs_scope_valid_value(vm, await->retval);
if (njs_slow_path(value == NULL)) {
return NJS_ERROR;
}
njs_set_function(&ctor, &vm->constructors[NJS_OBJ_TYPE_PROMISE]);
promise = njs_promise_resolve(vm, &ctor, value);
if (njs_slow_path(promise == NULL)) {
return NJS_ERROR;
}
ctx = active->function->await;
if (ctx == NULL) {
ctx = njs_mp_alloc(vm->mem_pool, sizeof(njs_async_ctx_t));
if (njs_slow_path(ctx == NULL)) {
njs_memory_error(vm);
return NJS_ERROR;
}
size = njs_function_frame_size(active);
fulfilled = njs_promise_create_function(vm, size);
if (njs_slow_path(fulfilled == NULL)) {
return NJS_ERROR;
}
ctx->await = fulfilled->context;
ctx->capability = active->function->context;
active->function->context = NULL;
ret = njs_function_frame_save(vm, ctx->await, NULL);
if (njs_slow_path(ret != NJS_OK)) {
return NJS_ERROR;
}
} else {
fulfilled = njs_promise_create_function(vm, 0);
if (njs_slow_path(fulfilled == NULL)) {
return NJS_ERROR;
}
}
ctx->pc = (u_char *) await + sizeof(njs_vmcode_await_t);
ctx->index = await->retval;
frame = (njs_frame_t *) active;
if (frame->exception.catch != NULL) {
ctx->await->native.pc = frame->exception.catch;
} else {
ctx->await->native.pc = ctx->pc;
}
fulfilled->context = ctx;
fulfilled->args_count = 1;
fulfilled->u.native = njs_await_fulfilled;
rejected = njs_promise_create_function(vm, 0);
if (njs_slow_path(rejected == NULL)) {
return NJS_ERROR;
}
rejected->context = ctx;
rejected->args_count = 1;
rejected->u.native = njs_await_rejected;
njs_set_object(&val, &promise->object);
njs_set_function(&on_fulfilled, fulfilled);
njs_set_function(&on_rejected, rejected);
ret = njs_promise_perform_then(vm, &val, &on_fulfilled, &on_rejected, NULL);
if (njs_slow_path(ret != NJS_OK)) {
return NJS_ERROR;
}
(void) njs_vmcode_return(vm, NULL, &vm->retval);
return NJS_AGAIN;
}

fz_hash_table *
fz_new_hash_table(fz_context *ctx, int initialsize, int keylen, int lock, fz_hash_table_drop_fn *drop_val)
{
fz_hash_table *table;
assert(keylen <= MAX_KEY_LEN);
table = fz_malloc_struct(ctx, fz_hash_table);
table->keylen = keylen;
table->size = initialsize;
table->load = 0;
table->lock = lock;
table->drop_val = drop_val;
fz_try(ctx)
{
table->ents = Memento_label(fz_malloc_array(ctx, table->size, fz_hash_entry), "hash_entries");
memset(table->ents, 0, sizeof(fz_hash_entry) * table->size);
}
fz_catch(ctx)
{
fz_free(ctx, table);
fz_rethrow(ctx);
}
return table;
}

