int
obj_string_stream (Bit_Chain *restrict dat, Dwg_Object *restrict obj,
Bit_Chain *restrict str)
{
BITCODE_RL start = obj->bitsize - 1;   BITCODE_RL data_size = 0;              BITCODE_RL old_size;                   BITCODE_RL old_byte;
assert (dat != str);
old_size = str->size;
old_byte = str->byte;
str->chain += str->byte;
str->byte = 0;
str->bit = 0;
str->size = (obj->bitsize / 8) + ((obj->bitsize % 8) ? 1 : 0);
bit_advance_position (str, start - 8);
if (str->byte >= old_size - old_byte)
{
LOG_WARN ("obj_string_stream overflow");
return DWG_ERR_VALUEOUTOFBOUNDS;
}
LOG_HANDLE (" obj string stream +%u: @%lu.%u (%lu)", start, str->byte,
str->bit & 7, bit_position (str));
obj->has_strings = bit_read_B (str);
LOG_TRACE (" has_strings: %d\n", (int)obj->has_strings);
if (!obj->has_strings)
{
if (obj->fixedtype == DWG_TYPE_SCALE)
obj->has_strings = 1;
return 0;
}
bit_advance_position (str, -1);   str->byte -= 2;
LOG_HANDLE (" @%lu.%u", str->byte, str->bit & 7);
data_size = (BITCODE_RL)bit_read_RS (str);
LOG_HANDLE (" data_size: %u/0x%x", data_size, data_size);
if (data_size & 0x8000)
{
BITCODE_RS hi_size;
bit_advance_position (str, -1);       str->byte -= 4;
data_size &= 0x7FFF;
hi_size = bit_read_RS (str);
data_size |= (hi_size << 15);
LOG_HANDLE (" data_size: %u/0x%x\n", data_size, data_size);
}
else
LOG_HANDLE ("\n");
str->byte -= 2;
if (data_size > obj->bitsize)
{
LOG_WARN ("Invalid string stream data_size: @%lu.%u\n", str->byte,
str->bit & 7);
obj->has_strings = 0;
bit_reset_chain (str);
return DWG_ERR_NOTYETSUPPORTED;     }
obj->stringstream_size = data_size;
bit_advance_position (str, -(int)data_size);
return 0;
}

int WebObjects_translate(request_rec *r) {
WebObjects_config *wc;
WOURLComponents url;
WOURLError urlerr;
wc = (WebObjects_config *)ap_get_module_config(r->server->module_config, &WebObjects_module);
if (strncmp(wc->WebObjects_alias, r->uri, strlen(wc->WebObjects_alias)) == 0) {
url = WOURLComponents_Initializer;
urlerr = WOParseApplicationName(&url, r->uri);
if (urlerr != WOURLOK && !((urlerr == WOURLInvalidApplicationName) && ac_authorizeAppListing(&url))) {
return DECLINED;
}
if (!adaptorEnabled)
{
WOLog(WO_ERR, "WebObjects_translate(): declining request due to initialization failure");
return DECLINED;
}
r->handler = (char *)ap_pstrdup(r->pool, WEBOBJECTS);
return OK;
}
return DECLINED;
}

