void * grow_temp(size_t s) {
if (temp_end == 0)
return alloc_temp(s);
unsigned old_size = temp_end - bottom;
unsigned size = old_size + s;
if (bottom + size <= top) {
temp_end = bottom + size;
} else {
size_t s = temp_end - bottom;
byte * p = bottom;
new_chunk();
memcpy(bottom, p, s);
temp_end = bottom + size;
}
return bottom + old_size;
}

