void forEachForBinding(ScriptState* scriptState, const ScriptValue& thisValue, const ScriptValue& callback, const ScriptValue& thisArg, ExceptionState& exceptionState)
{
IterationSource* source = this->startIteration(scriptState, exceptionState);
v8::Isolate* isolate = scriptState->isolate();
v8::TryCatch tryCatch(isolate);
v8::Local<v8::Object> creationContext(scriptState->context()->Global());
v8::Local<v8::Function> v8Callback(callback.v8Value().As<v8::Function>());
v8::Local<v8::Value> v8ThisArg(thisArg.v8Value());
v8::Local<v8::Value> args[3];
args[2] = thisValue.v8Value();
while (true) {
KeyType key;
ValueType value;
if (!source->next(scriptState, key, value, exceptionState))
return;
ASSERT(!exceptionState.hadException());
args[0] = toV8(value, creationContext, isolate);
args[1] = toV8(key, creationContext, isolate);
if (args[0].IsEmpty() || args[1].IsEmpty()) {
if (tryCatch.HasCaught())
exceptionState.rethrowV8Exception(tryCatch.Exception());
return;
}
v8::Local<v8::Value> result;
if (!V8ScriptRunner::callFunction(v8Callback, scriptState->executionContext(), v8ThisArg, 3, args, isolate).ToLocal(&result)) {
exceptionState.rethrowV8Exception(tryCatch.Exception());
return;
}
}
}

static int sendMessageAndDiscardReply(short ptype, short paylen, const void* payload) {
if (ServerMajorVersion >= 5) {
ENetEvent event;
PltLockMutex(&enetMutex);
if (!sendMessageEnet(ptype, paylen, payload)) {
PltUnlockMutex(&enetMutex);
return 0;
}
if (serviceEnetHost(client, &event, CONTROL_STREAM_TIMEOUT_SEC * 1000) <= 0 ||
event.type != ENET_EVENT_TYPE_RECEIVE) {
PltUnlockMutex(&enetMutex);
return 0;
}
enet_packet_destroy(event.packet);
PltUnlockMutex(&enetMutex);
}
else {
PNVCTL_TCP_PACKET_HEADER reply;
if (!sendMessageTcp(ptype, paylen, payload)) {
return 0;
}
reply = readNvctlPacketTcp();
if (reply == NULL) {
return 0;
}
free(reply);
}
return 1;
}

static int
dissect_kafka_varuint(proto_tree *tree, int hf_item, tvbuff_t *tvb, packet_info *pinfo, int offset,
guint64 *p_value)
{
guint64 value;
guint len;
proto_item *pi;
len = tvb_get_varint(tvb, offset, FT_VARINT_MAX_LEN, &value, ENC_VARINT_PROTOBUF);
pi = proto_tree_add_uint64(tree, hf_item, tvb, offset, len, value);
if (len == 0) {
expert_add_info(pinfo, pi, &ei_kafka_bad_varint);
return offset;
}
if (p_value != NULL) *p_value = value;
return offset + len;
}

