{
int totlen = mb_ptr2len(src - 1);
int charlen = mb_char2len(cc);
if (copy)
{
if (dst + charlen > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
mb_char2bytes(cc, dst);
}
dst += charlen - 1;
if (enc_utf8)
{
int clen = utf_ptr2len(src - 1);
if (clen < totlen)
{
if (copy)
{
if (dst + totlen - clen > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
mch_memmove(dst + 1, src - 1 + clen,
(size_t)(totlen - clen));
}
dst += totlen - clen;
}
}
src += totlen - 1;
}
else if (copy)
{
if (dst + 1 > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
*dst = cc;
}
dst++;
}
else
{
if (REG_MULTI)
{
clnum = rex.reg_mmatch->startpos[no].lnum;
if (clnum < 0 || rex.reg_mmatch->endpos[no].lnum < 0)
s = NULL;
else
{
s = reg_getline(clnum) + rex.reg_mmatch->startpos[no].col;
if (rex.reg_mmatch->endpos[no].lnum == clnum)
len = rex.reg_mmatch->endpos[no].col
- rex.reg_mmatch->startpos[no].col;
else
len = (int)STRLEN(s);
}
}
else
{
s = rex.reg_match->startp[no];
if (rex.reg_match->endp[no] == NULL)
s = NULL;
else
len = (int)(rex.reg_match->endp[no] - s);
}
if (s != NULL)
{
for (;;)
{
if (len == 0)
{
if (REG_MULTI)
{
if (rex.reg_mmatch->endpos[no].lnum == clnum)
break;
if (copy)
{
if (dst + 1 > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
*dst = CAR;
}
++dst;
s = reg_getline(++clnum);
if (rex.reg_mmatch->endpos[no].lnum == clnum)
len = rex.reg_mmatch->endpos[no].col;
else
len = (int)STRLEN(s);
}
else
break;
}
else if (*s == NUL)     {
if (copy)
iemsg(e_damaged_match_string);
goto exit;
}
else
{
if ((flags & REGSUB_BACKSLASH)
&& (*s == CAR || *s == '\\'))
{
if (copy)
{
if (dst + 2 > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
dst[0] = '\\';
dst[1] = *s;
}
dst += 2;
}
else
{
if (has_mbyte)
c = mb_ptr2char(s);
else
c = *s;
if (func_one != (fptr_T)NULL)
func_one = (fptr_T)(func_one(&cc, c));
else if (func_all != (fptr_T)NULL)
func_all = (fptr_T)(func_all(&cc, c));
else cc = c;
if (has_mbyte)
{
int l;
int charlen;
if (enc_utf8)
l = utf_ptr2len(s) - 1;
else
l = mb_ptr2len(s) - 1;
s += l;
len -= l;
charlen = mb_char2len(cc);
if (copy)
{
if (dst + charlen > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
mb_char2bytes(cc, dst);
}
dst += charlen - 1;
}
else if (copy)
{
if (dst + 1 > dest + destlen)
{
iemsg("vim_regsub_both(): not enough space");
return 0;
}
*dst = cc;
}
dst++;
}
++s;
--len;
}
}
}
no = -1;
}
}
if (copy)
*dst = NUL;
exit:
return (int)((dst - dest) + 1);
}

void color_esycc_to_rgb(opj_image_t *image)
{
int y, cb, cr, sign1, sign2, val;
unsigned int w, h, max, i;
int flip_value = (1 << (image->comps[0].prec-1));
int max_value = (1 << image->comps[0].prec) - 1;
if(image->numcomps < 3) return;
w = image->comps[0].w;
h = image->comps[0].h;
sign1 = (int)image->comps[1].sgnd;
sign2 = (int)image->comps[2].sgnd;
max = w * h;
for(i = 0; i < max; ++i)
{
y = image->comps[0].data[i]; cb = image->comps[1].data[i]; cr = image->comps[2].data[i];
if( !sign1) cb -= flip_value;
if( !sign2) cr -= flip_value;
val = (int)
((float)y - (float)0.0000368 * (float)cb
+ (float)1.40199 * (float)cr + (float)0.5);
if(val > max_value) val = max_value; else if(val < 0) val = 0;
image->comps[0].data[i] = val;
val = (int)
((float)1.0003 * (float)y - (float)0.344125 * (float)cb
- (float)0.7141128 * (float)cr + (float)0.5);
if(val > max_value) val = max_value; else if(val < 0) val = 0;
image->comps[1].data[i] = val;
val = (int)
((float)0.999823 * (float)y + (float)1.77204 * (float)cb
- (float)0.000008 *(float)cr + (float)0.5);
if(val > max_value) val = max_value; else if(val < 0) val = 0;
image->comps[2].data[i] = val;
}
image->color_space = OPJ_CLRSPC_SRGB;
}

static int dxtory_decode_v1_444(AVCodecContext *avctx, AVFrame *pic,
const uint8_t *src, int src_size)
{
int h, w;
uint8_t *Y, *U, *V;
int ret;
if (src_size < avctx->width * avctx->height * 3) {
av_log(avctx, AV_LOG_ERROR, "packet too small\n");
return AVERROR_INVALIDDATA;
}
avctx->pix_fmt = AV_PIX_FMT_YUV444P;
if ((ret = ff_get_buffer(avctx, pic, 0)) < 0)
return ret;
Y = pic->data[0];
U = pic->data[1];
V = pic->data[2];
for (h = 0; h < avctx->height; h++) {
for (w = 0; w < avctx->width; w++) {
Y[w] = *src++;
U[w] = *src++ ^ 0x80;
V[w] = *src++ ^ 0x80;
}
Y += pic->linesize[0];
U += pic->linesize[1];
V += pic->linesize[2];
}
return 0;
}

uint8_t _ReadStaticFiles(HTTPReqMessage *req, HTTPResMessage *res) {
uint8_t found = 0;
int8_t depth = 0;
char *uri = req->Header.URI;
size_t n = strlen(uri);
size_t i;
FILE *fp;
int size;
char path[128] = {STATIC_FILE_FOLDER};
char header[] = "HTTP/1.1 200 OK\r\nConnection: close\r\n"
"Content-Type: text/html; charset=UTF-8\r\n\r\n";
for(i=0; i<n; i++) {
if(uri[i] == '/') {
if(((n-i) > 2) && (uri[i+1] == '.') && ((uri[i+2] == '.'))) {
depth -= 1;
if(depth < 0)
break;
}
else if (((n-i) > 1) && (uri[i+1] == '.'))
continue;
else
depth += 1;
}
}
if((depth >= 0) && (uri[i-1] != '/')) {
memcpy(path + strlen(STATIC_FILE_FOLDER), uri, strlen(uri));
fp = fopen(path, "r");
if(fp != NULL) {
fseek(fp, 0, SEEK_END);
size = ftell(fp);
fseek(fp, 0, SEEK_SET);
if(size < MAX_BODY_SIZE) {
n = strlen(header);
memcpy(res->_buf, header, n);
i = n;
n = fread(res->_buf + i, 1, size, fp);
i += n;
res->_index = i;
found = 1;
}
fclose(fp);
}
}
return found;
}

static int
dissect_gryphon_message_with_offset(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, gboolean is_msgresp_add)
{
proto_tree      *gryphon_tree;
proto_item      *ti;
proto_tree      *header_tree, *body_tree;
int             msgend;
int             msglen, msgpad;
unsigned int    src, dest, i, frmtyp;
guint8          flags;
if (!is_msgresp_add) {
col_set_str(pinfo->cinfo, COL_PROTOCOL, "Gryphon");
col_clear(pinfo->cinfo, COL_INFO);
}
if (!is_msgresp_add) {
ti = proto_tree_add_item(tree, proto_gryphon, tvb, 0, -1, ENC_NA);
gryphon_tree = proto_item_add_subtree(ti, ett_gryphon);
} else
gryphon_tree = tree;
src = tvb_get_guint8(tvb, offset + 0);
dest = tvb_get_guint8(tvb, offset + 2);
msglen = tvb_get_ntohs(tvb, offset + 4);
flags = tvb_get_guint8(tvb, offset + 6);
frmtyp = flags & ~RESPONSE_FLAGS;
if (!is_msgresp_add) {
msgpad = 3 - (msglen + 3) % 4;
set_actual_length(tvb, msglen + msgpad + GRYPHON_FRAME_HEADER_LEN);
col_set_str(pinfo->cinfo, COL_INFO, val_to_str_const(frmtyp, frame_type, "- Invalid -"));
}
if (tree == NULL)
return offset;
if (try_val_to_str(frmtyp, frame_type) == NULL) {
proto_tree_add_item(gryphon_tree, hf_gryphon_data, tvb, offset, msglen, ENC_NA);
offset += msglen;
return offset;
}
header_tree = proto_tree_add_subtree(gryphon_tree, tvb, offset, MSG_HDR_SZ, ett_gryphon_header, NULL, "Header");
proto_tree_add_item(header_tree, hf_gryphon_src, tvb, offset, 1, ENC_BIG_ENDIAN);
if(is_special_client(src)) {
proto_tree_add_item(header_tree, hf_gryphon_srcchanclient, tvb, offset+1, 1, ENC_BIG_ENDIAN);
} else {
proto_tree_add_item(header_tree, hf_gryphon_srcchan, tvb, offset+1, 1, ENC_BIG_ENDIAN);
}
proto_tree_add_item(header_tree, hf_gryphon_dest, tvb, offset+2, 1, ENC_BIG_ENDIAN);
if(is_special_client(dest)) {
proto_tree_add_item(header_tree, hf_gryphon_destchanclient, tvb, offset+3, 1, ENC_BIG_ENDIAN);
} else {
proto_tree_add_item(header_tree, hf_gryphon_destchan, tvb, offset+3, 1, ENC_BIG_ENDIAN);
}
proto_tree_add_item(header_tree, hf_gryphon_data_length, tvb, offset+4, 2, ENC_BIG_ENDIAN);
proto_tree_add_item(header_tree, hf_gryphon_type, tvb, offset+6, 1, ENC_BIG_ENDIAN);
if (is_msgresp_add) {
static const int * wait_flags[] = {
&hf_gryphon_wait_resp,
&hf_gryphon_wait_prev_resp,
NULL
};
proto_tree_add_bitmask(header_tree, tvb, offset+6, hf_gryphon_wait_flags, ett_gryphon_flags, wait_flags, ENC_NA);
}
proto_tree_add_item(header_tree, hf_gryphon_reserved, tvb, offset+7, 1, ENC_NA);
offset += MSG_HDR_SZ;
msgpad = 3 - (msglen + 3) % 4;
msgend = offset + msglen + msgpad;
body_tree = proto_tree_add_subtree(gryphon_tree, tvb, offset, msglen , ett_gryphon_body, NULL, "Body");
switch (frmtyp) {
case GY_FT_CMD:
offset = decode_command(tvb, msglen, offset, dest, body_tree);
break;
case GY_FT_RESP:
offset = decode_response(tvb, offset, src, body_tree);
break;
case GY_FT_DATA:
offset = decode_data(tvb, offset, body_tree);
break;
case GY_FT_EVENT:
offset = decode_event(tvb, offset, body_tree);
break;
case GY_FT_MISC:
offset = decode_misc (tvb, offset, body_tree);
break;
case GY_FT_TEXT:
offset = decode_text (tvb, offset, msglen, body_tree);
break;
case GY_FT_SIG:
break;
default:
break;
}
if (offset < msgend) {
i = msgend - offset;
proto_tree_add_item(gryphon_tree, hf_gryphon_padding, tvb, offset, i, ENC_NA);
offset += i;
}
return offset;
}

static pj_status_t dlg_create_request_throw( pjsip_dialog *dlg,
const pjsip_method *method,
int cseq,
pjsip_tx_data **p_tdata )
{
pjsip_tx_data *tdata;
pjsip_contact_hdr *contact;
pjsip_route_hdr *route, *end_list;
pj_status_t status;
if (pjsip_method_creates_dialog(method))
contact = dlg->local.contact;
else
contact = NULL;
status = pjsip_endpt_create_request_from_hdr(dlg->endpt,
method,
dlg->target,
dlg->local.info,
dlg->remote.info,
contact,
dlg->call_id,
cseq,
NULL,
&tdata);
if (status != PJ_SUCCESS)
return status;
tdata->mod_data[dlg->ua->id] = dlg;
route = dlg->route_set.next;
end_list = &dlg->route_set;
for (; route != end_list; route = route->next ) {
pjsip_route_hdr *r;
r = (pjsip_route_hdr*) pjsip_hdr_shallow_clone( tdata->pool, route );
pjsip_routing_hdr_set_route(r);
pjsip_msg_add_hdr(tdata->msg, (pjsip_hdr*)r);
}
if (method->id != PJSIP_ACK_METHOD && method->id != PJSIP_CANCEL_METHOD) {
status = pjsip_auth_clt_init_req( &dlg->auth_sess, tdata );
if (status != PJ_SUCCESS)
return status;
}
*p_tdata = tdata;
return PJ_SUCCESS;
}

static Jsi_RC jsi_ArrayMapCmd(Jsi_Interp *interp, Jsi_Value *args, Jsi_Value *_this,Jsi_Value **ret, Jsi_Func *funcPtr) {
if (_this->vt != JSI_VT_OBJECT || !Jsi_ObjIsArray(interp, _this->d.obj))
return Jsi_LogError("expected array object");
Jsi_RC rc = JSI_OK;
int curlen, nsiz, i, maa = 0;
Jsi_Obj *obj, *nobj;
Jsi_Value *func, *vpargs, *nthis = NULL, *sthis;
Jsi_Func *fptr = NULL;
func = Jsi_ValueArrayIndex(interp, args, 0);
if (!Jsi_ValueIsFunction(interp, func)) 
return Jsi_LogError("expected function");
sthis = Jsi_ValueArrayIndex(interp, args, 1);
if (!sthis)
sthis = nthis = Jsi_ValueNew1(interp);
obj = _this->d.obj;
curlen = Jsi_ObjGetLength(interp, obj);    
if (curlen < 0) {
Jsi_ObjSetLength(interp, obj, 0);
}
Jsi_ObjListifyArray(interp, obj);
nobj = Jsi_ObjNewType(interp, JSI_OT_ARRAY);
nsiz = obj->arrCnt;
if (nsiz<=0) nsiz = 1;
if (Jsi_ObjArraySizer(interp, nobj, nsiz) <= 0) {
Jsi_LogError("index too large: %d", nsiz);
rc = JSI_ERROR;
goto bail;
}
Jsi_ValueMakeArrayObject(interp, ret, nobj);
Jsi_Value *vobjs[3];
fptr = func->d.obj->d.fobj->func;
maa = (fptr->argnames?fptr->argnames->argCnt:0);
if (maa>3)
maa = 3;
for (i = 0; i < curlen; i++) {
if (!obj->arr[i]) continue;
vobjs[0] = obj->arr[i];
vobjs[1] = (maa>1?Jsi_ValueNewNumber(interp, i):NULL);
vobjs[2] = _this;
vpargs = Jsi_ValueMakeObject(interp, NULL, Jsi_ObjNewArray(interp, vobjs, maa, 0));
Jsi_IncrRefCount(interp, vpargs);
nobj->arr[i] = Jsi_ValueNew1(interp);
rc = Jsi_FunctionInvoke(interp, func, vpargs, nobj->arr+i, sthis);
Jsi_DecrRefCount(interp, vpargs);
if( JSI_OK!=rc ) {
goto bail;
}
}
Jsi_ObjSetLength(interp, nobj, curlen);
if (nthis)
Jsi_DecrRefCount(interp, nthis);
return JSI_OK;
bail:
Jsi_ValueMakeNull(interp, ret);
if (nthis)
Jsi_DecrRefCount(interp, nthis);
return rc;
}

static void _on_unsuback(asymcute_con_t *con, const uint8_t *data, size_t len)
{
mutex_lock(&con->lock);
asymcute_req_t *req = _req_preprocess(con, len, MINLEN_UNSUBACK,
data, IDPOS_UNSUBACK);
if (req == NULL) {
mutex_unlock(&con->lock);
return;
}
asymcute_sub_t *sub = (asymcute_sub_t *)req->arg;
if (con->subscriptions == sub) {
con->subscriptions = sub->next;
}
else {
for (asymcute_sub_t *e = con->subscriptions; e && e->next; e = e->next) {
if (e->next == sub) {
e->next = e->next->next;
break;
}
}
}
sub->topic = NULL;
mutex_unlock(&req->lock);
mutex_unlock(&con->lock);
con->user_cb(req, ASYMCUTE_UNSUBSCRIBED);
}

