err(context, ret, "krb5_pac_verify_ext should have failed");
krb5_free_principal(context, ep);
krb5_free_principal(context, np);
}
krb5_pac_free(context, pac);
krb5_free_principal(context, p);
krb5_free_context(context);
return 0;
}

static void
virtio_vq_init(struct virtio_base *base, uint32_t pfn)
{
struct virtio_vq_info *vq;
uint64_t phys;
size_t size;
char *vb;
vq = &base->queues[base->curq];
vq->pfn = pfn;
phys = (uint64_t)pfn << VRING_PAGE_BITS;
size = vring_size(vq->qsize, VIRTIO_PCI_VRING_ALIGN);
vb = paddr_guest2host(base->dev->vmctx, phys, size);
vq->desc = (struct vring_desc *)vb;
vb += vq->qsize * sizeof(struct vring_desc);
vq->avail = (struct vring_avail *)vb;
vb += (2 + vq->qsize + 1) * sizeof(uint16_t);
vb = (char *)roundup2((uintptr_t)vb, VIRTIO_PCI_VRING_ALIGN);
vq->used = (struct vring_used *)vb;
vq->last_avail = 0;
vq->save_used = 0;
mb();
vq->flags = VQ_ALLOC;
}

Status ValidateInput(const OpInputList& indices_list_in,
const OpInputList& values_list_in,
const OpInputList& shapes_list_in,
const OpInputList& dense_list_in) {
const auto size = indices_list_in.size();
for (int i = 0; i < size; i++) {
if (!TensorShapeUtils::IsMatrix(indices_list_in[i].shape())) {
return errors::InvalidArgument(
"Input indices should be a matrix but received shape ",
indices_list_in[i].shape().DebugString(), " at position ", i);
}
if (indices_list_in[i].shape().dim_size(1) != 2) {
return errors::InvalidArgument("Expected D2 of index to be 2 got ",
indices_list_in[i].shape().dim_size(1),
" at position ", i);
}
}
if (values_list_in.size() != size) {
return errors::InvalidArgument("Expected ", size, " input values, got ",
values_list_in.size());
}
for (int i = 0; i < size; i++) {
if (!TensorShapeUtils::IsVector(values_list_in[i].shape())) {
return errors::InvalidArgument(
"Input values should be a vector but received shape ",
values_list_in[i].shape().DebugString(), " at position ", i);
}
if (indices_list_in[i].shape().dim_size(0) !=
values_list_in[i].shape().dim_size(0)) {
return errors::InvalidArgument(
"Expected size of values to be ",
indices_list_in[i].shape().dim_size(0), " got ",
values_list_in[i].shape().dim_size(0), " at position ", i);
}
}
if (shapes_list_in.size() != size) {
return errors::InvalidArgument("Expected ", size, " input shapes, got ",
shapes_list_in.size());
}
for (int i = 0; i < size; i++) {
if (!TensorShapeUtils::IsVector(shapes_list_in[i].shape())) {
return errors::InvalidArgument(
"Input shapes should be a vector but received shape ",
shapes_list_in[i].shape().DebugString(), " at position ", i);
}
if (shapes_list_in[i].vec<int64>().size() != 2) {
return errors::InvalidArgument("shape should imply a 2D tensor, but got ",
shapes_list_in[i].shape().DebugString(),
" at position ", i);
}
}
for (int i = 0; i < dense_list_in.size(); ++i) {
if (!TensorShapeUtils::IsMatrix(dense_list_in[i].shape())) {
return errors::InvalidArgument(
"Dense inputs should be a matrix but received shape ",
dense_list_in[i].shape().DebugString(), " at position ", i);
}
}
const auto batch_size = CalculateBatchSize(shapes_list_in, dense_list_in);
for (int i = 0; i < size; i++) {
if (shapes_list_in[i].vec<int64>()(0) != batch_size) {
return errors::InvalidArgument("Expected batch size ", batch_size,
" got ", shapes_list_in[i].vec<int64>()(0),
" at position ", i);
}
}
for (int i = 0; i < dense_list_in.size(); ++i) {
if (dense_list_in[i].dim_size(0) != batch_size) {
return errors::InvalidArgument("Expected batch size ", batch_size,
" got ", dense_list_in[i].dim_size(0),
" at dense tensor ", i);
}
}
return Status::OK();
}

static gint dissect_mutable_member(proto_tree *tree , tvbuff_t * tvb, gint offset, guint encoding, guint encoding_version,
dissection_info * info, gboolean * is_end, gboolean show) {
proto_tree * member;
guint32 member_id, member_length;
mutable_member_mapping * mapping;
gint64 key;
rtps_util_dissect_parameter_header(tvb, &offset, encoding, &member_id, &member_length);
if ((member_id & PID_LIST_END) == PID_LIST_END){
offset += 0;
*is_end = TRUE;
return offset;
}
if (member_length == 0){
return offset;
}
member = proto_tree_add_subtree_format(tree, tvb, offset, member_length, ett_rtps_dissection_tree,
NULL, "ID: %d, Length: %d", member_id, member_length);
{
if (info->base_type_id > 0) {
key = (info->base_type_id + info->base_type_id * member_id);
mapping = (mutable_member_mapping *) wmem_map_lookup(mutable_member_mappings, &(key));
if (mapping) { 
proto_item_append_text(member, "(base found 0x%016" PRIx64 ")", key);
dissect_user_defined(tree, tvb, offset, encoding, encoding_version, NULL, mapping->member_type_id,
mapping->member_name, EXTENSIBILITY_INVALID, offset, 0, mapping->member_id, show);
proto_item_set_hidden(member);
return offset + member_length;
} else
proto_item_append_text(member, "(base not found 0x%016" PRIx64 " from 0x%016" PRIx64 ")",
key, info->base_type_id);
}
}
key = (info->type_id + info->type_id * member_id);
mapping = (mutable_member_mapping *) wmem_map_lookup(mutable_member_mappings, &(key));
if (mapping) { 
proto_item_append_text(member, "(found 0x%016" PRIx64 ")", key);
dissect_user_defined(tree, tvb, offset, encoding, encoding_version, NULL, mapping->member_type_id,
mapping->member_name, EXTENSIBILITY_INVALID, offset, 0, mapping->member_id, show);
} else
proto_item_append_text(member, "(not found 0x%016" PRIx64 " from 0x%016" PRIx64 ")",
key, info->type_id);
proto_item_set_hidden(member);
return offset + member_length;
}

static void dlg_update_routeset(pjsip_dialog *dlg, const pjsip_rx_data *rdata)
{
const pjsip_hdr *hdr, *end_hdr;
const pjsip_msg *msg;
const pjsip_method update = { PJSIP_OTHER_METHOD, {"UPDATE", 6}};
msg = rdata->msg_info.msg;
if (dlg->route_set_frozen)
return;
if (pjsip_method_cmp(&rdata->msg_info.cseq->method, &update) == 0)
return;
if (dlg->role == PJSIP_ROLE_UAC) {
if (msg->type != PJSIP_RESPONSE_MSG)
return;
} else {
pj_assert(!"Should not happen");
}
pj_assert(msg->type == PJSIP_RESPONSE_MSG);
if (msg->line.status.code >= 300)
return;
pj_list_init(&dlg->route_set);
end_hdr = &msg->hdr;
for (hdr=msg->hdr.prev; hdr!=end_hdr; hdr=hdr->prev) {
if (hdr->type == PJSIP_H_RECORD_ROUTE) {
pjsip_route_hdr *r;
r = (pjsip_route_hdr*) pjsip_hdr_clone(dlg->pool, hdr);
pjsip_routing_hdr_set_route(r);
pj_list_push_back(&dlg->route_set, r);
}
}
PJ_LOG(5,(dlg->obj_name, "Route-set updated"));
if (pjsip_method_creates_dialog(&rdata->msg_info.cseq->method) &&
PJSIP_IS_STATUS_IN_CLASS(msg->line.status.code, 200))
{
dlg->route_set_frozen = PJ_TRUE;
PJ_LOG(5,(dlg->obj_name, "Route-set frozen"));
}
}

int
ImagingFliDecode(Imaging im, ImagingCodecState state, UINT8 *buf, Py_ssize_t bytes) {
UINT8 *ptr;
int framesize;
int c, chunks, advance;
int l, lines;
int i, j, x = 0, y, ymax;
if (bytes < 4) {
return 0;
}
ptr = buf;
framesize = I32(ptr);
if (framesize < I32(ptr)) {
return 0;
}
if (bytes < 8) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
if (I16(ptr + 4) != 0xF1FA) {
state->errcode = IMAGING_CODEC_UNKNOWN;
return -1;
}
chunks = I16(ptr + 6);
ptr += 16;
bytes -= 16;
for (c = 0; c < chunks; c++) {
UINT8 *data;
if (bytes < 10) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
data = ptr + 6;
switch (I16(ptr + 4)) {
case 4:
case 11:
break; 
case 7:
lines = I16(data);
data += 2;
for (l = y = 0; l < lines && y < state->ysize; l++, y++) {
UINT8 *local_buf = (UINT8 *)im->image[y];
int p, packets;
ERR_IF_DATA_OOB(2)
packets = I16(data);
data += 2;
while (packets & 0x8000) {
if (packets & 0x4000) {
y += 65536 - packets; 
if (y >= state->ysize) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
local_buf = (UINT8 *)im->image[y];
} else {
local_buf[state->xsize - 1] = (UINT8)packets;
}
ERR_IF_DATA_OOB(2)
packets = I16(data);
data += 2;
}
for (p = x = 0; p < packets; p++) {
ERR_IF_DATA_OOB(2)
x += data[0]; 
if (data[1] >= 128) {
ERR_IF_DATA_OOB(4)
i = 256 - data[1]; 
if (x + i + i > state->xsize) {
break;
}
for (j = 0; j < i; j++) {
local_buf[x++] = data[2];
local_buf[x++] = data[3];
}
data += 2 + 2;
} else {
i = 2 * (int)data[1]; 
if (x + i > state->xsize) {
break;
}
ERR_IF_DATA_OOB(2 + i)
memcpy(local_buf + x, data + 2, i);
data += 2 + i;
x += i;
}
}
if (p < packets) {
break; 
}
}
if (l < lines) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
break;
case 12:
y = I16(data);
ymax = y + I16(data + 2);
data += 4;
for (; y < ymax && y < state->ysize; y++) {
UINT8 *out = (UINT8 *)im->image[y];
ERR_IF_DATA_OOB(1)
int p, packets = *data++;
for (p = x = 0; p < packets; p++, x += i) {
ERR_IF_DATA_OOB(2)
x += data[0]; 
if (data[1] & 0x80) {
i = 256 - data[1]; 
if (x + i > state->xsize) {
break;
}
ERR_IF_DATA_OOB(3)
memset(out + x, data[2], i);
data += 3;
} else {
i = data[1]; 
if (x + i > state->xsize) {
break;
}
ERR_IF_DATA_OOB(2 + i)
memcpy(out + x, data + 2, i);
data += i + 2;
}
}
if (p < packets) {
break; 
}
}
if (y < ymax) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
break;
case 13:
for (y = 0; y < state->ysize; y++) {
memset(im->image[y], 0, state->xsize);
}
break;
case 15:
for (y = 0; y < state->ysize; y++) {
UINT8 *out = (UINT8 *)im->image[y];
data += 1; 
for (x = 0; x < state->xsize; x += i) {
ERR_IF_DATA_OOB(2)
if (data[0] & 0x80) {
i = 256 - data[0];
if (x + i > state->xsize) {
break; 
}
ERR_IF_DATA_OOB(i + 1)
memcpy(out + x, data + 1, i);
data += i + 1;
} else {
i = data[0];
if (x + i > state->xsize) {
break; 
}
memset(out + x, data[1], i);
data += 2;
}
}
if (x != state->xsize) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
}
break;
case 16:
if (state->xsize > bytes / state->ysize) {
return ptr - buf; 
}
for (y = 0; y < state->ysize; y++) {
UINT8 *local_buf = (UINT8 *)im->image[y];
memcpy(local_buf, data, state->xsize);
data += state->xsize;
}
break;
case 18:
break; 
default:
state->errcode = IMAGING_CODEC_UNKNOWN;
return -1;
}
advance = I32(ptr);
if (advance < 0 || advance > bytes) {
state->errcode = IMAGING_CODEC_OVERRUN;
return -1;
}
ptr += advance;
bytes -= advance;
}
return -1; 
}

vector<pair<vector<DNSRecord>, vector<DNSRecord> > > getIXFRDeltas(const ComboAddress& master, const DNSName& zone, const DNSRecord& oursr, 
const TSIGTriplet& tt, const ComboAddress* laddr)
{
vector<pair<vector<DNSRecord>, vector<DNSRecord> > >  ret;
vector<uint8_t> packet;
DNSPacketWriter pw(packet, zone, QType::IXFR);
pw.getHeader()->qr=0;
pw.getHeader()->rd=0;
pw.getHeader()->id=dns_random(0xffff);
pw.startRecord(zone, QType::SOA, 0, QClass::IN, DNSResourceRecord::AUTHORITY);
oursr.d_content->toPacket(pw);
pw.commit();
if(!tt.algo.empty()) {
TSIGHashEnum the;
getTSIGHashEnum(tt.algo, the);
TSIGRecordContent trc;
try {
trc.d_algoName = getTSIGAlgoName(the);
} catch(PDNSException& pe) {
throw std::runtime_error("TSIG algorithm '"+tt.algo.toString()+"' is unknown.");
}
trc.d_time = time((time_t*)NULL);
trc.d_fudge = 300;
trc.d_origID=ntohs(pw.getHeader()->id);
trc.d_eRcode=0;
addTSIG(pw, &trc, tt.name, tt.secret, "", false);
}
uint16_t len=htons(packet.size());
string msg((const char*)&len, 2);
msg.append((const char*)&packet[0], packet.size());
Socket s(master.sin4.sin_family, SOCK_STREAM);
if(laddr)
s.bind(*laddr);
s.connect(master);
s.writen(msg);
shared_ptr<SOARecordContent> masterSOA;
vector<DNSRecord> records;
for(;;) {
if(s.read((char*)&len, 2)!=2)
break;
len=ntohs(len);
if(!len)
break;
char reply[len]; 
readn2(s.getHandle(), reply, len);
MOADNSParser mdp(string(reply, len));
if(mdp.d_header.rcode) 
throw std::runtime_error("Got an error trying to IXFR zone '"+zone.toString()+"' from master '"+master.toStringWithPort()+"': "+RCode::to_s(mdp.d_header.rcode));
for(auto& r: mdp.d_answers) {
if(r.first.d_type == QType::TSIG) 
continue;
r.first.d_name = r.first.d_name.makeRelative(zone);
records.push_back(r.first);
if(r.first.d_type == QType::SOA) {
auto sr = getRR<SOARecordContent>(r.first);
if(sr) {
if(!masterSOA) {
if(sr->d_st.serial == std::dynamic_pointer_cast<SOARecordContent>(oursr.d_content)->d_st.serial) {       goto done;
}
masterSOA=sr;
}
else if(sr->d_st.serial == masterSOA->d_st.serial)
goto done;
}
}
}
}
done:;
for(unsigned int pos = 1;pos < records.size();) {
auto sr = getRR<SOARecordContent>(records[pos]);
vector<DNSRecord> remove, add;
if(!sr) {       return {{remove, records}};
}
if(sr->d_st.serial == masterSOA->d_st.serial)
break;
remove.push_back(records[pos]);     for(pos++; pos < records.size() && records[pos].d_type != QType::SOA; ++pos) {
remove.push_back(records[pos]);
}
sr = getRR<SOARecordContent>(records[pos]);
add.push_back(records[pos]);     for(pos++; pos < records.size() && records[pos].d_type != QType::SOA; ++pos)  {
add.push_back(records[pos]);
}
ret.push_back(make_pair(remove,add));
}
return ret;
}

void nsexec(void)
{
int pipenum;
jmp_buf env;
int syncpipe[2];
struct nlconfig_t config = {0};
pipenum = initpipe();
if (pipenum == -1)
return;
nl_parse(pipenum, &config);
if (config.cloneflags == -1)
bail("missing clone_flags");
if (pipe(syncpipe) < 0)
bail("failed to setup sync pipe between parent and child");
if (setjmp(env) == JUMP_VAL) {
uint8_t s = 0;
int consolefd = config.consolefd;
close(syncpipe[1]);
if (read(syncpipe[0], &s, sizeof(s)) != sizeof(s) || s != SYNC_VAL)
bail("failed to read sync byte from parent");
if (setsid() < 0)
bail("setsid failed");
if (setuid(0) < 0)
bail("setuid failed");
if (setgid(0) < 0)
bail("setgid failed");
if (setgroups(0, NULL) < 0)
bail("setgroups failed");
if (consolefd != -1) {
if (ioctl(consolefd, TIOCSCTTY, 0) < 0)
bail("ioctl TIOCSCTTY failed");
if (dup3(consolefd, STDIN_FILENO, 0) != STDIN_FILENO)
bail("failed to dup stdin");
if (dup3(consolefd, STDOUT_FILENO, 0) != STDOUT_FILENO)
bail("failed to dup stdout");
if (dup3(consolefd, STDERR_FILENO, 0) != STDERR_FILENO)
bail("failed to dup stderr");
}
nl_free(&config);
return;
}
start_child(pipenum, &env, syncpipe, &config);
bail("should never be reached");
}

void *malloc_wrapper(size_t size, void *caller)
{
void *ptr = NULL;
#ifdef MBED_MEM_TRACING_ENABLED
mbed_mem_trace_lock();
#endif
#ifdef MBED_HEAP_STATS_ENABLED
malloc_stats_mutex->lock();
alloc_info_t *alloc_info = (alloc_info_t *)SUPER_MALLOC(size + sizeof(alloc_info_t));
if (alloc_info != NULL) {
alloc_info->size = size;
alloc_info->signature = MBED_HEAP_STATS_SIGNATURE;
ptr = (void *)(alloc_info + 1);
heap_stats.current_size += size;
heap_stats.total_size += size;
heap_stats.alloc_cnt += 1;
if (heap_stats.current_size > heap_stats.max_size) {
heap_stats.max_size = heap_stats.current_size;
}
heap_stats.overhead_size += MALLOC_HEAP_TOTAL_SIZE(MALLOC_HEADER_PTR(alloc_info)) - size;
} else {
heap_stats.alloc_fail_cnt += 1;
}
malloc_stats_mutex->unlock();
#else     ptr = SUPER_MALLOC(size);
#endif #ifdef MBED_MEM_TRACING_ENABLED
mbed_mem_trace_malloc(ptr, size, caller);
mbed_mem_trace_unlock();
#endif     return ptr;
}

static int nft_set_desc_concat_parse(const struct nlattr *attr,
struct nft_set_desc *desc)
{
struct nlattr *tb[NFTA_SET_FIELD_MAX + 1];
u32 len;
int err;
err = nla_parse_nested_deprecated(tb, NFTA_SET_FIELD_MAX, attr,
nft_concat_policy, NULL);
if (err < 0)
return err;
if (!tb[NFTA_SET_FIELD_LEN])
return -EINVAL;
len = ntohl(nla_get_be32(tb[NFTA_SET_FIELD_LEN]));
if (len * BITS_PER_BYTE / 32 > NFT_REG32_COUNT)
return -E2BIG;
desc->field_len[desc->field_count++] = len;
return 0;
}

