void sh_emulate_unmap_dest(struct vcpu *v, void *addr, unsigned int bytes,
struct sh_emulate_ctxt *sh_ctxt)
{
u32 b1 = bytes, b2 = 0, shflags;
shflags = mfn_to_page(sh_ctxt->mfn[0])->shadow_flags;
#if (SHADOW_OPTIMIZATIONS & SHOPT_SKIP_VERIFY)
if ( sh_ctxt->low_bit_was_clear
&& !(*(u8 *)addr & _PAGE_PRESENT)
&& ((!(shflags & SHF_32)
&& ((unsigned long)addr & 7) == 0
&& bytes <= 8)
||
(!(shflags & (SHF_PAE|SHF_64))
&& ((unsigned long)addr & 3) == 0
&& bytes <= 4)) )
{
ASSERT(!mfn_valid(sh_ctxt->mfn[1]));
}
else
#endif 
{
if ( unlikely(mfn_valid(sh_ctxt->mfn[1])) )
{
b1 = PAGE_SIZE - (((unsigned long)addr) & ~PAGE_MASK);
b2 = bytes - b1;
ASSERT(b2 < bytes);
}
if ( likely(b1 > 0) )
sh_validate_guest_pt_write(v, sh_ctxt->mfn[0], addr, b1);
if ( unlikely(b2 > 0) )
sh_validate_guest_pt_write(v, sh_ctxt->mfn[1], addr + b1, b2);
}
paging_mark_dirty(v->domain, sh_ctxt->mfn[0]);
if ( unlikely(mfn_valid(sh_ctxt->mfn[1])) )
{
paging_mark_dirty(v->domain, sh_ctxt->mfn[1]);
vunmap((void *)((unsigned long)addr & PAGE_MASK));
}
else
unmap_domain_page(addr);
atomic_inc(&v->domain->arch.paging.shadow.gtable_dirty_version);
}

void
sfe_copy_data_fp (SNDFILE *outfile, SNDFILE *infile, int channels, int normalize)
{static doubledata [BUFFER_LEN], max ;
sf_count_tframes, readcount, k ;
frames = BUFFER_LEN / channels ;
readcount = frames ;
sf_command (infile, SFC_CALC_SIGNAL_MAX, &max, sizeof (max)) ;
if (!normalize && max < 1.0)
{while (readcount > 0)
{readcount = sf_readf_double (infile, data, frames) ;
sf_writef_double (outfile, data, readcount) ;
} ;
}
else
{sf_command (infile, SFC_SET_NORM_DOUBLE, NULL, SF_FALSE) ;
while (readcount > 0)
{readcount = sf_readf_double (infile, data, frames) ;
for (k = 0 ; k < readcount * channels ; k++)
data [k] /= max ;
sf_writef_double (outfile, data, readcount) ;
} ;
} ;
return ;
}

static void
dissect_e_dch_channel_info(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree,
int offset, struct fp_info *p_fp_info,
gboolean is_common, rlc_info  *rlcinf,
void *data)
{
gboolean is_control_frame;
guint8   number_of_subframes;
guint8   cfn;
int      n;
struct   edch_t1_subframe_info subframes[16];
guint16 header_crc = 0;
proto_item * header_crc_pi = NULL;
guint header_length = 0;
if (p_fp_info->edch_type == 1) {
col_append_str(pinfo->cinfo, COL_INFO, " (T2)");
}
header_crc = (tvb_get_bits8(tvb, offset*8, 7) << 4) + tvb_get_bits8(tvb, offset*8+8, 4);
is_control_frame = tvb_get_guint8(tvb, offset) & 0x01;
col_append_str(pinfo->cinfo, COL_INFO, is_control_frame ? " [Control] " : " [Data] ");
if (is_control_frame) {
header_crc = tvb_get_bits8(tvb, 0, 7);
header_crc_pi = proto_tree_add_item(tree, hf_fp_header_crc, tvb, 0, 1, ENC_BIG_ENDIAN);
proto_tree_add_item(tree, hf_fp_ft, tvb, 0, 1, ENC_BIG_ENDIAN);
offset++;
if (preferences_header_checksum) {
verify_control_frame_crc(tvb, pinfo, header_crc_pi, header_crc);
}
dissect_dch_control_frame(tree, pinfo, tvb, offset, p_fp_info);
}
else {
guint  bit_offset = 0;
guint  total_pdus = 0;
guint  total_bits = 0;
gboolean dissected = FALSE;
header_crc_pi = proto_tree_add_uint_format(tree, hf_fp_edch_header_crc, tvb,
offset, 2, header_crc,
"%u%u%u%u%u%u%u.%u%u%u%u.... = E-DCH Header CRC: 0x%x",
(header_crc >> 10) & 1,
(header_crc >> 9) & 1,
(header_crc >> 8) & 1,
(header_crc >> 7) & 1,
(header_crc >> 6) & 1,
(header_crc >> 5) & 1,
(header_crc >> 4) & 1,
(header_crc >> 3) & 1,
(header_crc >> 2) & 1,
(header_crc >> 1) & 1,
(header_crc >> 0) & 1, header_crc);
proto_tree_add_item(tree, hf_fp_ft, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
proto_tree_add_item(tree, hf_fp_edch_fsn, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
if ((p_fp_info->release >= 6) &&
((p_fp_info->release_year > 2005) ||
((p_fp_info->release_year == 2005) && (p_fp_info->release_month >= 9)))) {
number_of_subframes = (tvb_get_guint8(tvb, offset) & 0x0f) + 1;
}
else {
number_of_subframes = (tvb_get_guint8(tvb, offset) & 0x07);
}
proto_tree_add_uint(tree, hf_fp_edch_number_of_subframes, tvb, offset, 1,
number_of_subframes);
offset++;
cfn = tvb_get_guint8(tvb, offset);
proto_tree_add_item(tree, hf_fp_cfn, tvb, offset, 1, ENC_BIG_ENDIAN);
offset++;
if (p_fp_info->edch_type == 1) {
dissect_e_dch_t2_or_common_channel_info(tvb, pinfo, tree, offset, p_fp_info,
number_of_subframes,
is_common, header_crc,
header_crc_pi, data);
return;
}
for (n=0; n < number_of_subframes; n++) {
int i;
int start_offset = offset;
proto_item *subframe_header_ti;
proto_tree *subframe_header_tree;
subframe_header_ti = proto_tree_add_string_format(tree, hf_fp_edch_subframe_header, tvb, offset, 0,
"", "Subframe");
subframe_header_tree = proto_item_add_subtree(subframe_header_ti, ett_fp_edch_subframe_header);
proto_tree_add_item(subframe_header_tree, hf_fp_edch_harq_retransmissions, tvb,
offset, 1, ENC_BIG_ENDIAN);
subframes[n].subframe_number = (tvb_get_guint8(tvb, offset) & 0x07);
proto_tree_add_bits_item(subframe_header_tree, hf_fp_edch_subframe_number, tvb,
offset*8+5, 1, ENC_BIG_ENDIAN);
offset++;
subframes[n].number_of_mac_es_pdus = (tvb_get_guint8(tvb, offset) & 0xf0) >> 4;
proto_tree_add_item(subframe_header_tree, hf_fp_edch_number_of_mac_es_pdus,
tvb, offset, 1, ENC_BIG_ENDIAN);
bit_offset = 4;
proto_item_append_text(subframe_header_ti, " %u header (%u MAC-es PDUs)",
subframes[n].subframe_number,
subframes[n].number_of_mac_es_pdus);
for (i=0; i < subframes[n].number_of_mac_es_pdus; i++) {
guint64 ddi;
guint64 n_pdus;    
proto_item *ddi_ti;
gint ddi_size = -1;
int     p;
ddi_ti = proto_tree_add_bits_ret_val(subframe_header_tree, hf_fp_edch_ddi, tvb,
offset*8 + bit_offset, 6, &ddi, ENC_BIG_ENDIAN);
if (rlcinf) {
rlcinf->rbid[i] = (guint8)ddi;
}
for (p=0; p < p_fp_info->no_ddi_entries; p++) {
if (ddi == p_fp_info->edch_ddi[p]) {
ddi_size = p_fp_info->edch_macd_pdu_size[p];
break;
}
}
if (ddi_size == -1) {
expert_add_info_format(pinfo, ddi_ti, &ei_fp_ddi_not_defined, "DDI %u not defined for this UE!", (guint)ddi);
return;
}
else {
proto_item_append_text(ddi_ti, " (%d bits)", ddi_size);
}
subframes[n].ddi[i] = (guint8)ddi;
bit_offset += 6;
proto_tree_add_bits_ret_val(subframe_header_tree, hf_fp_edch_number_of_mac_d_pdus, tvb,
offset*8 + bit_offset, 6, &n_pdus, ENC_BIG_ENDIAN);
subframes[n].number_of_mac_d_pdus[i] = (guint8)n_pdus;
bit_offset += 6;
}
offset += ((bit_offset+7)/8);
proto_item_set_len(subframe_header_ti, offset - start_offset);
}
header_length = offset;
for (n=0; n < number_of_subframes; n++) {
int i;
proto_item *subframe_ti;
proto_tree *subframe_tree;
guint bits_in_subframe = 0;
guint mac_d_pdus_in_subframe = 0;
guint    lchid=0;    
umts_mac_info *macinf;
bit_offset = 0;
macinf = (umts_mac_info *)p_get_proto_data(wmem_file_scope(), pinfo, proto_umts_mac, 0);
subframe_ti = proto_tree_add_string_format(tree, hf_fp_edch_subframe, tvb, offset, 0,
"", "Subframe %u data", subframes[n].subframe_number);
subframe_tree = proto_item_add_subtree(subframe_ti, ett_fp_edch_subframe);
for (i=0; i < subframes[n].number_of_mac_es_pdus; i++) {
int         m;
guint16     size = 0;
guint       send_size;
proto_item  *ti;
int         macd_idx;
proto_tree  *maces_tree = NULL;
for (m=0; m < p_fp_info->no_ddi_entries; m++) {
if (subframes[n].ddi[i] == p_fp_info->edch_ddi[m]) {
size = p_fp_info->edch_macd_pdu_size[m];
break;
}
}
for (m=0; m < p_fp_info->no_ddi_entries; m++) {
if (subframes[n].ddi[i] == p_fp_info->edch_ddi[m]) {
lchid = p_fp_info->edch_lchId[m];
break;
}
}
if (m == p_fp_info->no_ddi_entries) {
expert_add_info(pinfo, NULL, &ei_fp_unable_to_locate_ddi_entry);
return;
}
send_size = size * subframes[n].number_of_mac_d_pdus[i];
proto_tree_add_item(subframe_tree, hf_fp_edch_pdu_padding, tvb,
offset + (bit_offset/8),
1, ENC_BIG_ENDIAN);
bit_offset += 2;
proto_tree_add_item(subframe_tree, hf_fp_edch_tsn, tvb,
offset + (bit_offset/8),
1, ENC_BIG_ENDIAN);
bit_offset += 6;
if (subframe_tree) {
ti = proto_tree_add_item(subframe_tree, hf_fp_edch_mac_es_pdu, tvb,
offset + (bit_offset/8),
((bit_offset % 8) + send_size + 7) / 8,
ENC_NA);
proto_item_append_text(ti, " (%u * %u = %u bits, PDU %d)",
size, subframes[n].number_of_mac_d_pdus[i],
send_size, n);
maces_tree = proto_item_add_subtree(ti, ett_fp_edch_maces);
}
for (macd_idx = 0; macd_idx < subframes[n].number_of_mac_d_pdus[i]; macd_idx++) {
if (preferences_call_mac_dissectors ) {
tvbuff_t *next_tvb;
pinfo->fd->subnum = macd_idx; 
next_tvb = tvb_new_subset(tvb, offset + bit_offset/8,
((bit_offset % 8) + size + 7) / 8, -1);
macinf->content[macd_idx] = lchId_type_table[lchid];     
macinf->lchid[macd_idx] = lchid;
rlcinf->mode[macd_idx] = lchId_rlc_map[lchid]; 
rlcinf->urnti[macd_idx] = p_fp_info->com_context_id;
rlcinf->rbid[macd_idx] = lchid;     
rlcinf->li_size[macd_idx] = RLC_LI_7BITS;
#if 0
if ( rrc_ciph_inf && g_tree_lookup(rrc_ciph_inf, GINT_TO_POINTER((gint)p_fp_info->com_context_id)) ) {
rlcinf->ciphered[macd_idx] = TRUE;
} else {
rlcinf->ciphered[macd_idx] = FALSE;
}
#endif
rlcinf->ciphered[macd_idx] = FALSE;
rlcinf->deciphered[macd_idx] = FALSE;
p_fp_info->cur_tb = macd_idx;    
call_dissector_with_data(mac_fdd_edch_handle, next_tvb, pinfo, top_level_tree, data);
dissected = TRUE;
}
else {
proto_tree_add_item(maces_tree, hf_fp_mac_d_pdu, tvb,
offset + (bit_offset/8),
((bit_offset % 8) + size + 7) / 8,
ENC_NA);
}
bit_offset += size;
}
bits_in_subframe += send_size;
mac_d_pdus_in_subframe += subframes[n].number_of_mac_d_pdus[i];
if (bit_offset % 8) {
bit_offset += (8 - (bit_offset % 8));
}
}
if (tree) {
proto_item_set_len(subframe_ti, bit_offset/8);
proto_item_append_text(subframe_ti, " (%u bits in %u MAC-d PDUs)",
bits_in_subframe, mac_d_pdus_in_subframe);
}
total_pdus += mac_d_pdus_in_subframe;
total_bits += bits_in_subframe;
offset += (bit_offset/8);
}
if (dissected == FALSE) {
col_append_fstr(pinfo->cinfo, COL_INFO,
" CFN = %03u   (%u bits in %u pdus in %u subframes)",
cfn, total_bits, total_pdus, number_of_subframes);
}
if (preferences_header_checksum) {
verify_header_crc_edch(tvb, pinfo, header_crc_pi, header_crc, header_length);
}
dissect_spare_extension_and_crc(tvb, pinfo, tree,
p_fp_info->dch_crc_present, offset, header_length);
}
}

static void bgp_packet_mpattr_tea(struct bgp *bgp, struct peer *peer,
struct stream *s, struct attr *attr,
uint8_t attrtype)
{
unsigned int attrlenfield = 0;
unsigned int attrhdrlen = 0;
struct bgp_attr_encap_subtlv *subtlvs;
struct bgp_attr_encap_subtlv *st;
const char *attrname;
if (!attr || (attrtype == BGP_ATTR_ENCAP
&& (!attr->encap_tunneltype
|| attr->encap_tunneltype == BGP_ENCAP_TYPE_MPLS)))
return;
switch (attrtype) {
case BGP_ATTR_ENCAP:
attrname = "Tunnel Encap";
subtlvs = attr->encap_subtlvs;
if (subtlvs == NULL) 
return;
attrlenfield = 2 + 2; 
attrhdrlen = 1 + 1;   
break;
#if ENABLE_BGP_VNC
case BGP_ATTR_VNC:
attrname = "VNC";
subtlvs = attr->vnc_subtlvs;
if (subtlvs == NULL) 
return;
attrlenfield = 0;   
attrhdrlen = 2 + 2; 
break;
#endif
default:
assert(0);
}
for (st = subtlvs; st; st = st->next) {
attrlenfield += (attrhdrlen + st->length);
}
if (attrlenfield > 0xffff) {
zlog_info("%s attribute is too long (length=%d), can't send it",
attrname, attrlenfield);
return;
}
if (attrlenfield > 0xff) {
stream_putc(s,
BGP_ATTR_FLAG_TRANS | BGP_ATTR_FLAG_OPTIONAL
| BGP_ATTR_FLAG_EXTLEN);
stream_putc(s, attrtype);
stream_putw(s, attrlenfield & 0xffff);
} else {
stream_putc(s, BGP_ATTR_FLAG_TRANS | BGP_ATTR_FLAG_OPTIONAL);
stream_putc(s, attrtype);
stream_putc(s, attrlenfield & 0xff);
}
if (attrtype == BGP_ATTR_ENCAP) {
stream_putw(s, attr->encap_tunneltype);
stream_putw(s, attrlenfield - 4);
}
for (st = subtlvs; st; st = st->next) {
if (attrtype == BGP_ATTR_ENCAP) {
stream_putc(s, st->type);
stream_putc(s, st->length);
#if ENABLE_BGP_VNC
} else {
stream_putw(s, st->type);
stream_putw(s, st->length);
#endif
}
stream_put(s, st->value, st->length);
}
}

static void isor_get_chapters(GF_ISOFile *file, GF_FilterPid *opid)
{
u32 i, count;
GF_PropertyValue p;
GF_PropUIntList times;
GF_PropStringList names;
count = gf_isom_get_chapter_count(file, 0);
if (count) {
times.vals = gf_malloc(sizeof(u32)*count);
names.vals = gf_malloc(sizeof(char *)*count);
times.nb_items = names.nb_items = count;
for (i=0; i<count; i++) {
const char *name;
u64 start;
gf_isom_get_chapter(file, 0, i+1, &start, &name);
times.vals[i] = (u32) start;
names.vals[i] = gf_strdup(name);
}
p.type = GF_PROP_UINT_LIST;
p.value.uint_list = times;
gf_filter_pid_set_property(opid, GF_PROP_PID_CHAP_TIMES, &p);
gf_free(times.vals);
p.type = GF_PROP_STRING_LIST;
p.value.string_list = names;
gf_filter_pid_set_property(opid, GF_PROP_PID_CHAP_NAMES, &p);
return;
}
u32 chap_tk=0;
count = gf_isom_get_track_count(file);
for (i=0; i<count; i++) {
u32 nb_ref = gf_isom_get_reference_count(file, i+1, GF_ISOM_REF_CHAP);
if (nb_ref) {
gf_isom_get_reference(file, i+1, GF_ISOM_REF_CHAP, 1, &chap_tk);
break;
}
}
if (chap_tk) {
count = gf_isom_get_sample_count(file, chap_tk);
if (!count) chap_tk=0;
}
if (!chap_tk) return;
times.vals = gf_malloc(sizeof(u32)*count);
names.vals = gf_malloc(sizeof(char *)*count);
times.nb_items = names.nb_items = count;
for (i=0; i<count; i++) {
u32 di;
GF_ISOSample *s = gf_isom_get_sample(file, chap_tk, i+1, &di);
if (!s) continue;
GF_BitStream *bs = gf_bs_new(s->data, s->dataLength, GF_BITSTREAM_READ);
GF_TextSample *txt = gf_isom_parse_text_sample(bs);
if (txt) {
times.vals[i] = (u32) s->DTS;
names.vals[i] = gf_strdup(txt->text ? txt->text : "");
gf_isom_delete_text_sample(txt);
}
gf_bs_del(bs);
gf_isom_sample_del(&s);
}
p.type = GF_PROP_UINT_LIST;
p.value.uint_list = times;
gf_filter_pid_set_property(opid, GF_PROP_PID_CHAP_TIMES, &p);
gf_free(times.vals);
p.type = GF_PROP_STRING_LIST;
p.value.string_list = names;
gf_filter_pid_set_property(opid, GF_PROP_PID_CHAP_NAMES, &p);
}

static void usbredir_handle_interrupt_out_data(USBRedirDevice *dev,
USBPacket *p, uint8_t ep)
{
struct usb_redir_interrupt_packet_header interrupt_packet;
uint8_t buf[p->iov.size];
DPRINTF("interrupt-out ep %02X len %zd id %"PRIu64"\n", ep,
p->iov.size, p->id);
interrupt_packet.endpoint  = ep;
interrupt_packet.length    = p->iov.size;
usb_packet_copy(p, buf, p->iov.size);
usbredir_log_data(dev, "interrupt data out:", buf, p->iov.size);
usbredirparser_send_interrupt_packet(dev->parser, p->id,
&interrupt_packet, buf, p->iov.size);
usbredirparser_do_write(dev->parser);
}

int Visualizer_command(effect_handle_t self, uint32_t cmdCode, uint32_t cmdSize,
void *pCmdData, uint32_t *replySize, void *pReplyData) {
VisualizerContext * pContext = (VisualizerContext *)self;
int retsize;
if (pContext == NULL || pContext->mState == VISUALIZER_STATE_UNINITIALIZED) {
return -EINVAL;
}
switch (cmdCode) {
case EFFECT_CMD_INIT:
if (pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)) {
return -EINVAL;
}
*(int *) pReplyData = Visualizer_init(pContext);
break;
case EFFECT_CMD_SET_CONFIG:
if (pCmdData == NULL || cmdSize != sizeof(effect_config_t)
|| pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)) {
return -EINVAL;
}
*(int *) pReplyData = Visualizer_setConfig(pContext,
(effect_config_t *) pCmdData);
break;
case EFFECT_CMD_GET_CONFIG:
if (pReplyData == NULL || replySize == NULL ||
*replySize != sizeof(effect_config_t)) {
return -EINVAL;
}
Visualizer_getConfig(pContext, (effect_config_t *)pReplyData);
break;
case EFFECT_CMD_RESET:
Visualizer_reset(pContext);
break;
case EFFECT_CMD_ENABLE:
if (pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)) {
return -EINVAL;
}
if (pContext->mState != VISUALIZER_STATE_INITIALIZED) {
return -ENOSYS;
}
pContext->mState = VISUALIZER_STATE_ACTIVE;
ALOGV("EFFECT_CMD_ENABLE() OK");
*(int *)pReplyData = 0;
break;
case EFFECT_CMD_DISABLE:
if (pReplyData == NULL || replySize == NULL || *replySize != sizeof(int)) {
return -EINVAL;
}
if (pContext->mState != VISUALIZER_STATE_ACTIVE) {
return -ENOSYS;
}
pContext->mState = VISUALIZER_STATE_INITIALIZED;
ALOGV("EFFECT_CMD_DISABLE() OK");
*(int *)pReplyData = 0;
break;
case EFFECT_CMD_GET_PARAM: {
if (pCmdData == NULL ||
cmdSize != (int)(sizeof(effect_param_t) + sizeof(uint32_t)) ||
pReplyData == NULL || replySize == NULL ||
*replySize < (int)(sizeof(effect_param_t) + sizeof(uint32_t) + sizeof(uint32_t))) {
return -EINVAL;
}
memcpy(pReplyData, pCmdData, sizeof(effect_param_t) + sizeof(uint32_t));
effect_param_t *p = (effect_param_t *)pReplyData;
p->status = 0;
*replySize = sizeof(effect_param_t) + sizeof(uint32_t);
if (p->psize != sizeof(uint32_t)) {
p->status = -EINVAL;
break;
}
switch (*(uint32_t *)p->data) {
case VISUALIZER_PARAM_CAPTURE_SIZE:
ALOGV("get mCaptureSize = %" PRIu32, pContext->mCaptureSize);
*((uint32_t *)p->data + 1) = pContext->mCaptureSize;
p->vsize = sizeof(uint32_t);
*replySize += sizeof(uint32_t);
break;
case VISUALIZER_PARAM_SCALING_MODE:
ALOGV("get mScalingMode = %" PRIu32, pContext->mScalingMode);
*((uint32_t *)p->data + 1) = pContext->mScalingMode;
p->vsize = sizeof(uint32_t);
*replySize += sizeof(uint32_t);
break;
case VISUALIZER_PARAM_MEASUREMENT_MODE:
ALOGV("get mMeasurementMode = %" PRIu32, pContext->mMeasurementMode);
*((uint32_t *)p->data + 1) = pContext->mMeasurementMode;
p->vsize = sizeof(uint32_t);
*replySize += sizeof(uint32_t);
break;
default:
p->status = -EINVAL;
}
} break;
case EFFECT_CMD_SET_PARAM: {
if (pCmdData == NULL ||
cmdSize != (int)(sizeof(effect_param_t) + sizeof(uint32_t) + sizeof(uint32_t)) ||
pReplyData == NULL || replySize == NULL || *replySize != sizeof(int32_t)) {
return -EINVAL;
}
*(int32_t *)pReplyData = 0;
effect_param_t *p = (effect_param_t *)pCmdData;
if (p->psize != sizeof(uint32_t) || p->vsize != sizeof(uint32_t)) {
*(int32_t *)pReplyData = -EINVAL;
break;
}
switch (*(uint32_t *)p->data) {
case VISUALIZER_PARAM_CAPTURE_SIZE:
pContext->mCaptureSize = *((uint32_t *)p->data + 1);
ALOGV("set mCaptureSize = %" PRIu32, pContext->mCaptureSize);
break;
case VISUALIZER_PARAM_SCALING_MODE:
pContext->mScalingMode = *((uint32_t *)p->data + 1);
ALOGV("set mScalingMode = %" PRIu32, pContext->mScalingMode);
break;
case VISUALIZER_PARAM_LATENCY:
pContext->mLatency = *((uint32_t *)p->data + 1);
ALOGV("set mLatency = %" PRIu32, pContext->mLatency);
break;
case VISUALIZER_PARAM_MEASUREMENT_MODE:
pContext->mMeasurementMode = *((uint32_t *)p->data + 1);
ALOGV("set mMeasurementMode = %" PRIu32, pContext->mMeasurementMode);
break;
default:
*(int32_t *)pReplyData = -EINVAL;
}
} break;
case EFFECT_CMD_SET_DEVICE:
case EFFECT_CMD_SET_VOLUME:
case EFFECT_CMD_SET_AUDIO_MODE:
break;
case VISUALIZER_CMD_CAPTURE: {
uint32_t captureSize = pContext->mCaptureSize;
if (pReplyData == NULL || replySize == NULL || *replySize != captureSize) {
ALOGV("VISUALIZER_CMD_CAPTURE() error *replySize %" PRIu32 " captureSize %" PRIu32,
*replySize, captureSize);
return -EINVAL;
}
if (pContext->mState == VISUALIZER_STATE_ACTIVE) {
const uint32_t deltaMs = Visualizer_getDeltaTimeMsFromUpdatedTime(pContext);
if ((pContext->mLastCaptureIdx == pContext->mCaptureIdx) &&
(pContext->mBufferUpdateTime.tv_sec != 0) &&
(deltaMs > MAX_STALL_TIME_MS)) {
ALOGV("capture going to idle");
pContext->mBufferUpdateTime.tv_sec = 0;
memset(pReplyData, 0x80, captureSize);
} else {
int32_t latencyMs = pContext->mLatency;
latencyMs -= deltaMs;
if (latencyMs < 0) {
latencyMs = 0;
}
const uint32_t deltaSmpl =
pContext->mConfig.inputCfg.samplingRate * latencyMs / 1000;
int32_t capturePoint = pContext->mCaptureIdx - captureSize - deltaSmpl;
if (capturePoint < 0) {
uint32_t size = -capturePoint;
if (size > captureSize) {
size = captureSize;
}
memcpy(pReplyData,
pContext->mCaptureBuf + CAPTURE_BUF_SIZE + capturePoint,
size);
pReplyData = (char *)pReplyData + size;
captureSize -= size;
capturePoint = 0;
}
memcpy(pReplyData,
pContext->mCaptureBuf + capturePoint,
captureSize);
}
pContext->mLastCaptureIdx = pContext->mCaptureIdx;
} else {
memset(pReplyData, 0x80, captureSize);
}
} break;
case VISUALIZER_CMD_MEASURE: {
if (pReplyData == NULL || replySize == NULL ||
*replySize < (sizeof(int32_t) * MEASUREMENT_COUNT)) {
if (replySize == NULL) {
ALOGV("VISUALIZER_CMD_MEASURE() error replySize NULL");
} else {
ALOGV("VISUALIZER_CMD_MEASURE() error *replySize %" PRIu32
" < (sizeof(int32_t) * MEASUREMENT_COUNT) %" PRIu32,
*replySize,
uint32_t(sizeof(int32_t)) * MEASUREMENT_COUNT);
}
android_errorWriteLog(0x534e4554, "30229821");
return -EINVAL;
}
uint16_t peakU16 = 0;
float sumRmsSquared = 0.0f;
uint8_t nbValidMeasurements = 0;
const int32_t delayMs = Visualizer_getDeltaTimeMsFromUpdatedTime(pContext);
if (delayMs > DISCARD_MEASUREMENTS_TIME_MS) {
ALOGV("Discarding measurements, last measurement is %" PRId32 "ms old", delayMs);
for (uint32_t i=0 ; i<pContext->mMeasurementWindowSizeInBuffers ; i++) {
pContext->mPastMeasurements[i].mIsValid = false;
pContext->mPastMeasurements[i].mPeakU16 = 0;
pContext->mPastMeasurements[i].mRmsSquared = 0;
}
pContext->mMeasurementBufferIdx = 0;
} else {
for (uint32_t i=0 ; i < pContext->mMeasurementWindowSizeInBuffers ; i++) {
if (pContext->mPastMeasurements[i].mIsValid) {
if (pContext->mPastMeasurements[i].mPeakU16 > peakU16) {
peakU16 = pContext->mPastMeasurements[i].mPeakU16;
}
sumRmsSquared += pContext->mPastMeasurements[i].mRmsSquared;
nbValidMeasurements++;
}
}
}
float rms = nbValidMeasurements == 0 ? 0.0f : sqrtf(sumRmsSquared / nbValidMeasurements);
int32_t* pIntReplyData = (int32_t*)pReplyData;
if (rms < 0.000016f) {
pIntReplyData[MEASUREMENT_IDX_RMS] = -9600;         } else {
pIntReplyData[MEASUREMENT_IDX_RMS] = (int32_t) (2000 * log10(rms / 32767.0f));
}
if (peakU16 == 0) {
pIntReplyData[MEASUREMENT_IDX_PEAK] = -9600;         } else {
pIntReplyData[MEASUREMENT_IDX_PEAK] = (int32_t) (2000 * log10(peakU16 / 32767.0f));
}
ALOGV("VISUALIZER_CMD_MEASURE peak=%" PRIu16 " (%" PRId32 "mB), rms=%.1f (%" PRId32 "mB)",
peakU16, pIntReplyData[MEASUREMENT_IDX_PEAK],
rms, pIntReplyData[MEASUREMENT_IDX_RMS]);
}
break;
default:
ALOGW("Visualizer_command invalid command %" PRIu32, cmdCode);
return -EINVAL;
}
return 0;
}

TfLiteStatus ResizeOutputTensor(TfLiteContext* context,
SpaceToBatchNDContext* op_context) {
TfLiteIntArray* input_size = op_context->input->dims;
const int32* block_shape = GetTensorData<int32>(op_context->block_shape);
const int32* paddings_data = GetTensorData<int32>(op_context->paddings);
int spatial_dims_num = input_size->size - 2;
TF_LITE_ENSURE_EQ(context, NumDimensions(op_context->block_shape), 1);
TF_LITE_ENSURE_EQ(context, op_context->block_shape->dims->data[0],
spatial_dims_num);
TF_LITE_ENSURE_EQ(context, NumDimensions(op_context->paddings), 2);
TF_LITE_ENSURE_EQ(context, op_context->paddings->dims->data[0],
spatial_dims_num);
TF_LITE_ENSURE_EQ(context, op_context->paddings->dims->data[1], 2);
TfLiteIntArray* output_size = TfLiteIntArrayCopy(input_size);
int output_batch_size = input_size->data[0];
for (int dim = 0; dim < spatial_dims_num; ++dim) {
int final_dim_size = (input_size->data[dim + 1] + paddings_data[dim * 2] +
paddings_data[dim * 2 + 1]);
TF_LITE_ENSURE_EQ(context, final_dim_size % block_shape[dim], 0);
output_size->data[dim + 1] = final_dim_size / block_shape[dim];
output_batch_size *= block_shape[dim];
}
output_size->data[0] = output_batch_size;
output_size->data[input_size->size - 1] =
input_size->data[input_size->size - 1];
return context->ResizeTensor(context, op_context->output, output_size);
}

static void *proc_pid_follow_link(struct dentry *dentry, struct nameidata *nd)
{
struct inode *inode = dentry->d_inode;
int error = -EACCES;
path_put(&nd->path);
if (!proc_fd_access_allowed(inode))
goto out;
error = PROC_I(inode)->op.proc_get_link(inode, &nd->path);
nd->last_type = LAST_BIND;
out:
return ERR_PTR(error);
}

IW_IMPL(int) iw_read_miff_file(struct iw_context *ctx, struct iw_iodescr *iodescr)
{
struct iw_image img;
struct iwmiffrcontext rctx;
int retval=0;
iw_zeromem(&rctx,sizeof(struct iwmiffrcontext));
iw_zeromem(&img,sizeof(struct iw_image));
rctx.ctx = ctx;
rctx.host_endian = iw_get_host_endianness();
rctx.iodescr = iodescr;
rctx.img = &img;
rctx.compression = IW_COMPRESSION_NONE;
rctx.zmod = iw_get_zlib_module(ctx);
iw_make_srgb_csdescr_2(&rctx.csdescr);
img.sampletype = IW_SAMPLETYPE_FLOATINGPOINT;
if(!iwmiff_read_header(&rctx))
goto done;
if(!iw_check_image_dimensions(rctx.ctx,img.width,img.height))
goto done;
if(rctx.is_grayscale) {
img.imgtype = rctx.has_alpha ? IW_IMGTYPE_GRAYA : IW_IMGTYPE_GRAY;
img.native_grayscale = 1;
}
else {
img.imgtype = rctx.has_alpha ? IW_IMGTYPE_RGBA : IW_IMGTYPE_RGB;
}
if(rctx.density_known && rctx.density_units==1) {
img.density_x = rctx.density_x*100.0;
img.density_y = rctx.density_y*100.0;
img.density_code = IW_DENSITY_UNITS_PER_METER;
}
if(!iwmiff_read_icc_profile(&rctx))
goto done;
if(!iwmiff_read_pixels(&rctx))
goto done;
iw_set_input_image(ctx, &img);
iw_set_input_colorspace(ctx,&rctx.csdescr);
retval = 1;
done:
if(!retval) {
iw_set_error(ctx,"Failed to read MIFF file");
}
return retval;
}

static int
dissect_pvfs2_getconfig_response(tvbuff_t *tvb, proto_tree *parent_tree,
int offset, packet_info *pinfo)
{
guint32 i;
guint32 total_bytes = 0, total_config_bytes = 0, total_lines = 0;
guint32 bytes_processed = 0;
guint32 length_remaining = 0;
const char *ptr = NULL;
proto_tree *tree, *config_tree = NULL;
tree = proto_tree_add_subtree(parent_tree, tvb, offset, 12,
ett_pvfs_server_config, NULL, "Server Config");
total_bytes = tvb_get_letohl(tvb, offset);
proto_tree_add_item(tree, hf_pvfs_getconfig_response_total_bytes, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
if (total_bytes < 4)
{
return offset;
}
total_lines = tvb_get_letohl(tvb, offset);
proto_tree_add_item(tree, hf_pvfs_getconfig_response_lines, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
total_config_bytes = tvb_get_letohl(tvb, offset);
proto_tree_add_item(tree, hf_pvfs_getconfig_response_config_bytes, tvb, offset, 4, ENC_LITTLE_ENDIAN);
offset += 4;
ptr = tvb_get_ptr(tvb, offset, total_config_bytes);
length_remaining = tvb_captured_length_remaining(tvb, offset);
if (length_remaining < total_config_bytes)
{
total_config_bytes = length_remaining;
}
bytes_processed = 0;
for (i = 0; i < total_lines; i++)
{
guint8 entry[256], *pentry = entry, *tmp_entry = NULL;
guint32 entry_length = 0, tmp_entry_length = 0;
guint32 bufsiz = sizeof(entry);
while ((*ptr != '\n') && (*ptr != '\0') &&
(bytes_processed < total_config_bytes) &&
(entry_length < bufsiz))
{
*pentry++ = *ptr++;
bytes_processed++;
entry_length++;
}
if ((entry_length == bufsiz) &&
((entry[entry_length - 1] != '\n') &&
(entry[entry_length - 1] != '\0')))
{
break;
}
if (bytes_processed == total_config_bytes)
{
break;
}
*pentry= '\0';
tmp_entry = entry;
tmp_entry_length = entry_length;
while ((tmp_entry_length > 0) && (!g_ascii_isalnum(*tmp_entry)) &&
(*tmp_entry != '<'))
{
tmp_entry++;
tmp_entry_length--;
}
if (tmp_entry[0] == '<')
{
if (tmp_entry[tmp_entry_length - 1] == '>')
{
if (tmp_entry[1] != '/')
{
config_tree = proto_tree_add_subtree(tree, tvb, offset,
tmp_entry_length, ett_pvfs_server_config_branch, NULL, tmp_entry);
}
else
{
config_tree = NULL;
}
}
else
{
break;
}
}
else
{
if (config_tree == NULL)
config_tree = tree;
if (tmp_entry_length > 0)
{
proto_tree_add_string_format(config_tree, hf_pvfs_getconfig_response_entry, tvb, offset, tmp_entry_length,
tmp_entry, "%s", tmp_entry);
}
}
offset += entry_length + 1;
ptr++;
bytes_processed++;
}
if (bytes_processed < total_config_bytes)
{
proto_tree_add_expert(config_tree, pinfo, &ei_pvfs_malformed, tvb, offset, -1);
}
return offset;
}

