ecma_value_t
ecma_proxy_object_get (ecma_object_t *obj_p, 
ecma_string_t *prop_name_p, 
ecma_value_t receiver) 
{
JERRY_ASSERT (ECMA_OBJECT_IS_PROXY (obj_p));
ecma_proxy_object_t *proxy_obj_p = (ecma_proxy_object_t *) obj_p;
ecma_value_t handler = proxy_obj_p->handler;
ecma_value_t trap = ecma_validate_proxy_object (handler, LIT_MAGIC_STRING_GET);
if (ECMA_IS_VALUE_ERROR (trap))
{
return trap;
}
ecma_value_t target = proxy_obj_p->target;
ecma_object_t *target_obj_p = ecma_get_object_from_value (target);
if (ecma_is_value_undefined (trap))
{
return ecma_op_object_get_with_receiver (target_obj_p, prop_name_p, receiver);
}
ecma_object_t *func_obj_p = ecma_get_object_from_value (trap);
ecma_value_t prop_value = ecma_make_prop_name_value (prop_name_p);
ecma_value_t args[] = { target, prop_value, receiver };
ecma_value_t trap_result = ecma_op_function_call (func_obj_p, handler, args, 3);
ecma_deref_object (func_obj_p);
if (ECMA_IS_VALUE_ERROR (trap_result))
{
return trap_result;
}
ecma_property_descriptor_t target_desc;
ecma_value_t status = ecma_op_object_get_own_property_descriptor (target_obj_p, prop_name_p, &target_desc);
if (ECMA_IS_VALUE_ERROR (status))
{
return status;
}
if (ecma_is_value_true (status))
{
ecma_value_t ret_value = ECMA_VALUE_EMPTY;
if ((target_desc.flags & ECMA_PROP_IS_VALUE_DEFINED)
&& !(target_desc.flags & ECMA_PROP_IS_CONFIGURABLE)
&& !(target_desc.flags & ECMA_PROP_IS_WRITABLE)
&& !ecma_op_same_value (trap_result, target_desc.value))
{
ret_value = ecma_raise_type_error (ECMA_ERR_MSG ("given property is a read-only and non-configurable"
" data property on the proxy target"));
}
else if (!(target_desc.flags & ECMA_PROP_IS_CONFIGURABLE)
&& (target_desc.flags & (ECMA_PROP_IS_GET_DEFINED | ECMA_PROP_IS_SET_DEFINED))
&& target_desc.get_p == NULL
&& !ecma_is_value_undefined (trap_result))
{
ret_value = ecma_raise_type_error (ECMA_ERR_MSG ("given property is a non-configurable property and"
" does not have a getter function"));
}
ecma_free_property_descriptor (&target_desc);
if (ECMA_IS_VALUE_ERROR (ret_value))
{
ecma_free_value (trap_result);
return ret_value;
}
}
return trap_result;
}

int main(int argc, char **argv)
{
opj_decompress_parameters parameters;           
OPJ_INT32 num_images, imageno;
img_fol_t img_fol;
dircnt_t *dirptr = NULL;
int failed = 0;
OPJ_FLOAT64 t, tCumulative = 0;
OPJ_UINT32 numDecompressedImages = 0;
OPJ_UINT32 cp_reduce;
set_default_parameters(&parameters);
memset(&img_fol, 0, sizeof(img_fol_t));
if (parse_cmdline_decoder(argc, argv, &parameters, &img_fol) == 1) {
failed = 1;
goto fin;
}
cp_reduce = parameters.core.cp_reduce;
if (getenv("USE_OPJ_SET_DECODED_RESOLUTION_FACTOR") != NULL) {
parameters.core.cp_reduce = 0;
}
if (img_fol.set_imgdir == 1) {
int it_image;
num_images = get_num_images(img_fol.imgdirpath);
dirptr = (dircnt_t*)malloc(sizeof(dircnt_t));
if (!dirptr) {
destroy_parameters(&parameters);
return EXIT_FAILURE;
}
memset(dirptr, 0, sizeof(dircnt_t));
dirptr->filename_buf = (char*)malloc(sizeof(char) *
(size_t)num_images * OPJ_PATH_LEN);
if (!dirptr->filename_buf) {
failed = 1;
goto fin;
}
dirptr->filename = (char**) malloc((size_t)num_images * sizeof(char*));
if (!dirptr->filename) {
failed = 1;
goto fin;
}
for (it_image = 0; it_image < num_images; it_image++) {
dirptr->filename[it_image] = dirptr->filename_buf + it_image * OPJ_PATH_LEN;
}
if (load_images(dirptr, img_fol.imgdirpath) == 1) {
failed = 1;
goto fin;
}
if (num_images == 0) {
fprintf(stderr, "Folder is empty\n");
failed = 1;
goto fin;
}
} else {
num_images = 1;
}
for (imageno = 0; imageno < num_images ; imageno++)  {
opj_image_t* image = NULL;
opj_stream_t *l_stream = NULL;              
opj_codec_t* l_codec = NULL;                
opj_codestream_index_t* cstr_index = NULL;
if (!parameters.quiet) {
fprintf(stderr, "\n");
}
if (img_fol.set_imgdir == 1) {
if (get_next_file(imageno, dirptr, &img_fol, &parameters)) {
fprintf(stderr, "skipping file...\n");
destroy_parameters(&parameters);
continue;
}
}
l_stream = opj_stream_create_default_file_stream(parameters.infile, 1);
if (!l_stream) {
fprintf(stderr, "ERROR -> failed to create the stream from the file %s\n",
parameters.infile);
failed = 1;
goto fin;
}
switch (parameters.decod_format) {
case J2K_CFMT: { 
l_codec = opj_create_decompress(OPJ_CODEC_J2K);
break;
}
case JP2_CFMT: { 
l_codec = opj_create_decompress(OPJ_CODEC_JP2);
break;
}
case JPT_CFMT: { 
l_codec = opj_create_decompress(OPJ_CODEC_JPT);
break;
}
default:
fprintf(stderr, "skipping file..\n");
destroy_parameters(&parameters);
opj_stream_destroy(l_stream);
continue;
}
if (parameters.quiet) {
opj_set_info_handler(l_codec, quiet_callback, 00);
opj_set_warning_handler(l_codec, quiet_callback, 00);
opj_set_error_handler(l_codec, quiet_callback, 00);
} else {
opj_set_info_handler(l_codec, info_callback, 00);
opj_set_warning_handler(l_codec, warning_callback, 00);
opj_set_error_handler(l_codec, error_callback, 00);
}
t = opj_clock();
if (!opj_setup_decoder(l_codec, &(parameters.core))) {
fprintf(stderr, "ERROR -> opj_decompress: failed to setup the decoder\n");
opj_stream_destroy(l_stream);
opj_destroy_codec(l_codec);
failed = 1;
goto fin;
}
if (parameters.num_threads >= 1 &&
!opj_codec_set_threads(l_codec, parameters.num_threads)) {
fprintf(stderr, "ERROR -> opj_decompress: failed to set number of threads\n");
opj_stream_destroy(l_stream);
opj_destroy_codec(l_codec);
failed = 1;
goto fin;
}
if (! opj_read_header(l_stream, l_codec, &image)) {
fprintf(stderr, "ERROR -> opj_decompress: failed to read the header\n");
opj_stream_destroy(l_stream);
opj_destroy_codec(l_codec);
opj_image_destroy(image);
failed = 1;
goto fin;
}
if (parameters.numcomps) {
if (! opj_set_decoded_components(l_codec,
parameters.numcomps,
parameters.comps_indices,
OPJ_FALSE)) {
fprintf(stderr,
"ERROR -> opj_decompress: failed to set the component indices!\n");
opj_destroy_codec(l_codec);
opj_stream_destroy(l_stream);
opj_image_destroy(image);
failed = 1;
goto fin;
}
}
if (getenv("USE_OPJ_SET_DECODED_RESOLUTION_FACTOR") != NULL) {
if (! opj_set_decoded_resolution_factor(l_codec, cp_reduce)) {
fprintf(stderr,
"ERROR -> opj_decompress: failed to set the resolution factor tile!\n");
opj_destroy_codec(l_codec);
opj_stream_destroy(l_stream);
opj_image_destroy(image);
failed = 1;
goto fin;
}
}
if (!parameters.nb_tile_to_decode) {
if (getenv("SKIP_OPJ_SET_DECODE_AREA") != NULL &&
parameters.DA_x0 == 0 &&
parameters.DA_y0 == 0 &&
parameters.DA_x1 == 0 &&
parameters.DA_y1 == 0) {
}
else if (!opj_set_decode_area(l_codec, image, (OPJ_INT32)parameters.DA_x0,
(OPJ_INT32)parameters.DA_y0, (OPJ_INT32)parameters.DA_x1,
(OPJ_INT32)parameters.DA_y1)) {
fprintf(stderr, "ERROR -> opj_decompress: failed to set the decoded area\n");
opj_stream_destroy(l_stream);
opj_destroy_codec(l_codec);
opj_image_destroy(image);
failed = 1;
goto fin;
}
if (!(opj_decode(l_codec, l_stream, image) &&
opj_end_decompress(l_codec,   l_stream))) {
fprintf(stderr, "ERROR -> opj_decompress: failed to decode image!\n");
opj_destroy_codec(l_codec);
opj_stream_destroy(l_stream);
opj_image_destroy(image);
failed = 1;
goto fin;
}
} else {
if (!(parameters.DA_x0 == 0 &&
parameters.DA_y0 == 0 &&
parameters.DA_x1 == 0 &&
parameters.DA_y1 == 0)) {
if (!(parameters.quiet)) {
fprintf(stderr, "WARNING: -d option ignored when used together with -t\n");
}
}
if (!opj_get_decoded_tile(l_codec, l_stream, image, parameters.tile_index)) {
fprintf(stderr, "ERROR -> opj_decompress: failed to decode tile!\n");
opj_destroy_codec(l_codec);
opj_stream_destroy(l_stream);
opj_image_destroy(image);
failed = 1;
goto fin;
}
if (!(parameters.quiet)) {
fprintf(stdout, "tile %d is decoded!\n\n", parameters.tile_index);
}
}
tCumulative += opj_clock() - t;
numDecompressedImages++;
opj_stream_destroy(l_stream);
if (image->color_space != OPJ_CLRSPC_SYCC
&& image->numcomps == 3 && image->comps[0].dx == image->comps[0].dy
&& image->comps[1].dx != 1) {
image->color_space = OPJ_CLRSPC_SYCC;
} else if (image->numcomps <= 2) {
image->color_space = OPJ_CLRSPC_GRAY;
}
if (image->color_space == OPJ_CLRSPC_SYCC) {
color_sycc_to_rgb(image);
} else if ((image->color_space == OPJ_CLRSPC_CMYK) &&
(parameters.cod_format != TIF_DFMT)) {
color_cmyk_to_rgb(image);
} else if (image->color_space == OPJ_CLRSPC_EYCC) {
color_esycc_to_rgb(image);
}
if (image->icc_profile_buf) {
#if defined(OPJ_HAVE_LIBLCMS1) || defined(OPJ_HAVE_LIBLCMS2)
if (image->icc_profile_len) {
color_apply_icc_profile(image);
} else {
color_cielab_to_rgb(image);
}
#endif
free(image->icc_profile_buf);
image->icc_profile_buf = NULL;
image->icc_profile_len = 0;
}
if (parameters.precision != NULL) {
OPJ_UINT32 compno;
for (compno = 0; compno < image->numcomps; ++compno) {
OPJ_UINT32 precno = compno;
OPJ_UINT32 prec;
if (precno >= parameters.nb_precision) {
precno = parameters.nb_precision - 1U;
}
prec = parameters.precision[precno].prec;
if (prec == 0) {
prec = image->comps[compno].prec;
}
switch (parameters.precision[precno].mode) {
case OPJ_PREC_MODE_CLIP:
clip_component(&(image->comps[compno]), prec);
break;
case OPJ_PREC_MODE_SCALE:
scale_component(&(image->comps[compno]), prec);
break;
default:
break;
}
}
}
if (parameters.upsample) {
image = upsample_image_components(image);
if (image == NULL) {
fprintf(stderr,
"ERROR -> opj_decompress: failed to upsample image components!\n");
opj_destroy_codec(l_codec);
failed = 1;
goto fin;
}
}
if (parameters.force_rgb) {
switch (image->color_space) {
case OPJ_CLRSPC_SRGB:
break;
case OPJ_CLRSPC_GRAY:
image = convert_gray_to_rgb(image);
break;
default:
fprintf(stderr,
"ERROR -> opj_decompress: don't know how to convert image to RGB colorspace!\n");
opj_image_destroy(image);
image = NULL;
break;
}
if (image == NULL) {
fprintf(stderr, "ERROR -> opj_decompress: failed to convert to RGB image!\n");
opj_destroy_codec(l_codec);
failed = 1;
goto fin;
}
}
switch (parameters.cod_format) {
case PXM_DFMT:          
if (imagetopnm(image, parameters.outfile, parameters.split_pnm)) {
fprintf(stderr, "[ERROR] Outfile %s not generated\n", parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
case PGX_DFMT:          
if (imagetopgx(image, parameters.outfile)) {
fprintf(stderr, "[ERROR] Outfile %s not generated\n", parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
case BMP_DFMT:          
if (imagetobmp(image, parameters.outfile)) {
fprintf(stderr, "[ERROR] Outfile %s not generated\n", parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
#ifdef OPJ_HAVE_LIBTIFF
case TIF_DFMT:          
if (imagetotif(image, parameters.outfile)) {
fprintf(stderr, "[ERROR] Outfile %s not generated\n", parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
#endif 
case RAW_DFMT:          
if (imagetoraw(image, parameters.outfile)) {
fprintf(stderr,
"[ERROR] Error generating raw or yuv file. Outfile %s not generated\n",
parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
case RAWL_DFMT:         
if (imagetorawl(image, parameters.outfile)) {
fprintf(stderr,
"[ERROR] Error generating rawl file. Outfile %s not generated\n",
parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
case TGA_DFMT:          
if (imagetotga(image, parameters.outfile)) {
fprintf(stderr, "[ERROR] Error generating tga file. Outfile %s not generated\n",
parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
#ifdef OPJ_HAVE_LIBPNG
case PNG_DFMT:          
if (imagetopng(image, parameters.outfile)) {
fprintf(stderr, "[ERROR] Error generating png file. Outfile %s not generated\n",
parameters.outfile);
failed = 1;
} else if (!(parameters.quiet)) {
fprintf(stdout, "[INFO] Generated Outfile %s\n", parameters.outfile);
}
break;
#endif 
default:
fprintf(stderr, "[ERROR] Outfile %s not generated\n", parameters.outfile);
failed = 1;
}
if (l_codec) {
opj_destroy_codec(l_codec);
}
opj_image_destroy(image);
opj_destroy_cstr_index(&cstr_index);
if (failed) {
(void)remove(parameters.outfile);    
}
}
fin:
destroy_parameters(&parameters);
if (failed && img_fol.imgdirpath) {
free(img_fol.imgdirpath);
}
if (dirptr) {
if (dirptr->filename) {
free(dirptr->filename);
}
if (dirptr->filename_buf) {
free(dirptr->filename_buf);
}
free(dirptr);
}
if (numDecompressedImages && !failed && !(parameters.quiet)) {
fprintf(stdout, "decode time: %d ms\n",
(int)((tCumulative * 1000.0) / (OPJ_FLOAT64)numDecompressedImages));
}
return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

bool stringTo<bool>(const std::string& s, bool& ok)
{
std::string lcs(s); 
for(unsigned i = 0; i < lcs.length(); i++) {
lcs[i] = std::tolower(s[i]);
}
if (lcs == "false" || lcs == "f" || lcs == "0") {
ok = true;
return false;
}
if (lcs == "true" || lcs == "t" || lcs == "1") {
ok = true;
return true;
}
ok = false;
return false;
}

Status Examples::CreateSparseFeatureRepresentation(
const DeviceBase::CpuWorkerThreads& worker_threads, const int num_examples,
const int num_sparse_features, const ModelWeights& weights,
const OpInputList& sparse_example_indices_inputs,
const OpInputList& sparse_feature_indices_inputs,
const OpInputList& sparse_feature_values_inputs,
std::vector<Example>* const examples) {
mutex mu;
Status result;    auto parse_partition = [&](const int64 begin, const int64 end) {
for (int i = static_cast<int>(begin); i < end; ++i) {
auto example_indices =
sparse_example_indices_inputs[i].template flat<int64>();
auto feature_indices =
sparse_feature_indices_inputs[i].template flat<int64>();
int start_id = -1;
int end_id = 0;
for (int example_id = 0; example_id < num_examples; ++example_id) {
start_id = end_id;
while (end_id < example_indices.size() &&
example_indices(end_id) == example_id) {
++end_id;
}
Example::SparseFeatures* const sparse_features =
&(*examples)[example_id].sparse_features_[i];
if (start_id < example_indices.size() &&
example_indices(start_id) == example_id) {
sparse_features->indices.reset(new UnalignedInt64Vector(
&(feature_indices(start_id)), end_id - start_id));
if (sparse_feature_values_inputs.size() > i) {
auto feature_weights =
sparse_feature_values_inputs[i].flat<float>();
sparse_features->values.reset(new UnalignedFloatVector(
&(feature_weights(start_id)), end_id - start_id));
}
if (end_id - start_id > 0) {
for (int64 k = 0; k < sparse_features->indices->size(); ++k) {
const int64 feature_index = (*sparse_features->indices)(k);
if (!weights.SparseIndexValid(i, feature_index)) {
mutex_lock l(mu);
result = errors::InvalidArgument(
"Found sparse feature indices out of valid range: ",
(*sparse_features->indices)(k));
return;
}
}
}
} else {
sparse_features->indices.reset(
new UnalignedInt64Vector(&(feature_indices(0)), 0));
if (sparse_feature_values_inputs.size() > i) {
auto feature_weights =
sparse_feature_values_inputs[i].flat<float>();
sparse_features->values.reset(
new UnalignedFloatVector(&(feature_weights(0)), 0));
}
}
}
}
};
const int64 kCostPerUnit = num_examples;
Shard(worker_threads.num_threads, worker_threads.workers, num_sparse_features,
kCostPerUnit, parse_partition);
return result;
}

BOOL planar_decompress(BITMAP_PLANAR_CONTEXT* planar, const BYTE* pSrcData, UINT32 SrcSize,
UINT32 nSrcWidth, UINT32 nSrcHeight, BYTE* pDstData, UINT32 DstFormat,
UINT32 nDstStep, UINT32 nXDst, UINT32 nYDst, UINT32 nDstWidth,
UINT32 nDstHeight, BOOL vFlip)
{
BOOL cs;
BOOL rle;
UINT32 cll;
BOOL alpha;
BOOL useAlpha = FALSE;
INT32 status;
const BYTE* srcp;
UINT32 subSize;
UINT32 subWidth;
UINT32 subHeight;
UINT32 planeSize;
INT32 rleSizes[4] = { 0, 0, 0, 0 };
UINT32 rawSizes[4];
UINT32 rawWidths[4];
UINT32 rawHeights[4];
BYTE FormatHeader;
const BYTE* planes[4] = { 0 };
const UINT32 w = MIN(nSrcWidth, nDstWidth);
const UINT32 h = MIN(nSrcHeight, nDstHeight);
const primitives_t* prims = primitives_get();
WINPR_ASSERT(planar);
WINPR_ASSERT(prims);
if (nDstStep <= 0)
nDstStep = nDstWidth * FreeRDPGetBytesPerPixel(DstFormat);
srcp = pSrcData;
if (!pSrcData)
{
WLog_ERR(TAG, "Invalid argument pSrcData=NULL");
return FALSE;
}
if (!pDstData)
{
WLog_ERR(TAG, "Invalid argument pDstData=NULL");
return FALSE;
}
FormatHeader = *srcp++;
cll = (FormatHeader & PLANAR_FORMAT_HEADER_CLL_MASK);
cs = (FormatHeader & PLANAR_FORMAT_HEADER_CS) ? TRUE : FALSE;
rle = (FormatHeader & PLANAR_FORMAT_HEADER_RLE) ? TRUE : FALSE;
alpha = (FormatHeader & PLANAR_FORMAT_HEADER_NA) ? FALSE : TRUE;
DstFormat = planar_invert_format(planar, alpha, DstFormat);
if (alpha)
useAlpha = FreeRDPColorHasAlpha(DstFormat);
if (!cll && cs)
{
WLog_ERR(TAG, "Chroma subsampling requires YCoCg and does not work with RGB data");
return FALSE; 
}
subWidth = (nSrcWidth / 2) + (nSrcWidth % 2);
subHeight = (nSrcHeight / 2) + (nSrcHeight % 2);
planeSize = nSrcWidth * nSrcHeight;
subSize = subWidth * subHeight;
if (!cs)
{
rawSizes[0] = planeSize; 
rawWidths[0] = nSrcWidth;
rawHeights[0] = nSrcHeight;
rawSizes[1] = planeSize; 
rawWidths[1] = nSrcWidth;
rawHeights[1] = nSrcHeight;
rawSizes[2] = planeSize; 
rawWidths[2] = nSrcWidth;
rawHeights[2] = nSrcHeight;
rawSizes[3] = planeSize; 
rawWidths[3] = nSrcWidth;
rawHeights[3] = nSrcHeight;
}
else 
{
rawSizes[0] = planeSize; 
rawWidths[0] = nSrcWidth;
rawHeights[0] = nSrcHeight;
rawSizes[1] = subSize; 
rawWidths[1] = subWidth;
rawHeights[1] = subHeight;
rawSizes[2] = subSize; 
rawWidths[2] = subWidth;
rawHeights[2] = subHeight;
rawSizes[3] = planeSize; 
rawWidths[3] = nSrcWidth;
rawHeights[3] = nSrcHeight;
}
if (!rle) 
{
UINT32 base = planeSize * 3;
if (cs)
base = planeSize + planeSize / 2;
if (alpha)
{
if ((SrcSize - (srcp - pSrcData)) < (planeSize + base))
{
WLog_ERR(TAG, "Alpha plane size mismatch %" PRIu32 " < %" PRIu32,
SrcSize - (srcp - pSrcData), (planeSize + base));
return FALSE;
}
planes[3] = srcp;                    
planes[0] = planes[3] + rawSizes[3]; 
planes[1] = planes[0] + rawSizes[0]; 
planes[2] = planes[1] + rawSizes[1]; 
if ((planes[2] + rawSizes[2]) > &pSrcData[SrcSize])
{
WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p", planes[2], rawSizes[2],
&pSrcData[SrcSize]);
return FALSE;
}
}
else
{
if ((SrcSize - (srcp - pSrcData)) < base)
{
WLog_ERR(TAG, "plane size mismatch %" PRIu32 " < %" PRIu32,
SrcSize - (srcp - pSrcData), base);
return FALSE;
}
planes[0] = srcp;                    
planes[1] = planes[0] + rawSizes[0]; 
planes[2] = planes[1] + rawSizes[1]; 
if ((planes[2] + rawSizes[2]) > &pSrcData[SrcSize])
{
WLog_ERR(TAG, "plane size mismatch %p + %" PRIu32 " > %p", planes[2], rawSizes[2],
&pSrcData[SrcSize]);
return FALSE;
}
}
}
else 
{
if (alpha)
{
planes[3] = srcp;
rleSizes[3] = planar_skip_plane_rle(planes[3], SrcSize - (planes[3] - pSrcData),
rawWidths[3], rawHeights[3]); 
if (rleSizes[3] < 0)
return FALSE;
planes[0] = planes[3] + rleSizes[3];
}
else
planes[0] = srcp;
rleSizes[0] = planar_skip_plane_rle(planes[0], SrcSize - (planes[0] - pSrcData),
rawWidths[0], rawHeights[0]); 
if (rleSizes[0] < 0)
return FALSE;
planes[1] = planes[0] + rleSizes[0];
rleSizes[1] = planar_skip_plane_rle(planes[1], SrcSize - (planes[1] - pSrcData),
rawWidths[1], rawHeights[1]); 
if (rleSizes[1] < 1)
return FALSE;
planes[2] = planes[1] + rleSizes[1];
rleSizes[2] = planar_skip_plane_rle(planes[2], SrcSize - (planes[2] - pSrcData),
rawWidths[2], rawHeights[2]); 
if (rleSizes[2] < 1)
return FALSE;
}
if (!cll) 
{
UINT32 TempFormat;
BYTE* pTempData = pDstData;
UINT32 nTempStep = nDstStep;
UINT32 nTotalHeight = nYDst + nDstHeight;
if (useAlpha)
TempFormat = PIXEL_FORMAT_BGRA32;
else
TempFormat = PIXEL_FORMAT_BGRX32;
TempFormat = planar_invert_format(planar, alpha, TempFormat);
if ((TempFormat != DstFormat) || (nSrcWidth != nDstWidth) || (nSrcHeight != nDstHeight))
{
pTempData = planar->pTempData;
nTempStep = planar->nTempStep;
nTotalHeight = planar->maxHeight;
}
if (!rle) 
{
if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, nXDst,
nYDst, nSrcWidth, nSrcHeight, vFlip, nTotalHeight))
return FALSE;
if (alpha)
srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
else 
srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];
if ((SrcSize - (srcp - pSrcData)) == 1)
srcp++; 
}
else 
{
status =
planar_decompress_plane_rle(planes[0], rleSizes[0], pTempData, nTempStep, nXDst,
nYDst, nSrcWidth, nSrcHeight, 2, vFlip); 
if (status < 0)
return FALSE;
status = planar_decompress_plane_rle(planes[1], rleSizes[1], pTempData, nTempStep,
nXDst, nYDst, nSrcWidth, nSrcHeight, 1,
vFlip); 
if (status < 0)
return FALSE;
status =
planar_decompress_plane_rle(planes[2], rleSizes[2], pTempData, nTempStep, nXDst,
nYDst, nSrcWidth, nSrcHeight, 0, vFlip); 
if (status < 0)
return FALSE;
srcp += rleSizes[0] + rleSizes[1] + rleSizes[2];
if (useAlpha)
{
status = planar_decompress_plane_rle(planes[3], rleSizes[3], pTempData, nTempStep,
nXDst, nYDst, nSrcWidth, nSrcHeight, 3,
vFlip); 
}
else
status = planar_set_plane(0xFF, pTempData, nTempStep, nXDst, nYDst, nSrcWidth,
nSrcHeight, 3, vFlip);
if (status < 0)
return FALSE;
if (alpha)
srcp += rleSizes[3];
}
if (pTempData != pDstData)
{
if (!freerdp_image_copy(pDstData, DstFormat, nDstStep, nXDst, nYDst, w, h, pTempData,
TempFormat, nTempStep, nXDst, nYDst, NULL, FREERDP_FLIP_NONE))
{
WLog_ERR(TAG, "planar image copy failed");
return FALSE;
}
}
}
else 
{
UINT32 TempFormat;
BYTE* pTempData = planar->pTempData;
UINT32 nTempStep = planar->nTempStep;
UINT32 nTotalHeight = planar->maxHeight;
BYTE* dst = &pDstData[nXDst * FreeRDPGetBytesPerPixel(DstFormat) + nYDst * nDstStep];
if (useAlpha)
TempFormat = PIXEL_FORMAT_BGRA32;
else
TempFormat = PIXEL_FORMAT_BGRX32;
if (!pTempData)
{
return FALSE;
}
if (rle) 
{
BYTE* rleBuffer[4] = { 0 };
rleBuffer[3] = planar->rlePlanesBuffer;  
rleBuffer[0] = rleBuffer[3] + planeSize; 
rleBuffer[1] = rleBuffer[0] + planeSize; 
rleBuffer[2] = rleBuffer[1] + planeSize; 
if (useAlpha)
{
status =
planar_decompress_plane_rle_only(planes[3], rleSizes[3], rleBuffer[3],
rawWidths[3], rawHeights[3]); 
if (status < 0)
return FALSE;
}
if (alpha)
srcp += rleSizes[3];
status = planar_decompress_plane_rle_only(planes[0], rleSizes[0], rleBuffer[0],
rawWidths[0], rawHeights[0]); 
if (status < 0)
return FALSE;
status =
planar_decompress_plane_rle_only(planes[1], rleSizes[1], rleBuffer[1], rawWidths[1],
rawHeights[1]); 
if (status < 0)
return FALSE;
status =
planar_decompress_plane_rle_only(planes[2], rleSizes[2], rleBuffer[2], rawWidths[2],
rawHeights[2]); 
if (status < 0)
return FALSE;
planes[0] = rleBuffer[0];
planes[1] = rleBuffer[1];
planes[2] = rleBuffer[2];
planes[3] = rleBuffer[3];
}
{
if (cs)
{ 
if (!planar_subsample_expand(planes[1], rawSizes[1], nSrcWidth, nSrcHeight,
rawWidths[1], rawHeights[1], planar->deltaPlanes[0]))
return FALSE;
planes[1] = planar->deltaPlanes[0];
rawSizes[1] = planeSize; 
rawWidths[1] = nSrcWidth;
rawHeights[1] = nSrcHeight;
if (!planar_subsample_expand(planes[2], rawSizes[2], nSrcWidth, nSrcHeight,
rawWidths[2], rawHeights[2], planar->deltaPlanes[1]))
return FALSE;
planes[2] = planar->deltaPlanes[1];
rawSizes[2] = planeSize; 
rawWidths[2] = nSrcWidth;
rawHeights[2] = nSrcHeight;
}
if (!planar_decompress_planes_raw(planes, pTempData, TempFormat, nTempStep, nXDst,
nYDst, nSrcWidth, nSrcHeight, vFlip, nTotalHeight))
return FALSE;
if (alpha)
srcp += rawSizes[0] + rawSizes[1] + rawSizes[2] + rawSizes[3];
else 
srcp += rawSizes[0] + rawSizes[1] + rawSizes[2];
if ((SrcSize - (srcp - pSrcData)) == 1)
srcp++; 
}
WINPR_ASSERT(prims->YCoCgToRGB_8u_AC4R);
int rc = prims->YCoCgToRGB_8u_AC4R(pTempData, nTempStep, dst, DstFormat, nDstStep, w, h,
cll, useAlpha);
if (rc != PRIMITIVES_SUCCESS)
{
WLog_ERR(TAG, "YCoCgToRGB_8u_AC4R failed with %d", rc);
return FALSE;
}
}
WINPR_UNUSED(srcp);
return TRUE;
}

int xenmem_add_to_physmap_one(
struct domain *d,
unsigned int space,
union add_to_physmap_extra extra,
unsigned long idx,
gfn_t gfn)
{
mfn_t mfn = INVALID_MFN;
int rc;
p2m_type_t t;
struct page_info *page = NULL;
switch ( space )
{
case XENMAPSPACE_grant_table:
rc = gnttab_map_frame(d, idx, gfn, &mfn);
if ( rc )
return rc;
t = p2m_ram_rw;
break;
case XENMAPSPACE_shared_info:
if ( idx != 0 )
return -EINVAL;
mfn = virt_to_mfn(d->shared_info);
t = p2m_ram_rw;
break;
case XENMAPSPACE_gmfn_foreign:
{
struct domain *od;
p2m_type_t p2mt;
od = get_pg_owner(extra.foreign_domid);
if ( od == NULL )
return -ESRCH;
if ( od == d )
{
put_pg_owner(od);
return -EINVAL;
}
rc = xsm_map_gmfn_foreign(XSM_TARGET, d, od);
if ( rc )
{
put_pg_owner(od);
return rc;
}
page = get_page_from_gfn(od, idx, &p2mt, P2M_ALLOC);
if ( !page )
{
put_pg_owner(od);
return -EINVAL;
}
if ( p2m_is_ram(p2mt) )
t = (p2mt == p2m_ram_rw) ? p2m_map_foreign_rw : p2m_map_foreign_ro;
else
{
put_page(page);
put_pg_owner(od);
return -EINVAL;
}
mfn = page_to_mfn(page);
put_pg_owner(od);
break;
}
case XENMAPSPACE_dev_mmio:
rc = map_dev_mmio_region(d, gfn, 1, _mfn(idx));
return rc;
default:
return -ENOSYS;
}
rc = guest_physmap_add_entry(d, gfn, mfn, 0, t);
if ( rc && space == XENMAPSPACE_gmfn_foreign )
{
ASSERT(page != NULL);
put_page(page);
}
return rc;
}

