static ssize_t ucma_process_join(struct ucma_file *file,
struct rdma_ucm_join_mcast *cmd,  int out_len)
{
struct rdma_ucm_create_id_resp resp;
struct ucma_context *ctx;
struct ucma_multicast *mc;
struct sockaddr *addr;
int ret;
u8 join_state;
if (out_len < sizeof(resp))
return -ENOSPC;
addr = (struct sockaddr *) &cmd->addr;
if (cmd->addr_size != rdma_addr_size(addr))
return -EINVAL;
if (cmd->join_flags == RDMA_MC_JOIN_FLAG_FULLMEMBER)
join_state = BIT(FULLMEMBER_JOIN);
else if (cmd->join_flags == RDMA_MC_JOIN_FLAG_SENDONLY_FULLMEMBER)
join_state = BIT(SENDONLY_FULLMEMBER_JOIN);
else
return -EINVAL;
ctx = ucma_get_ctx_dev(file, cmd->id);
if (IS_ERR(ctx))
return PTR_ERR(ctx);
mutex_lock(&file->mut);
mc = ucma_alloc_multicast(ctx);
if (!mc) {
ret = -ENOMEM;
goto err1;
}
mc->join_state = join_state;
mc->uid = cmd->uid;
memcpy(&mc->addr, addr, cmd->addr_size);
ret = rdma_join_multicast(ctx->cm_id, (struct sockaddr *)&mc->addr,
join_state, mc);
if (ret)
goto err2;
resp.id = mc->id;
if (copy_to_user(u64_to_user_ptr(cmd->response),
&resp, sizeof(resp))) {
ret = -EFAULT;
goto err3;
}
mutex_unlock(&file->mut);
ucma_put_ctx(ctx);
return 0;
err3:
rdma_leave_multicast(ctx->cm_id, (struct sockaddr *) &mc->addr);
ucma_cleanup_mc_events(mc);
err2:
mutex_lock(&mut);
idr_remove(&multicast_idr, mc->id);
mutex_unlock(&mut);
list_del(&mc->list);
kfree(mc);
err1:
mutex_unlock(&file->mut);
ucma_put_ctx(ctx);
return ret;
}

static gboolean
dissect_cbor_text_string(tvbuff_t *tvb, packet_info *pinfo, proto_tree *cbor_tree, gint *offset, guint8 type_minor)
{
const guint8 *value = NULL;
guint64  length = 0;
gint     eof_type;
proto_tree *subtree;
proto_item *item;
item = proto_tree_add_item(cbor_tree, hf_cbor_item_text_string, tvb, *offset, -1, ENC_NA);
subtree = proto_item_add_subtree(item, ett_cbor_text_string);
proto_tree_add_item(subtree, hf_cbor_item_major_type, tvb, *offset, 1, ENC_BIG_ENDIAN);
if (type_minor <= 0x17) {
proto_tree_add_item(subtree, hf_cbor_item_length5, tvb, *offset, 1, ENC_BIG_ENDIAN);
length = type_minor;
} else {
proto_tree_add_item(subtree, hf_cbor_item_length_size, tvb, *offset, 1, ENC_BIG_ENDIAN);
}
*offset += 1;
switch (type_minor) {
case 0x18:
proto_tree_add_item_ret_uint64(subtree, hf_cbor_item_length, tvb, *offset, 1, ENC_BIG_ENDIAN, &length);
*offset += 1;
break;
case 0x19:
proto_tree_add_item_ret_uint64(subtree, hf_cbor_item_length, tvb, *offset, 2, ENC_BIG_ENDIAN, &length);
*offset += 2;
break;
case 0x1a:
proto_tree_add_item_ret_uint64(subtree, hf_cbor_item_length, tvb, *offset, 4, ENC_BIG_ENDIAN, &length);
*offset += 4;
break;
case 0x1b:
proto_tree_add_item_ret_uint64(subtree, hf_cbor_item_length, tvb, *offset, 8, ENC_BIG_ENDIAN, &length);
*offset += 8;
break;
case 0x1f:
proto_item_append_text(item, ": (indefinite length)");
item = proto_tree_add_item(subtree, hf_cbor_type_text_string_indef, tvb, *offset, 1, ENC_NA);
subtree = proto_item_add_subtree(item, ett_cbor_text_string_indef);
while (1) {
eof_type = tvb_get_guint8(tvb, *offset);
if (eof_type == 0xff) {
dissect_cbor_float_simple_data(tvb, pinfo, subtree, offset, 0x1f);
proto_item_set_end(item, tvb, *offset);
return TRUE;
}
if (((eof_type & 0xe0) >> 5) != CBOR_TYPE_TEXT_STRING) {
expert_add_info_format(pinfo, subtree, &ei_cbor_invalid_element,
"invalid element %i, expected text string", (eof_type & 0xe0) >> 5);
return FALSE;
}
if (!dissect_cbor_text_string(tvb, pinfo, subtree, offset, eof_type & 0x1f)) {
return FALSE;
}
}
DISSECTOR_ASSERT_NOT_REACHED();
return FALSE;
default:
if (type_minor > 0x17) {
expert_add_info_format(pinfo, subtree, &ei_cbor_invalid_minor_type,
"invalid minor type %i in text string", type_minor);
return FALSE;
}
break;
}
if (length > G_MAXINT32 || *offset + (gint)length < *offset) {
expert_add_info_format(pinfo, subtree, &ei_cbor_too_long_length,
"the length (%" PRIu64 ") of the text string too long", length);
return FALSE;
}
proto_tree_add_item_ret_string(subtree, hf_cbor_type_text_string, tvb, *offset, (gint)length, ENC_BIG_ENDIAN|ENC_UTF_8, pinfo->pool, &value);
*offset += (gint)length;
proto_item_append_text(item, ": %s", value);
proto_item_set_end(item, tvb, *offset);
return TRUE;
}

void gfs2_clear_rgrpd(struct gfs2_sbd *sdp)
{
struct rb_node *n;
struct gfs2_rgrpd *rgd;
struct gfs2_glock *gl;
while ((n = rb_first(&sdp->sd_rindex_tree))) {
rgd = rb_entry(n, struct gfs2_rgrpd, rd_node);
gl = rgd->rd_gl;
rb_erase(n, &sdp->sd_rindex_tree);
if (gl) {
spin_lock(&gl->gl_lockref.lock);
gl->gl_object = NULL;
spin_unlock(&gl->gl_lockref.lock);
gfs2_glock_add_to_lru(gl);
gfs2_glock_put(gl);
}
gfs2_free_clones(rgd);
kfree(rgd->rd_bits);
return_all_reservations(rgd);
kmem_cache_free(gfs2_rgrpd_cachep, rgd);
}
}

key_ref_t lookup_user_key(key_serial_t id, unsigned long lflags,
key_perm_t perm)
{
struct keyring_search_context ctx = {
.match_data.cmp= lookup_user_key_possessed,
.match_data.lookup_type= KEYRING_SEARCH_LOOKUP_DIRECT,
.flags= KEYRING_SEARCH_NO_STATE_CHECK,
};
struct request_key_auth *rka;
struct key *key;
key_ref_t key_ref, skey_ref;
int ret;
try_again:
ctx.cred = get_current_cred();
key_ref = ERR_PTR(-ENOKEY);
switch (id) {
case KEY_SPEC_THREAD_KEYRING:
if (!ctx.cred->thread_keyring) {
if (!(lflags & KEY_LOOKUP_CREATE))
goto error;
ret = install_thread_keyring();
if (ret < 0) {
key_ref = ERR_PTR(ret);
goto error;
}
goto reget_creds;
}
key = ctx.cred->thread_keyring;
__key_get(key);
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_PROCESS_KEYRING:
if (!ctx.cred->process_keyring) {
if (!(lflags & KEY_LOOKUP_CREATE))
goto error;
ret = install_process_keyring();
if (ret < 0) {
key_ref = ERR_PTR(ret);
goto error;
}
goto reget_creds;
}
key = ctx.cred->process_keyring;
__key_get(key);
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_SESSION_KEYRING:
if (!ctx.cred->session_keyring) {
ret = install_user_keyrings();
if (ret < 0)
goto error;
if (lflags & KEY_LOOKUP_CREATE)
ret = join_session_keyring(NULL);
else
ret = install_session_keyring(
ctx.cred->user->session_keyring);
if (ret < 0)
goto error;
goto reget_creds;
} else if (ctx.cred->session_keyring ==
ctx.cred->user->session_keyring &&
lflags & KEY_LOOKUP_CREATE) {
ret = join_session_keyring(NULL);
if (ret < 0)
goto error;
goto reget_creds;
}
rcu_read_lock();
key = rcu_dereference(ctx.cred->session_keyring);
__key_get(key);
rcu_read_unlock();
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_USER_KEYRING:
if (!ctx.cred->user->uid_keyring) {
ret = install_user_keyrings();
if (ret < 0)
goto error;
}
key = ctx.cred->user->uid_keyring;
__key_get(key);
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_USER_SESSION_KEYRING:
if (!ctx.cred->user->session_keyring) {
ret = install_user_keyrings();
if (ret < 0)
goto error;
}
key = ctx.cred->user->session_keyring;
__key_get(key);
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_GROUP_KEYRING:
key_ref = ERR_PTR(-EINVAL);
goto error;
case KEY_SPEC_REQKEY_AUTH_KEY:
key = ctx.cred->request_key_auth;
if (!key)
goto error;
__key_get(key);
key_ref = make_key_ref(key, 1);
break;
case KEY_SPEC_REQUESTOR_KEYRING:
if (!ctx.cred->request_key_auth)
goto error;
down_read(&ctx.cred->request_key_auth->sem);
if (test_bit(KEY_FLAG_REVOKED,
&ctx.cred->request_key_auth->flags)) {
key_ref = ERR_PTR(-EKEYREVOKED);
key = NULL;
} else {
rka = ctx.cred->request_key_auth->payload.data[0];
key = rka->dest_keyring;
__key_get(key);
}
up_read(&ctx.cred->request_key_auth->sem);
if (!key)
goto error;
key_ref = make_key_ref(key, 1);
break;
default:
key_ref = ERR_PTR(-EINVAL);
if (id < 1)
goto error;
key = key_lookup(id);
if (IS_ERR(key)) {
key_ref = ERR_CAST(key);
goto error;
}
key_ref = make_key_ref(key, 0);
ctx.index_key.type= key->type;
ctx.index_key.description= key->description;
ctx.index_key.desc_len= strlen(key->description);
ctx.match_data.raw_data= key;
kdebug("check possessed");
skey_ref = search_process_keyrings(&ctx);
kdebug("possessed=%p", skey_ref);
if (!IS_ERR(skey_ref)) {
key_put(key);
key_ref = skey_ref;
}
break;
}
if (lflags & KEY_LOOKUP_FOR_UNLINK) {
ret = 0;
goto error;
}
if (!(lflags & KEY_LOOKUP_PARTIAL)) {
ret = wait_for_key_construction(key, true);
switch (ret) {
case -ERESTARTSYS:
goto invalid_key;
default:
if (perm)
goto invalid_key;
case 0:
break;
}
} else if (perm) {
ret = key_validate(key);
if (ret < 0)
goto invalid_key;
}
ret = -EIO;
if (!(lflags & KEY_LOOKUP_PARTIAL) &&
!test_bit(KEY_FLAG_INSTANTIATED, &key->flags))
goto invalid_key;
ret = key_task_permission(key_ref, ctx.cred, perm);
if (ret < 0)
goto invalid_key;
key->last_used_at = current_kernel_time().tv_sec;
error:
put_cred(ctx.cred);
return key_ref;
invalid_key:
key_ref_put(key_ref);
key_ref = ERR_PTR(ret);
goto error;
reget_creds:
put_cred(ctx.cred);
goto try_again;
}

void gatt_end_operation(tGATT_CLCB* p_clcb, tGATT_STATUS status, void* p_data) {
tGATT_CL_COMPLETE cb_data;
tGATT_CMPL_CBACK* p_cmpl_cb =
(p_clcb->p_reg) ? p_clcb->p_reg->app_cb.p_cmpl_cb : NULL;
tGATTC_OPTYPE op = p_clcb->operation;
tGATT_DISC_TYPE disc_type = GATT_DISC_MAX;
tGATT_DISC_CMPL_CB* p_disc_cmpl_cb =
(p_clcb->p_reg) ? p_clcb->p_reg->app_cb.p_disc_cmpl_cb : NULL;
uint16_t conn_id;
uint8_t operation;
VLOG(1) << __func__
<< StringPrintf(" status=%d op=%d subtype=%d", status,
p_clcb->operation, p_clcb->op_subtype);
memset(&cb_data.att_value, 0, sizeof(tGATT_VALUE));
if (p_cmpl_cb != NULL && p_clcb->operation != 0) {
if (p_clcb->operation == GATTC_OPTYPE_READ) {
cb_data.att_value.handle = p_clcb->s_handle;
cb_data.att_value.len = p_clcb->counter;
if (p_data && p_clcb->counter)
memcpy(cb_data.att_value.value, p_data, cb_data.att_value.len);
}
if (p_clcb->operation == GATTC_OPTYPE_WRITE) {
memset(&cb_data.att_value, 0, sizeof(tGATT_VALUE));
cb_data.handle = cb_data.att_value.handle = p_clcb->s_handle;
if (p_clcb->op_subtype == GATT_WRITE_PREPARE) {
if (p_data) {
cb_data.att_value = *((tGATT_VALUE*)p_data);
} else {
VLOG(1) << "Rcv Prepare write rsp but no data";
}
}
}
if (p_clcb->operation == GATTC_OPTYPE_CONFIG)
cb_data.mtu = p_clcb->p_tcb->payload_size;
if (p_clcb->operation == GATTC_OPTYPE_DISCOVERY) {
disc_type = static_cast<tGATT_DISC_TYPE>(p_clcb->op_subtype);
}
}
osi_free_and_reset((void**)&p_clcb->p_attr_buf);
operation = p_clcb->operation;
conn_id = p_clcb->conn_id;
gatt_stop_rsp_timer(p_clcb);
gatt_clcb_dealloc(p_clcb);
if (p_disc_cmpl_cb && (op == GATTC_OPTYPE_DISCOVERY))
(*p_disc_cmpl_cb)(conn_id, disc_type, status);
else if (p_cmpl_cb && op)
(*p_cmpl_cb)(conn_id, op, status, &cb_data);
else
LOG(WARNING) << __func__
<< StringPrintf(
": not sent out op=%d p_disc_cmpl_cb:%p p_cmpl_cb:%p",
operation, p_disc_cmpl_cb, p_cmpl_cb);
}

inline void GatherNd(const RuntimeShape& params_shape,
const ParamsT* params_data,
const RuntimeShape& indices_shape,
const IndicesT* indices_data,
const RuntimeShape& output_shape, ParamsT* output_data) {
ruy::profiler::ScopeLabel label("GatherNd");
const GatherNdHelperResult res = GatherNdHelper(params_shape, indices_shape);
for (int i = 0; i < res.n_slices; ++i) {
int from_pos = 0;
for (int j = 0; j < res.indices_nd; ++j) {
from_pos += indices_data[i * res.indices_nd + j] * res.dims_to_count[j];
}
std::memcpy(output_data + i * res.slice_size, params_data + from_pos,
sizeof(ParamsT) * res.slice_size);
}
}

static const char *ctxload_probe_data(const u8 *probe_data, u32 size, GF_FilterProbeScore *score)
{
const char *mime_type = NULL;
char *dst = NULL;
u8 *res;
if ((size>2) && (probe_data[0] == 0x1f) && (probe_data[1] == 0x8b)) {
*score = GF_FPROBE_EXT_MATCH;
return "btz|bt.gz|xmt.gz|xmtz|wrl.gz|x3dv.gz|x3dvz|x3d.gz|x3dz";
}
res = gf_utf_get_utf8_string_from_bom((char *)probe_data, size, &dst);
if (res) probe_data = res;
while (probe_data[0] && strchr("\n\r\t ", (char) probe_data[0]))
probe_data ++;
while (1) {
if (!strncmp(probe_data, "<!DOCTYPE", 9)) {
probe_data = strchr(probe_data, '>');
if (!probe_data) goto exit;
probe_data++;
while (probe_data[0] && strchr("\n\r\t ", (char) probe_data[0]))
probe_data ++;
}
else if (!strncmp(probe_data, "<?xml", 5)) {
probe_data = strstr(probe_data, "?>");
if (!probe_data) goto exit;
probe_data += 2;
while (probe_data[0] && strchr("\n\r\t ", (char) probe_data[0]))
probe_data ++;
}
else if (!strncmp(probe_data, "<!--", 4)) {
probe_data = strstr(probe_data, "-->");
if (!probe_data) goto exit;
probe_data += 3;
while (probe_data[0] && strchr("\n\r\t ", (char) probe_data[0]))
probe_data ++;
} else {
break;
}
}
if (!strncmp(probe_data, "<XMT-A", strlen("<XMT-A"))
|| strstr(probe_data, "urn:mpeg:mpeg4:xmta:schema:2002")
) {
mime_type = "application/x-xmt";
} else if (strstr(probe_data, "<X3D")
|| strstr(probe_data, "http:) {
mime_type = "model/x3d+xml";
} else if (strstr(probe_data, "<saf")
|| strstr(probe_data, "urn:mpeg:mpeg4:SAF:2005")
|| strstr(probe_data, "urn:mpeg:mpeg4:LASeR:2005")
) {
mime_type = "application/x-LASeR+xml";
} else if (!strncmp(probe_data, "<DIMSStream", strlen("<DIMSStream") ) ) {
mime_type = "application/dims";
} else if (!strncmp(probe_data, "<svg", 4) || strstr(probe_data, "http:mime_type = "image/svg+xml";
} else if (!strncmp(probe_data, "<widget", strlen("<widget") ) ) {
mime_type = "application/widget";
} else if (!strncmp(probe_data, "<NHNTStream", strlen("<NHNTStream") ) ) {
mime_type = "application/x-nhml";
} else if (!strncmp(probe_data, "<TextStream", strlen("<TextStream") ) ) {
mime_type = "text/ttxt";
} else if (!strncmp(probe_data, "<text3GTrack", strlen("<text3GTrack") ) ) {
mime_type = "quicktime/text";
}
else {
while (1) {
while (probe_data[0] && strchr("\n\r\t ", (char) probe_data[0]))
probe_data ++;
if (!strncmp(probe_data, "#VRML V2.0", strlen("#VRML V2.0"))) {
mime_type = "model/vrml";
goto exit;
}
if (!strncmp(probe_data, "#X3D V3.0", strlen("#X3D V3.0"))) {
mime_type = "model/x3d+vrml";
goto exit;
}
if ((probe_data[0] != '#')
&& strncmp(probe_data, "PROFILE", strlen("PROFILE"))
&& strncmp(probe_data, "COMPONENT", strlen("COMPONENT"))
&& strncmp(probe_data, "META", strlen("META"))
&& strncmp(probe_data, "IMPORT", strlen("IMPORT"))
&& strncmp(probe_data, "EXPORT", strlen("EXPORT"))
) {
break;
}
probe_data = strchr(probe_data, '\n');
if (!probe_data) goto exit;
}
if (!strncmp(probe_data, "InitialObjectDescriptor", strlen("InitialObjectDescriptor"))
|| !strncmp(probe_data, "EXTERNPROTO", strlen("EXTERNPROTO"))
|| !strncmp(probe_data, "PROTO", strlen("PROTO"))
|| !strncmp(probe_data, "Group", strlen("Group"))
|| !strncmp(probe_data, "OrderedGroup", strlen("OrderedGroup"))
|| !strncmp(probe_data, "Layer2D", strlen("Layer2D"))
|| !strncmp(probe_data, "Layer3D", strlen("Layer3D"))
) {
if (strstr(probe_data, "children"))
mime_type = "application/x-bt";
}
}
exit:
if (dst) gf_free(dst);
if (mime_type) {
*score = GF_FPROBE_MAYBE_SUPPORTED;
return mime_type;
}
*score = GF_FPROBE_NOT_SUPPORTED;
return NULL;
}

static XML_Char *
copyString(const XML_Char *s, const XML_Memory_Handling_Suite *memsuite) {
int charsRequired = 0;
XML_Char *result;
while (s[charsRequired] != 0) {
charsRequired++;
}
charsRequired++;
result = memsuite->malloc_fcn(charsRequired * sizeof(XML_Char));
if (result == NULL)
return NULL;
memcpy(result, s, charsRequired * sizeof(XML_Char));
return result;
}

DNSInfo DNSRequest::ResultIsReady(DNSHeader &header, unsigned length)
{
unsigned i = 0, o;
int q = 0;
int curanswer;
ResourceRecord rr;
unsigned short ptr;
rr.type = DNS_QUERY_NONE;
rr.rdlength = 0;
rr.ttl = 1;
rr.rr_class = 0; 
if (!(header.flags1 & FLAGS_MASK_QR))
return std::make_pair((unsigned char*)NULL,"Not a query result");
if (header.flags1 & FLAGS_MASK_OPCODE)
return std::make_pair((unsigned char*)NULL,"Unexpected value in DNS reply packet");
if (header.flags2 & FLAGS_MASK_RCODE)
return std::make_pair((unsigned char*)NULL,"Domain name not found");
if (header.ancount < 1)
return std::make_pair((unsigned char*)NULL,"No resource records returned");
length -= 12;
while ((unsigned int)q < header.qdcount && i < length)
{
if (header.payload[i] > 63)
{
i += 6;
q++;
}
else
{
if (header.payload[i] == 0)
{
q++;
i += 5;
}
else i += header.payload[i] + 1;
}
}
curanswer = 0;
while ((unsigned)curanswer < header.ancount)
{
q = 0;
while (q == 0 && i < length)
{
if (header.payload[i] > 63)
{
i += 2;
q = 1;
}
else
{
if (header.payload[i] == 0)
{
i++;
q = 1;
}
else i += header.payload[i] + 1; 
}
}
if (length - i < 10)
return std::make_pair((unsigned char*)NULL,"Incorrectly sized DNS reply");
DNS::FillResourceRecord(&rr,&header.payload[i]);
i += 10;
ServerInstance->Logs->Log("RESOLVER",DEBUG,"Resolver: rr.type is %d and this.type is %d rr.class %d this.class %d", rr.type, this->type, rr.rr_class, this->rr_class);
if (rr.type != this->type)
{
curanswer++;
i += rr.rdlength;
continue;
}
if (rr.rr_class != this->rr_class)
{
curanswer++;
i += rr.rdlength;
continue;
}
break;
}
if ((unsigned int)curanswer == header.ancount)
return std::make_pair((unsigned char*)NULL,"No A, AAAA or PTR type answers (" + ConvToStr(header.ancount) + " answers)");
if (i + rr.rdlength > (unsigned int)length)
return std::make_pair((unsigned char*)NULL,"Resource record larger than stated");
if (rr.rdlength > 1023)
return std::make_pair((unsigned char*)NULL,"Resource record too large");
this->ttl = rr.ttl;
switch (rr.type)
{
case DNS_QUERY_CNAME:
case DNS_QUERY_PTR:
o = 0;
q = 0;
while (q == 0 && i < length && o + 256 < 1023)
{
if (header.payload[i] > 63)
{
memcpy(&ptr,&header.payload[i],2);
i = ntohs(ptr);
if (!(i & DN_COMP_BITMASK))
return std::make_pair((unsigned char *) NULL, "DN label decompression header is bogus");
i &= ~DN_COMP_BITMASK;
i =- 12;
}
else
{
if (header.payload[i] == 0)
{
q = 1;
}
else
{
res[o] = 0;
if (o != 0)
res[o++] = '.';
if (o + header.payload[i] > sizeof(DNSHeader))
return std::make_pair((unsigned char *) NULL, "DN label decompression is impossible -- malformed/hostile packet?");
memcpy(&res[o], &header.payload[i + 1], header.payload[i]);
o += header.payload[i];
i += header.payload[i] + 1;
}
}
}
res[o] = 0;
break;
case DNS_QUERY_AAAA:
if (rr.rdlength != sizeof(struct in6_addr))
return std::make_pair((unsigned char *) NULL, "rr.rdlength is larger than 16 bytes for an ipv6 entry -- malformed/hostile packet?");
memcpy(res,&header.payload[i],rr.rdlength);
res[rr.rdlength] = 0;
break;
case DNS_QUERY_A:
if (rr.rdlength != sizeof(struct in_addr))
return std::make_pair((unsigned char *) NULL, "rr.rdlength is larger than 4 bytes for an ipv4 entry -- malformed/hostile packet?");
memcpy(res,&header.payload[i],rr.rdlength);
res[rr.rdlength] = 0;
break;
default:
return std::make_pair((unsigned char *) NULL, "don't know how to handle undefined type (" + ConvToStr(rr.type) + ") -- rejecting");
break;
}
return std::make_pair(res,"No error");
}

static VALUE foreach(int argc, VALUE* argv, VALUE self) {
char *DELIM=DEF_DELIM;
char *line = NULL;
char *line2 =NULL, *new_line=NULL;
size_t len = 0, len2=0, i, pairs_count;
char *token,*start,*nobackslash,*t2;
size_t idx,count,searchfield,flag,array_length,range_i;
long check;
int  was_read;
FILE *file;
ID min_method, max_method;
VALUE min_val, max_val;
VALUE tmp_value, rest_args, filename;
ID    array_length_method; 
struct pair_st pairs[MAX_INTERVALS];
VALUE ary;
rb_scan_args(argc,argv,"1*", &filename, &rest_args);
file = fopen(StringValueCStr(filename), "r");
if(file==NULL){
rb_raise(rb_eRuntimeError, "File not found");
}
if (argc >1 ) { 
tmp_value=rb_ary_entry(rest_args,0);
DELIM=StringValueCStr(tmp_value);;
}
if (argc >2 ) { 
tmp_value=rb_ary_entry(rest_args,1);
searchfield=NUM2INT(tmp_value);
}
else{
searchfield=-1;
}
array_length_method=rb_funcall(rest_args,rb_intern("length"), 0);
array_length=NUM2INT(array_length_method);
min_method = rb_intern("first");
max_method = rb_intern("last");
range_i=0;
for(idx=2;idx<array_length;++idx){
min_val=rb_funcall(rb_ary_entry(rest_args,idx),rb_intern("length"), 0);
len2=NUM2INT(min_val);
for(i=0;i<len2;++i){
VALUE e=rb_ary_entry(rb_ary_entry(rest_args,idx),i);
if(range_i>MAX_INTERVALS)
rb_raise(rb_eRuntimeError, "Too much ranges passed");
if(TYPE(e) == T_NIL){
pairs[range_i].low=LONG_MIN;
pairs[range_i].high=LONG_MAX;
continue; 
}
if (! (rb_respond_to(e, min_method) & rb_respond_to(e, max_method)))
rb_raise(rb_eRuntimeError, "Not range passed to Ccsv.foreach");
min_val=rb_funcall(e, min_method, 0);
max_val=rb_funcall(e, max_method, 0);
pairs[range_i].low=NUM2LONG(min_val);
pairs[range_i].high=NUM2LONG(max_val);
range_i++;
}
}
pairs_count=range_i;
while ((was_read=getline(&line, &len, file)) != -1) {
if(was_read<1)
continue;
len=was_read-1;
for(;;) {
if(line[len]!=EOL)
break;
if(line[len]==CR){
len-=1;
}
count=0;
t2=line+len-1;
while((t2>=line) && (*t2=='\\'))
{++count;--t2;}
if(count%2 ==1){ 
line2=NULL;
len2=0;
if((was_read=getline(&line2, &len2, file)) != -1) {
len2=was_read;
if(new_line)
free(new_line);           new_line=malloc(len+len2+1);
strcpy(new_line,line);
new_line[len-1]='\n';
strcpy(new_line+len,line2);
line=new_line;
start=new_line;
len+=len2-1;
nobackslash=start;
free(line);
free(line2);
continue;
}
}
break;
}
if(line[len]==EOL){
if(line[len-1]==CR)
len-=1;
line[len]='\0';
}
if(len<2)
continue;
ary = rb_ary_new();
start=line;
nobackslash=line;
idx = 0;
flag=1;
while (nobackslash != NULL) {
while(token=strstr(nobackslash, DELIM)){
count=0;
t2=token-1;
while((t2>=line) && (*t2=='\\'))
{++count;--t2;}
if(count%2 ==1){ 
nobackslash=token;
continue;
}
break;
}
if(token)
*token='\0';
else
token=start+strlen(start);
if(searchfield==idx){
flag=0;
sscanf(start,"%ld",&check);
for(i=0;i<pairs_count;++i){
if(pairs[i].low<check && pairs[i].high>check){
flag=1; 
break;
}
}
}
if(flag==0)
break;
rb_ary_store(ary, idx, rb_str_new(start, token-start));
idx++;
nobackslash=start=token+strlen(DELIM);
while(token=strstr(nobackslash, DELIM)){
count=0;
t2=token-1;
while((t2>=line) && (*t2=='\\'))
{++count;--t2;}
if(count%2 ==1){ 
nobackslash=token+strlen(DELIM);
continue;
}
break;
}
nobackslash=token;
}
if(flag==0)
continue;
rb_ary_store(ary, idx, rb_str_new(start, strlen(start)));
rb_yield(ary);
}
fclose(file);
free(line);
return Qnil;
}

