char* parseTag( char* ptr, std::string& tag_name,
std::string& type_name, int& tag_type )
{
if( *ptr == '\0' )
CV_PARSE_ERROR_CPP( "Unexpected end of the stream" );
if( *ptr != '<' )
CV_PARSE_ERROR_CPP( "Tag should start with \'<\'" );
ptr++;
CV_PERSISTENCE_CHECK_END_OF_BUFFER_BUG_CPP();
if( cv_isalnum(*ptr) || *ptr == '_' )
tag_type = CV_XML_OPENING_TAG;
else if( *ptr == '/' )
{
tag_type = CV_XML_CLOSING_TAG;
ptr++;
}
else if( *ptr == '?' )
{
tag_type = CV_XML_HEADER_TAG;
ptr++;
}
else if( *ptr == '!' )
{
tag_type = CV_XML_DIRECTIVE_TAG;
assert( ptr[1] != '-' || ptr[2] != '-' );
ptr++;
}
else
CV_PARSE_ERROR_CPP( "Unknown tag type" );
tag_name.clear();
type_name.clear();
for(;;)
{
char c, *endptr;
if( !cv_isalpha(*ptr) && *ptr != '_' )
CV_PARSE_ERROR_CPP( "Name should start with a letter or underscore" );
endptr = ptr - 1;
do c = *++endptr;
while( cv_isalnum(c) || c == '_' || c == '-' );
std::string attrname(ptr, (size_t)(endptr - ptr));
ptr = endptr;
CV_PERSISTENCE_CHECK_END_OF_BUFFER_BUG_CPP();
if( tag_name.empty() )
tag_name = attrname;
else
{
if( tag_type == CV_XML_CLOSING_TAG )
CV_PARSE_ERROR_CPP( "Closing tag should not contain any attributes" );
if( *ptr != '=' )
{
ptr = skipSpaces( ptr, CV_XML_INSIDE_TAG );
if( *ptr != '=' )
CV_PARSE_ERROR_CPP( "Attribute name should be followed by \'=\'" );
}
c = *++ptr;
if( c != '\"' && c != '\'' )
{
ptr = skipSpaces( ptr, CV_XML_INSIDE_TAG );
if( *ptr != '\"' && *ptr != '\'' )
CV_PARSE_ERROR_CPP( "Attribute value should be put into single or double quotes" );
}
char quote = *ptr++;
endptr = ptr;
for(;;)
{
c = *endptr++;
if( c == quote )
break;
if( c == '\0' )
CV_PARSE_ERROR_CPP( "Unexpected end of line" );
}
if( attrname == "type_id" )
{
CV_Assert( type_name.empty() );
type_name = std::string(ptr, (size_t)(endptr - 1 - ptr));
}
ptr = endptr;
}
c = *ptr;
bool have_space = cv_isspace(c) || c == '\0';
if( c != '>' )
{
ptr = skipSpaces( ptr, CV_XML_INSIDE_TAG );
c = *ptr;
}
if( c == '>' )
{
if( tag_type == CV_XML_HEADER_TAG )
CV_PARSE_ERROR_CPP( "Invalid closing tag for <?xml ..." );
ptr++;
break;
}
else if( c == '?' && tag_type == CV_XML_HEADER_TAG )
{
if( ptr[1] != '>'  )                      CV_PARSE_ERROR_CPP( "Invalid closing tag for <?xml ..." );
ptr += 2;
break;
}
else if( c == '/' && ptr[1] == '>' && tag_type == CV_XML_OPENING_TAG )              {
tag_type = CV_XML_EMPTY_TAG;
ptr += 2;
break;
}
if( !have_space )
CV_PARSE_ERROR_CPP( "There should be space between attributes" );
}
return ptr;
}

hsm_com_errno_t
unix_client_connect(hsm_com_client_hdl_t *hdl)
{
intfd, len;
struct sockaddr_ununix_addr;
if ((fd = socket(AF_UNIX, SOCK_STREAM, 0)) < 0) 
{
return HSM_COM_ERROR;
}
memset(&unix_addr,0,sizeof(unix_addr));
unix_addr.sun_family = AF_UNIX;
if(strlen(hdl->c_path) >= sizeof(unix_addr.sun_path))
{
close(fd);
return HSM_COM_PATH_ERR;
}
snprintf(unix_addr.sun_path, sizeof(unix_addr.sun_path), "%s", hdl->c_path);
len = SUN_LEN(&unix_addr);
unlink(unix_addr.sun_path);
if(bind(fd, (struct sockaddr *)&unix_addr, len) < 0)
{
unlink(hdl->c_path);
close(fd);
return HSM_COM_BIND_ERR;
}
if(chmod(unix_addr.sun_path, S_IRWXU) < 0)
{
unlink(hdl->c_path);
close(fd);
return HSM_COM_CHMOD_ERR;
}
memset(&unix_addr,0,sizeof(unix_addr));
unix_addr.sun_family = AF_UNIX;
strncpy(unix_addr.sun_path, hdl->s_path, sizeof(unix_addr.sun_path));
unix_addr.sun_path[sizeof(unix_addr.sun_path)-1] = 0;
len = SUN_LEN(&unix_addr);
if (connect(fd, (struct sockaddr *) &unix_addr, len) < 0) 
{
unlink(hdl->c_path);
close(fd);
return HSM_COM_CONX_ERR;
}
hdl->client_fd = fd;
hdl->client_state = HSM_COM_C_STATE_CT;
if(unix_sck_send_conn(hdl, 2) != HSM_COM_OK)
{
hdl->client_state = HSM_COM_C_STATE_IN;
return HSM_COM_SEND_ERR;
}
return HSM_COM_OK;
}

