static int
computeOutputPixelOffsets (struct crop_mask *crop, struct image_data *image,
struct pagedef *page, struct pageseg *sections,
struct dump_opts* dump)
{
double scale;
double pwidth, plength;          
uint32_t iwidth, ilength;          
uint32_t owidth, olength;          
uint32_t orows, ocols;             
uint32_t hmargin, vmargin;         
uint32_t x1, x2, y1, y2, line_bytes;
uint32_t i, j, k;
scale = 1.0;
if (page->res_unit == RESUNIT_NONE)
page->res_unit = image->res_unit;
switch (image->res_unit) {
case RESUNIT_CENTIMETER:
if (page->res_unit == RESUNIT_INCH)
scale = 1.0/2.54;
break;
case RESUNIT_INCH:
if (page->res_unit == RESUNIT_CENTIMETER)
scale = 2.54;
break;
case RESUNIT_NONE: 
default:
break;
}
if (crop->combined_width > 0)
iwidth = crop->combined_width;
else
iwidth = image->width;
if (crop->combined_length > 0)
ilength = crop->combined_length;
else
ilength = image->length;
if (page->hres <= 1.0)
page->hres = image->xres;
if (page->vres <= 1.0)
page->vres = image->yres;
if ((page->hres < 1.0) || (page->vres < 1.0))
{
TIFFError("computeOutputPixelOffsets",
"Invalid horizontal or vertical resolution specified or read from input image");
return (1);
}
if (page->width <= 0)
pwidth = iwidth;
else
pwidth = page->width;
if (page->length <= 0)
plength = ilength;
else
plength = page->length;
if (dump->debug)
{
TIFFError("", "Page size: %s, Vres: %3.2f, Hres: %3.2f, "
"Hmargin: %3.2f, Vmargin: %3.2f",
page->name, page->vres, page->hres,
page->hmargin, page->vmargin);
TIFFError("", "Res_unit: %"PRIu16", Scale: %3.2f, Page width: %3.2f, length: %3.2f",
page->res_unit, scale, pwidth, plength);
}
if (page->mode & PAGE_MODE_MARGINS)
{
if (page->res_unit == RESUNIT_INCH || page->res_unit == RESUNIT_CENTIMETER)
{ 
hmargin = (uint32_t)(page->hmargin * scale * page->hres * ((image->bps + 7) / 8));
vmargin = (uint32_t)(page->vmargin * scale * page->vres * ((image->bps + 7) / 8));
}
else
{ 
hmargin = (uint32_t)(page->hmargin * scale * ((image->bps + 7) / 8));
vmargin = (uint32_t)(page->vmargin * scale * ((image->bps + 7) / 8));
}
if ((hmargin * 2.0) > (pwidth * page->hres))
{
TIFFError("computeOutputPixelOffsets", 
"Combined left and right margins exceed page width");
hmargin = (uint32_t) 0;
return (-1);
}
if ((vmargin * 2.0) > (plength * page->vres))
{
TIFFError("computeOutputPixelOffsets", 
"Combined top and bottom margins exceed page length"); 
vmargin = (uint32_t) 0;
return (-1);
}
}
else
{
hmargin = 0;
vmargin = 0;
}
if (page->mode & PAGE_MODE_ROWSCOLS )
{
if (page->mode & PAGE_MODE_MARGINS)
TIFFError("computeOutputPixelOffsets", 
"Output margins cannot be specified with rows and columns"); 
owidth  = TIFFhowmany(iwidth, page->cols);
olength = TIFFhowmany(ilength, page->rows);
}
else
{
if (page->mode & PAGE_MODE_PAPERSIZE )
{
owidth  = (uint32_t)((pwidth * page->hres) - (hmargin * 2));
olength = (uint32_t)((plength * page->vres) - (vmargin * 2));
}
else
{
owidth = (uint32_t)(iwidth - (hmargin * 2 * page->hres));
olength = (uint32_t)(ilength - (vmargin * 2 * page->vres));
}
}
if (owidth > iwidth)
owidth = iwidth;
if (olength > ilength)
olength = ilength;
switch (page->orient)
{
case ORIENTATION_NONE:
case ORIENTATION_PORTRAIT:
ocols = TIFFhowmany(iwidth, owidth);
orows = TIFFhowmany(ilength, olength);
break;
case ORIENTATION_LANDSCAPE:
ocols = TIFFhowmany(iwidth, olength);
orows = TIFFhowmany(ilength, owidth);
x1 = olength;
olength = owidth;
owidth = x1;
break;
case ORIENTATION_AUTO:
default:
x1 = TIFFhowmany(iwidth, owidth);
x2 = TIFFhowmany(ilength, olength); 
y1 = TIFFhowmany(iwidth, olength);
y2 = TIFFhowmany(ilength, owidth); 
if ( (x1 * x2) < (y1 * y2))
{ 
ocols = x1;
orows = x2;
}
else
{ 
ocols = y1;
orows = y2;
x1 = olength;
olength = owidth;
owidth = x1;
}
}
if (ocols < 1)
ocols = 1;
if (orows < 1)
orows = 1;
if ((page->rows > 0) && (page->rows != orows)) {
TIFFError("computeOutputPixelOffsets",
"Number of user input section rows down (%"PRIu32") was changed to (%"PRIu32")", page->rows, orows);
}
page->rows = orows;
if ((page->cols > 0) && (page->cols != ocols)) {
TIFFError("computeOutputPixelOffsets",
"Number of user input section cols across (%"PRIu32") was changed to (%"PRIu32")", page->cols, ocols);
}
page->cols = ocols;
line_bytes = TIFFhowmany8(owidth * image->spp * image->bps);
if ((orows * ocols) > MAX_SECTIONS)
{
TIFFError("computeOutputPixelOffsets",
"Rows and Columns exceed maximum sections\nIncrease resolution or reduce sections");
return (-1);
}
for (k = 0, i = 0; i < orows; i++)
{
y1 = (uint32_t)(olength * i);
y2 = (uint32_t)(olength * (i + 1) - 1);
if (y2 >= ilength)
y2 = ilength - 1;
for (j = 0; (j < ocols) && (k < MAX_SECTIONS); j++, k++)
{
x1 = (uint32_t)(owidth * j);
x2 = (uint32_t)(owidth * (j + 1) - 1);
if (x2 >= iwidth)
x2 = iwidth - 1;
sections[k].x1 = x1;
sections[k].x2 = x2;
sections[k].y1 = y1;
sections[k].y2 = y2;
sections[k].buffsize = line_bytes * olength;
sections[k].position = k + 1;
sections[k].total = orows * ocols;
} 
} 
return (0);
}

static bfd_boolean
get_unwind_section_word (struct arm_unw_aux_info *  aux,
struct arm_section *       arm_sec,
Elf_Internal_Shdr *        sec,
bfd_vma     word_offset,
unsigned int *             wordp,
struct absaddr *           addr,
bfd_vma *    sym_name)
{
Elf_Internal_Rela *rp;
Elf_Internal_Sym *sym;
const char * relname;
unsigned int word;
bfd_boolean wrapped;
if (sec == NULL || arm_sec == NULL)
return FALSE;
addr->section = SHN_UNDEF;
addr->offset = 0;
if (sym_name != NULL)
*sym_name = (bfd_vma) -1;
if (sec != arm_sec->sec)
{
Elf_Internal_Shdr *relsec;
arm_free_section (arm_sec);
arm_sec->sec = sec;
arm_sec->data = get_data (NULL, aux->file, sec->sh_offset, 1,
sec->sh_size, _("unwind data"));
arm_sec->rela = NULL;
arm_sec->nrelas = 0;
for (relsec = section_headers;
relsec < section_headers + elf_header.e_shnum;
++relsec)
{
if (relsec->sh_info >= elf_header.e_shnum
|| section_headers + relsec->sh_info != sec
|| (relsec->sh_type != SHT_REL
&& relsec->sh_type != SHT_RELA))
continue;
arm_sec->rel_type = relsec->sh_type;
if (relsec->sh_type == SHT_REL)
{
if (!slurp_rel_relocs (aux->file, relsec->sh_offset,
relsec->sh_size,
& arm_sec->rela, & arm_sec->nrelas))
return FALSE;
}
else 
{
if (!slurp_rela_relocs (aux->file, relsec->sh_offset,
relsec->sh_size,
& arm_sec->rela, & arm_sec->nrelas))
return FALSE;
}
break;
}
arm_sec->next_rela = arm_sec->rela;
}
if (arm_sec->data == NULL)
return FALSE;
if (word_offset > (sec->sh_size - 4)
|| (sec->sh_size < 5 && word_offset >= sec->sh_size)
|| ((bfd_signed_vma) word_offset) < 0)
return FALSE;
word = byte_get (arm_sec->data + word_offset, 4);
if (arm_sec->rela == NULL)
{
* wordp = word;
return TRUE;
}
wrapped = FALSE;
for (rp = arm_sec->next_rela; rp != arm_sec->rela + arm_sec->nrelas; rp++)
{
bfd_vma prelval, offset;
if (rp->r_offset > word_offset && !wrapped)
{
rp = arm_sec->rela;
wrapped = TRUE;
}
if (rp->r_offset > word_offset)
break;
if (rp->r_offset & 3)
{
warn (_("Skipping unexpected relocation at offset 0x%lx\n"),
(unsigned long) rp->r_offset);
continue;
}
if (rp->r_offset < word_offset)
continue;
if (aux->symtab == NULL)
continue;
if (arm_sec->rel_type == SHT_REL)
{
offset = word & 0x7fffffff;
if (offset & 0x40000000)
offset |= ~ (bfd_vma) 0x7fffffff;
}
else if (arm_sec->rel_type == SHT_RELA)
offset = rp->r_addend;
else
{
error (_("Unknown section relocation type %d encountered\n"),
arm_sec->rel_type);
break;
}
if (ELF32_R_SYM (rp->r_info) >= aux->nsyms)
{
error (_("Bad symbol index in unwind relocation (%lu > %lu)\n"),
(unsigned long) ELF32_R_SYM (rp->r_info), aux->nsyms);
break;
}
sym = aux->symtab + ELF32_R_SYM (rp->r_info);
offset += sym->st_value;
prelval = offset - (arm_sec->sec->sh_addr + rp->r_offset);
if (elf_header.e_machine == EM_ARM)
{
relname = elf_arm_reloc_type (ELF32_R_TYPE (rp->r_info));
if (relname == NULL)
{
warn (_("Skipping unknown ARM relocation type: %d\n"),
(int) ELF32_R_TYPE (rp->r_info));
continue;
}
if (streq (relname, "R_ARM_NONE"))
continue;
if (! streq (relname, "R_ARM_PREL31"))
{
warn (_("Skipping unexpected ARM relocation type %s\n"), relname);
continue;
}
}
else if (elf_header.e_machine == EM_TI_C6000)
{
relname = elf_tic6x_reloc_type (ELF32_R_TYPE (rp->r_info));
if (relname == NULL)
{
warn (_("Skipping unknown C6000 relocation type: %d\n"),
(int) ELF32_R_TYPE (rp->r_info));
continue;
}
if (streq (relname, "R_C6000_NONE"))
continue;
if (! streq (relname, "R_C6000_PREL31"))
{
warn (_("Skipping unexpected C6000 relocation type %s\n"), relname);
continue;
}
prelval >>= 1;
}
else
{
warn (_("Only TI and ARM unwinders are currently supported\n"));
break;
}
word = (word & ~ (bfd_vma) 0x7fffffff) | (prelval & 0x7fffffff);
addr->section = sym->st_shndx;
addr->offset = offset;
if (sym_name)
* sym_name = sym->st_name;
break;
}
*wordp = word;
arm_sec->next_rela = rp;
return TRUE;
}

void __split_huge_pmd(struct vm_area_struct *vma, pmd_t *pmd,
unsigned long address, bool freeze, struct page *page)
{
spinlock_t *ptl;
struct mmu_notifier_range range;
mmu_notifier_range_init(&range, MMU_NOTIFY_CLEAR, 0, vma, vma->vm_mm,
address & HPAGE_PMD_MASK,
(address & HPAGE_PMD_MASK) + HPAGE_PMD_SIZE);
mmu_notifier_invalidate_range_start(&range);
ptl = pmd_lock(vma->vm_mm, pmd);
VM_BUG_ON(freeze && !page);
if (page && page != pmd_page(*pmd))
goto out;
if (pmd_trans_huge(*pmd)) {
page = pmd_page(*pmd);
if (PageMlocked(page))
clear_page_mlock(page);
} else if (!(pmd_devmap(*pmd) || is_pmd_migration_entry(*pmd)))
goto out;
__split_huge_pmd_locked(vma, pmd, range.start, freeze);
out:
spin_unlock(ptl);
mmu_notifier_invalidate_range_only_end(&range);
}

MagickExport ssize_t WriteBlob(Image *image,const size_t length,
const void *data)
{
int
c;
register const unsigned char
*p;
ssize_t
count;
assert(image != (Image *) NULL);
assert(image->signature == MagickCoreSignature);
assert(data != (const void *) NULL);
assert(image->blob != (BlobInfo *) NULL);
assert(image->blob->type != UndefinedStream);
if (length == 0)
return(0);
count=0;
p=(const unsigned char *) data;
switch (image->blob->type)
{
case UndefinedStream:
break;
case StandardStream:
case FileStream:
case PipeStream:
{
switch (length)
{
default:
{
count=(ssize_t) fwrite((const char *) data,1,length,
image->blob->file_info.file);
break;
}
case 4:
{
c=putc((int) *p++,image->blob->file_info.file);
if (c == EOF)
break;
count++;
}
case 3:
{
c=putc((int) *p++,image->blob->file_info.file);
if (c == EOF)
break;
count++;
}
case 2:
{
c=putc((int) *p++,image->blob->file_info.file);
if (c == EOF)
break;
count++;
}
case 1:
{
c=putc((int) *p++,image->blob->file_info.file);
if (c == EOF)
break;
count++;
}
case 0:
break;
}
break;
}
case ZipStream:
{
#if defined(MAGICKCORE_ZLIB_DELEGATE)
switch (length)
{
default:
{
count=(ssize_t) gzwrite(image->blob->file_info.gzfile,(void *) data,
(unsigned int) length);
break;
}
case 4:
{
c=gzputc(image->blob->file_info.gzfile,(int) *p++);
if (c == EOF)
break;
count++;
}
case 3:
{
c=gzputc(image->blob->file_info.gzfile,(int) *p++);
if (c == EOF)
break;
count++;
}
case 2:
{
c=gzputc(image->blob->file_info.gzfile,(int) *p++);
if (c == EOF)
break;
count++;
}
case 1:
{
c=gzputc(image->blob->file_info.gzfile,(int) *p++);
if (c == EOF)
break;
count++;
}
case 0:
break;
}
#endif
break;
}
case BZipStream:
{
#if defined(MAGICKCORE_BZLIB_DELEGATE)
count=(ssize_t) BZ2_bzwrite(image->blob->file_info.bzfile,(void *) data,
(int) length);
#endif
break;
}
case FifoStream:
{
count=(ssize_t) image->blob->stream(image,data,length);
break;
}
case BlobStream:
{
register unsigned char
*q;
if ((image->blob->offset+(MagickOffsetType) length) >=
(MagickOffsetType) image->blob->extent)
{
if (image->blob->mapped != MagickFalse)
return(0);
image->blob->extent+=length+image->blob->quantum;
image->blob->quantum<<=1;
image->blob->data=(unsigned char *) ResizeQuantumMemory(
image->blob->data,image->blob->extent+1,sizeof(*image->blob->data));
(void) SyncBlob(image);
if (image->blob->data == (unsigned char *) NULL)
{
(void) DetachBlob(image->blob);
return(0);
}
}
q=image->blob->data+image->blob->offset;
(void) memcpy(q,p,length);
image->blob->offset+=length;
if (image->blob->offset >= (MagickOffsetType) image->blob->length)
image->blob->length=(size_t) image->blob->offset;
count=(ssize_t) length;
break;
}
case CustomStream:
{
count=image->blob->custom_stream->writer((const unsigned char *) data,
length,image->blob->custom_stream->data);
break;
}
}
return(count);
}

