static void LoadOpenCLDevices(MagickCLEnv clEnv)
{
cl_context_properties
properties[3];
cl_device_id
*devices;
cl_int
status;
cl_platform_id
*platforms;
cl_uint
i,
j,
next,
number_devices,
number_platforms;
size_t
length;
number_platforms=0;
if (openCL_library->clGetPlatformIDs(0,NULL,&number_platforms) != CL_SUCCESS)
return;
if (number_platforms == 0)
return;
platforms=(cl_platform_id *) AcquireMagickMemory(number_platforms*
sizeof(cl_platform_id));
if (platforms == (cl_platform_id *) NULL)
return;
if (openCL_library->clGetPlatformIDs(number_platforms,platforms,NULL) != CL_SUCCESS)
{
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
return;
}
for (i = 0; i < number_platforms; i++)
{
number_devices=GetOpenCLDeviceCount(clEnv,platforms[i]);
if (number_devices == 0)
platforms[i]=(cl_platform_id) NULL;
else
clEnv->number_devices+=number_devices;
}
if (clEnv->number_devices == 0)
{
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
return;
}
clEnv->devices=(MagickCLDevice *) AcquireQuantumMemory(clEnv->number_devices,
sizeof(MagickCLDevice));
if (clEnv->devices == (MagickCLDevice *) NULL)
{
RelinquishMagickCLDevices(clEnv);
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
return;
}
(void) ResetMagickMemory(clEnv->devices,0,clEnv->number_devices*
sizeof(MagickCLDevice));
devices=(cl_device_id *) AcquireQuantumMemory(clEnv->number_devices,
sizeof(cl_device_id));
if (devices == (cl_device_id *) NULL)
{
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
RelinquishMagickCLDevices(clEnv);
return;
}
clEnv->number_contexts=(size_t) number_platforms;
clEnv->contexts=(cl_context *) AcquireQuantumMemory(clEnv->number_contexts,
sizeof(cl_context));
if (clEnv->contexts == (cl_context *) NULL)
{
devices=(cl_device_id *) RelinquishMagickMemory(devices);
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
RelinquishMagickCLDevices(clEnv);
return;
}
next=0;
for (i = 0; i < number_platforms; i++)
{
if (platforms[i] == (cl_platform_id) NULL)
continue;
status=clEnv->library->clGetDeviceIDs(platforms[i],CL_DEVICE_TYPE_CPU | 
CL_DEVICE_TYPE_GPU,(cl_uint) clEnv->number_devices,devices,&number_devices);
if (status != CL_SUCCESS)
continue;
properties[0]=CL_CONTEXT_PLATFORM;
properties[1]=(cl_context_properties) platforms[i];
properties[2]=0;
clEnv->contexts[i]=openCL_library->clCreateContext(properties,number_devices,
devices,NULL,NULL,&status);
if (status != CL_SUCCESS)
continue;
for (j = 0; j < number_devices; j++,next++)
{
MagickCLDevice
device;
device=AcquireMagickCLDevice();
if (device == (MagickCLDevice) NULL)
break;
device->context=clEnv->contexts[i];
device->deviceID=devices[j];
openCL_library->clGetPlatformInfo(platforms[i],CL_PLATFORM_NAME,0,NULL,
&length);
device->platform_name=AcquireQuantumMemory(length,
sizeof(*device->platform_name));
openCL_library->clGetPlatformInfo(platforms[i],CL_PLATFORM_NAME,length,
device->platform_name,NULL);
openCL_library->clGetPlatformInfo(platforms[i],CL_PLATFORM_VENDOR,0,NULL,
&length);
device->vendor_name=AcquireQuantumMemory(length,
sizeof(*device->vendor_name));
openCL_library->clGetPlatformInfo(platforms[i],CL_PLATFORM_VENDOR,length,
device->vendor_name,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_NAME,0,NULL,
&length);
device->name=AcquireQuantumMemory(length,sizeof(*device->name));
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_NAME,length,
device->name,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DRIVER_VERSION,0,NULL,
&length);
device->version=AcquireQuantumMemory(length,sizeof(*device->version));
openCL_library->clGetDeviceInfo(devices[j],CL_DRIVER_VERSION,length,
device->version,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_MAX_CLOCK_FREQUENCY,
sizeof(cl_uint),&device->max_clock_frequency,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_MAX_COMPUTE_UNITS,
sizeof(cl_uint),&device->max_compute_units,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_TYPE,
sizeof(cl_device_type),&device->type,NULL);
openCL_library->clGetDeviceInfo(devices[j],CL_DEVICE_LOCAL_MEM_SIZE,
sizeof(cl_ulong),&device->local_memory_size,NULL);
clEnv->devices[next]=device;
}
}
if (next != clEnv->number_devices)
RelinquishMagickCLDevices(clEnv);
platforms=(cl_platform_id *) RelinquishMagickMemory(platforms);
devices=(cl_device_id *) RelinquishMagickMemory(devices);
}

GlyphCache::GlyphCache(const Face & face, const uint32 face_options)
: _glyph_loader(new Loader(face, bool(face_options & gr_face_dumbRendering))),
_glyphs(_glyph_loader && *_glyph_loader && _glyph_loader->num_glyphs()
? grzeroalloc<const GlyphFace *>(_glyph_loader->num_glyphs()) : 0),
_boxes(_glyph_loader && _glyph_loader->has_boxes() && _glyph_loader->num_glyphs()
? grzeroalloc<GlyphBox *>(_glyph_loader->num_glyphs()) : 0),
_num_glyphs(_glyphs ? _glyph_loader->num_glyphs() : 0),
_num_attrs(_glyphs ? _glyph_loader->num_attrs() : 0),
_upem(_glyphs ? _glyph_loader->units_per_em() : 0)
{
if ((face_options & gr_face_preloadGlyphs) && _glyph_loader && _glyphs)
{
int numsubs = 0;
GlyphFace * const glyphs = new GlyphFace [_num_glyphs];
if (!glyphs)
return;
_glyphs[0] = _glyph_loader->read_glyph(0, glyphs[0], &numsubs);
const GlyphFace * loaded = _glyphs[0];
for (uint16 gid = 1; loaded && gid != _num_glyphs; ++gid)
_glyphs[gid] = loaded = _glyph_loader->read_glyph(gid, glyphs[gid], &numsubs);
if (!loaded)
{
_glyphs[0] = 0;
delete [] glyphs;
}
else if (numsubs > 0 && _boxes)
{
GlyphBox * boxes = (GlyphBox *)gralloc<char>(_num_glyphs * sizeof(GlyphBox) + numsubs * 8 * sizeof(float));
GlyphBox * currbox = boxes;
for (uint16 gid = 0; currbox && gid != _num_glyphs; ++gid)
{
_boxes[gid] = currbox;
currbox = _glyph_loader->read_box(gid, currbox, *_glyphs[gid]);
}
if (!currbox)
{
free(boxes);
_boxes[0] = 0;
}
}
delete _glyph_loader;
_glyph_loader = 0;
}
if (_glyphs && glyph(0) == 0)
{
free(_glyphs);
_glyphs = 0;
if (_boxes)
{
free(_boxes);
_boxes = 0;
}
_num_glyphs = _num_attrs = _upem = 0;
}
}

int SEIUnit::isMVCSEI()
{
pic_struct = -1;
uint8_t* nalEnd = m_nalBuffer + m_nalBufferLen;
try
{
int rez = NALUnit::deserialize(m_nalBuffer, nalEnd);
if (rez != 0)
return NOT_ENOUGH_BUFFER;
uint8_t* curBuff = m_nalBuffer + 1;
while (curBuff < nalEnd - 1)
{
int payloadType = 0;
for (; *curBuff == 0xFF && curBuff < nalEnd; curBuff++) payloadType += 0xFF;
if (curBuff >= nalEnd)
return NOT_ENOUGH_BUFFER;
payloadType += *curBuff++;
if (curBuff >= nalEnd)
return NOT_ENOUGH_BUFFER;
int payloadSize = 0;
for (; *curBuff == 0xFF && curBuff < nalEnd; curBuff++) payloadSize += 0xFF;
if (curBuff >= nalEnd)
return NOT_ENOUGH_BUFFER;
payloadSize += *curBuff++;
if (curBuff >= nalEnd)
return NOT_ENOUGH_BUFFER;
if (payloadType == 37)
return 1;              curBuff += payloadSize;
}
}
catch (BitStreamException)
{
;
}
return 0;
}

static int
hwloc_linux_get_thread_cpubind(hwloc_topology_t topology, pthread_t tid, hwloc_bitmap_t hwloc_set, int flags __hwloc_attribute_unused)
{
int err;
if (topology->pid) {
errno = ENOSYS;
return -1;
}
if (!pthread_self) {
errno = ENOSYS;
return -1;
}
if (tid == pthread_self())
return hwloc_linux_get_tid_cpubind(topology, 0, hwloc_set);
if (!pthread_getaffinity_np) {
errno = ENOSYS;
return -1;
}
#if defined(HWLOC_HAVE_CPU_SET_S) && !defined(HWLOC_HAVE_OLD_SCHED_SETAFFINITY)
{
cpu_set_t *plinux_set;
unsigned cpu;
int last;
size_t setsize;
last = hwloc_bitmap_last(topology->levels[0][0]->complete_cpuset);
assert (last != -1);
setsize = CPU_ALLOC_SIZE(last+1);
plinux_set = CPU_ALLOC(last+1);
err = pthread_getaffinity_np(tid, setsize, plinux_set);
if (err) {
CPU_FREE(plinux_set);
errno = err;
return -1;
}
hwloc_bitmap_zero(hwloc_set);
for(cpu=0; cpu<=(unsigned) last; cpu++)
if (CPU_ISSET_S(cpu, setsize, plinux_set))
hwloc_bitmap_set(hwloc_set, cpu);
CPU_FREE(plinux_set);
}
#elif defined(HWLOC_HAVE_CPU_SET)
{
cpu_set_t linux_set;
unsigned cpu;
#ifdef HWLOC_HAVE_OLD_SCHED_SETAFFINITY
err = pthread_getaffinity_np(tid, &linux_set);
#else 
err = pthread_getaffinity_np(tid, sizeof(linux_set), &linux_set);
#endif 
if (err) {
errno = err;
return -1;
}
hwloc_bitmap_zero(hwloc_set);
for(cpu=0; cpu<CPU_SETSIZE; cpu++)
if (CPU_ISSET(cpu, &linux_set))
hwloc_bitmap_set(hwloc_set, cpu);
}
#else 
{
unsigned long mask;
#ifdef HWLOC_HAVE_OLD_SCHED_SETAFFINITY
err = pthread_getaffinity_np(tid, (void*) &mask);
#else 
err = pthread_getaffinity_np(tid, sizeof(mask), (void*) &mask);
#endif 
if (err) {
errno = err;
return -1;
}
hwloc_bitmap_from_ulong(hwloc_set, mask);
}
#endif 
return 0;
}

unsigned int
ip6t_do_table(struct sk_buff *skb,
const struct nf_hook_state *state,
struct xt_table *table)
{
unsigned int hook = state->hook;
static const char nulldevname[IFNAMSIZ] __attribute__((aligned(sizeof(long))));
unsigned int verdict = NF_DROP;
const char *indev, *outdev;
const void *table_base;
struct ip6t_entry *e, **jumpstack;
unsigned int stackidx, cpu;
const struct xt_table_info *private;
struct xt_action_param acpar;
unsigned int addend;
stackidx = 0;
indev = state->in ? state->in->name : nulldevname;
outdev = state->out ? state->out->name : nulldevname;
acpar.hotdrop = false;
acpar.state   = state;
WARN_ON(!(table->valid_hooks & (1 << hook)));
local_bh_disable();
addend = xt_write_recseq_begin();
private = READ_ONCE(table->private); 
cpu        = smp_processor_id();
table_base = private->entries;
jumpstack  = (struct ip6t_entry **)private->jumpstack[cpu];
if (static_key_false(&xt_tee_enabled))
jumpstack += private->stacksize * __this_cpu_read(nf_skb_duplicated);
e = get_entry(table_base, private->hook_entry[hook]);
do {
const struct xt_entry_target *t;
const struct xt_entry_match *ematch;
struct xt_counters *counter;
WARN_ON(!e);
acpar.thoff = 0;
if (!ip6_packet_match(skb, indev, outdev, &e->ipv6,
&acpar.thoff, &acpar.fragoff, &acpar.hotdrop)) {
no_match:
e = ip6t_next_entry(e);
continue;
}
xt_ematch_foreach(ematch, e) {
acpar.match     = ematch->u.kernel.match;
acpar.matchinfo = ematch->data;
if (!acpar.match->match(skb, &acpar))
goto no_match;
}
counter = xt_get_this_cpu_counter(&e->counters);
ADD_COUNTER(*counter, skb->len, 1);
t = ip6t_get_target_c(e);
WARN_ON(!t->u.kernel.target);
#if IS_ENABLED(CONFIG_NETFILTER_XT_TARGET_TRACE)
if (unlikely(skb->nf_trace))
trace_packet(state->net, skb, hook, state->in,
state->out, table->name, private, e);
#endif
if (!t->u.kernel.target->target) {
int v;
v = ((struct xt_standard_target *)t)->verdict;
if (v < 0) {
if (v != XT_RETURN) {
verdict = (unsigned int)(-v) - 1;
break;
}
if (stackidx == 0)
e = get_entry(table_base,
private->underflow[hook]);
else
e = ip6t_next_entry(jumpstack[--stackidx]);
continue;
}
if (table_base + v != ip6t_next_entry(e) &&
!(e->ipv6.flags & IP6T_F_GOTO)) {
jumpstack[stackidx++] = e;
}
e = get_entry(table_base, v);
continue;
}
acpar.target   = t->u.kernel.target;
acpar.targinfo = t->data;
verdict = t->u.kernel.target->target(skb, &acpar);
if (verdict == XT_CONTINUE)
e = ip6t_next_entry(e);
else
break;
} while (!acpar.hotdrop);
xt_write_recseq_end(addend);
local_bh_enable();
if (acpar.hotdrop)
return NF_DROP;
else return verdict;
}

static cairo_surface_t *
rsvg_filter_primitive_image_render_in (RsvgFilterPrimitive * self, RsvgFilterContext * context)
{
