SDL_Surface * SDL_LoadGIF(const char * file)
{
SDL_Surface * surface;
struct ngiflib_gif * gif;
FILE *fgif;
int err,i;
u8 * pdst, * psrc;
u8 * p = NULL;
#ifdef NGIFLIB_NO_FILE
u8 * buffer;
long filesize;
#endif 
fgif = fopen(file, "rb");
if(fgif==NULL)
return NULL;
gif = (struct ngiflib_gif *)ngiflib_malloc(sizeof(struct ngiflib_gif));
ngiflib_memset(gif, 0, sizeof(struct ngiflib_gif));
#ifdef NGIFLIB_NO_FILE
fseek(fgif, 0, SEEK_END);
filesize = ftell(fgif);
fseek(fgif, 0, SEEK_SET);
buffer = malloc(filesize);
if(buffer == NULL) {
GifDestroy(gif);
return NULL;
}
fread(buffer, 1, filesize, fgif);
gif->input.bytes = buffer;
gif->mode = NGIFLIB_MODE_FROM_MEM | NGIFLIB_MODE_INDEXED;
#else 
gif->input.file = fgif;
gif->mode = NGIFLIB_MODE_FROM_FILE | NGIFLIB_MODE_INDEXED;
#ifdef NGIFLIBSDL_LOG
gif->log = stdout;
#endif 
#endif 
err = LoadGif(gif);
fclose(fgif);
#ifdef NGIFLIB_NO_FILE
free(buffer);
#endif 
if(err!=1)
{
GifDestroy(gif);
return NULL;
}
p = gif->frbuff.p8;
surface = SDL_CreateRGBSurface(SDL_SWSURFACE | SDL_SRCCOLORKEY,
gif->width, gif->height, 8,
0,0,0,0);
SDL_LockSurface(surface);
if(gif->cur_img->gce.transparent_flag)
{
SDL_SetColorKey(surface, SDL_SRCCOLORKEY, gif->cur_img->gce.transparent_color);
}
for(i=0; i<gif->ncolors; i++)
{
surface->format->palette->colors[i].r = gif->palette[i].r;
surface->format->palette->colors[i].g = gif->palette[i].g;
surface->format->palette->colors[i].b = gif->palette[i].b;
}
psrc = p; pdst = surface->pixels;
for(i=0; i<gif->height; i++)
{
ngiflib_memcpy(pdst, psrc, gif->width);
pdst += surface->pitch;
psrc += gif->width;
}
SDL_UnlockSurface(surface);
GifDestroy(gif);
return surface;
}

int luaD_pretailcall (lua_State *L, CallInfo *ci, StkId func,
int narg1, int delta) {
retry:
switch (ttypetag(s2v(func))) {
case LUA_VCCL:  
return precallC(L, func, LUA_MULTRET, clCvalue(s2v(func))->f);
case LUA_VLCF:  
return precallC(L, func, LUA_MULTRET, fvalue(s2v(func)));
case LUA_VLCL: {  
Proto *p = clLvalue(s2v(func))->p;
int fsize = p->maxstacksize;  
int nfixparams = p->numparams;
int i;
ci->func -= delta;  
for (i = 0; i < narg1; i++)  
setobjs2s(L, ci->func + i, func + i);
checkstackGC(L, fsize);
func = ci->func;  
for (; narg1 <= nfixparams; narg1++)
setnilvalue(s2v(func + narg1));  
ci->top = func + 1 + fsize;  
lua_assert(ci->top <= L->stack_last);
ci->u.l.savedpc = p->code;  
ci->callstatus |= CIST_TAIL;
L->top = func + narg1;  
return -1;
}
default: {  
func = luaD_tryfuncTM(L, func);  
narg1++;
goto retry;  
}
}
}

int
parse_mpls(const u_char *pktdata, uint32_t datalen, uint16_t *next_protocol, uint32_t *l2len, uint32_t *l2offset)
{
struct tcpr_mpls_label *mpls_label;
const u_char *end_ptr = pktdata + datalen;
u_char first_nibble;
eth_hdr_t *eth_hdr;
bool bos = false;
uint32_t label;
int len;
assert(next_protocol);
assert(l2len);
assert(l2offset);
len = (int)*l2len;
while (!bos) {
if (pktdata + len + sizeof(*mpls_label) > end_ptr)
return -1;
mpls_label = (struct tcpr_mpls_label *)(pktdata + len);
len += sizeof(*mpls_label);
bos = (ntohl(mpls_label->entry) & MPLS_LS_S_MASK) != 0;
label = ntohl(mpls_label->entry) >> MPLS_LS_LABEL_SHIFT;
if (label == MPLS_LABEL_GACH) {
warn("GACH MPLS label not supported at this time");
return -1;
}
}
if ((u_char *)mpls_label + 1 > end_ptr)
return -1;
first_nibble = *((u_char *)(mpls_label + 1)) >> 4;
switch (first_nibble) {
case 4:
*next_protocol = ETHERTYPE_IP;
break;
case 6:
*next_protocol = ETHERTYPE_IP6;
break;
case 0:
if (pktdata + len + 4 + sizeof(*eth_hdr) > end_ptr)
return -1;
len += 4;
*l2offset = len;
eth_hdr = (eth_hdr_t *)(pktdata + len);
len += sizeof(*eth_hdr);
*next_protocol = ntohs(eth_hdr->ether_type);
break;
default:
return -1;
}
*l2len = (uint32_t)len;
return 0;
}

static int
xps_true_callback_glyph_name(gs_font *pfont, gs_glyph glyph, gs_const_string *pstr)
{
int table_length;
int table_offset;
ulong format;
uint numGlyphs;
uint glyph_name_index;
const byte *postp; 
if ( pfont->FontType != ft_TrueType )
{
glyph -= 29;
if (glyph < 258 )
{
pstr->data = (byte*) pl_mac_names[glyph];
pstr->size = strlen((char*)pstr->data);
return 0;
}
else
{
return gs_throw1(-1, "glyph index %lu out of range", (ulong)glyph);
}
}
table_offset = xps_find_sfnt_table((xps_font_t*)pfont->client_data, "post", &table_length);
if (table_offset < 0)
return gs_throw(-1, "no post table");
if ( table_length == 0 )
return gs_throw(-1, "zero-size post table");
((gs_font_type42 *)pfont)->data.string_proc((gs_font_type42 *)pfont,
table_offset, table_length, &postp);
format = u32(postp);
if ( format != 0x20000 )
{
char buf[32];
gs_sprintf(buf, "glyph%d", (int)glyph);
pstr->data = (byte*)buf;
pstr->size = strlen((char*)pstr->data);
return 0;
}
numGlyphs = u16(postp + 32);
if (glyph > numGlyphs - 1)
{
return gs_throw1(-1, "glyph index %lu out of range", (ulong)glyph);
}
glyph_name_index = u16(postp + 34 + (glyph * 2));
if ( glyph_name_index > 0x7fff )
return gs_throw(-1, "post table format error");
if ( glyph_name_index < 258 )
{
pstr->data = (byte*) pl_mac_names[glyph_name_index];
pstr->size = strlen((char*)pstr->data);
return 0;
}
else
{
byte *mydata;
const byte *pascal_stringp = postp + 34 + (numGlyphs * 2);
glyph_name_index -= 258;
while (glyph_name_index > 0)
{
pascal_stringp += ((int)(*pascal_stringp)+1);
glyph_name_index--;
}
pstr->size = (int)(*pascal_stringp);
pstr->data = pascal_stringp + 1;
if ( pstr->data + pstr->size > postp + table_length || pstr->data - 1 < postp)
return gs_throw(-1, "data out of range");
mydata = gs_alloc_bytes(pfont->memory, pstr->size + 1, "glyph to name");
if ( mydata == 0 )
return -1;
memcpy(mydata, pascal_stringp + 1, pstr->size);
pstr->data = mydata;
mydata[pstr->size] = 0;
return 0;
}
}

int ntfs_trim_fs(struct ntfs_sb_info *sbi, struct fstrim_range *range)
{
int err = 0;
struct super_block *sb = sbi->sb;
struct wnd_bitmap *wnd = &sbi->used.bitmap;
u32 wbits = 8 * sb->s_blocksize;
CLST len = 0, lcn = 0, done = 0;
CLST minlen = bytes_to_cluster(sbi, range->minlen);
CLST lcn_from = bytes_to_cluster(sbi, range->start);
size_t iw = lcn_from >> (sb->s_blocksize_bits + 3);
u32 wbit = lcn_from & (wbits - 1);
const ulong *buf;
CLST lcn_to;
if (!minlen)
minlen = 1;
if (range->len == (u64)-1)
lcn_to = wnd->nbits;
else
lcn_to = bytes_to_cluster(sbi, range->start + range->len);
down_read_nested(&wnd->rw_lock, BITMAP_MUTEX_CLUSTERS);
for (; iw < wnd->nbits; iw++, wbit = 0) {
CLST lcn_wnd = iw * wbits;
struct buffer_head *bh;
if (lcn_wnd > lcn_to)
break;
if (!wnd->free_bits[iw])
continue;
if (iw + 1 == wnd->nwnd)
wbits = wnd->bits_last;
if (lcn_wnd + wbits > lcn_to)
wbits = lcn_to - lcn_wnd;
bh = wnd_map(wnd, iw);
if (IS_ERR(bh)) {
err = PTR_ERR(bh);
break;
}
buf = (ulong *)bh->b_data;
for (; wbit < wbits; wbit++) {
if (!test_bit(wbit, buf)) {
if (!len)
lcn = lcn_wnd + wbit;
len += 1;
continue;
}
if (len >= minlen) {
err = ntfs_discard(sbi, lcn, len);
if (err)
goto out;
done += len;
}
len = 0;
}
put_bh(bh);
}
if (len >= minlen) {
err = ntfs_discard(sbi, lcn, len);
if (err)
goto out;
done += len;
}
out:
range->len = (u64)done << sbi->cluster_bits;
up_read(&wnd->rw_lock);
return err;
}

static void zend_throw_or_error(int fetch_type, zend_class_entry *exception_ce, const char *format, ...) 
{
va_list va;
char *message = NULL;
va_start(va, format);
zend_vspprintf(&message, 0, format, va);
if (fetch_type & ZEND_FETCH_CLASS_EXCEPTION) {
zend_throw_error(exception_ce, message);
} else {
zend_error(E_ERROR, "%s", message);
}
efree(message);
va_end(va);
}

int
ethertype_print(netdissect_options *ndo,
u_short ether_type, const u_char *p,
u_int length, u_int caplen,
const struct lladdr_info *src, const struct lladdr_info *dst)
{
switch (ether_type) {
case ETHERTYPE_IP:
ip_print(ndo, p, length);
return (1);
case ETHERTYPE_IPV6:
ip6_print(ndo, p, length);
return (1);
case ETHERTYPE_ARP:
case ETHERTYPE_REVARP:
arp_print(ndo, p, length, caplen);
return (1);
case ETHERTYPE_DN:
decnet_print(ndo, p, length, caplen);
return (1);
case ETHERTYPE_ATALK:
if (ndo->ndo_vflag)
ND_PRINT((ndo, "et1 "));
atalk_print(ndo, p, length);
return (1);
case ETHERTYPE_AARP:
aarp_print(ndo, p, length);
return (1);
case ETHERTYPE_IPX:
ND_PRINT((ndo, "(NOV-ETHII) "));
ipx_print(ndo, p, length);
return (1);
case ETHERTYPE_ISO:
if (length == 0 || caplen == 0) {
ND_PRINT((ndo, " [|osi]"));
return (1);
}
isoclns_print(ndo, p + 1, length - 1, caplen - 1);
return(1);
case ETHERTYPE_PPPOED:
case ETHERTYPE_PPPOES:
case ETHERTYPE_PPPOED2:
case ETHERTYPE_PPPOES2:
pppoe_print(ndo, p, length);
return (1);
case ETHERTYPE_EAPOL:
eap_print(ndo, p, length);
return (1);
case ETHERTYPE_RRCP:
rrcp_print(ndo, p, length, src, dst);
return (1);
case ETHERTYPE_PPP:
if (length) {
ND_PRINT((ndo, ": "));
ppp_print(ndo, p, length);
}
return (1);
case ETHERTYPE_MPCP:
mpcp_print(ndo, p, length);
return (1);
case ETHERTYPE_SLOW:
slow_print(ndo, p, length);
return (1);
case ETHERTYPE_CFM:
case ETHERTYPE_CFM_OLD:
cfm_print(ndo, p, length);
