case WASM_OP_F32X4REPLACELANE:
case WASM_OP_F64X2EXTRACTLANE:
case WASM_OP_F64X2REPLACELANE:
{
if (buf_len < 3) {
goto err;
}
unsigned char lane = buf[1 + simdop_size];
++op->len;
if (txt) {
op->txt = r_str_newf ("%s %d", opdef->txt, lane);
}
}
break;
}
} else {
goto err;
}
return op->len;
err:
op->len = 1;
if (txt) {
op->txt = strdup ("invalid");
}
return op->len;
}

GF_EXPORT
GF_Err gf_isom_get_user_data(GF_ISOFile *movie, u32 trackNumber, u32 UserDataType, bin128 UUID, u32 UserDataIndex, u8 **userData, u32 *userDataSize)
{
GF_UserDataMap *map;
GF_UnknownBox *ptr;
GF_BitStream *bs;
u32 i;
bin128 t;
GF_TrackBox *trak;
GF_UserDataBox *udta;
if (!movie || !movie->moov) return GF_BAD_PARAM;
if (trackNumber) {
trak = gf_isom_get_track_from_file(movie, trackNumber);
if (!trak) return GF_BAD_PARAM;
udta = trak->udta;
} else {
if (!movie->moov) return GF_BAD_PARAM;
udta = movie->moov->udta;
}
if (!udta) return GF_BAD_PARAM;
if (UserDataType == GF_ISOM_BOX_TYPE_UUID) UserDataType = 0;
memset(t, 1, 16);
if (!userData || !userDataSize || *userData) return GF_BAD_PARAM;
i=0;
while ((map = (GF_UserDataMap*)gf_list_enum(udta->recordList, &i))) {
if ((map->boxType == GF_ISOM_BOX_TYPE_UUID) && !memcmp(map->uuid, UUID, 16)) goto found;
else if (map->boxType == UserDataType) goto found;
}
return GF_BAD_PARAM;
found:
if (UserDataIndex) {
if (UserDataIndex > gf_list_count(map->boxes) ) return GF_BAD_PARAM;
ptr = (GF_UnknownBox*)gf_list_get(map->boxes, UserDataIndex-1);
if (ptr->type == GF_ISOM_BOX_TYPE_UNKNOWN) {
if (!ptr->dataSize) {
*userData = NULL;
*userDataSize = 0;
return GF_OK;
}
*userData = (char *)gf_malloc(sizeof(char)*ptr->dataSize);
if (!*userData) return GF_OUT_OF_MEM;
memcpy(*userData, ptr->data, sizeof(char)*ptr->dataSize);
*userDataSize = ptr->dataSize;
return GF_OK;
} else if (ptr->type == GF_ISOM_BOX_TYPE_UUID) {
GF_UnknownUUIDBox *p_uuid = (GF_UnknownUUIDBox *)ptr;
if (!p_uuid->dataSize) {
*userData = NULL;
*userDataSize = 0;
return GF_OK;
}
*userData = (char *)gf_malloc(sizeof(char)*p_uuid->dataSize);
if (!*userData) return GF_OUT_OF_MEM;
memcpy(*userData, p_uuid->data, sizeof(char)*p_uuid->dataSize);
*userDataSize = p_uuid->dataSize;
return GF_OK;
} else {
char *str = NULL;
switch (ptr->type) {
case GF_ISOM_BOX_TYPE_NAME:
str = ((GF_NameBox *)ptr)->string;
break;
case GF_ISOM_BOX_TYPE_KIND:
str = ((GF_KindBox *)ptr)->value;
break;
}
if (str) {
u32 len = (u32) strlen(str) + 1;
*userData = (char *)gf_malloc(sizeof(char) * len);
if (!*userData) return GF_OUT_OF_MEM;
memcpy(*userData, str, sizeof(char)*len);
*userDataSize = len;
return GF_OK;
}
return GF_NOT_SUPPORTED;
}
}
bs = gf_bs_new(NULL, 0, GF_BITSTREAM_WRITE);
i=0;
while ( (ptr = (GF_UnknownBox*)gf_list_enum(map->boxes, &i))) {
u32 type, s, data_size;
char *data=NULL;
if (ptr->type == GF_ISOM_BOX_TYPE_UNKNOWN) {
type = ptr->original_4cc;
data_size = ptr->dataSize;
data = ptr->data;
} else if (ptr->type == GF_ISOM_BOX_TYPE_UUID) {
GF_UnknownUUIDBox *p_uuid = (GF_UnknownUUIDBox *)ptr;
type = p_uuid->type;
data_size = p_uuid->dataSize;
data = p_uuid->data;
} else {
#ifndef GPAC_DISABLE_ISOM_WRITE
gf_isom_box_write((GF_Box *)ptr, bs);
#else
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("ISOBMF: udta is a box-list - cannot export in read-only version of libisom in GPAC\n" ));
#endif
continue;
}
s = data_size+8;
if (ptr->type==GF_ISOM_BOX_TYPE_UUID) s += 16;
gf_bs_write_u32(bs, s);
gf_bs_write_u32(bs, type);
if (type==GF_ISOM_BOX_TYPE_UUID) gf_bs_write_data(bs, (char *) map->uuid, 16);
if (data) {
gf_bs_write_data(bs, data, data_size);
} else if (ptr->child_boxes) {
#ifndef GPAC_DISABLE_ISOM_WRITE
gf_isom_box_array_write((GF_Box *)ptr, ptr->child_boxes, bs);
#else
GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("ISOBMF: udta is a box-list - cannot export in read-only version of libisom in GPAC\n" ));
#endif
}
}
gf_bs_get_content(bs, userData, userDataSize);
gf_bs_del(bs);
return GF_OK;
}

static int wolfSSH_SFTP_DoStatus(WOLFSSH* ssh, word32 reqId,
WS_SFTP_BUFFER* buffer)
{
word32 sz;
word32 status = WOLFSSH_FTP_FAILURE;
word32 localIdx = wolfSSH_SFTP_buffer_idx(buffer);
word32 maxIdx = wolfSSH_SFTP_buffer_size(buffer);
byte* buf = wolfSSH_SFTP_buffer_data(buffer);
(void)reqId;
if (localIdx + UINT32_SZ > maxIdx) {
return WS_FATAL_ERROR;
}
ato32(buf + localIdx, &status);
localIdx += UINT32_SZ;
if (localIdx + UINT32_SZ > maxIdx) {
return WS_FATAL_ERROR;
}
ato32(buf + localIdx, &sz);
localIdx += UINT32_SZ;
if (sz > 0) {
byte* s;
if (localIdx + sz > maxIdx) {
return WS_FATAL_ERROR;
}
s = (byte*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (s == NULL) {
return WS_MEMORY_E;
}
WMEMCPY(s, buf + localIdx, sz);
s[sz] = '\0';
WLOG(WS_LOG_SFTP, "Status Recv : %s", s);
WFREE(s, ssh->ctx->heap, DYNTYPE_BUFFER);
localIdx += sz;
}
if (localIdx + UINT32_SZ > maxIdx) {
return WS_FATAL_ERROR;
}
ato32(buf + localIdx, &sz);
localIdx += UINT32_SZ;
if (sz > 0) {
byte* s;
if (localIdx + sz > maxIdx) {
return WS_FATAL_ERROR;
}
s = (byte*)WMALLOC(sz + 1, ssh->ctx->heap, DYNTYPE_BUFFER);
if (s == NULL) {
return WS_MEMORY_E;
}
WMEMCPY(s, buf + localIdx, sz);
s[sz] = '\0';
WLOG(WS_LOG_SFTP, "Status Language : %s", s);
WFREE(s, ssh->ctx->heap, DYNTYPE_BUFFER);
localIdx += sz;
}
wolfSSH_SFTP_buffer_seek(buffer, 0, localIdx);
return status;
}

static int uapi_finalize(struct uverbs_api *uapi)
{
const struct uverbs_api_write_method **data;
unsigned long max_write_ex = 0;
unsigned long max_write = 0;
struct radix_tree_iter iter;
void __rcu **slot;
int rc;
int i;
radix_tree_for_each_slot (slot, &uapi->radix, &iter, 0) {
struct uverbs_api_ioctl_method *method_elm =
rcu_dereference_protected(*slot, true);
if (uapi_key_is_ioctl_method(iter.index)) {
rc = uapi_finalize_ioctl_method(uapi, method_elm,
iter.index);
if (rc)
return rc;
}
if (uapi_key_is_write_method(iter.index))
max_write = max(max_write,
iter.index & UVERBS_API_ATTR_KEY_MASK);
if (uapi_key_is_write_ex_method(iter.index))
max_write_ex =
max(max_write_ex,
iter.index & UVERBS_API_ATTR_KEY_MASK);
}
uapi->notsupp_method.handler = ib_uverbs_notsupp;
uapi->num_write = max_write + 1;
uapi->num_write_ex = max_write_ex + 1;
data = kmalloc_array(uapi->num_write + uapi->num_write_ex,
sizeof(*uapi->write_methods), GFP_KERNEL);
for (i = 0; i != uapi->num_write + uapi->num_write_ex; i++)
data[i] = &uapi->notsupp_method;
uapi->write_methods = data;
uapi->write_ex_methods = data + uapi->num_write;
radix_tree_for_each_slot (slot, &uapi->radix, &iter, 0) {
if (uapi_key_is_write_method(iter.index))
uapi->write_methods[iter.index &
UVERBS_API_ATTR_KEY_MASK] =
rcu_dereference_protected(*slot, true);
if (uapi_key_is_write_ex_method(iter.index))
uapi->write_ex_methods[iter.index &
UVERBS_API_ATTR_KEY_MASK] =
rcu_dereference_protected(*slot, true);
}
return 0;
}

int readSBits(FILE *f, int number)
{
int num = readBits(f, number);
if(num & (1<<(number-1)))
return num - (1<<number);
else
return num;
}

