int saa7164_bus_get(struct saa7164_dev *dev, struct tmComResInfo* msg,
void *buf, int peekonly)
{
struct tmComResBusInfo *bus = &dev->bus;
u32 bytes_to_read, write_distance, curr_grp, curr_gwp,
new_grp, buf_size, space_rem;
struct tmComResInfo msg_tmp;
int ret = SAA_ERR_BAD_PARAMETER;
saa7164_bus_verify(dev);
if (msg == NULL)
return ret;
if (msg->size > dev->bus.m_wMaxReqSize) {
printk(KERN_ERR "%s() Exceeded dev->bus.m_wMaxReqSize\n",
__func__);
return ret;
}
if ((peekonly == 0) && (msg->size > 0) && (buf == NULL)) {
printk(KERN_ERR
"%s() Missing msg buf, size should be %d bytes\n",
__func__, msg->size);
return ret;
}
mutex_lock(&bus->lock);
curr_gwp = saa7164_readl(bus->m_dwGetWritePos);
curr_grp = saa7164_readl(bus->m_dwGetReadPos);
if (curr_gwp == curr_grp) {
ret = SAA_ERR_EMPTY;
goto out;
}
bytes_to_read = sizeof(*msg);
write_distance = 0;
if (curr_gwp >= curr_grp)
write_distance = curr_gwp - curr_grp;
else
write_distance = curr_gwp + bus->m_dwSizeGetRing - curr_grp;
if (bytes_to_read > write_distance) {
printk(KERN_ERR "%s() No message/response found\n", __func__);
ret = SAA_ERR_INVALID_COMMAND;
goto out;
}
new_grp = curr_grp + bytes_to_read;
if (new_grp > bus->m_dwSizeGetRing) {
new_grp -= bus->m_dwSizeGetRing;
space_rem = bus->m_dwSizeGetRing - curr_grp;
memcpy_fromio(&msg_tmp, bus->m_pdwGetRing + curr_grp, space_rem);
memcpy_fromio((u8 *)&msg_tmp + space_rem, bus->m_pdwGetRing,
bytes_to_read - space_rem);
} else {
memcpy_fromio(&msg_tmp, bus->m_pdwGetRing + curr_grp, bytes_to_read);
}
msg_tmp.size = le16_to_cpu((__force __le16)msg_tmp.size);
msg_tmp.command = le32_to_cpu((__force __le32)msg_tmp.command);
msg_tmp.controlselector = le16_to_cpu((__force __le16)msg_tmp.controlselector);
if (peekonly) {
memcpy(msg, &msg_tmp, sizeof(*msg));
goto peekout;
}
if ((msg_tmp.id != msg->id) || (msg_tmp.command != msg->command) ||
(msg_tmp.controlselector != msg->controlselector) ||
(msg_tmp.seqno != msg->seqno) || (msg_tmp.size != msg->size)) {
printk(KERN_ERR "%s() Unexpected msg miss-match\n", __func__);
saa7164_bus_dumpmsg(dev, msg, buf);
saa7164_bus_dumpmsg(dev, &msg_tmp, NULL);
ret = SAA_ERR_INVALID_COMMAND;
goto out;
}
buf_size = msg->size;
bytes_to_read = sizeof(*msg) + msg->size;
write_distance = 0;
if (curr_gwp >= curr_grp)
write_distance = curr_gwp - curr_grp;
else
write_distance = curr_gwp + bus->m_dwSizeGetRing - curr_grp;
if (bytes_to_read > write_distance) {
printk(KERN_ERR "%s() Invalid bus state, missing msg or mangled ring, faulty H/W / bad code?\n",
__func__);
ret = SAA_ERR_INVALID_COMMAND;
goto out;
}
new_grp = curr_grp + bytes_to_read;
if (new_grp > bus->m_dwSizeGetRing) {
new_grp -= bus->m_dwSizeGetRing;
space_rem = bus->m_dwSizeGetRing - curr_grp;
if (space_rem < sizeof(*msg)) {
memcpy_fromio(msg, bus->m_pdwGetRing + curr_grp, space_rem);
memcpy_fromio((u8 *)msg + space_rem, bus->m_pdwGetRing,
sizeof(*msg) - space_rem);
if (buf)
memcpy_fromio(buf, bus->m_pdwGetRing + sizeof(*msg) -
space_rem, buf_size);
} else if (space_rem == sizeof(*msg)) {
memcpy_fromio(msg, bus->m_pdwGetRing + curr_grp, sizeof(*msg));
if (buf)
memcpy_fromio(buf, bus->m_pdwGetRing, buf_size);
} else {
memcpy_fromio(msg, bus->m_pdwGetRing + curr_grp, sizeof(*msg));
if (buf) {
memcpy_fromio(buf, bus->m_pdwGetRing + curr_grp +
sizeof(*msg), space_rem - sizeof(*msg));
memcpy_fromio(buf + space_rem - sizeof(*msg),
bus->m_pdwGetRing, bytes_to_read -
space_rem);
}
}
} else {
memcpy_fromio(msg, bus->m_pdwGetRing + curr_grp, sizeof(*msg));
if (buf)
memcpy_fromio(buf, bus->m_pdwGetRing + curr_grp + sizeof(*msg),
buf_size);
}
msg->size = le16_to_cpu((__force __le16)msg->size);
msg->command = le32_to_cpu((__force __le32)msg->command);
msg->controlselector = le16_to_cpu((__force __le16)msg->controlselector);
saa7164_writel(bus->m_dwGetReadPos, new_grp);
peekout:
ret = SAA_OK;
out:
mutex_unlock(&bus->lock);
saa7164_bus_verify(dev);
return ret;
}

int
XSetFontPath (
register Display *dpy,
char **directories,
int ndirs)
{
register int n = 0;
register int i;
register int nbytes;
char *p;
register xSetFontPathReq *req;
int retCode;
LockDisplay(dpy);
GetReq (SetFontPath, req);
req->nFonts = ndirs;
for (i = 0; i < ndirs; i++) {
n = (int) ((size_t) n + (safestrlen (directories[i]) + 1));
}
nbytes = (n + 3) & ~3;
req->length += nbytes >> 2;
if ((p = Xmalloc (nbytes))) {
char*tmp = p;
for (i = 0; i < ndirs; i++) {
register int length = (int) safestrlen (directories[i]);
*p = length;
memcpy (p + 1, directories[i], (size_t)length);
p += length + 1;
}
Data (dpy, tmp, nbytes);
Xfree (tmp);
retCode = 1;
}
else
retCode = 0;
UnlockDisplay(dpy);
SyncHandle();
return (retCode);
}

static int mqtt_read_message_chunk(struct mqtt_client *client,
struct buf_ctx *buf, u32_t length)
{
int remaining;
int len;
remaining = length - (buf->end - buf->cur);
if (remaining <= 0) {
return 0;
}
if (buf->end + remaining > client->rx_buf + client->rx_buf_size) {
MQTT_ERR("[CID %p]: Buffer too small to receive the message",
client);
return -ENOMEM;
}
len = mqtt_transport_read(client, buf->end, remaining, false);
if (len < 0) {
MQTT_TRC("[CID %p]: Transport read error: %d", client, len);
return len;
}
if (len == 0) {
MQTT_TRC("[CID %p]: Connection closed.", client);
return -ENOTCONN;
}
client->internal.rx_buf_datalen += len;
buf->end += len;
if (len < remaining) {
MQTT_TRC("[CID %p]: Message partially received.", client);
return -EAGAIN;
}
return 0;
}

Status GetTensorArray(OpKernelContext* ctx, TensorArray** tensor_array) {
string container;
string ta_handle;
if (ctx->input_dtype(0) != DT_RESOURCE) {
TF_RETURN_IF_ERROR(GetHandle(ctx, &container, &ta_handle));
ResourceMgr* rm = ctx->resource_manager();
if (rm == nullptr) return errors::Internal("No resource manager.");
TF_RETURN_IF_ERROR(
ctx->step_container()->Lookup(rm, container + ta_handle, tensor_array));
return OkStatus();
} else {
return LookupResource(ctx, HandleFromInput(ctx, 0), tensor_array);
}
}

u32 gf_m2ts_stream_process_pmt(GF_M2TS_Mux *muxer, GF_M2TS_Mux_Stream *stream)
{
if (stream->table_needs_update) { 
GF_M2TS_Mux_Stream *es;
u8 *payload;
u32 i;
u32 length, nb_streams=0;
u32 info_length = 0, es_info_length = 0;
GF_BitStream *bs;
bs = gf_bs_new(NULL,0,GF_BITSTREAM_WRITE);
gf_bs_write_int(bs,0x7, 3); gf_bs_write_int(bs,stream->program->pcr->pid, 13);
gf_bs_write_int(bs,0xF, 4); 
if (stream->program->loop_descriptors) {
for (i=0; i<gf_list_count(stream->program->loop_descriptors); i++) {
GF_M2TSDescriptor *desc = (GF_M2TSDescriptor*)gf_list_get(stream->program->loop_descriptors, i);
info_length += 2 + desc->data_len;
}
}
if (!stream->program->iod) {
gf_bs_write_int(bs,info_length, 12); } else {
u32 len, i;
GF_ESD *esd;
GF_BitStream *bs_iod;
char *iod_data;
u32 iod_data_len;
i=0;
while (NULL != (esd = (GF_ESD*)gf_list_enum(((GF_ObjectDescriptor*)stream->program->iod)->ESDescriptors, &i))) {
GF_M2TS_Mux_Stream *es_stream = stream->program->streams;
while (es_stream) {
if (es_stream->ifce && (es_stream->ifce->stream_id==esd->ESID)) {
memcpy(esd->slConfig, es_stream->ifce->sl_config, sizeof(GF_SLConfig));
break;
}
es_stream = es_stream->next;
}
}
bs_iod = gf_bs_new(NULL,0,GF_BITSTREAM_WRITE);
gf_odf_write_descriptor(bs_iod, stream->program->iod);
gf_bs_get_content(bs_iod, &iod_data, &iod_data_len);
gf_bs_del(bs_iod);
len = iod_data_len + 4;
gf_bs_write_int(bs,len + info_length, 12); 
gf_bs_write_int(bs,GF_M2TS_MPEG4_IOD_DESCRIPTOR, 8);
len = iod_data_len + 2;
gf_bs_write_int(bs,len, 8);
gf_bs_write_int(bs,2, 8);
gf_bs_write_int(bs,2, 8);  
gf_bs_write_data(bs, iod_data, iod_data_len);
gf_free(iod_data);
}
if (stream->program->loop_descriptors) {
for (i=0; i<gf_list_count(stream->program->loop_descriptors); i++) {
GF_M2TSDescriptor *desc = (GF_M2TSDescriptor*)gf_list_get(stream->program->loop_descriptors, i);
gf_bs_write_int(bs,desc->tag, 8);
gf_bs_write_int(bs,desc->data_len, 8);
gf_bs_write_data(bs, desc->data, desc->data_len);
}
}
es = stream->program->streams;
while (es) {
Bool has_lang = GF_FALSE;
u8 type = es->mpeg2_stream_type;
nb_streams++;
es_info_length = 0;
switch (es->mpeg2_stream_type) {
case GF_M2TS_AUDIO_AC3:
case GF_M2TS_VIDEO_VC1:
es_info_length += 2 + 4;
type = GF_M2TS_PRIVATE_DATA;
break;
case GF_M2TS_AUDIO_EC3:
es_info_length += 2;
type = GF_M2TS_PRIVATE_DATA;
break;
}
gf_bs_write_int(bs,type, 8);
gf_bs_write_int(bs,0x7, 3); gf_bs_write_int(bs,es->pid, 13);
gf_bs_write_int(bs,0xF, 4); 
if (stream->program->iod && !(es->ifce->caps & GF_ESI_STREAM_WITHOUT_MPEG4_SYSTEMS))
es_info_length += 4;
if (es->loop_descriptors)
{
for (i=0; i<gf_list_count(es->loop_descriptors); i++)
{
GF_M2TSDescriptor *desc = (GF_M2TSDescriptor*)gf_list_get(es->loop_descriptors, i);
es_info_length += 2 +desc->data_len;
}
}
if (es->ifce && es->ifce->lang && (es->ifce->lang  != GF_MEDIA_LANG_UND) ) {
es_info_length += 2 + 3;
has_lang = GF_TRUE;
}
gf_bs_write_int(bs,es_info_length, 12);
if (stream->program->iod && !(es->ifce->caps & GF_ESI_STREAM_WITHOUT_MPEG4_SYSTEMS)) {
gf_bs_write_int(bs,GF_M2TS_MPEG4_SL_DESCRIPTOR, 8);
gf_bs_write_int(bs,2, 8);
gf_bs_write_int(bs,es->ifce->stream_id, 16);  }
if (has_lang) {
gf_bs_write_int(bs,GF_M2TS_ISO_639_LANGUAGE_DESCRIPTOR, 8);
gf_bs_write_int(bs,3, 8);
gf_bs_write_int(bs,(es->ifce->lang>>24) & 0xFF, 8);
gf_bs_write_int(bs,(es->ifce->lang>>16) & 0xFF, 8);
gf_bs_write_int(bs,es->ifce->lang & 0xFF, 8);
}
switch (es->mpeg2_stream_type) {
case GF_M2TS_AUDIO_AC3:
gf_bs_write_int(bs,GF_M2TS_REGISTRATION_DESCRIPTOR, 8);
gf_bs_write_int(bs,4, 8);
gf_bs_write_int(bs,'A', 8);
gf_bs_write_int(bs,'C', 8);
gf_bs_write_int(bs,'-', 8);
gf_bs_write_int(bs,'3', 8);
break;
case GF_M2TS_VIDEO_VC1:
gf_bs_write_int(bs,GF_M2TS_REGISTRATION_DESCRIPTOR, 8);
gf_bs_write_int(bs,4, 8);
gf_bs_write_int(bs,'V', 8);
gf_bs_write_int(bs,'C', 8);
gf_bs_write_int(bs,'-', 8);
gf_bs_write_int(bs,'1', 8);
break;
case GF_M2TS_AUDIO_EC3:
gf_bs_write_int(bs,GF_M2TS_DVB_EAC3_DESCRIPTOR, 8);
gf_bs_write_int(bs,0, 8); break;
}
if (es->loop_descriptors)
{
for (i=0; i<gf_list_count(es->loop_descriptors); i++)
{
GF_M2TSDescriptor *desc = (GF_M2TSDescriptor *)gf_list_get(es->loop_descriptors, i);
gf_bs_write_int(bs,desc->tag, 8);
gf_bs_write_int(bs,desc->data_len, 8);
gf_bs_write_data(bs, desc->data, desc->data_len);
}
}
es = es->next;
}
gf_bs_get_content(bs, (char**)&payload, &length);
gf_bs_del(bs);
gf_m2ts_mux_table_update(stream, GF_M2TS_TABLE_ID_PMT, stream->program->number, payload, length, GF_TRUE, GF_FALSE, GF_FALSE);
stream->table_needs_update = GF_FALSE;
stream->table_needs_send = GF_TRUE;
gf_free(payload);
GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[MPEG-2 TS Muxer] PID %d: Updating PMT - Program Number %d - %d streams - size %d%s\n", stream->pid, stream->program->number, nb_streams, length, stream->program->iod ? " - MPEG-4 Systems detected":""));
}
if (stream->table_needs_send)
return 1;
if (stream->refresh_rate_ms)
return 1;
return 0;
}

static noinline int join_transaction(struct btrfs_fs_info *fs_info,
unsigned int type)
{
struct btrfs_transaction *cur_trans;
spin_lock(&fs_info->trans_lock);
loop:
if (test_bit(BTRFS_FS_STATE_ERROR, &fs_info->fs_state)) {
spin_unlock(&fs_info->trans_lock);
return -EROFS;
}
cur_trans = fs_info->running_transaction;
if (cur_trans) {
if (TRANS_ABORTED(cur_trans)) {
spin_unlock(&fs_info->trans_lock);
return cur_trans->aborted;
}
if (btrfs_blocked_trans_types[cur_trans->state] & type) {
spin_unlock(&fs_info->trans_lock);
return -EBUSY;
}
refcount_inc(&cur_trans->use_count);
atomic_inc(&cur_trans->num_writers);
extwriter_counter_inc(cur_trans, type);
spin_unlock(&fs_info->trans_lock);
return 0;
}
spin_unlock(&fs_info->trans_lock);
if (type == TRANS_ATTACH)
return -ENOENT;
BUG_ON(type == TRANS_JOIN_NOLOCK);
cur_trans = kmalloc(sizeof(*cur_trans), GFP_NOFS);
if (!cur_trans)
return -ENOMEM;
spin_lock(&fs_info->trans_lock);
if (fs_info->running_transaction) {
kfree(cur_trans);
goto loop;
} else if (test_bit(BTRFS_FS_STATE_ERROR, &fs_info->fs_state)) {
spin_unlock(&fs_info->trans_lock);
kfree(cur_trans);
return -EROFS;
}
cur_trans->fs_info = fs_info;
atomic_set(&cur_trans->pending_ordered, 0);
init_waitqueue_head(&cur_trans->pending_wait);
atomic_set(&cur_trans->num_writers, 1);
extwriter_counter_init(cur_trans, type);
init_waitqueue_head(&cur_trans->writer_wait);
init_waitqueue_head(&cur_trans->commit_wait);
cur_trans->state = TRANS_STATE_RUNNING;
refcount_set(&cur_trans->use_count, 2);
cur_trans->flags = 0;
cur_trans->start_time = ktime_get_seconds();
memset(&cur_trans->delayed_refs, 0, sizeof(cur_trans->delayed_refs));
cur_trans->delayed_refs.href_root = RB_ROOT_CACHED;
cur_trans->delayed_refs.dirty_extent_root = RB_ROOT;
atomic_set(&cur_trans->delayed_refs.num_entries, 0);
smp_mb();
if (!list_empty(&fs_info->tree_mod_seq_list))
WARN(1, KERN_ERR "BTRFS: tree_mod_seq_list not empty when creating a fresh transaction\n");
if (!RB_EMPTY_ROOT(&fs_info->tree_mod_log))
WARN(1, KERN_ERR "BTRFS: tree_mod_log rb tree not empty when creating a fresh transaction\n");
atomic64_set(&fs_info->tree_mod_seq, 0);
spin_lock_init(&cur_trans->delayed_refs.lock);
INIT_LIST_HEAD(&cur_trans->pending_snapshots);
INIT_LIST_HEAD(&cur_trans->dev_update_list);
INIT_LIST_HEAD(&cur_trans->switch_commits);
INIT_LIST_HEAD(&cur_trans->dirty_bgs);
INIT_LIST_HEAD(&cur_trans->io_bgs);
INIT_LIST_HEAD(&cur_trans->dropped_roots);
mutex_init(&cur_trans->cache_write_mutex);
spin_lock_init(&cur_trans->dirty_bgs_lock);
INIT_LIST_HEAD(&cur_trans->deleted_bgs);
spin_lock_init(&cur_trans->dropped_roots_lock);
INIT_LIST_HEAD(&cur_trans->releasing_ebs);
spin_lock_init(&cur_trans->releasing_ebs_lock);
atomic64_set(&cur_trans->chunk_bytes_reserved, 0);
init_waitqueue_head(&cur_trans->chunk_reserve_wait);
list_add_tail(&cur_trans->list, &fs_info->trans_list);
extent_io_tree_init(fs_info, &cur_trans->dirty_pages,
IO_TREE_TRANS_DIRTY_PAGES, fs_info->btree_inode);
extent_io_tree_init(fs_info, &cur_trans->pinned_extents,
IO_TREE_FS_PINNED_EXTENTS, NULL);
fs_info->generation++;
cur_trans->transid = fs_info->generation;
fs_info->running_transaction = cur_trans;
cur_trans->aborted = 0;
spin_unlock(&fs_info->trans_lock);
return 0;
}

